embedforge/agent/context.py:
"""What the model sees each step: a budgeted view of the full history plus a ground-truth state block.

The full history is kept (and persisted, minus harness notices). Each step the model gets:
  * the system prompt and a STATE block regenerated from disk, the Fact Ledger and the last build/verify, so its
    memory of the project can never be lost to compaction;
  * the last VERBATIM_TURNS assistant turns exactly, older tool results as one-line digests and older large
    tool arguments (file bodies) elided — tool-call/result pairs always stay intact;
  * user messages with stale harness context removed, exact duplicates merged.
Nothing here creates facts or decides outcomes; it only summarises real tool results.
"""

import json
import re
from typing import Any, Dict, List, Optional, Tuple

CONTEXT_BUDGET_CHARS = 120_000
VERBATIM_TURNS = 10
PERSIST_MAX_MESSAGES = 800
_BIG_ARGS = ("content", "old", "new", "markdown")
_POWER_NET = re.compile(r"^(\+?\d+(\.\d+)?V\d*|\d+V\d+|V(CC|DD|BAT|BUS|IN|SYS|REG)\w*|AGND|DGND|PGND|GND\w*|VSS\w*|3V3|5V|1V1|1V8)$", re.I)
_CONTEXT_MARKERS = re.compile(r"\n\n\[(?:Requirement Engine|Board imported)")


def visible_user_text(content: str) -> str:
    """The user's own words, without the context blocks the runner used to append for the model."""
    return _CONTEXT_MARKERS.split(content or "", maxsplit=1)[0]


def strip_private(m: Dict[str, Any]) -> Dict[str, Any]:
    return {k: v for k, v in m.items() if not k.startswith("_")}


def is_notice(m: Dict[str, Any]) -> bool:
    return m.get("role") == "user" and (m.get("_ephemeral") or str(m.get("content") or "").startswith("[System Notice]"))


# ------------------------------------------------------------------ digests
def digest(name: str, args: Dict[str, Any], result: Any) -> str:
    """One line that preserves what a tool call established (used once the full result leaves the window)."""
    r = result if isinstance(result, dict) else {}
    err = r.get("error")
    if err and not (name == "build" and r.get("diagnostics")):  # a failed build's first diagnostic says more than its error
        return f"{name} ERROR: {str(err)[:160]}"
    if name == "record_fact" or name == "record_user_fact":
        f = r.get("fact") or {}
        return (f"{name} -> {f.get('id')} {f.get('subject')}.{f.get('property')}={f.get('value')}" if r.get("ok")
                else f"{name} REJECTED: {str(r.get('error'))[:120]}")
    if name == "record_board_pins":
        rec = ", ".join(str(x) for x in r.get("recorded") or [])
        extra = [f"{len(r[k])} {k.replace('_', ' ')}" for k in ("tagged", "mismatched", "not_in_config", "rejected") if r.get(k)]
        return f"record_board_pins -> {rec or 'none'}" + (f"; {', '.join(extra)}" if extra else "")
    if name == "record_sequence":
        s = r.get("sequence") or {}
        return (f"record_sequence -> {s.get('id')} {s.get('subject')}.{s.get('name')} in {s.get('entry')}() ({len(s.get('steps') or [])} steps)"
                if r.get("ok") else f"record_sequence REJECTED: {str(r.get('error'))[:140]}")
    if name in ("record_facts", "record_registers", "record_layouts") or (name == "record_formula" and "recorded" in r):
        rec =[str(x).split(":")[0] for x in (r.get("recorded") or [])] + [str(x).split(":")[0] for x in (r.get("bursts") or [])]
        rej = r.get("rejected") or []
        return (f"{name} -> {', '.join(rec[:14]) or 'none'}" + (f" (+{len(rec) - 14})" if len(rec) > 14 else "")
                + (f"; {len(rej)} rejected, e.g. {rej[0].get('item') or rej[0].get('register') or rej[0].get('layout') or rej[0].get('burst')}: "
                   f"{str(rej[0].get('error'))[:90]}" if rej else ""))
    if name == "record_formula":
        return f"record_formula -> {str(r.get('formula'))[:150]}" if r.get("ok") else f"record_formula REJECTED: {str(r.get('error'))[:140]}"
    if name == "coding_brief":
        reqs = (r.get("datasheet_requirements") or {}).get("counts") or {}
        return (f"coding_brief: {len(r.get('sequences') or [])} sequence(s), {len(r.get('rules_after_every_write') or [])} rule(s), "
                f"{len(r.get('conversions') or [])} conversion(s), {reqs.get('open', 0)} open requirement(s)")
    if name == "resolve_requirements":
        return (f"resolve_requirements -> {', '.join(r.get('resolved') or []) or 'none'}"
                + (f"; {len(r['rejected'])} rejected: {str(r['rejected'][0].get('error'))[:80]}" if r.get("rejected") else ""))
    if name == "record_constraint":
        return (f"record_constraint -> {str(r.get('constraint'))[:150]}" if r.get("ok")
                else f"record_constraint REJECTED: {str(r.get('error'))[:140]}")
    if name == "read_file":
        return f"read_file {args.get('path')} lines {r.get('start')}-{r.get('end')}/{r.get('total_lines')}"
    if name in ("write_file", "replace_in_file"):
        lint = r.get("lint") or []
        return f"{name} {args.get('path')} ({r.get('bytes')} B)" + (f"; lint: {lint[0]}" if lint else "")
    if name == "build":
        if r.get("ok"):
            return f"build OK v{r.get('version')} flash {r.get('flash_used')}/{r.get('flash_total')}"
        diags = r.get("diagnostics") or []
        if not diags:
            return f"build FAILED: {str(r.get('error') or 'see log')[:160]}"
        d = diags[0]
        more = max(0, len(diags) - 1)
        return f"build FAILED: {d.get('file')}:{d.get('line')} {str(d.get('message'))[:120]}" + (f" (+{more} more)" if more else "")
    if name == "verify":
        f0 = (r.get("findings") or [{}])[0]
        return f"verify {r.get('summary')}" + (f"; first: {f0.get('code')} {f0.get('file')}:{f0.get('line')}" if f0 else "")
    if name == "query_board":
        lines = r.get("lines") or []
        return f"query_board {args.get('query')!r}: {len(lines)} lines" + (f"; e.g. {lines[0][:120]}" if lines else "")
    if name in ("init_betaflight", "init_project"):
        board = r.get("board") if isinstance(r.get("board"), dict) else {}
        return f"{name} -> {r.get('config_path') or board.get('id') or 'ok'}"
    if name == "web_search":
        return f"web_search {args.get('query')!r}: " + ", ".join(x.get("source_id", "") for x in (r.get("results") or []))
    if name in ("read_framework_file",):
        return f"read_framework_file {args.get('path')} lines {r.get('start')}-{r.get('end')}/{r.get('total_lines')}"
    if name == "search_framework":
        return f"search_framework {args.get('pattern')!r}: {len(r.get('matches') or [])} matches"
    s = json.dumps(r, default=str)
    return f"{name}: {s[:160]}"


def _elide_calls(tool_calls: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    out = []
    for tc in tool_calls:
        fn = dict(tc.get("function") or {})
        try:
            args = json.loads(fn.get("arguments") or "{}")
        except (ValueError, TypeError):
            args = None
        if isinstance(args, dict):
            for k in _BIG_ARGS:
                if isinstance(args.get(k), str) and len(args[k]) > 300:
                    args[k] = f"<{len(args[k])} chars elided>"
            fn["arguments"] = json.dumps(args)
        out.append({**tc, "function": fn})
    return out


def _size(m: Dict[str, Any]) -> int:
    return len(str(m.get("content") or "")) + len(json.dumps(m.get("tool_calls") or []))


# ------------------------------------------------------------------ context building
def build_context(history: List[Dict[str, Any]], budget: int = CONTEXT_BUDGET_CHARS,
                  verbatim_turns: int = VERBATIM_TURNS) -> List[Dict[str, Any]]:
    """Budgeted, well-formed message list for the LLM (system prompt and state block are added by the caller)."""
    # group into units: a user message, or an assistant message with the tool results that answer it
    units: List[List[Dict[str, Any]]] = []
    for m in history:
        if m.get("role") == "tool" and units and units[-1][0].get("role") == "assistant":
            units[-1].append(m)
        elif m.get("role") == "tool":
            continue  # orphan tool result (can happen in old saved histories) — providers reject it
        else:
            units.append([m])

    assistant_idx = [i for i, u in enumerate(units) if u[0].get("role") == "assistant"]
    verbatim_from = assistant_idx[-verbatim_turns] if len(assistant_idx) >= verbatim_turns else 0
    last_user = max((i for i, u in enumerate(units) if u[0].get("role") == "user" and not is_notice(u[0])), default=-1)

    out_units: List[List[Dict[str, Any]]] = []
    seen_user: Dict[str, int] = {}
    for i, u in enumerate(units):
        head = u[0]
        if head.get("role") == "user":
            if is_notice(head) and i < verbatim_from:
                continue  # stale harness notice
            text = str(head.get("content") or "")
            if i != last_user and not is_notice(head):
                text = visible_user_text(text)
            key = text.strip()
            if key in seen_user:  # exact duplicate request: keep only the latest copy
                out_units[seen_user[key]] = []
            seen_user[key] = len(out_units)
            out_units.append([{"role": "user", "content": text}])
            continue
        if i >= verbatim_from:
            out_units.append([strip_private(m) for m in u])
            continue
        a = strip_private(head)
        if a.get("tool_calls"):
            a["tool_calls"] = _elide_calls(a["tool_calls"])
        group = [a]
        for t in u[1:]:
            group.append({"role": "tool", "tool_call_id": t.get("tool_call_id"),
                          "content": t.get("_digest") or str(t.get("content") or "")[:200]})
        out_units.append(group)

    out_units = [u for u in out_units if u]
    total = sum(_size(m) for u in out_units for m in u)
    # still too big: drop the oldest assistant groups (never the verbatim window, never user turns)
    keep_from = next((k for k, u in enumerate(out_units) if u and u[0].get("role") == "assistant" and
                      sum(1 for x in out_units[k:] if x and x[0].get("role") == "assistant") <= verbatim_turns), len(out_units))
    k = 0
    while total > budget and k < keep_from:
        u = out_units[k]
        if u and u[0].get("role") == "assistant":
            total -= sum(_size(m) for m in u)
            out_units[k] = []
        k += 1
    # the verbatim window alone is over budget (many huge results): digest it from the oldest, keeping the last 3 turns
    asst = [k for k, u in enumerate(out_units) if u and u[0].get("role") == "assistant"]
    for k in asst[:-3]:
        if total <= budget:
            break
        before = sum(_size(m) for m in out_units[k])
        digests = {m.get("tool_call_id"): m.get("_digest") for m in history if m.get("role") == "tool"}
        a = dict(out_units[k][0])
        if a.get("tool_calls"):
            a["tool_calls"] = _elide_calls(a["tool_calls"])
        out_units[k] = [a] + [{"role": "tool", "tool_call_id": t.get("tool_call_id"),
                               "content": digests.get(t.get("tool_call_id")) or str(t.get("content") or "")[:200]} for t in out_units[k][1:]]
        total -= before - sum(_size(m) for m in out_units[k])
    return [m for u in out_units for m in u]


def for_persistence(history: List[Dict[str, Any]], max_messages: int = PERSIST_MAX_MESSAGES) -> List[Dict[str, Any]]:
    """Full history minus harness notices, capped at a clean boundary (never starting with a tool result)."""
    kept = [m for m in history if not is_notice(m)]
    if len(kept) > max_messages:
        kept = kept[-max_messages:]
        while kept and kept[0].get("role") == "tool":
            kept.pop(0)
    return kept


def latest_request(history: List[Dict[str, Any]], min_chars: int = 40) -> str:
    """The most recent substantive user request ('continue' / 'ok' are not requests)."""
    for m in reversed(history):
        if m.get("role") == "user" and not is_notice(m):
            t = visible_user_text(str(m.get("content") or "")).strip()
            if len(t) >= min_chars:
                return t
    return ""


# ------------------------------------------------------------------ ground-truth state block
def uncovered_pins(board: Any, facts: List[Any], limit: int = 40) -> Tuple[List[str], Optional[str]]:
    """Wired MCU GPIO pins (signal nets) that no recorded fact's quote names yet."""
    from embedforge.eda.board import _AUTO_NET
    from embedforge.truth.verifier import quote_pins
    if board is None:
        return [], None
    mcus = board.mcus()
    if not mcus:
        return [], None
    mcu = mcus[0]
    nets = board.nets()
    covered = set()
    for f in facts:
        covered |= quote_pins(f.quote)
    out = []
    for pin in sorted(mcu.pins.values(), key=lambda p: [int(t) if t.isdigit() else t for t in re.split(r"(\d+)", p.number)]):
        m = re.match(r"GPIO(\d+)", pin.name or "", re.I)
        if not m or not pin.net or _POWER_NET.match(pin.net) or _AUTO_NET.match(pin.net):
            continue
        if len(nets.get(pin.net, [])) < 2:
            continue
        g = f"GPIO{int(m.group(1))}"
        if g not in covered:
            out.append(f"{g} ({pin.net})")
    return out[:limit], mcu.ref


_PIN_DEFINE = re.compile(r"^\s*#\s*define\s+(\w+_PIN)\s+PA(\d{1,2})\b(.*)$")


def config_pin_status(text: str, ledger: Any, board: Any, limit: int = 24) -> List[str]:
    """'DEFINE=PAn -> GPIOn net X (problem)' for each active pin define without a valid fact. The net is shown so a wrong
    assignment is visible; it is not a claim that the pin is right."""
    from embedforge.truth.verifier import pin_key, quote_pins
    out = []
    for raw in text.split("\n"):
        m = _PIN_DEFINE.match(raw)
        if not m:
            continue
        name, n, rest = m.group(1), int(m.group(2)), m.group(3)
        gpio = f"GPIO{n}"
        tags = re.findall(r"FACT-\d{3,}", rest)
        facts = [ledger.get(t) for t in tags if ledger.get(t)]
        if not tags:
            problem = "no fact tag" if not re.search(r"FACT", rest) else "invalid tag"
        elif not facts:
            problem = f"{tags[0]} is not in the ledger"
        elif not any(pin_key(f.value, True) == gpio or (pin_key(f.value, True) is None and quote_pins(f.quote) == {gpio}) for f in facts):
            problem = f"{facts[0].id} is {facts[0].value}"
        elif any(re.fullmatch(r"[A-Z][A-Z0-9_]*_PIN", f.property) and f.property != name for f in facts):
            problem = f"{facts[0].id} was recorded for {facts[0].property}"
        else:
            continue
        net = ""
        if board is not None:
            lines = board.mcu_pin_lines(n)
            nm = re.search(r"-> net (\S+)", lines[0]) if lines else None
            net = (f" net {nm.group(1)}" if nm else " NOT CONNECTED (remove)" if lines else " not on the MCU")
        out.append(f"{name}=PA{n} -> {gpio}{net} ({problem})")
    return out[:limit]


def state_block(project: Any, ledger: Any, belt: Any, history: List[Dict[str, Any]]) -> Tuple[str, str]:
    """(text, next_step). Everything comes from disk, the ledger and real tool results."""
    from embedforge import eda
    meta = project.meta()
    kind = meta.get("kind") or ("platformio" if (project.root / "platformio.ini").exists() else "")
    board = eda.load_board(project.root)
    facts = list(ledger.facts.values())
    current = belt.source_hash()
    lb = meta.get("last_build") or {}
    lv = meta.get("last_verify") or {}
    lines = ["PROJECT STATE (generated by EmbedForge from files, the Fact Ledger and real tool results; trust it over memory)"]

    req = latest_request(history)
    if req:
        lines.append(f"- Task (latest request; it replaces older requests): {req[:600]}")
    if board is not None:
        s = board.summary()
        mcu = ", ".join(f"{m['ref']} = {m['mpn'] or m['value']} ({m['pin_count']} pins)" for m in s["mcus"]) or "not identified"
        lines.append(f"- Imported schematic: {s['parts']} parts, {s['nets']} nets; MCU {mcu}. Look up wiring with query_board.")
        ics = [f"{p['ref']} {p['mpn'] or p['value']}"[:40] for p in s.get("ics", []) if not p.get("is_mcu")]
        if ics:
            lines.append("- Parts (all ICs, transistors and connectors on the board — do not probe other designators): " + "; ".join(ics))
    if kind == "betaflight":
        cfg = f"betaflight/configs/CUST/{meta.get('board')}/config.h"
        exists = (project.root / cfg).exists()
        n = len((project.root / cfg).read_text(encoding="utf-8", errors="ignore").splitlines()) if exists else 0
        lines.append(f"- Project: Betaflight {meta.get('framework', '')}, target {meta.get('bf_target')}, board {meta.get('board')} "
                     f"(already initialised — do not call init_betaflight again). Config: {cfg} "
                     + (f"({n} lines)" if exists else "(not written yet)"))
    elif kind == "platformio":
        lines.append(f"- Project: PlatformIO board {meta.get('board')} ({meta.get('mcu')}), framework {meta.get('framework')}")
    else:
        lines.append("- Project: not initialised yet")

    if facts:
        shown = facts[-40:]
        lines.append(f"- Facts recorded ({len(facts)}): " + "; ".join(f"{f.id} {f.subject}.{f.property}={f.value}" for f in shown))
    else:
        lines.append("- Facts recorded: none")
    unc, mcu_ref = uncovered_pins(board, facts)
    if unc:
        lines.append(f"- Wired {mcu_ref} pins with no fact yet (record the ones the firmware uses): " + ", ".join(unc))
    pin_problems: List[str] = []
    if kind == "betaflight":
        cfgp = project.root / "betaflight" / "configs" / "CUST" / str(meta.get("board")) / "config.h"
        if cfgp.exists():
            pin_problems = config_pin_status(cfgp.read_text(encoding="utf-8", errors="ignore"), ledger, board)
            if pin_problems:
                lines.append(f"- config.h pins without a valid fact ({len(pin_problems)}): " + "; ".join(pin_problems))

    changed = lb.get("hash") != current
    if lb:
        state = "OK" if lb.get("ok") else "FAILED"
        lines.append(f"- Last build: {state}" + (" (sources changed since)" if changed else " (current sources)")
                     + "".join(f"\n    {d}" for d in (lb.get("diagnostics") or [])[:3]))
    else:
        lines.append("- Last build: never built")
    from embedforge.truth.sequences import SequenceBook
    seqs = list(SequenceBook(project.root).items.values())
    if seqs:
        lines.append(f"- Datasheet sequences recorded ({len(seqs)}): "
                     + "; ".join(f"{s.id} {s.subject}.{s.name} in {s.entry}() ({len(s.steps)} steps)" for s in seqs[:8]))
    from embedforge.truth.registers import RegisterBook
    book = RegisterBook(project.root)
    if not book.empty():
        regs = sorted(book.registers.values(), key=lambda r: r.addr)
        lines.append(f"- Register map: {len(regs)} registers (" + ", ".join(f"{r.name} 0x{r.addr:02X}" for r in regs[:16])
                     + f"), {len(book.layouts)} layouts, {len(book.bursts)} burst rules, {len(book.formulas)} formulas"
                     + (" (" + ", ".join(f.name for f in list(book.formulas.values())[:12]) + ")" if book.formulas else ""))
    unread = []
    for sid in (belt.state.get("unread") or {}):   # datasheet sections the code depends on (known after a verify)
        unread += [f"{sid} {s.num} {s.title[:40]}" for s, _ in belt._required_for(sid) if belt.reads.seen(sid, s.start, s.end) < 0.5]
    if unread:
        lines.append(f"- Datasheet sections your code depends on, not read yet ({len(unread)}): " + "; ".join(unread[:8])
                     + " — read_section them (several per call) and record the rules they state.")
    from embedforge.truth.knowledge import Requirements
    rq = Requirements(project.root)
    if rq.items:
        c = rq.counts()
        lines.append(f"- Datasheet requirements: {len(rq.items)} ({c['covered']} covered by records, {c['implemented']} implemented, "
                     f"{c['not_applicable']} not applicable, {c['open']} open). coding_brief shows them with everything the code must do.")
    inputs_stale = bool(lv) and lv.get("hash") == current and lv.get("inputs") not in (None, belt.verify_inputs_hash())
    if lv:
        lines.append(f"- Last verify: {lv.get('summary')}"
                     + (" (sources changed since)" if lv.get("hash") != current else " (facts/sequences changed since: verify again)" if inputs_stale else "")
                     + "".join(f"\n    {d}" for d in (lv.get("findings") or [])[:3]))
    else:
        lines.append("- Last verify: never run")
    if inputs_stale:
        lv = {**lv, "hash": None}

    nxt = next_step(project, kind, meta, facts, unc, lb, lv, current, req, pin_problems if board is not None else [])
    lines.append(f"- NEXT STEP: {nxt}")
    return "\n".join(lines), nxt


_DRIVER_TASK = re.compile(r"\b(driver|sensor|datasheet|register|barometer|imu|gyro|accelerometer|magnetometer|adc|dac|eeprom)\b", re.I)


def driver_plan(project: Any, facts: List[Any], request: str) -> str:
    """Before writing a device driver: the facts its constants need and the register map it writes, so the first code
    is written from the datasheet. The rest (layouts, formulas, the init sequence) can follow the first build: verify
    fails on anything the code uses that is not on record, and its findings say what to record next."""
    from embedforge.truth.registers import RegisterBook
    ds_facts = [f for f in facts if str(getattr(f, "source_url", "")).startswith("http")]
    if not (_DRIVER_TASK.search(request or "") or ds_facts):
        return ""
    book = RegisterBook(project.root)
    if not ds_facts:
        return ("DRIVER — record_facts from the datasheet (read_source first): bus address for the strap on the schematic, ID "
                "register + value, command values, start-up/conversion times with units; then record_registers; then "
                "write_file the driver and build")
    if not book.registers:
        return ("DRIVER — record_registers: the registers the driver will write, poll or test, with fields (bits, named "
                "values) and bursts for data that must be read in one transaction; then write_file the driver and build")
    return ("write_file the driver from the recorded facts and registers (values composed from their fields), then build "
            "and verify: verify names what else to record (layouts for multi-byte values, formulas for conversions, the "
            "init sequence). Layouts, formulas and sequences recorded now are checked from the first verify")


def next_step(project: Any, kind: str, meta: Dict[str, Any], facts: List[Any], unc: List[str],
              lb: Dict[str, Any], lv: Dict[str, Any], current: str, request: str = "",
              pin_problems: Optional[List[str]] = None) -> str:
    if not kind and re.search(r"platform\s*io|arduino|pico[- ]?sdk|esp[- ]?idf|stm32cube", request, re.I) and not re.search(r"beta\s*flight", request, re.I):
        board = re.search(r"\bboard\s+([a-z0-9_]{3,40})\b", request, re.I)
        return ("resolve_target, then init_project" + (f"(board='{board.group(1)}', framework=<the framework the user named>)" if board else "")
                + " — the user asked for a PlatformIO/SDK project (not Betaflight)")
    if not kind and re.search(r"\bbeta\s*flight\b", request, re.I):
        return ("init_betaflight(board_name=<short board name>, target=<in-tree target, e.g. RP2350B for an RP2350B/RP2354B>, "
                "flash_mb=<2 for RP2354A/B>) — Betaflight has its own build; do not use resolve_target/init_project")
    if kind == "betaflight":
        cfg = project.root / "betaflight" / "configs" / "CUST" / str(meta.get("board")) / "config.h"
        if not cfg.exists():
            if unc:
                return ("record_board_pins for the pins the firmware will use (one call, each with the exact query_board "
                        "line), then write_file the config.h")
            return "write_file the config.h (copy define names from a reference config; pins only from recorded facts)"
        if pin_problems and lb.get("hash") != current:  # once these sources are built, move on (verify reports what's left)
            return ("record_board_pins with {define, line} for the defines under 'config.h pins without a valid fact' (lines "
                    "from query_board('U1')); it tags config.h. If a net does not fit its define, fix or remove the define; "
                    "remove defines on not-connected pins. Then build")
    elif kind != "platformio":
        return "set up the target: resolve_target + init_project (or init_betaflight for a Betaflight flight controller)"
    else:
        from embedforge.truth.verifier import collect_sources
        if not any(p.suffix in (".c", ".cpp", ".ino") for p in collect_sources(project.root)):
            plan = driver_plan(project, facts, request)
            if plan:
                return plan
            return ("record the facts the firmware needs (record_user_fact / record_fact), then write_file the sources "
                    "(src/main.c and modules), then build")
    built_now = lb.get("hash") == current
    if not built_now:
        return "build (sources changed since the last build)"
    if not lb.get("ok"):
        d = (lb.get("diagnostics") or ["see the last build result"])[0]
        return f"fix the FIRST build error ({d}) with replace_in_file, then build again"
    verified_now = lv.get("hash") == current
    if not verified_now:
        return "verify"
    if not lv.get("passed"):
        found = lv.get("findings") or []
        codes = {str(x).split(" ", 1)[0] for x in found}
        # what the code uses but nothing records yet: record it (no rebuild needed), every kind in one go
        record = {"REG_MAP_MISSING": "record_registers (+ record_layouts, record_formula)", "REG_FIELDS_MISSING": "record_registers with fields",
                  "REG_UNMAPPED": "record_registers / record_layouts for the unmapped addresses",
                  "REGISTER_WIDTH_UNRECORDED": "record_registers again with width '16', fields and byte_order_quote",
                  "REG_LAYOUT_MISSING": "record_layouts for the 16-bit measurement registers (+ record_formula)",
                  "LAYOUT_INVALID": "record_layouts again for the layouts it names (each register once)",
                  "FORMULA_SOURCE_UNOFFICIAL": "record_formula again from the manufacturer's documents",
                  "FORMULA_MISSING": "record_formula for the conversions", "FLOW_UNSPECIFIED": "record_sequence for the init order"}
        todo = [t for c, t in record.items() if c in codes]
        if todo:
            return (f"record what verify found unrecorded: {'; '.join(todo)} (each finding's suggestion says what to quote), "
                    "then verify again — new records need no rebuild")
        f = (found or ["see the last verify result"])[0]
        return f"fix the verify findings (first: {f}), then build and verify again"
    return "finish(status='success', summary=...) — the current sources built and verified"

embedforge/agent/llm.py:
"""Tool-calling LLM client used by the agent loop: the Anthropic Claude API (Messages API, official SDK) and
OpenAI-compatible providers (Google Gemini, Nebius Token Factory, NVIDIA NIM). The loop speaks one message format
(OpenAI-style role/content/tool_calls); the Claude path translates it to and from the Messages API."""

import json
import os
import re
import threading
import time
from dataclasses import dataclass
from typing import Any, Dict, List, Optional

import httpx

from embedforge.core.config import config
from embedforge.core.logger import logger


class LLMError(RuntimeError):
    """`transient`: the provider failed on its side (5xx, rate limit, unreachable), so the request may work later."""

    def __init__(self, message: str, transient: bool = False):
        super().__init__(message)
        self.transient = transient


@dataclass(frozen=True)
class Provider:
    id: str
    name: str
    base_url: str
    api_key: Optional[str]

    @property
    def configured(self) -> bool:
        return bool(self.api_key and self.api_key.strip())


def providers() -> Dict[str, Provider]:
    return {
        "anthropic": Provider("anthropic", "Anthropic Claude API", "https://api.anthropic.com", config.anthropic_api_key),
        "gemini": Provider("gemini", "Google Gemini API", config.gemini_base_url.rstrip("/"), config.gemini_api_key),
        "nebius": Provider("nebius", "Nebius Token Factory", config.nebius_base_url.rstrip("/"), config.nebius_api_key),
        "nvidia": Provider("nvidia", "NVIDIA API (NIM)", config.nvidia_base_url.rstrip("/"), config.nvidia_api_key),
        # a server without an API key ignores the Authorization header: any non-empty token marks it configured
        "selfhosted": Provider("selfhosted", "Self-hosted (vLLM / Ollama)", config.selfhosted_base_url.rstrip("/"),
                               (config.selfhosted_api_key or "none") if config.selfhosted_base_url else None),
    }


# Provider order when nothing is forced: a self-hosted server you set up (e.g. Nemotron on a Nebius AI Cloud VM), then
# NVIDIA Nemotron on Nebius Token Factory, then Nemotron from the NVIDIA API catalog, then Claude, then Gemini
# (EMBEDFORGE_PROVIDER forces one)
PREFERRED = ("selfhosted", "nebius", "nvidia", "anthropic", "gemini")


def default_provider() -> str:
    """EMBEDFORGE_PROVIDER if set; otherwise the first configured provider in PREFERRED (Nebius when none is)."""
    if config.llm_provider in providers():
        return config.llm_provider
    ps = providers()
    return next((pid for pid in PREFERRED if ps[pid].configured), "nebius")


def default_model(provider_id: str) -> str:
    return {"anthropic": config.anthropic_model, "gemini": config.gemini_model, "selfhosted": config.selfhosted_model,
            "nvidia": config.nvidia_model}.get(provider_id, config.agent_model)


def resolve_provider(requested: Optional[str]) -> str:
    """The provider a run uses: a forced EMBEDFORGE_PROVIDER wins; a project keeps the provider it saved while that
    provider is configured; otherwise the default."""
    if config.llm_provider in providers():
        return config.llm_provider
    p = providers().get(requested or "")
    return requested if p is not None and p.configured else default_provider()


# (base URL, model) pairs whose provider rejected Nemotron's chat_template_kwargs: later runs send none
_NO_TEMPLATE_KWARGS: set = set()

# ------------------------------------------------------------------ model catalogue
_MODEL_CACHE: Dict[str, Any] = {}
_MODEL_CACHE_LOCK = threading.Lock()
_MODEL_CACHE_TTL = 600
_NON_CHAT = re.compile(r"embed|rerank|guard|reward|clip|whisper|tts|parse|retriever|-v-|vision|ocr|"
                       r"image|veo|imagen|aqa|native-audio|-live|robotics", re.I)


def _describe(model_id: str) -> Dict[str, Any]:
    """Family + size label parsed from the model id (e.g. '30B · 3B active'); no claims beyond the id itself."""
    low = model_id.lower()
    family = model_id.split("/", 1)[0] if "/" in model_id else ""
    is_nvidia = family.lower() == "nvidia" or "nemotron" in low
    size = ""
    m = re.search(r"(\d+(?:\.\d+)?)b[-_]a(\d+(?:\.\d+)?)b", low)
    if m:
        size = f"{m.group(1).upper()}B · {m.group(2).upper()}B active"
    else:
        m = re.search(r"(?<![\d.])(\d+(?:\.\d+)?)b(?![a-z])", low)
        if m:
            size = f"{m.group(1)}B"
    label = model_id.split("/", 1)[-1]
    return {"family": family, "nvidia": is_nvidia, "size": size, "label": label}


def list_models(provider_id: str, force: bool = False) -> Dict[str, Any]:
    """Chat models available from a provider's /models endpoint (cached). Never raises."""
    p = providers().get(provider_id)
    if p is None or not p.configured:
        return {"provider": provider_id, "models": [], "error": "not configured"}
    with _MODEL_CACHE_LOCK:
        hit = _MODEL_CACHE.get(provider_id)
        if hit and not force and time.time() - hit["t"] < _MODEL_CACHE_TTL:
            return hit["v"]
    if provider_id == "anthropic":
        try:
            import anthropic
            ids = sorted({m.id for m in anthropic.Anthropic(api_key=p.api_key).models.list()})
            out = {"provider": provider_id, "error": "",
                   "models": [{"id": i, "provider": provider_id, "family": "anthropic", "nvidia": False, "size": "", "label": i} for i in ids]}
        except Exception as e:
            out = {"provider": provider_id, "models": [], "error": f"{type(e).__name__}: {str(e)[:200]}"}
        with _MODEL_CACHE_LOCK:
            _MODEL_CACHE[provider_id] = {"t": time.time(), "v": out}
        return out
    try:
        with httpx.Client(timeout=20.0) as c:
            r = c.get(f"{p.base_url}/models", headers={"Authorization": f"Bearer {p.api_key}"})
        r.raise_for_status()
        # Gemini's native ids carry a 'models/' prefix; requests take the bare name
        ids = sorted({str(m.get("id")).removeprefix("models/") for m in r.json().get("data", []) if m.get("id")})
        models = [{"id": i, "provider": provider_id, **_describe(i)} for i in ids if not _NON_CHAT.search(i)]
        models.sort(key=lambda m: (not m["nvidia"], m["id"].lower()))
        out = {"provider": provider_id, "models": models, "error": ""}
    except Exception as e:  # offline / bad key: the UI still shows the configured default
        out = {"provider": provider_id, "models": [], "error": f"{type(e).__name__}: {str(e)[:200]}"}
    with _MODEL_CACHE_LOCK:
        _MODEL_CACHE[provider_id] = {"t": time.time(), "v": out}
    return out


class AgentLLM:
    def __init__(self, model: Optional[str] = None, provider: Optional[str] = None):
        pid = resolve_provider(provider)
        p = providers().get(pid)
        if p is None:
            raise LLMError(f"Unknown LLM provider '{pid}'.")
        self.provider = p
        # a project saved with another provider's model keeps working: the run uses this provider's default model
        if pid == "anthropic":
            self.model = model if model and model.startswith("claude-") else config.anthropic_model
        elif pid == "gemini":
            self.model = model if model and model.startswith("gemini") else config.gemini_model
        elif pid == "selfhosted":   # the name the server serves the model under; a model picked from its list is kept
            self.model = model if model and provider == "selfhosted" else config.selfhosted_model
        elif pid == "nvidia":       # NVIDIA's own model ids ('nvidia/nemotron-3-super-120b-a12b'), not Nebius's spelling
            self.model = model if model and provider == "nvidia" else config.nvidia_model
        else:
            self.model = model if model and not model.startswith(("claude-", "gemini")) else config.agent_model
        self.base_url = p.base_url
        self.api_key = p.api_key

    def sampling(self) -> Dict[str, float]:
        """Nemotron reasoning models loop and repeat when run near-greedy. The Nemotron 3 model card samples at
        temperature 1.0 / top_p 0.95; older Nemotron reasoning models at 0.6 / 0.95. Other models keep a low temperature.
        EMBEDFORGE_TEMPERATURE / EMBEDFORGE_TOP_P override."""
        if self.provider.id == "anthropic":
            return {}   # Claude's current models take no sampling parameters (effort and adaptive thinking instead)
        if self.provider.id == "gemini" and config.agent_temperature is None and config.agent_top_p is None:
            return {}   # Gemini 3 is tuned for its default temperature (1.0); Google warns lower values can make it loop
        mid = self.model.lower()
        nemotron = "nemotron" in mid
        default_t = (1.0 if re.search(r"nemotron-?3", mid) else 0.6) if nemotron else 0.1
        out = {"temperature": config.agent_temperature if config.agent_temperature is not None else default_t}
        top_p = config.agent_top_p if config.agent_top_p is not None else (0.95 if nemotron else None)
        if top_p is not None:
            out["top_p"] = top_p
        return out

    def template_kwargs(self) -> Dict[str, Any]:
        """Nemotron 3 chat-template options, as NVIDIA's model card recommends for coding agents and tool calling:
        reasoning on, and a non-empty answer after the reasoning (so a reply is never only a thought);
        EMBEDFORGE_NEMOTRON_EFFORT=medium asks for markedly shorter reasoning."""
        if self.provider.id not in ("nebius", "nvidia", "selfhosted") or (self.base_url, self.model) in _NO_TEMPLATE_KWARGS:
            return {}
        if not re.search(r"nemotron-?3", self.model.lower()):
            return {}
        out: Dict[str, Any] = {"enable_thinking": True, "force_nonempty_content": True}
        if os.getenv("EMBEDFORGE_NEMOTRON_EFFORT", "").strip().lower() == "medium":
            out["medium_effort"] = True
        return out

    def default_max_tokens(self) -> int:
        """Reasoning models spend thousands of tokens thinking before a config rewrite; give them room."""
        if getattr(self, "_max_tokens_cap", None):
            return self._max_tokens_cap
        env = os.getenv("EMBEDFORGE_MAX_TOKENS")
        if env and env.isdigit():
            return int(env)
        if self.provider.id == "gemini":
            return 32768   # Gemini 3 always thinks, and its thinking counts toward the output limit
        return 16384 if re.search(r"nemotron|reason|r1|qwq|thinking", self.model.lower()) else 8192

    def chat(
        self, messages: List[Dict[str, Any]], tools: Optional[List[Dict[str, Any]]] = None,
        temperature: Optional[float] = None, max_tokens: Optional[int] = None, retries: int = 6,
    ) -> Dict[str, Any]:
        if not self.api_key:
            raise LLMError(f"{self.provider.name} API key is not configured; the agent cannot reason without an LLM.")
        if self.provider.id == "anthropic":
            return self._chat_anthropic(messages, tools, max_tokens)
        payload: Dict[str, Any] = {"model": self.model, "messages": messages,
                                   "max_tokens": max_tokens or self.default_max_tokens(), **self.sampling()}
        if temperature is not None:
            payload["temperature"] = temperature
        if tools:
            payload["tools"] = tools
            payload["tool_choice"] = "auto"
        if self.provider.id == "gemini":   # Gemini takes minimal | low | medium | high
            effort = config.anthropic_effort.lower()
            payload["reasoning_effort"] = effort if effort in ("minimal", "low", "medium") else "high"
        template = self.template_kwargs()
        if template:
            payload["chat_template_kwargs"] = template
        headers = {"Authorization": f"Bearer {self.api_key}", "Content-Type": "application/json"}
        last: Optional[str] = None

        def wait(attempt: int, r: Any = None) -> None:
            # the provider's Retry-After, else 2, 4, 8, 16, 32 s: a hosted endpoint's outage often lasts a minute or two
            if attempt == retries - 1:
                return
            try:
                after = float((getattr(r, "headers", None) or {}).get("retry-after") or 0)
            except ValueError:
                after = 0.0
            time.sleep(min(after, 60.0) if after > 0 else min(2 ** attempt * 2.0, 45.0))

        for attempt in range(retries):
            try:
                with httpx.Client(timeout=180.0) as c:
                    r = c.post(f"{self.base_url}/chat/completions", headers=headers, json=payload)
                # NVIDIA's API answers 404 "Function id ... is not found" while a listed model's deployment is being
                # replaced: an outage on their side, like a 503
                gone = r.status_code == 404 and re.search(r"function id|specified function", r.text or "", re.I)
                if r.status_code in (429, 500, 502, 503, 504) or gone:
                    last = f"HTTP {r.status_code}: {r.text[:200]}"
                    wait(attempt, r)
                    continue
                if r.status_code == 400 and "max_tokens" in r.text and payload["max_tokens"] > 8192:
                    self._max_tokens_cap = payload["max_tokens"] = 8192  # provider limit: remember it for this model
                    continue
                if r.status_code in (400, 422) and "chat_template_kwargs" in payload and re.search(
                        r"chat_template|template_kwargs|force_nonempty|medium_effort|extra (inputs|fields)|unrecognized|not permitted", r.text, re.I):
                    _NO_TEMPLATE_KWARGS.add((self.base_url, self.model))   # this provider does not take them: run without
                    payload.pop("chat_template_kwargs")
                    continue
                if r.status_code >= 400:
                    raise LLMError(f"LLM request failed ({self.model}): HTTP {r.status_code}: {r.text[:500]}")
                data = r.json()
                msg = data["choices"][0]["message"]
                content = (msg.get("content") or "").strip()
                reasoning = (msg.get("reasoning_content") or msg.get("reasoning") or "").strip()
                if "</think>" in content:  # some served models put their reasoning inline instead of a separate field
                    head, _, content = content.rpartition("</think>")
                    reasoning = (reasoning + "\n" + head.replace("<think>", "")).strip()
                    content = content.strip()
                elif content.startswith("<think>"):  # cut off mid-thought: all of it is reasoning, none of it an answer
                    reasoning, content = (reasoning + "\n" + content[len("<think>"):]).strip(), ""
                calls = []
                for i, tc in enumerate(msg.get("tool_calls") or []):
                    fn = tc.get("function") or {}
                    a = fn.get("arguments")
                    call = {"id": tc.get("id") or f"call_{int(time.time() * 1000)}_{i}", "type": "function",
                            "function": {"name": fn.get("name") or "", "arguments": a if isinstance(a, str) else json.dumps(a or {})}}
                    if tc.get("extra_content"):   # Gemini 3's thought signature: it must come back with the call
                        call["extra_content"] = tc["extra_content"]
                    calls.append(call)
                return {
                    "content": content,
                    "reasoning": reasoning,
                    "tool_calls": calls,
                    "finish_reason": data["choices"][0].get("finish_reason"),
                    "usage": data.get("usage", {}),
                }
            except (httpx.TimeoutException, httpx.TransportError) as e:
                last = str(e)
                wait(attempt)
        logger.log_event("LLM_ERROR", f"gave up after {retries} attempts: {last}")
        raise LLMError(f"LLM unavailable after {retries} attempts: {last}", transient=True)


    # ------------------------------------------------------------------ Claude (Messages API)
    _STATE_MARK = "PROJECT STATE"

    def _chat_anthropic(self, messages: List[Dict[str, Any]], tools: Optional[List[Dict[str, Any]]],
                        max_tokens: Optional[int]) -> Dict[str, Any]:
        """One agent step on Claude. The harness rebuilds its context every step (a fresh state block, digests of old
        tool results), so the history is not append-only: thinking blocks are never replayed (preserved thinking would
        reject an edited history), the stable system prompt and the tools are prompt-cached, and the per-step state
        block follows the cache breakpoint."""
        import anthropic

        system, msgs = to_anthropic_messages(messages)
        kwargs: Dict[str, Any] = {
            "model": self.model,
            "max_tokens": max_tokens or int(os.getenv("EMBEDFORGE_MAX_TOKENS") or 32000),
            "system": system,
            "messages": msgs,
            "thinking": {"type": "adaptive", "display": "summarized"},   # summaries feed the UI's reasoning panel
            "output_config": {"effort": config.anthropic_effort},
            # on a safety decline the API re-runs the request on a fallback model it picks by refusal category
            "betas": ["server-side-fallback-2026-07-01"],
            "fallbacks": "default",
        }
        if tools:
            kwargs["tools"] = to_anthropic_tools(tools)
        client = anthropic.Anthropic(api_key=self.api_key, max_retries=4)
        try:
            with client.beta.messages.stream(**kwargs) as stream:   # streaming: long turns never hit HTTP timeouts
                msg = stream.get_final_message()
        except anthropic.AuthenticationError as e:
            raise LLMError(f"Claude API key rejected: {e.message}")
        except anthropic.PermissionDeniedError as e:
            raise LLMError(f"Claude API permission denied: {e.message}")
        except anthropic.BadRequestError as e:
            raise LLMError(f"Claude API rejected the request ({self.model}): {e.message}")
        except anthropic.RateLimitError as e:
            raise LLMError(f"Claude API rate limit (after retries): {e.message}", transient=True)
        except anthropic.APIStatusError as e:
            raise LLMError(f"Claude API error HTTP {e.status_code}: {e.message}", transient=e.status_code >= 500)
        except anthropic.APIConnectionError as e:
            raise LLMError(f"Claude API unreachable: {e}", transient=True)
        return from_anthropic_message(msg)


def to_anthropic_tools(tools: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """OpenAI function specs -> Claude tool definitions (cached together with the system prompt, which renders after them)."""
    out = []
    for t in tools:
        fn = t.get("function") or t
        schema = dict(fn.get("parameters") or {"type": "object", "properties": {}})
        schema.setdefault("type", "object")
        out.append({"name": fn["name"], "description": fn.get("description", ""), "input_schema": schema})
    return out


def _tool_id(raw: Any) -> str:
    return re.sub(r"[^a-zA-Z0-9_-]", "_", str(raw or "call"))[:64]


def to_anthropic_messages(messages: List[Dict[str, Any]]):
    """OpenAI-style history -> (system blocks, Claude messages). Tool calls become tool_use blocks, tool results are
    gathered into one user message, consecutive same-role turns are merged and empty turns dropped."""
    system_text = "\n\n".join(str(m.get("content") or "") for m in messages if m.get("role") == "system")
    cut = system_text.find(AgentLLM._STATE_MARK)
    stable, state = (system_text[:cut], system_text[cut:]) if cut > 0 else (system_text, "")
    system: List[Dict[str, Any]] = [{"type": "text", "text": stable.strip() or "You are EmbedForge.", "cache_control": {"type": "ephemeral"}}]
    if state.strip():
        system.append({"type": "text", "text": state.strip()})
    out: List[Dict[str, Any]] = []

    def push(role: str, blocks: List[Dict[str, Any]]) -> None:
        if not blocks:
            return
        if out and out[-1]["role"] == role:
            out[-1]["content"].extend(blocks)
        else:
            out.append({"role": role, "content": list(blocks)})

    pending_tool_ids: set = set()
    for m in messages:
        role = m.get("role")
        if role == "system":
            continue
        if role == "assistant":
            blocks: List[Dict[str, Any]] = []
            text = str(m.get("content") or "").strip()
            if text:
                blocks.append({"type": "text", "text": text})
            for tc in m.get("tool_calls") or []:
                fn = tc.get("function") or {}
                try:
                    args = parse_tool_args(fn.get("arguments"))
                except ValueError:
                    args = {}
                tid = _tool_id(tc.get("id"))
                pending_tool_ids.add(tid)
                blocks.append({"type": "tool_use", "id": tid, "name": fn.get("name") or "unknown", "input": args})
            push("assistant", blocks)
        elif role == "tool":
            tid = _tool_id(m.get("tool_call_id"))
            if tid not in pending_tool_ids:
                continue   # no matching tool_use in the history sent: the API would reject it
            content = str(m.get("content") or "")
            push("user", [{"type": "tool_result", "tool_use_id": tid, "content": content or "(empty)",
                           **({"is_error": True} if content.startswith('{"error"') else {})}])
        else:
            text = m.get("content")
            if isinstance(text, list):
                push("user", [b if isinstance(b, dict) else {"type": "text", "text": str(b)} for b in text])
            elif str(text or "").strip():
                push("user", [{"type": "text", "text": str(text)}])
    if not out or out[0]["role"] != "user":
        out.insert(0, {"role": "user", "content": [{"type": "text", "text": "Continue the task."}]})
    # every tool_use needs its tool_result in the next user turn: answer any that the history lost
    for i, m in enumerate(out):
        if m["role"] != "assistant":
            continue
        ids = [b["id"] for b in m["content"] if b["type"] == "tool_use"]
        nxt = out[i + 1] if i + 1 < len(out) else None
        have = {b.get("tool_use_id") for b in (nxt["content"] if nxt and nxt["role"] == "user" else [])}
        missing = [x for x in ids if x not in have]
        if missing:
            results = [{"type": "tool_result", "tool_use_id": x, "content": "(result not kept in context)"} for x in missing]
            if nxt and nxt["role"] == "user":
                nxt["content"][:0] = results
            else:
                out.insert(i + 1, {"role": "user", "content": results})
    return system, out


def from_anthropic_message(msg: Any) -> Dict[str, Any]:
    """A Claude message -> the loop's response shape (content, reasoning, tool_calls, finish_reason, usage)."""
    texts, thoughts, calls = [], [], []
    for b in msg.content:
        t = getattr(b, "type", "")
        if t == "text":
            texts.append(b.text)
        elif t == "thinking":
            if getattr(b, "thinking", ""):
                thoughts.append(b.thinking)
        elif t == "tool_use":
            calls.append({"id": b.id, "type": "function",
                          "function": {"name": b.name, "arguments": json.dumps(b.input if isinstance(b.input, dict) else {})}})
    stop = getattr(msg, "stop_reason", None)
    content = "\n".join(x for x in texts if x).strip()
    if stop == "max_tokens":
        calls = []   # a tool input cut off at the token limit parses as a partial object: never run it
    if stop == "refusal":
        details = getattr(msg, "stop_details", None)
        cat = getattr(details, "category", None) if details else None
        calls = []   # a declined turn's tool calls may be cut off mid-input: never run them
        content = (content + "\n\n" if content else "") + f"[The model declined this request{f' ({cat})' if cat else ''}.]"
    u = getattr(msg, "usage", None)
    cached = (getattr(u, "cache_read_input_tokens", 0) or 0) if u else 0
    created = (getattr(u, "cache_creation_input_tokens", 0) or 0) if u else 0
    usage = {"prompt_tokens": ((getattr(u, "input_tokens", 0) or 0) + cached + created) if u else 0,
             "completion_tokens": (getattr(u, "output_tokens", 0) or 0) if u else 0,
             "cache_read_input_tokens": cached, "cache_creation_input_tokens": created}
    finish = {"end_turn": "stop", "tool_use": "tool_calls", "max_tokens": "length", "stop_sequence": "stop",
              "pause_turn": "stop", "refusal": "refusal"}.get(stop or "", stop)
    return {"content": content, "reasoning": "\n\n".join(thoughts).strip(), "tool_calls": calls,
            "finish_reason": finish, "usage": usage}


def parse_tool_args(raw: Any) -> Dict[str, Any]:
    if isinstance(raw, dict):
        return raw
    if not raw:
        return {}
    try:
        v = json.loads(raw)
        return v if isinstance(v, dict) else {}
    except json.JSONDecodeError:
        start, end = raw.find("{"), raw.rfind("}")
        if start != -1 and end > start:
            try:
                return json.loads(raw[start : end + 1])
            except json.JSONDecodeError:
                pass
    raise ValueError("Tool arguments were not valid JSON.")

embedforge/agent/textcalls.py:
"""Tool calls a model wrote as text instead of the API's tool_calls field.

Some models (Nemotron / Qwen-coder style) sometimes put their calls in the message text, and the provider does not
always turn them into structured calls:

    <tool_call>
    <function=read_source>            (or, malformed, <read_source>)
    <parameter=source_id>
    SRC-002
    </parameter>
    </function>
    </tool_call>

or Hermes style  <tool_call>{"name": "read_source", "arguments": {...}}</tool_call>, or a bare JSON object in the text
(often in a ```json fence): {"tool": "resolve_target", "arguments": {...}}.
Only names of real tools are accepted; anything else stays text.
"""

import json
import re
import uuid
from typing import Any, Dict, Iterable, List, Tuple

_BLOCK = re.compile(r"<tool_call>\s*(.*?)\s*(?:</tool_call>|$)", re.S)
_PARAM = re.compile(r"<parameter=([A-Za-z_]\w*)>\s*\n?(.*?)\n?\s*</parameter>", re.S)


def _value(raw: str) -> Any:
    s = raw.strip()
    if s[:1] in "[{" or re.fullmatch(r"-?\d+(\.\d+)?|true|false|null", s):
        try:
            return json.loads(s)
        except ValueError:
            pass
    return raw.strip("\n")


_NAME_KEYS = ("name", "tool", "tool_name", "function")
_ARG_KEYS = ("arguments", "parameters", "args", "input")


def _call(name: str, args: Dict[str, Any]) -> Dict[str, Any]:
    return {"id": f"call_text_{uuid.uuid4().hex[:12]}", "type": "function", "function": {"name": name, "arguments": json.dumps(args)}}


def _bare_json_calls(content: str, names: set) -> Tuple[List[Dict[str, Any]], str]:
    """JSON objects in the text that are exactly a call of a real tool: {"tool"|"name": <tool>, "arguments": {...}}."""
    calls: List[Dict[str, Any]] = []
    spans: List[Tuple[int, int]] = []
    dec = json.JSONDecoder()
    i = content.find("{")
    while i != -1:
        try:
            obj, end = dec.raw_decode(content, i)
        except ValueError:
            i = content.find("{", i + 1)
            continue
        name = next((obj.get(k) for k in _NAME_KEYS if isinstance(obj, dict) and isinstance(obj.get(k), str)), None)
        args = next((obj.get(k) for k in _ARG_KEYS if isinstance(obj, dict) and k in obj), {}) if name else None
        if isinstance(args, str):
            try:
                args = json.loads(args)
            except ValueError:
                args = None
        if name in names and isinstance(args, dict) and set(obj) <= set(_NAME_KEYS) | set(_ARG_KEYS) | {"id", "type"}:
            calls.append(_call(name, args))
            spans.append((i, end))
        i = content.find("{", end)
    rest = content
    for a, b in reversed(spans):
        rest = rest[:a] + rest[b:]
    rest = re.sub(r"```(?:json)?\s*```", "", rest).strip() if calls else content
    return calls, rest


def parse_text_tool_calls(content: str, tool_names: Iterable[str]) -> Tuple[List[Dict[str, Any]], str]:
    """(calls in the OpenAI tool_calls shape, the text with the call blocks removed)."""
    names = set(tool_names)
    calls: List[Dict[str, Any]] = []
    if "<tool_call>" not in (content or ""):
        return _bare_json_calls(content or "", names)
    for m in _BLOCK.finditer(content):
        body = m.group(1)
        name, args = None, None
        if body.lstrip().startswith("{"):
            try:
                obj = json.loads(body[body.index("{"):body.rindex("}") + 1])
                name, args = obj.get("name"), obj.get("arguments") or obj.get("parameters") or {}
                if isinstance(args, str):
                    args = json.loads(args)
            except ValueError:
                continue
        else:
            head = re.match(r"\s*<(?:function=)?([A-Za-z_]\w*)\s*>", body)
            if head:
                name = head.group(1)
                args = {k: _value(v) for k, v in _PARAM.findall(body)}
        if name in names and isinstance(args, dict):
            calls.append(_call(name, args))
    rest = _BLOCK.sub("", content).strip() if calls else content
    return calls, rest

embedforge/agent/workspace.py:
"""Project workspace: real files on disk, sandboxed paths, versioned build outputs."""

import json
import re
import shutil
import threading
import time
import uuid
from pathlib import Path
from typing import Dict, List, Optional, Any

from embedforge.core.config import config
from embedforge.core.files import load_json, write_atomic

TEXT_EXTS = {
    ".c", ".h", ".cpp", ".hpp", ".cc", ".ino", ".ini", ".md", ".txt", ".json",
    ".py", ".s", ".ld", ".cmake", ".mmd", ".csv", ".yaml", ".yml", ".toml",
    ".sch", ".kicad_sch", ".kicad_pcb", ".brd", ".net",
    ".esch", ".enet", ".asc", ".tsv",  # EasyEDA Pro sheets/netlists, PADS netlists, BOMs
    ".mk",  # readable (generated Betaflight config.mk); the agent's write policy still forbids writing it
}
IMAGE_EXTS = {".png", ".jpg", ".jpeg", ".webp", ".svg", ".bmp", ".gif", ".ico"}
DOC_EXTS = {".pdf"}
ARCHIVE_EXTS = {".zip", ".epro", ".epro2"}
ALLOWED_EXTS = TEXT_EXTS | IMAGE_EXTS | DOC_EXTS | ARCHIVE_EXTS
HIDDEN_DIRS = {".pio", "sources", "builds", "__pycache__", ".git", ".vscode"}
MAX_FILE_BYTES = 400_000
MAX_UPLOAD_BYTES = 50_000_000


def workspace_root() -> Path:
    p = Path(config.workspace_root) / "workspace" / "projects"
    p.mkdir(parents=True, exist_ok=True)
    return p


class Project:
    def __init__(self, project_id: str, root: Path):
        self.id = project_id
        self.root = root
        for d in ("src", "include", "lib", "sources", "builds", "artifacts", "docs", "schematics"):
            (root / d).mkdir(parents=True, exist_ok=True)
        self._lock = threading.Lock()

    # ------------------------------------------------------------ meta
    @property
    def meta_path(self) -> Path:
        return self.root / "project.json"

    def meta(self) -> Dict[str, Any]:
        m = load_json(self.meta_path, None)
        return m if isinstance(m, dict) else {"id": self.id, "name": self.id, "created": time.time()}

    def update_meta(self, **kw) -> Dict[str, Any]:
        with self._lock:
            m = self.meta()
            m.update(kw)
            write_atomic(self.meta_path, json.dumps(m, indent=2))
        return m

    # ------------------------------------------------------------ files
    def safe_path(self, rel: str, allow_binary: bool = True) -> Path:
        rel = (rel or "").replace("\\", "/").lstrip("/")
        if not rel or ".." in Path(rel).parts:
            raise ValueError(f"Illegal path: {rel!r}")
        p = (self.root / rel).resolve()
        if self.root.resolve() not in p.parents and p != self.root.resolve():
            raise ValueError(f"Path escapes project: {rel!r}")
        top = Path(rel).parts[0]
        if top in HIDDEN_DIRS:
            raise ValueError(f"'{top}/' is managed by EmbedForge and cannot be edited directly.")
        valid_exts = ALLOWED_EXTS if allow_binary else TEXT_EXTS
        if p.suffix.lower() not in valid_exts and p.name not in ("platformio.ini",):
            raise ValueError(f"Unsupported file type: {p.suffix}")
        return p

    def write_file(self, rel: str, content: str) -> Dict[str, Any]:
        if len(content.encode("utf-8")) > MAX_FILE_BYTES:
            raise ValueError("File too large.")
        p = self.safe_path(rel, allow_binary=False)
        p.parent.mkdir(parents=True, exist_ok=True)
        existed = p.exists()
        write_atomic(p, content)
        return {"path": rel.replace("\\", "/"), "bytes": len(content.encode("utf-8")), "created": not existed}

    def write_bytes(self, rel: str, data: bytes) -> Dict[str, Any]:
        if len(data) > MAX_UPLOAD_BYTES:
            raise ValueError(f"File exceeds maximum upload limit ({MAX_UPLOAD_BYTES // 1_000_000} MB).")
        p = self.safe_path(rel, allow_binary=True)
        p.parent.mkdir(parents=True, exist_ok=True)
        existed = p.exists()
        p.write_bytes(data)
        return {"path": rel.replace("\\", "/"), "bytes": len(data), "created": not existed}

    def read_file(self, rel: str) -> str:
        p = self.safe_path(rel, allow_binary=False)
        if not p.is_file():
            raise FileNotFoundError(f"No such file: {rel}")
        return p.read_text(encoding="utf-8", errors="replace")

    def read_bytes(self, rel: str) -> bytes:
        p = self.safe_path(rel, allow_binary=True)
        if not p.is_file():
            raise FileNotFoundError(f"No such file: {rel}")
        return p.read_bytes()

    def list_files(self) -> List[Dict[str, Any]]:
        out = []
        for p in sorted(self.root.rglob("*")):
            if not p.is_file():
                continue
            rel = p.relative_to(self.root)
            if rel.parts[0] in HIDDEN_DIRS or rel.name in ("project.json", "conversation.json", "trace.jsonl", "ledger.json",
                                                           "board.json", "user_messages.jsonl", "verify_report.json"):
                continue
            suffix = p.suffix.lower()
            kind = ("image" if suffix in IMAGE_EXTS else "pdf" if suffix in DOC_EXTS
                    else "schematic" if suffix in {".sch", ".kicad_sch", ".kicad_pcb", ".brd", ".epro", ".epro2", ".esch"} else "text")
            out.append({"path": str(rel).replace("\\", "/"), "bytes": p.stat().st_size, "kind": kind})
        return out

    # ------------------------------------------------------------ conversation
    def load_conversation(self) -> List[Dict[str, Any]]:
        m = load_json(self.root / "conversation.json", [])
        return m if isinstance(m, list) else []

    def save_conversation(self, messages: List[Dict[str, Any]]) -> None:
        write_atomic(self.root / "conversation.json", json.dumps(messages, indent=1))

    def user_messages(self, seed: Optional[List[str]] = None) -> List[str]:
        """Everything the user has typed, append-only (the USER-tier source is built from this, never from the
        model-facing history, so harness notices can't become 'user statements')."""
        p = self.root / "user_messages.jsonl"
        if not p.exists():
            if not seed:
                return []
            with self._lock, open(p, "w", encoding="utf-8") as f:
                f.writelines(json.dumps({"t": None, "text": s}) + "\n" for s in seed)
        out = []
        for line in p.read_text(encoding="utf-8").splitlines():
            try:
                out.append(json.loads(line)["text"])
            except Exception:
                continue
        return out

    def append_user_message(self, text: str) -> None:
        with self._lock, open(self.root / "user_messages.jsonl", "a", encoding="utf-8") as f:
            f.write(json.dumps({"t": time.time(), "text": text}) + "\n")

    def trace(self, record: Dict[str, Any]) -> None:
        with self._lock, open(self.root / "trace.jsonl", "a", encoding="utf-8") as f:
            f.write(json.dumps({"t": time.time(), **record}, default=str) + "\n")

    def close_interrupted_run(self) -> bool:
        """A run whose server stopped mid-way (a run_start with no run_end): record it as interrupted, so the history is
        whole and 'continue' resumes from the conversation saved after its last step. Call only when no run is active.
        True when there was one."""
        p = self.root / "trace.jsonl"
        if not p.exists():
            return False
        open_run, steps = False, 0
        with open(p, encoding="utf-8") as f:
            for line in f:
                if '"event": "run_start"' in line:
                    open_run, steps = True, 0
                elif '"event": "run_end"' in line:
                    open_run = False
                elif open_run and '"results"' in line:
                    steps += 1
        if open_run:
            self.trace({"event": "run_end", "status": "interrupted", "steps": steps,
                        "next_step": "continue: the server stopped during this run; it resumes from its last saved step"})
        return open_run

    # ------------------------------------------------------------ builds
    def builds(self) -> List[Dict[str, Any]]:
        out = []
        for d in sorted((self.root / "builds").glob("v*"), key=lambda p: int(re.sub(r"\D", "", p.name) or 0)):
            mf = d / "manifest.json"
            if mf.exists():
                try:
                    out.append(json.loads(mf.read_text(encoding="utf-8")))
                except Exception:
                    pass
        return out

    def register_build(self, artifacts: Dict[str, str], manifest: Dict[str, Any]) -> Dict[str, Any]:
        n = len(self.builds()) + 1
        d = self.root / "builds" / f"v{n}"
        d.mkdir(parents=True, exist_ok=True)
        files = {}
        for kind, src in artifacts.items():
            dst = d / f"{self.meta().get('name', self.id)}_v{n}.{kind}".replace(" ", "_")
            shutil.copy2(src, dst)
            files[kind] = dst.name
        mf = {"version": n, "timestamp": time.time(), "files": files, **manifest}
        write_atomic(d / "manifest.json", json.dumps(mf, indent=2))
        return mf

    def build_file(self, version: int, kind: str) -> Optional[Path]:
        mf = self.root / "builds" / f"v{version}" / "manifest.json"
        if not mf.exists():
            return None
        data = json.loads(mf.read_text(encoding="utf-8"))
        name = data.get("files", {}).get(kind)
        return (self.root / "builds" / f"v{version}" / name) if name else None


class ProjectManager:
    @staticmethod
    def create(name: str = "") -> Project:
        pid = time.strftime("%Y%m%d-%H%M%S-") + uuid.uuid4().hex[:4]
        p = Project(pid, workspace_root() / pid)
        p.update_meta(id=pid, name=name or f"project-{pid[-4:]}", created=time.time())
        return p

    @staticmethod
    def open(project_id: str) -> Project:
        if not re.fullmatch(r"[A-Za-z0-9_-]+", project_id or ""):
            raise ValueError("Bad project id")
        root = workspace_root() / project_id
        if not root.is_dir():
            raise FileNotFoundError(project_id)
        return Project(project_id, root)

    @staticmethod
    def list() -> List[Dict[str, Any]]:
        out = []
        for d in sorted(workspace_root().iterdir(), reverse=True):
            if d.is_dir():
                try:
                    out.append(Project(d.name, d).meta())
                except Exception:
                    pass
        return out

embedforge/core/config.py:
"""Core configuration management for EmbedForge."""

import os
from pathlib import Path
from typing import Optional
from dotenv import load_dotenv
from pydantic import BaseModel, Field

# Automatically load .env if present
load_dotenv()

class EmbedForgeConfig(BaseModel):
    """System-wide configuration settings."""
    nebius_api_key: Optional[str] = Field(
        default_factory=lambda: os.getenv("NEBIUS_API_KEY")
    )
    nebius_base_url: str = Field(
        default_factory=lambda: os.getenv("NEBIUS_BASE_URL", "https://api.tokenfactory.nebius.com/v1")
    )
    nebius_model: str = Field(
        default_factory=lambda: os.getenv("NEBIUS_MODEL", "nvidia/Nemotron-3-Ultra-550b-a55b")
    )
    tavily_api_key: Optional[str] = Field(
        default_factory=lambda: os.getenv("TAVILY_API_KEY")
    )
    # advanced (2 credits): the most relevant chunks of each page, better on technical documents; basic: 1 credit
    tavily_search_depth: str = Field(default_factory=lambda: os.getenv("TAVILY_SEARCH_DEPTH", "advanced"))
    # Tavily searches and maps one run may make: past it the agent works from the sources it has
    tavily_max_calls: int = Field(default_factory=lambda: int(os.getenv("EMBEDFORGE_TAVILY_MAX_CALLS", "12")))
    agent_model: str = Field(
        # Ultra is the only Nemotron that produced correct firmware in our evals (Nano: 0 of 4)
        default_factory=lambda: os.getenv("NEBIUS_AGENT_MODEL") or os.getenv("NEBIUS_MODEL", "nvidia/Nemotron-3-Ultra-550b-a55b")
    )
    # Optional second provider: NVIDIA API catalog / NIM (OpenAI-compatible), https://build.nvidia.com
    nvidia_api_key: Optional[str] = Field(
        default_factory=lambda: os.getenv("NVIDIA_API_KEY")
    )
    nvidia_base_url: str = Field(
        default_factory=lambda: os.getenv("NVIDIA_BASE_URL", "https://integrate.api.nvidia.com/v1")
    )
    # the NVIDIA API names models its own way (Ultra's id from its build.nvidia.com example; the IDE's model picker lists
    # the rest, e.g. nvidia/nemotron-3-super-120b-a12b)
    nvidia_model: str = Field(default_factory=lambda: os.getenv("NVIDIA_MODEL", "nvidia/nemotron-3-ultra-550b-a55b"))
    # A self-hosted OpenAI-compatible server (vLLM / SGLang on a Nebius AI Cloud GPU VM, Ollama / llama.cpp locally):
    # used first when its base URL is set. The key is only needed if the server was started with one.
    selfhosted_base_url: str = Field(default_factory=lambda: os.getenv("SELFHOSTED_BASE_URL", "").strip())
    selfhosted_model: str = Field(default_factory=lambda: os.getenv("SELFHOSTED_MODEL", "nemotron-3-super"))
    selfhosted_api_key: str = Field(default_factory=lambda: os.getenv("SELFHOSTED_API_KEY", ""))
    # Anthropic Claude API (the SDK also reads ANTHROPIC_API_KEY itself; ANTHROPIC_AUTH_TOKEN works too)
    anthropic_api_key: Optional[str] = Field(
        default_factory=lambda: os.getenv("ANTHROPIC_API_KEY") or os.getenv("ANTHROPIC_AUTH_TOKEN")
    )
    anthropic_model: str = Field(
        default_factory=lambda: os.getenv("EMBEDFORGE_ANTHROPIC_MODEL", "claude-opus-5-5")
    )
    anthropic_effort: str = Field(   # low | medium | high | xhigh | max (Claude Opus 5.5 defaults to medium)
        default_factory=lambda: os.getenv("EMBEDFORGE_EFFORT", "high")
    )
    # Google Gemini API through its OpenAI-compatible endpoint (keys from Google AI Studio)
    gemini_api_key: Optional[str] = Field(
        default_factory=lambda: os.getenv("GEMINI_API_KEY") or os.getenv("GOOGLE_API_KEY")
    )
    gemini_base_url: str = Field(
        default_factory=lambda: os.getenv("GEMINI_BASE_URL", "https://generativelanguage.googleapis.com/v1beta/openai")
    )
    gemini_model: str = Field(   # on the free tier; gemini-3.1-pro-preview is paid-only
        default_factory=lambda: os.getenv("EMBEDFORGE_GEMINI_MODEL", "gemini-3.8-flash")
    )
    # Force one provider for every run: selfhosted | nebius | nvidia | anthropic | gemini (empty: the first configured,
    # in that order)
    llm_provider: str = Field(
        default_factory=lambda: os.getenv("EMBEDFORGE_PROVIDER", "").strip().lower()
    )
    # the vision model that transcribes datasheet figures (timing diagrams, mode transitions, tables drawn as images);
    # any OpenAI-compatible provider with image input: NVIDIA's Nemotron VL, Gemini, a self-hosted VLM
    vision_provider: str = Field(default_factory=lambda: os.getenv("EMBEDFORGE_VISION_PROVIDER", "nvidia").strip().lower())
    vision_model: str = Field(default_factory=lambda: os.getenv("EMBEDFORGE_VISION_MODEL", "nvidia/nemotron-3.5-super-vl-120b-a12b"))
    # the embedding model behind search_datasheet (semantic search over long datasheets): NVIDIA's Nemotron Embed
    embed_provider: str = Field(default_factory=lambda: os.getenv("EMBEDFORGE_EMBED_PROVIDER", "nvidia").strip().lower())
    embed_model: str = Field(default_factory=lambda: os.getenv("EMBEDFORGE_EMBED_MODEL", "nvidia/nemotron-3-embed-1b"))
    # an independent model call reviews the agent's 'implemented' / 'not applicable' claims about datasheet requirements
    claim_review: bool = Field(default_factory=lambda: os.getenv("EMBEDFORGE_CLAIM_REVIEW", "1") != "0")
    # cppcheck + MISRA C:2012 after each PlatformIO build (PlatformIO installs tool-cppcheck on first use)
    static_analysis: bool = Field(default_factory=lambda: os.getenv("EMBEDFORGE_STATIC_ANALYSIS", "1") != "0")
    # measure verification strength on each delivered driver (plant faults, count those verify catches)
    mutation_test: bool = Field(default_factory=lambda: os.getenv("EMBEDFORGE_MUTATION_TEST", "1") != "0")
    agent_max_steps: int = Field(
        default_factory=lambda: int(os.getenv("EMBEDFORGE_MAX_STEPS", "60"))
    )
    # Sampling for the agent LLM; empty = per-model default (reasoning models loop and repeat when run near-greedy)
    agent_temperature: Optional[float] = Field(
        default_factory=lambda: float(os.environ["EMBEDFORGE_TEMPERATURE"]) if os.getenv("EMBEDFORGE_TEMPERATURE") else None
    )
    agent_top_p: Optional[float] = Field(
        default_factory=lambda: float(os.environ["EMBEDFORGE_TOP_P"]) if os.getenv("EMBEDFORGE_TOP_P") else None
    )
    workspace_root: Path = Field(
        default_factory=lambda: Path(os.getenv("EMBEDFORGE_WORKSPACE", Path.cwd()))
    )
    # a hosted IDE asks for this password (HTTP Basic auth); required when EMBEDFORGE_HOST is not this machine
    server_password: str = Field(default_factory=lambda: os.getenv("EMBEDFORGE_PASSWORD", ""))
    temperature: float = 0.2
    max_tokens: int = 4096
    bounded_search_limit: int = 5

    @property
    def has_nebius(self) -> bool:
        return bool(self.nebius_api_key and len(self.nebius_api_key.strip()) > 0)

    @property
    def has_nvidia(self) -> bool:
        return bool(self.nvidia_api_key and self.nvidia_api_key.strip())

    @property
    def has_anthropic(self) -> bool:
        return bool(self.anthropic_api_key and self.anthropic_api_key.strip())

    @property
    def has_gemini(self) -> bool:
        return bool(self.gemini_api_key and self.gemini_api_key.strip())

    @property
    def has_selfhosted(self) -> bool:
        return bool(self.selfhosted_base_url)

    @property
    def has_llm(self) -> bool:
        return self.has_selfhosted or self.has_anthropic or self.has_gemini or self.has_nebius or self.has_nvidia

    @property
    def has_tavily(self) -> bool:
        return bool(self.tavily_api_key and len(self.tavily_api_key.strip()) > 0)

