embedforge/core/telemetry.py:
"""Observability and tracing integration for LangSmith and OpenTelemetry."""

import os
import time
import uuid
from typing import Dict, Any, Optional
from datetime import datetime, timezone
from pydantic import BaseModel, Field
from embedforge.core.logger import logger

class Span(BaseModel):
    id: str = Field(default_factory=lambda: str(uuid.uuid4()))
    name: str
    run_type: str = "chain" # "llm", "tool", "chain"
    inputs: Dict[str, Any] = Field(default_factory=dict)
    outputs: Dict[str, Any] = Field(default_factory=dict)
    start_time: float = Field(default_factory=time.time)
    end_time: Optional[float] = None
    metadata: Dict[str, Any] = Field(default_factory=dict)

class LangSmithTracer:
    """Telemetry tracer creating runs and exporting execution spans to LangSmith."""

    def __init__(self):
        self.api_key = os.getenv("LANGCHAIN_API_KEY")
        self.project = os.getenv("LANGCHAIN_PROJECT", "EmbedForge")
        self.endpoint = os.getenv("LANGCHAIN_ENDPOINT", "https://api.smith.langchain.com")
        self.tracing_enabled = os.getenv("LANGCHAIN_TRACING_V2", "false").lower() == "true" and bool(self.api_key)
        self.active_spans: Dict[str, Span] = {}
        self._client = None

        if self.tracing_enabled:
            try:
                from langsmith import Client
                self._client = Client(api_key=self.api_key, api_url=self.endpoint)
            except Exception as e:
                logger.log_event("LANGSMITH_WARN", f"Could not initialize LangSmith Client: {e}")

    def start_span(self, span_id: str, name: str, run_type: str = "chain", inputs: Dict[str, Any] = None, metadata: Dict[str, Any] = None) -> Span:
        span = Span(
            name=name,
            run_type=run_type,
            inputs=inputs or {},
            metadata=metadata or {}
        )
        self.active_spans[span_id] = span

        if self.tracing_enabled:
            logger.log_event("LANGSMITH", f"Started trace: [{name}] (Type: {run_type}) in project '{self.project}'")
            if self._client:
                try:
                    self._client.create_run(
                        id=span.id,
                        name=name,
                        run_type=run_type,
                        inputs=inputs or {},
                        project_name=self.project,
                        start_time=datetime.now(timezone.utc),
                        extra={"metadata": metadata or {}}
                    )
                except Exception as e:
                    self._failed(e, "start")

        return span

    def _failed(self, e: Exception, what: str) -> None:
        """A post that failed. Over quota or unauthorised, LangSmith refuses every later post too, and its client retries
        each one with back-off, on every agent step and tool call: stop tracing for this process instead (logged once)."""
        text = str(e)
        if any(s in text for s in ("429", "usage limit", "Too Many Requests", "401", "403", "Unauthorized", "Forbidden")):
            self.tracing_enabled = False
            logger.log_event("LANGSMITH_OFF", f"LangSmith refused a trace ({text[:160]}); tracing is off until the server "
                                              "restarts. Runs are unaffected; their trace.jsonl is complete.")
            return
        logger.log_event("LANGSMITH_ERR", f"Failed to post {what} run to LangSmith: {e}")

    def end_span(self, span_id: str, outputs: Dict[str, Any] = None) -> Optional[Span]:
        span = self.active_spans.pop(span_id, None)
        if span:
            span.end_time = time.time()
            span.outputs = outputs or {}
            duration_ms = (span.end_time - span.start_time) * 1000

            if self.tracing_enabled:
                logger.log_event("LANGSMITH", f"Completed trace: [{span.name}] (duration={duration_ms:.1f}ms)")
                if self._client:
                    try:
                        self._client.update_run(
                            run_id=span.id,
                            outputs=outputs or {},
                            end_time=datetime.now(timezone.utc)
                        )
                    except Exception as e:
                        self._failed(e, "end")

        return span

tracer = LangSmithTracer()

embedforge/eda/__init__.py:
"""EDA import: turn EasyEDA (Standard/Pro), Protel, PADS, KiCad netlists and BOMs into one Board.

Usage from the server: `detect(name, data)` to route an upload, then `rebuild_project_board(project)`
to merge every EDA file in the project into `board.json` + a quotable connectivity source.
"""

import io
import json
import re
import zipfile
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple

from embedforge.eda.board import Board
from embedforge.eda.bom import decode_text, looks_like_bom, parse_bom
from embedforge.eda.easyeda_std import is_easyeda_std, parse_easyeda_std
from embedforge.eda.netlists import parse_kicad, parse_pads, parse_protel

__all__ = ["Board", "detect", "parse", "FORMAT_LABELS", "EDA_EXTS", "EDA_DIR", "load_board", "rebuild_project_board", "BOARD_SOURCE_URL"]

EDA_EXTS = {".json", ".epro", ".epro2", ".zip", ".net", ".asc", ".csv", ".tsv", ".txt"}
BOARD_SOURCE_URL = "user://board"
FORMAT_LABELS = {
    "easyeda_std": "EasyEDA Standard schematic", "easyeda_pro": "EasyEDA Pro project",
    "protel": "Protel2 netlist", "pads": "PADS netlist", "kicad": "KiCad netlist", "bom": "BOM",
}
_NETLIST_KINDS = ("protel", "pads", "kicad")
_SCHEMATIC_KINDS = ("easyeda_std", "easyeda_pro")


def _zip_names(data: bytes) -> List[str]:
    try:
        with zipfile.ZipFile(io.BytesIO(data)) as z:
            return z.namelist()
    except zipfile.BadZipFile:
        return []


def detect(name: str, data: bytes) -> Optional[str]:
    """Identify an EDA export by content (extension is only a hint). Returns a key of FORMAT_LABELS or None."""
    n = name.lower()
    if data[:2] == b"PK":
        from embedforge.eda.easyeda_pro import is_pro_archive
        return "easyeda_pro" if is_pro_archive(_zip_names(data)) else None
    text = decode_text(data[:4_000_000])
    s = text.lstrip()
    if s.startswith("{"):
        try:
            doc = json.loads(text)
        except ValueError:
            doc = None
        if is_easyeda_std(doc):
            return "easyeda_std"
    if re.match(r"^[*!]PADS", s, re.I):
        return "pads"
    if s.startswith("(export"):
        return "kicad"
    if n.endswith((".net", ".txt")) and re.search(r"^\[\s*$", text, re.M) and re.search(r"^\(\s*$", text, re.M):
        return "protel"
    if n.endswith((".csv", ".tsv", ".txt")) and looks_like_bom(text):
        return "bom"
    return None


def parse(kind: str, name: str, data: bytes) -> Optional[Board]:
    if kind == "easyeda_std":
        return parse_easyeda_std(json.loads(decode_text(data)), name)
    if kind == "easyeda_pro":
        from embedforge.eda.easyeda_pro import parse_epro
        return parse_epro(data, name)
    text = decode_text(data)
    if kind == "protel":
        return parse_protel(text, name)
    if kind == "pads":
        return parse_pads(text, name)
    if kind == "kicad":
        return parse_kicad(text, name)
    if kind == "bom":
        return parse_bom(text, name)
    return None


# ------------------------------------------------------------------ project integration
EDA_DIR = "schematics"  # uploads only; the agent's write policy excludes it, so it cannot plant a fake board


def _eda_files(root: Path) -> List[Tuple[Path, str]]:
    base = root / EDA_DIR
    if not base.is_dir():
        return []
    out = []
    for p in sorted(base.rglob("*")):
        if not p.is_file() or p.suffix.lower() not in EDA_EXTS:
            continue
        if p.stat().st_size > 50_000_000:
            continue
        kind = detect(p.name, p.read_bytes())
        if kind:
            out.append((p, kind))
    return out


def build_board(root: Path, name: str = "board") -> Optional[Board]:
    files = _eda_files(root)
    if not files:
        return None
    order = {k: i for i, k in enumerate(_NETLIST_KINDS + _SCHEMATIC_KINDS + ("bom",))}
    files.sort(key=lambda f: order.get(f[1], 99))
    board = Board(name=name)
    for path, kind in files:
        rel = str(path.relative_to(root)).replace("\\", "/")
        try:
            part = parse(kind, rel, path.read_bytes())
        except Exception as e:  # a broken file must not hide the others
            board.warnings.append(f"{rel}: could not parse as {FORMAT_LABELS.get(kind, kind)} ({type(e).__name__}: {e})")
            continue
        if part is not None:
            board.merge(part)
    return board if board.parts else None


def load_board(root: Path) -> Optional[Board]:
    p = Path(root) / "board.json"
    if not p.exists():
        return None
    try:
        return Board.from_json(json.loads(p.read_text(encoding="utf-8")))
    except Exception:
        return None


def rebuild_project_board(root: Path, store: Any, name: str = "board") -> Optional[Dict[str, Any]]:
    """Merge all EDA files in the project, persist board.json and the quotable connectivity source."""
    root = Path(root)
    board = build_board(root, name)
    bp = root / "board.json"
    if board is None:
        if bp.exists():
            bp.unlink()
        return None
    bp.write_text(json.dumps(board.to_json(), indent=1), encoding="utf-8")
    src = store.add(BOARD_SOURCE_URL, f"Board connectivity ({name})", board.report(), kind="schematic", replace=True)
    return {**board.summary(), "source_id": src.id}

embedforge/eda/board.py:
"""Board connectivity model shared by every EDA importer (EasyEDA Standard/Pro, Protel, PADS, KiCad, BOM).

A Board is parts -> pins (number, name, net) plus nets -> nodes. Importers produce partial boards
(a netlist has connectivity but no pin names; a BOM has part numbers but no nets) and `merge`
combines them. `report()` renders a plain-text connectivity listing that is stored as a project
source, so the agent can quote wiring verbatim into the Fact Ledger like any datasheet line.
"""

import re
from dataclasses import dataclass, field, asdict
from typing import Any, Dict, List, Optional, Tuple

MCU_PREFIXES = (
    "STM32", "AT32", "GD32", "APM32", "CH32", "HK32", "MM32", "N32", "ESP32", "ESP8266", "RP20", "RP23",
    "NRF51", "NRF52", "NRF53", "ATMEGA", "ATTINY", "ATSAM", "SAMD", "PIC", "DSPIC", "MSP430", "EFM32", "EFR32",
    "LPC", "MK", "MKL", "S32", "TM4C", "CC26", "CC13", "R7F", "RA", "PY32", "CW32", "HC32", "BL6", "W806",
)


# Tool-generated names for unlabelled nets (EasyEDA, Altium, KiCad, ours) — never a conflict worth reporting.
_AUTO_NET = re.compile(r"^(NET_|Net-|Net\$|\$|N\$|NetU|Net[A-Z]+\d|unconnected-|\$\$)", re.I)


def natural_key(s: str) -> List[Any]:
    return [int(t) if t.isdigit() else t.lower() for t in re.split(r"(\d+)", str(s))]


@dataclass
class Pin:
    number: str
    name: str = ""
    net: str = ""


@dataclass
class Part:
    ref: str
    value: str = ""
    footprint: str = ""
    mpn: str = ""
    manufacturer: str = ""
    lcsc: str = ""
    pins: Dict[str, Pin] = field(default_factory=dict)

    def pin(self, number: str) -> Pin:
        number = str(number).strip()
        if number not in self.pins:
            self.pins[number] = Pin(number)
        return self.pins[number]

    @property
    def label(self) -> str:
        return self.mpn or self.value

    def is_mcu(self) -> bool:
        txt = re.sub(r"[^A-Z0-9]", "", f"{self.mpn} {self.value}".upper())
        return any(txt.startswith(p) for p in MCU_PREFIXES) and len(self.pins) >= 8


@dataclass
class Board:
    name: str = "board"
    parts: Dict[str, Part] = field(default_factory=dict)
    imported: List[Dict[str, str]] = field(default_factory=list)   # [{file, format}]
    warnings: List[str] = field(default_factory=list)

    # ------------------------------------------------------------------ building
    def part(self, ref: str) -> Part:
        ref = str(ref).strip()
        if ref not in self.parts:
            self.parts[ref] = Part(ref)
        return self.parts[ref]

    def connect(self, net: str, ref: str, pin: str, pin_name: str = "") -> None:
        p = self.part(ref).pin(pin)
        p.net = net
        if pin_name and not p.name:
            p.name = pin_name

    def nets(self) -> Dict[str, List[Tuple[str, str]]]:
        out: Dict[str, List[Tuple[str, str]]] = {}
        for part in self.parts.values():
            for pin in part.pins.values():
                if pin.net:
                    out.setdefault(pin.net, []).append((part.ref, pin.number))
        for nodes in out.values():
            nodes.sort(key=lambda n: (natural_key(n[0]), natural_key(n[1])))
        return dict(sorted(out.items(), key=lambda kv: natural_key(kv[0])))

    def merge(self, other: "Board") -> None:
        """Combine another partial board into this one; existing connectivity wins, gaps are filled."""
        for ref, op in other.parts.items():
            mine = self.part(ref)
            for attr in ("value", "footprint", "mpn", "manufacturer", "lcsc"):
                if getattr(op, attr) and not getattr(mine, attr):
                    setattr(mine, attr, getattr(op, attr))
            for num, opin in op.pins.items():
                p = mine.pin(num)
                if opin.name and not p.name:
                    p.name = opin.name
                if opin.net:
                    if not p.net or (_AUTO_NET.match(p.net) and not _AUTO_NET.match(opin.net)):
                        p.net = opin.net
                    elif p.net != opin.net and not _AUTO_NET.match(opin.net):
                        src = other.imported[-1]["file"] if other.imported else "another file"
                        self.warnings.append(f"{ref} pin {num}: net '{p.net}' here but '{opin.net}' in {src}")
        self.imported += other.imported
        self.warnings += other.warnings

    # ------------------------------------------------------------------ queries
    def mcus(self) -> List[Part]:
        found = [p for p in self.parts.values() if p.is_mcu()]
        if not found:
            ics = [p for p in self.parts.values() if p.ref.upper().startswith(("U", "IC")) and len(p.pins) >= 16]
            found = sorted(ics, key=lambda p: -len(p.pins))[:1]
        return sorted(found, key=lambda p: natural_key(p.ref))

    def node_label(self, ref: str, number: str) -> str:
        part = self.parts.get(ref)
        name = part.pins[number].name if part and number in part.pins else ""
        return f"{ref}.{number}" + (f" ({name})" if name and name != number else "")

    def pin_line(self, part: Part, pin: Pin, nets: Dict[str, List[Tuple[str, str]]]) -> str:
        head = f"{part.ref} pin {pin.number}" + (f" ({pin.name})" if pin.name and pin.name != pin.number else "")
        if not pin.net:
            return f"{head} -> not connected"
        others = [self.node_label(r, n) for r, n in nets.get(pin.net, []) if not (r == part.ref and n == pin.number)]
        return f"{head} -> net {pin.net}" + (f" -> {', '.join(others)}" if others else "")

    _STOP = {"ALL", "AND", "THE", "FOR", "WITH", "LIST", "PIN", "PINS", "NET", "NETS", "PART", "PARTS", "SHOW", "GET",
             "CONNECTED", "CONNECTIONS", "NUMBER", "NUMBERS", "NAME", "NAMES", "WIRING", "OF", "TO", "ON", "IN", "MCU"}

    def query(self, q: str, limit: int = 120) -> Dict[str, Any]:
        """Look up designators, nets, pin names or part numbers. Sentence-style queries ('U3 BMP388 pins') are split
        into identifier-like terms and the matches merged."""
        res = self._query_one(q, limit)
        if "error" not in res or not q.strip():
            return res
        terms = [t for t in re.findall(r"[A-Za-z0-9_+./\-]+", q)
                 if t.upper() not in self._STOP and (re.search(r"\d|_", t) or (t.isupper() and len(t) >= 3))]
        lines: List[str] = []
        parts: List[Dict[str, Any]] = []
        matched: List[str] = []
        for t in dict.fromkeys(terms):
            r = self._query_one(t, limit)
            if "error" in r:
                continue
            matched.append(t)
            lines += [ln for ln in r.get("lines", []) if ln not in lines]
            parts += ([r["part"]] if "part" in r else []) + r.get("parts", [])
        if not lines:
            return res
        return {"matched_terms": matched, "lines": lines[:limit], **({"parts": parts[:10]} if parts else {})}

    @staticmethod
    def _clip(line: str, width: int = 170) -> str:
        """Shorten very long lines (power nets) at a node boundary; the kept prefix is still verbatim source text."""
        if len(line) <= width:
            return line
        cut = line.rfind(", ", 0, width)
        return line[: cut if cut > 0 else width] + " …"

    def _part_lines(self, part: Part, nets: Dict[str, List[Tuple[str, str]]], limit: int) -> List[str]:
        connected = [self._clip(self.pin_line(part, pin, nets)) for pin in self._sorted_pins(part) if pin.net]
        loose = [f"{pin.number}" + (f" ({pin.name})" if pin.name and pin.name != pin.number else "")
                 for pin in self._sorted_pins(part) if not pin.net]
        out = connected[:limit]
        if loose:
            out.append(f"{part.ref} pins not connected: " + ", ".join(loose))
        return out

    def _query_one(self, q: str, limit: int = 120) -> Dict[str, Any]:
        nets = self.nets()
        qs = q.strip()
        qu = qs.upper()
        if not qs:
            return {"summary": self.summary()}
        net = next((n for n in nets if n.upper() == qu), None)
        if qs in self.parts or qu in {r.upper() for r in self.parts}:
            part = next(p for r, p in self.parts.items() if r.upper() == qu)
            res = {"part": self._part_dict(part), "lines": self._part_lines(part, nets, limit)}
            if net:  # a part and a net with the same name (test point 'Moto0' on net 'MOTO0'): show both
                res["net"] = net
                res["lines"] = [f"net {net}: " + ", ".join(self.node_label(r, n) for r, n in nets[net])] + res["lines"]
            return res
        if net:
            return {"net": net, "lines": [f"net {net}: " + ", ".join(self.node_label(r, n) for r, n in nets[net])]}
        lines = [self.pin_line(part, pin, nets) for part, pin in self._pins_named(qu)]
        if lines:
            return {"pin_name": qs, "lines": lines[:limit]}
        alias = next((rx for words, rx in self._FUNCTION_ALIASES if qu in words), None)
        hits = [p for p in self.parts.values() if qu and (qu in p.value.upper() or qu in p.mpn.upper() or qu in p.footprint.upper()
                                                         or (alias and re.search(alias, f"{p.value} {p.mpn}".upper())))]
        if hits:
            out = []
            for part in hits[:3]:
                out += self._part_lines(part, nets, limit)
            return {"parts": [self._part_dict(p) for p in hits[:10]], "lines": out[:limit]}
        fuzzy = [n for n in nets if qu in n.upper()]
        if not fuzzy and len(qu) >= 4:  # 'MOTOR' -> MOTO0..3, 'LEDS' -> LED1: match on a shared stem
            stem = qu[:4]
            fuzzy = [n for n in nets if stem in n.upper()]
        if fuzzy:
            return {"nets": fuzzy[:20], "lines": [f"net {n}: " + ", ".join(self.node_label(r, x) for r, x in nets[n]) for n in fuzzy[:20]]}
        mcu = self.mcus()[0] if self.mcus() else None
        example = next((p.name for p in (self._sorted_pins(mcu) if mcu else []) if p.name and p.net), "PA8")
        return {"error": f"Nothing on the board matches '{qs}'. Try a designator ({mcu.ref if mcu else 'U1'} lists every MCU "
                         f"pin), a net name, a pin name ({example}) or a part number.",
                "available_nets": sorted(nets)[:60]}

    # function words -> part-number patterns (so 'gyro' finds a BMI270 and 'baro' a BMP388)
    _FUNCTION_ALIASES = [
        ({"GYRO", "IMU", "ACCEL", "ACC", "ACCELEROMETER", "GYROSCOPE"}, r"BMI\d|ICM|MPU|LSM|BMX|LSM6"),
        ({"BARO", "BAROMETER", "PRESSURE"}, r"BMP\d|DPS\d|SPL\d|MS56|LPS\d|BME\d"),
        ({"FLASH", "BLACKBOX"}, r"W25|GD25|MX25|IS25|M25P|AT25"),
        ({"SD", "SDCARD", "MICROSD", "TF"}, r"\bSD\b|SD-CARD|MICRO\s*SD|TF"),
        ({"OSD"}, r"MAX7456|AT7456"),
        ({"MAG", "COMPASS", "MAGNETOMETER"}, r"QMC|HMC|IST\d|LIS3MDL|MMC"),
        ({"LED", "LEDS", "LED_STRIP", "WS2812", "RGB"}, r"WS2812|SK6812"),
    ]

    def _pins_named(self, qu: str) -> List[Tuple[Part, Pin]]:
        """Pins whose name is `qu` or has `qu` as one of its '_' or '/' separated tokens (GPIO43 -> GPIO43_ADC3). On an MCU
        whose pins are named GPIOn, PAn means GPIOn (Betaflight's RP2350 naming)."""
        alts = {qu}
        m = re.fullmatch(r"PA(\d{1,2})", qu)
        if m:
            alts.add(f"GPIO{int(m.group(1))}")
        out = []
        for part in self.parts.values():
            for pin in self._sorted_pins(part):
                name = (pin.name or "").upper()
                if name and (name in alts or alts & set(re.split(r"[_/]", name))):
                    out.append((part, pin))
        return out

    def gpio_net(self, gpio: int) -> Tuple[str, List[str]]:
        """(net, other part refs on it) for the MCU's GPIO n; ('', []) when it is not connected or not found."""
        refs = {m.ref for m in self.mcus()}
        for part, pin in self._pins_named(f"GPIO{int(gpio)}"):
            if part.ref in refs and pin.net:
                return pin.net, sorted({r for r, _ in self.nets().get(pin.net, []) if r != part.ref})
        return "", []

    def mcu_pin_lines(self, gpio: int) -> List[str]:
        """Connectivity line(s) of the MCU pin for GPIO n (exact report text, so it can be quoted)."""
        nets = self.nets()
        refs = {m.ref for m in self.mcus()}
        return [self.pin_line(part, pin, nets) for part, pin in self._pins_named(f"GPIO{int(gpio)}") if part.ref in refs]

    # ------------------------------------------------------------------ rendering
    @staticmethod
    def _sorted_pins(part: Part) -> List[Pin]:
        return sorted(part.pins.values(), key=lambda p: natural_key(p.number))

    @staticmethod
    def _part_dict(p: Part) -> Dict[str, Any]:
        return {"ref": p.ref, "value": p.value, "footprint": p.footprint, "mpn": p.mpn, "manufacturer": p.manufacturer,
                "lcsc": p.lcsc, "pin_count": len(p.pins), "is_mcu": p.is_mcu()}

    def summary(self) -> Dict[str, Any]:
        nets = self.nets()
        return {
            "name": self.name, "parts": len(self.parts), "nets": len(nets),
            "mcus": [self._part_dict(p) for p in self.mcus()],
            "ics": [self._part_dict(p) for p in sorted(self.parts.values(), key=lambda p: natural_key(p.ref))
                    if p.ref.upper().startswith(("U", "IC", "Q", "J", "P", "CN"))][:40],
            "imported": self.imported, "warnings": self.warnings[:20],
            "pin_names_known": any(pin.name for p in self.parts.values() for pin in p.pins.values()),
        }

    def report(self) -> str:
        """Plain-text connectivity listing; every line is a quotable fact about the user's wiring."""
        nets = self.nets()
        lines = [f"Board connectivity: {self.name}",
                 "Imported from: " + ", ".join(f"{i['file']} ({i['format']})" for i in self.imported),
                 f"Parts: {len(self.parts)}  Nets: {len(nets)}", ""]
        mcu_refs = {p.ref for p in self.mcus()}
        ordered = sorted(self.parts.values(), key=lambda p: (p.ref not in mcu_refs, natural_key(p.ref)))
        for part in ordered:
            desc = " ".join(x for x in (part.label, f"[{part.footprint}]" if part.footprint else "", "(MCU)" if part.ref in mcu_refs else "") if x)
            lines.append(f"== {part.ref} {desc}".rstrip())
            if part.manufacturer or part.lcsc:
                lines.append(f"{part.ref} manufacturer: {part.manufacturer or '-'}  supplier part: {part.lcsc or '-'}")
            lines += [self.pin_line(part, pin, nets) for pin in self._sorted_pins(part)]
            lines.append("")
        lines.append("== Nets")
        lines += [f"net {n}: " + ", ".join(self.node_label(r, x) for r, x in nodes) for n, nodes in nets.items()]
        if self.warnings:
            lines += ["", "== Import warnings"] + self.warnings[:50]
        return "\n".join(lines) + "\n"

    def to_json(self) -> Dict[str, Any]:
        return {"name": self.name, "imported": self.imported, "warnings": self.warnings,
                "parts": {r: {**self._part_dict(p), "pins": [asdict(x) for x in self._sorted_pins(p)]}
                          for r, p in sorted(self.parts.items(), key=lambda kv: natural_key(kv[0]))},
                "nets": {n: [list(x) for x in v] for n, v in self.nets().items()}}

    @classmethod
    def from_json(cls, d: Dict[str, Any]) -> "Board":
        b = cls(name=d.get("name", "board"), imported=d.get("imported", []), warnings=d.get("warnings", []))
        for ref, pd in (d.get("parts") or {}).items():
            part = b.part(ref)
            for attr in ("value", "footprint", "mpn", "manufacturer", "lcsc"):
                setattr(part, attr, pd.get(attr, "") or "")
            for pin in pd.get("pins", []):
                part.pins[str(pin["number"])] = Pin(str(pin["number"]), pin.get("name", ""), pin.get("net", ""))
        return b

embedforge/eda/bom.py:
"""BOM parser (EasyEDA Standard/Pro, JLCPCB, KiCad, generic CSV/TSV) -> part numbers per designator."""

import csv
import io
import re
from typing import Dict, List, Optional

from embedforge.eda.board import Board

_ALIASES = {
    "ref": ("designator", "designators", "reference", "references", "ref", "refs", "refdes", "part reference"),
    "value": ("name", "value", "comment", "description", "device"),
    "footprint": ("footprint", "package", "pcb footprint", "jlcpcb footprint"),
    "mpn": ("manufacturer part", "manufacturer part number", "mpn", "mfr part", "mfr. part #", "mfr.part #", "part number", "bom_manufacturer part"),
    "manufacturer": ("manufacturer", "mfr", "mfr.", "bom_manufacturer"),
    "lcsc": ("supplier part", "lcsc", "lcsc part", "lcsc part #", "lcsc part number", "jlcpcb part #", "bom_supplier part"),
}


def decode_text(data: bytes) -> str:
    """EasyEDA Standard exports its BOM as UTF-16 (tab-separated) despite the .csv extension."""
    if data[:2] in (b"\xff\xfe", b"\xfe\xff"):
        return data.decode("utf-16", errors="replace")
    if data[:3] == b"\xef\xbb\xbf":
        return data[3:].decode("utf-8", errors="replace")
    if len(data) > 4 and data[1:2] == b"\x00" and data[3:4] == b"\x00":
        return data.decode("utf-16-le", errors="replace")
    return data.decode("utf-8", errors="replace")


def _columns(header: List[str]) -> Dict[str, int]:
    norm = [re.sub(r"\s+", " ", h.strip().strip('"').lower()) for h in header]
    cols: Dict[str, int] = {}
    for key, names in _ALIASES.items():
        for i, h in enumerate(norm):
            if h in names and key not in cols and i not in cols.values():
                cols[key] = i
    return cols


def looks_like_bom(text: str) -> bool:
    head = text.lstrip("﻿").split("\n", 1)[0].lower()
    return any(k in head for k in ("designator", "reference", "refdes")) and any(
        k in head for k in ("footprint", "package", "manufacturer", "value", "name", "comment", "quantity", "qty"))


def parse_bom(text: str, filename: str = "bom.csv") -> Optional[Board]:
    text = text.lstrip("﻿")
    first = text.split("\n", 1)[0]
    delim = "\t" if first.count("\t") >= max(1, first.count(",")) else ";" if first.count(";") > first.count(",") else ","
    rows = list(csv.reader(io.StringIO(text), delimiter=delim))
    if not rows:
        return None
    cols = _columns(rows[0])
    if "ref" not in cols:
        return None
    b = Board(imported=[{"file": filename, "format": "BOM"}])
    for row in rows[1:]:
        if len(row) <= cols["ref"]:
            continue
        refs = [r for r in re.split(r"[,\s;]+", row[cols["ref"]].strip()) if r]
        for ref in refs:
            part = b.part(ref)
            for key in ("value", "footprint", "mpn", "manufacturer", "lcsc"):
                if key in cols and cols[key] < len(row):
                    setattr(part, key, row[cols[key]].strip())
    return b if b.parts else None

embedforge/eda/easyeda_pro.py:
"""EasyEDA Pro project importer: V2 `.epro` (zip of JSON-array lines) and V3 `.epro2` (zip with a `.epru` log).

Both versions are normalised into the same intermediate form (symbols, devices, pages of components and
wires) and then connected by one routine. The rules below reproduced the PCB pad nets of real sample
projects (KiCad QA data) exactly:

- a placed pin's connection point is the symbol PIN x/y, rotated counter-clockwise, mirrored on X, then
  translated to the component; V2 uses a y-up axis, V3 a y-down axis;
- every polyline/LINE of one WIRE is one node; wires and pins connect where vertices coincide;
- a wire's name is its `NET` attribute; power flags (symbol type 18) and net ports (19) name their pin;
- equal names connect across all pages; Short symbols (22) merge their nets, alphabetically lowest name wins;
- unnamed nets are named like EasyEDA does: "$" + page + "N" + wire number.

References: https://prodocs.easyeda.com/en/format/index , KiCad eeschema/sch_io/easyedapro.
"""

import io
import json
import math
import re
import zipfile
from collections import defaultdict
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Tuple

from embedforge.eda.board import Board
from embedforge.eda.easyeda_std import _DSU

SYM_NORMAL, SYM_BLOCK, SYM_FLAG, SYM_PORT, SYM_FRAME, SYM_SHORT = 2, 17, 18, 19, 20, 22
Point = Tuple[float, float]


@dataclass
class _Symbol:
    type: int = SYM_NORMAL
    parts: Dict[str, List[Tuple[str, float, float]]] = field(default_factory=lambda: defaultdict(list))
    part_titles: Dict[str, str] = field(default_factory=dict)   # V3: PART title -> PART id
    pin_num: Dict[str, str] = field(default_factory=dict)
    pin_name: Dict[str, str] = field(default_factory=dict)
    root: Dict[str, str] = field(default_factory=dict)

    def pins_for(self, part: str) -> List[Tuple[str, float, float]]:
        if part in self.parts:
            return self.parts[part]
        if part in self.part_titles and self.part_titles[part] in self.parts:
            return self.parts[self.part_titles[part]]
        return next(iter(self.parts.values())) if len(self.parts) == 1 else []


@dataclass
class _Comp:
    id: str
    part: str
    x: float
    y: float
    rot: float
    mirror: bool


@dataclass
class _Page:
    number: int
    comps: List[_Comp] = field(default_factory=list)
    wires: Dict[str, List[Point]] = field(default_factory=lambda: defaultdict(list))
    attrs: Dict[str, Dict[str, Any]] = field(default_factory=lambda: defaultdict(dict))  # parentId -> {key: value}


@dataclass
class _Project:
    version: str
    symbols: Dict[str, _Symbol] = field(default_factory=dict)
    devices: Dict[str, Dict[str, Any]] = field(default_factory=dict)
    footprints: Dict[str, str] = field(default_factory=dict)
    schematics: List[Tuple[str, List[_Page]]] = field(default_factory=list)


# ------------------------------------------------------------------ entry points
def is_pro_archive(names: List[str]) -> bool:
    has_v2 = any(n.endswith("project.json") for n in names) and any(n.endswith(".esch") for n in names)
    has_v3 = any(n.endswith(".epru") for n in names)
    return has_v2 or has_v3


def parse_epro(data: bytes, filename: str = "project.epro") -> Board:
    with zipfile.ZipFile(io.BytesIO(data)) as z:
        names = z.namelist()
        if any(n.endswith(".epru") for n in names):
            proj = _load_v3(z, names)
        else:
            proj = _load_v2(z, names)
    label = "EasyEDA Pro project" + (" (V3)" if proj.version == "v3" else "")
    boards = [_connect(proj, title, pages, filename, label) for title, pages in proj.schematics]
    boards = [b for b in boards if b.parts]
    if not boards:
        b = Board(imported=[{"file": filename, "format": label}])
        b.warnings.append(f"{filename}: no schematic components found")
        return b
    boards.sort(key=lambda b: -len(b.parts))
    best = boards[0]
    if len(boards) > 1:
        best.warnings.append(f"{filename} has {len(boards)} schematics; imported '{best.name}' (most parts). Others: "
                             + ", ".join(b.name for b in boards[1:]))
    return best


# ------------------------------------------------------------------ V2 (.epro)
def _json_lines(text: str) -> List[List[Any]]:
    out = []
    for line in text.splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            rec = json.loads(line)
        except ValueError:
            continue
        if isinstance(rec, list) and rec:
            out.append(rec)
    return out


def _load_v2(z: zipfile.ZipFile, names: List[str]) -> _Project:
    pj = next(n for n in names if n.endswith("project.json"))
    prefix = pj[: -len("project.json")]
    prj = json.loads(z.read(pj).decode("utf-8"))
    proj = _Project("v2")
    for uuid, dev in (prj.get("devices") or {}).items():
        proj.devices[uuid] = {**(dev.get("attributes") or {}), "_title": dev.get("title", "")}
    for uuid, fp in (prj.get("footprints") or {}).items():
        proj.footprints[uuid] = fp.get("title", "") if isinstance(fp, dict) else str(fp)
    for n in names:
        if n.startswith(prefix + "SYMBOL/") and n.endswith(".esym"):
            proj.symbols[n.rsplit("/", 1)[-1][:-5]] = _v2_symbol(_json_lines(z.read(n).decode("utf-8")))
    for suuid, sch in (prj.get("schematics") or {}).items():
        pages = []
        for sheet in sch.get("sheets") or []:
            path = f"{prefix}SHEET/{suuid}/{sheet.get('id')}.esch"
            if path in names:
                pages.append(_v2_page(int(sheet.get("id") or len(pages) + 1), _json_lines(z.read(path).decode("utf-8"))))
        if pages:
            proj.schematics.append((sch.get("name") or suuid, pages))
    return proj


def _v2_symbol(recs: List[List[Any]]) -> _Symbol:
    s = _Symbol()
    cur = ""
    for r in recs:
        if r[0] == "HEAD" and isinstance(r[1], dict):
            s.type = int(r[1].get("symbolType", SYM_NORMAL) or SYM_NORMAL)
        elif r[0] == "PART":
            cur = r[1]
        elif r[0] == "PIN" and len(r) > 5:
            s.parts[cur].append((r[1], float(r[4]), float(r[5])))
        elif r[0] == "ATTR" and len(r) > 4:
            _symbol_attr(s, r[2], r[3], r[4])
    return s


def _v2_page(number: int, recs: List[List[Any]]) -> _Page:
    page = _Page(number)
    for r in recs:
        if r[0] == "COMPONENT" and len(r) > 6:
            page.comps.append(_Comp(r[1], r[2] or "", float(r[3]), float(r[4]), float(r[5] or 0), bool(r[6])))
        elif r[0] == "WIRE" and len(r) > 2:
            for poly in r[2] or []:
                page.wires[r[1]] += [(float(poly[i]), float(poly[i + 1])) for i in range(0, len(poly) - 1, 2)]
        elif r[0] == "ATTR" and len(r) > 4:
            page.attrs[r[2]][r[3]] = r[4]
    return page


# ------------------------------------------------------------------ V3 (.epro2)
def _epru_docs(text: str) -> Dict[Tuple[str, str], Dict[Tuple[str, str], Tuple[Dict[str, Any], Any]]]:
    """(docType, uuid) -> {(rowType, rowId): (outer, inner)}, keeping the highest ticket and dropping tombstones."""
    docs: Dict[Tuple[str, str], Dict[Tuple[str, str], Tuple[Dict[str, Any], Any]]] = {}
    cur: Optional[Dict[Tuple[str, str], Tuple[Dict[str, Any], Any]]] = None
    for raw in text.splitlines():
        line = raw.rstrip("\r\n")
        if not line:
            continue
        if line.endswith("|"):
            line = line[:-1]
        i = line.find("||")
        if i < 0:
            continue
        try:
            outer = json.loads(line[:i])
            rest = line[i + 2:]
            inner = json.loads(rest) if rest.strip() else None
        except ValueError:
            continue
        if outer.get("type") == "DOCHEAD":
            if isinstance(inner, dict):
                cur = docs.setdefault((inner.get("docType", ""), inner.get("uuid", "")), {})
            continue
        if cur is None:
            continue
        key = (outer.get("type"), outer.get("id"))
        old = cur.get(key)
        if old is None or (outer.get("ticket") or 0) >= (old[0].get("ticket") or 0):
            cur[key] = (outer, inner)
    return {k: {rk: rv for rk, rv in rows.items() if rv[1] not in (None, "")} for k, rows in docs.items()}


def _rows(doc: Dict[Tuple[str, str], Tuple[Dict[str, Any], Any]], t: str) -> List[Tuple[Dict[str, Any], Dict[str, Any]]]:
    return [(o, i) for (tt, _), (o, i) in doc.items() if tt == t and isinstance(i, dict)]


def _meta(doc: Dict[Tuple[str, str], Tuple[Dict[str, Any], Any]]) -> Dict[str, Any]:
    rows = _rows(doc, "META")
    return rows[0][1] if rows else {}


def _load_v3(z: zipfile.ZipFile, names: List[str]) -> _Project:
    epru = next(n for n in names if n.endswith(".epru"))
    docs = _epru_docs(z.read(epru).decode("utf-8", errors="replace"))
    proj = _Project("v3")
    sch_titles: Dict[str, str] = {}
    pages_by_sch: Dict[str, List[_Page]] = defaultdict(list)
    for (dtype, uuid), doc in docs.items():
        meta = _meta(doc)
        if dtype == "SYMBOL":
            s = _Symbol(type=int(meta.get("docType", SYM_NORMAL) or SYM_NORMAL))
            for o, i in _rows(doc, "PART"):
                if i.get("title"):
                    s.part_titles[i["title"]] = o.get("id")
            for o, i in _rows(doc, "PIN"):
                s.parts[i.get("partId") or ""].append((o.get("id"), float(i.get("x") or 0), float(i.get("y") or 0)))
            for o, i in _rows(doc, "ATTR"):
                _symbol_attr(s, i.get("parentId"), i.get("key"), i.get("value"))
            proj.symbols[uuid] = s
        elif dtype == "DEVICE":
            proj.devices[uuid] = {**(meta.get("attributes") or {}), "_title": meta.get("title", "")}
        elif dtype == "FOOTPRINT":
            proj.footprints[uuid] = meta.get("title", "")
        elif dtype == "SCH":
            sch_titles[uuid] = meta.get("title", "")
        elif dtype == "SCH_PAGE":
            page = _Page(int(meta.get("zIndex") or len(pages_by_sch[meta.get("schematic", "")]) + 1))
            for o, i in _rows(doc, "COMPONENT"):
                page.comps.append(_Comp(o.get("id"), i.get("partId") or "", float(i.get("x") or 0), float(i.get("y") or 0),
                                        float(i.get("rotation") or 0), bool(i.get("isMirror"))))
            for o, i in _rows(doc, "WIRE"):
                page.wires.setdefault(o.get("id"), [])
            for o, i in _rows(doc, "LINE"):
                g = i.get("lineGroup")
                if g:
                    page.wires[g] += [(float(i.get("startX") or 0), float(i.get("startY") or 0)),
                                      (float(i.get("endX") or 0), float(i.get("endY") or 0))]
            for o, i in _rows(doc, "ATTR"):
                page.attrs[i.get("parentId")][i.get("key")] = i.get("value")
            pages_by_sch[meta.get("schematic", "")].append(page)
    for suuid, pages in pages_by_sch.items():
        proj.schematics.append((sch_titles.get(suuid) or suuid or "schematic", sorted(pages, key=lambda p: p.number)))
    return proj


# ------------------------------------------------------------------ shared
def _symbol_attr(s: _Symbol, parent: Any, key: Any, value: Any) -> None:
    if value is None:
        return
    if key in ("NUMBER", "Pin Number"):
        s.pin_num[parent] = str(value)
    elif key in ("NAME", "Pin Name"):
        s.pin_name[parent] = str(value)
    elif parent in ("", None):
        s.root[key] = str(value)


def _xf(px: float, py: float, c: _Comp, y_down: bool) -> Point:
    a = math.radians(c.rot or 0)
    cos, sin = math.cos(a), math.sin(a)
    if y_down:
        x, y = px * cos + py * sin, -px * sin + py * cos
    else:
        x, y = px * cos - py * sin, px * sin + py * cos
    if c.mirror:
        x = -x
    return (round(x + c.x, 3), round(y + c.y, 3))


def _resolve(value: Any, *scopes: Dict[str, Any]) -> str:
    """Resolve '={Attr}' / '={@Attr}' variables against the given attribute scopes."""
    v = "" if value is None else str(value)
    m = re.fullmatch(r"=\{@?([^}]+)\}", v.strip())
    if m:
        for sc in scopes:
            if sc.get(m.group(1)) not in (None, ""):
                return str(sc[m.group(1)])
        return ""
    return v


def _first(*vals: Any) -> str:
    for v in vals:
        if v not in (None, ""):
            return str(v)
    return ""


def _connect(proj: _Project, title: str, pages: List[_Page], filename: str, label: str) -> Board:
    b = Board(name=title, imported=[{"file": filename, "format": label}])
    y_down = proj.version == "v3"
    dsu = _DSU()
    names: Dict[Any, set] = defaultdict(set)
    wire_num: Dict[Any, Tuple[int, int]] = {}
    pin_nodes: Dict[Any, Tuple[str, str, str]] = {}   # node -> (ref, number, name)
    shorted: List[Any] = []
    missing_symbols = 0

    for page in pages:
        at_point: Dict[Point, List[Any]] = defaultdict(list)
        for wid, pts in page.wires.items():
            node = ("w", page.number, wid)
            dsu.find(node)
            m = re.search(r"\d+", str(wid))
            wire_num[node] = (page.number, int(m.group()) if m else 0)
            net = page.attrs.get(wid, {}).get("NET")
            if net:
                names[node].add(str(net))
            for p in pts:
                at_point[(round(p[0], 3), round(p[1], 3))].append(node)

        for c in page.comps:
            a = page.attrs.get(c.id, {})
            dev = proj.devices.get(a.get("Device") or "", {})
            sym = proj.symbols.get(a.get("Symbol") or dev.get("Symbol") or "")
            if sym is None:
                if a.get("Designator"):
                    missing_symbols += 1
                continue
            if sym.type in (SYM_FRAME, SYM_BLOCK):
                continue
            pins = sym.pins_for(c.part)
            nodes = []
            ref = _resolve(a.get("Designator"), dev) if sym.type == SYM_NORMAL else ""
            for pid, px, py in pins:
                node = ("p", page.number, c.id, pid)
                dsu.find(node)
                nodes.append(node)
                at_point[_xf(px, py, c, y_down)].append(node)
                if sym.type == SYM_FLAG:
                    nm = _first(a.get("Global Net Name"), a.get("Name"), dev.get("Global Net Name"), dev.get("Name"), sym.root.get("Global Net Name"))
                    if nm:
                        names[node].add(_resolve(nm, dev))
                elif sym.type == SYM_PORT:
                    if a.get("Name"):
                        names[node].add(_resolve(a.get("Name"), dev))
                elif ref:
                    ov = page.attrs.get(c.id + pid) or page.attrs.get(f"{c.id}-{pid}") or {}
                    if str(ov.get("NO_CONNECT", "")).lower() == "yes":
                        continue
                    num = _first(ov.get("NUMBER"), ov.get("Pin Number"), sym.pin_num.get(pid), pid)
                    nm = _first(ov.get("NAME"), ov.get("Pin Name"), sym.pin_name.get(pid))
                    pin_nodes[node] = (ref, num, nm)
            if sym.type == SYM_SHORT and nodes:
                for n in nodes[1:]:
                    dsu.union(nodes[0], n)
                shorted.append(nodes[0])
            if ref:
                part = b.part(ref)
                fp = proj.footprints.get(a.get("Footprint") or dev.get("Footprint") or "", "")
                part.value = part.value or _resolve(_first(a.get("Value"), a.get("Name"), dev.get("Value"), dev.get("Name"), dev.get("_title")), dev)
                part.footprint = part.footprint or fp
                part.mpn = part.mpn or _resolve(_first(a.get("Manufacturer Part"), dev.get("Manufacturer Part")), dev)
                part.manufacturer = part.manufacturer or _resolve(_first(a.get("Manufacturer"), dev.get("Manufacturer")), dev)
                part.lcsc = part.lcsc or _resolve(_first(a.get("Supplier Part"), dev.get("Supplier Part"), dev.get("LCSC Part Name")), dev)

        for nodes_here in at_point.values():
            for n in nodes_here[1:]:
                dsu.union(nodes_here[0], n)

    for node, ns in names.items():
        for nm in ns:
            dsu.union(node, ("name", nm))

    groups: Dict[Any, Dict[str, Any]] = defaultdict(lambda: {"pins": [], "names": set(), "wires": [], "short": False})
    for node, ns in names.items():
        groups[dsu.find(node)]["names"] |= ns
    for node, num in wire_num.items():
        groups[dsu.find(node)]["wires"].append(num)
    for node, info in pin_nodes.items():
        groups[dsu.find(node)]["pins"].append(info)
    for node in shorted:
        groups[dsu.find(node)]["short"] = True

    for g in groups.values():
        if not g["pins"]:
            continue
        if g["names"]:
            ordered = sorted(g["names"])
            net = ordered[0]
            if len(ordered) > 1 and not g["short"]:
                b.warnings.append(f"Pins joined under several net names {ordered}; using '{net}'")
        elif len(g["pins"]) >= 2 and g["wires"]:
            page_no, num = min(g["wires"])
            net = f"${page_no}N{num}"
        elif len(g["pins"]) >= 2:
            ref, num, _ = sorted(g["pins"])[0]
            net = f"NET_{ref}_{num}"
        else:
            net = ""  # a pin touching nothing else has no net (matches EasyEDA's PCB)
        for ref, num, nm in g["pins"]:
            pin = b.part(ref).pin(num)
            if nm and not pin.name:
                pin.name = nm
            if net:
                pin.net = net
    if missing_symbols:
        b.warnings.append(f"{missing_symbols} component(s) reference symbols missing from the archive")
    return b

embedforge/eda/easyeda_std.py:
"""EasyEDA Standard schematic source (.json) importer.

Format reference: https://docs.easyeda.com/en/DocumentFormat/2-EasyEDA-Schematic-File-Format/
Shapes are '~'-separated strings; a component ("LIB") holds its pins/texts after '#@$' separators and
pin sub-fields are split by '^^'. Child shapes are stored in absolute sheet coordinates (KiCad's importer
subtracts the LIB origin to build its symbols). Connectivity is geometric: wire vertices, pin end-points, net labels
("N") and net flags/power ports ("F") that share a coordinate (or touch a wire segment) are one net;
equally named labels/flags join nets across the whole design.
"""

import json
from typing import Any, Dict, Iterable, List, Optional, Tuple

from embedforge.eda.board import Board

Point = Tuple[int, int]
TOL = 1  # coordinates are compared in 1/10 units


def _pt(x: str, y: str) -> Optional[Point]:
    try:
        return (round(float(x) * 10), round(float(y) * 10))
    except (TypeError, ValueError):
        return None


class _DSU:
    def __init__(self) -> None:
        self.p: Dict[Any, Any] = {}

    def find(self, a: Any) -> Any:
        self.p.setdefault(a, a)
        while self.p[a] != a:
            self.p[a] = self.p[self.p[a]]
            a = self.p[a]
        return a

    def union(self, a: Any, b: Any) -> None:
        ra, rb = self.find(a), self.find(b)
        if ra != rb:
            self.p[ra] = rb


def _on_segment(p: Point, a: Point, b: Point) -> bool:
    (px, py), (ax, ay), (bx, by) = p, a, b
    if not (min(ax, bx) - TOL <= px <= max(ax, bx) + TOL and min(ay, by) - TOL <= py <= max(ay, by) + TOL):
        return False
    cross = (bx - ax) * (py - ay) - (by - ay) * (px - ax)
    seg_len = max(abs(bx - ax), abs(by - ay), 1)
    return abs(cross) <= TOL * seg_len


def _attrs(s: str) -> Dict[str, str]:
    parts = s.split("`")
    return {parts[i]: parts[i + 1] for i in range(0, len(parts) - 1, 2)}


def _sheets(doc: Dict[str, Any]) -> Iterable[Tuple[str, Dict[str, Any]]]:
    """Yield (title, sheet) for a single sheet, a multi-sheet schematic or a project export."""
    def as_dict(x: Any) -> Dict[str, Any]:
        if isinstance(x, str):
            try:
                return json.loads(x)
            except ValueError:
                return {}
        return x if isinstance(x, dict) else {}

    if isinstance(doc.get("schematics"), list):
        for i, s in enumerate(doc["schematics"]):
            s = as_dict(s)
            yield s.get("title") or f"sheet{i + 1}", as_dict(s.get("dataStr")) or s
        return
    if "dataStr" in doc and not doc.get("shape"):
        inner = as_dict(doc["dataStr"])
        if inner:
            yield from _sheets(inner)
            return
    yield doc.get("title", "sheet1"), doc


def is_easyeda_std(doc: Any) -> bool:
    if not isinstance(doc, dict):
        return False
    if isinstance(doc.get("schematics"), list):
        return True
    head = doc.get("head")
    has_shapes = any(k.startswith("shape") for k in doc)
    return has_shapes and (isinstance(head, (str, dict)) or "canvas" in doc)


def parse_easyeda_std(doc: Dict[str, Any], filename: str = "schematic.json") -> Board:
    b = Board(imported=[{"file": filename, "format": "EasyEDA Standard schematic"}])
    dsu = _DSU()
    pins: List[Tuple[Point, str, str, str]] = []       # (point, ref, number, name)
    labels: List[Tuple[Point, str]] = []                # (point, net name)
    wires: List[List[Point]] = []
    anon = 0

    for title, sheet in _sheets(doc):
        shapes: List[str] = []
        for k, v in sheet.items():
            if k.startswith("shape") and isinstance(v, list):
                shapes += [s for s in v if isinstance(s, str)]
        sheet_tag = title
        for s in shapes:
            kind = s.split("~", 1)[0]
            if kind == "W":
                f = s.split("~")
                nums = f[1].split() if len(f) > 1 else []
                pts = [p for p in (_pt(nums[i], nums[i + 1]) for i in range(0, len(nums) - 1, 2)) if p]
                pts = [(sheet_tag, p) for p in pts]
                if pts:
                    wires.append(pts)  # type: ignore[arg-type]
            elif kind == "N":
                f = s.split("~")
                p = _pt(f[1], f[2]) if len(f) > 5 else None
                if p and f[5].strip():
                    labels.append(((sheet_tag, p), f[5].strip()))  # type: ignore[arg-type]
            elif kind == "F":  # net flag / power port ("O" is a no-connect marker and carries no net)
                seg = s.split("^^")
                f0 = seg[0].split("~")
                p = _pt(f0[2], f0[3]) if len(f0) > 3 else None
                if p is None and len(seg) > 1 and "~" in seg[1]:
                    p = _pt(*seg[1].split("~")[:2])
                name = seg[2].split("~")[0].strip() if len(seg) > 2 else ""
                if p and name:
                    labels.append(((sheet_tag, p), name))  # type: ignore[arg-type]
            elif kind == "LIB":
                anon += 1
                _parse_lib(s, sheet_tag, b, pins, anon)

    # union all vertices of each wire, then anything touching a wire segment
    for w in wires:
        for p in w[1:]:
            dsu.union(w[0], p)
    anchors = [p for p, *_ in pins] + [p for p, _ in labels] + [w[0] for w in wires] + [w[-1] for w in wires]
    for w in wires:
        for a, c in zip(w, w[1:]):
            if a[0] != c[0]:
                continue
            for p in anchors:
                if p[0] == a[0] and _on_segment(p[1], a[1], c[1]):
                    dsu.union(p, a)
    for p, name in labels:
        dsu.union(p, ("label", name))  # same name joins nets globally

    groups: Dict[Any, Dict[str, Any]] = {}
    for p, ref, num, pname in pins:
        g = groups.setdefault(dsu.find(p), {"pins": [], "names": set()})
        g["pins"].append((ref, num, pname))
    for p, name in labels:
        groups.setdefault(dsu.find(p), {"pins": [], "names": set()})["names"].add(name)

    for g in groups.values():
        if not g["pins"]:
            continue
        names = sorted(g["names"])
        if len(names) > 1:
            b.warnings.append(f"Pins joined under several net names {names}; using '{names[0]}'")
        if names:
            net = names[0]
        elif len(g["pins"]) >= 2:
            ref, num, _ = sorted(g["pins"])[0]
            net = f"NET_{ref}_{num}"
        else:
            continue
        for ref, num, pname in g["pins"]:
            b.connect(net, ref, num, pname)
    if not b.parts:
        b.warnings.append(f"{filename}: no components found — is this a schematic (not a PCB/symbol) source?")
    return b


def _parse_lib(s: str, sheet: str, b: Board, pins: List[Tuple[Any, str, str, str]], idx: int) -> None:
    chunks = s.split("#@$")
    head = chunks[0].split("~")
    attrs = _attrs(head[3]) if len(head) > 3 else {}
    ref = ""
    name = ""
    lib_pins: List[Tuple[Point, str, str]] = []
    for c in chunks[1:]:
        kind = c.split("~", 1)[0]
        if kind == "T":
            f = c.split("~")
            if len(f) > 12 and f[1] == "P":
                ref = f[12].strip()
            elif len(f) > 12 and f[1] == "N":
                name = f[12].strip()
        elif kind == "P":
            seg = c.split("^^")
            f0 = seg[0].split("~")
            p = _pt(f0[4], f0[5]) if len(f0) > 5 else None
            if p is None and len(seg) > 1:
                p = _pt(*seg[1].split("~")[:2])
            pname = seg[3].split("~")[4].strip() if len(seg) > 3 and len(seg[3].split("~")) > 4 else ""
            # the 4th field is the pin number EasyEDA uses for netlists (KiCad's importer reads the same field);
            # the visible number text in segment 4 is only a fallback
            pnum = f0[3].strip() if len(f0) > 3 else ""
            if not pnum and len(seg) > 4 and len(seg[4].split("~")) > 4:
                pnum = seg[4].split("~")[4].strip()
            if p and pnum:
                lib_pins.append((p, pnum, pname))
    ref = ref or attrs.get("pre", "").replace("?", str(idx)) or f"X{idx}"
    if ref.endswith("?"):
        ref = ref[:-1] + str(idx)
    part = b.part(ref)
    part.value = name or attrs.get("name", "") or attrs.get("Value", "")
    part.footprint = attrs.get("package", "")
    part.mpn = attrs.get("BOM_Manufacturer Part", "") or attrs.get("Manufacturer Part", "")
    part.manufacturer = attrs.get("BOM_Manufacturer", "") or attrs.get("Manufacturer", "")
    part.lcsc = attrs.get("BOM_Supplier Part", "") or attrs.get("Supplier Part", "") or attrs.get("LCSC Part", "")
    for p, pnum, pname in lib_pins:
        part.pin(pnum).name = pname
        pins.append(((sheet, p), ref, pnum, pname))

embedforge/eda/netlists.py:
"""Netlist parsers: Protel2/Altium (.net), PADS ASCII (.asc/.net) and KiCad (.net s-expression).

EasyEDA Standard exports Protel/Altium and PADS; EasyEDA Pro exports Protel2 and PADS. These give
reliable connectivity (designator + pin number per net); KiCad netlists also carry pin names.
"""

import re
from typing import Any, List, Tuple

from embedforge.eda.board import Board


def _split_node(node: str, sep: str) -> Tuple[str, str]:
    ref, _, pin = node.strip().rpartition(sep)
    return ref, pin


_PIN_TYPES = {"passive", "input", "output", "bidirectional", "bidirection", "bi", "power", "powerinput", "poweroutput",
              "opencollector", "openemitter", "hiz", "tristate", "unspecified", "undefined", "in", "out", "io", "nc"}


def _protel_component(block: List[str], b: Board, parttypes: dict) -> None:
    """Classic layout is positional (REF, FOOTPRINT, VALUE, ...); EasyEDA Pro's 'PROTEL NETLIST 2.0' is KEY/VALUE pairs."""
    if block and block[0].upper() == "DESIGNATOR":
        kv = {}
        for k, v in zip(block[0::2], block[1::2]):
            kv.setdefault(k.strip(), v.strip())
        ref = kv.get("DESIGNATOR") or kv.get("Designator")
        if not ref:
            return
        part = b.part(ref)
        parttype = kv.get("PARTTYPE", "")
        parttypes[ref] = parttype
        part.footprint = kv.get("FOOTPRINT", "")
        part.value = kv.get("Value") or kv.get("Name") or parttype
        part.mpn = kv.get("Manufacturer Part", "")
        part.manufacturer = kv.get("Manufacturer", "")
        part.lcsc = kv.get("Supplier Part", "")
    elif block and block[0]:
        part = b.part(block[0])
        part.footprint = block[1] if len(block) > 1 else ""
        part.value = block[2] if len(block) > 2 else ""
        parttypes[block[0]] = part.value


def _protel_node(node: str, parttypes: dict) -> Tuple[str, str, str]:
    """'U1-3' (classic) or 'U1-3 RP2354B_C39843328-GPIO6 Passive' (EasyEDA Pro: REF-PIN PARTTYPE-PINNAME TYPE)."""
    node = node.strip()
    first, _, rest = node.partition(" ")
    ref, pin = _split_node(first, "-")
    rest = rest.strip()
    if rest:
        toks = rest.split()
        if len(toks) > 1 and toks[-1].lower() in _PIN_TYPES:
            rest = rest[: rest.rfind(toks[-1])].strip()
    name = ""
    if rest:
        pt = parttypes.get(ref, "")
        name = rest[len(pt) + 1:] if pt and rest.startswith(pt + "-") else rest.rpartition("-")[2]
    return ref, pin, (name if name != pin else "")


def parse_protel(text: str, filename: str = "netlist.net") -> Board:
    """Protel2 / Altium netlist:  [ component ]  and  ( NETNAME  REF-PIN ... ), incl. EasyEDA Pro's key/value variant."""
    b = Board(imported=[{"file": filename, "format": "Protel2 netlist"}])
    lines = [ln.strip() for ln in text.replace("\r", "").split("\n")]
    parttypes: dict = {}
    nets: List[List[str]] = []
    i = 0
    while i < len(lines):
        ln = lines[i]
        if ln in ("[", "("):
            close = "]" if ln == "[" else ")"
            block = []
            i += 1
            while i < len(lines) and lines[i] != close:
                block.append(lines[i])
                i += 1
            if ln == "[":
                _protel_component(block, b, parttypes)
            elif block:
                nets.append(block)
        i += 1
    for block in nets:  # after all components, so PARTTYPEs are known for splitting pin names
        net = block[0]
        for node in block[1:]:
            if node and "-" in node.split(" ", 1)[0]:
                ref, pin, name = _protel_node(node, parttypes)
                if ref and pin:
                    b.connect(net, ref, pin, name)
    if not b.parts:
        b.warnings.append(f"{filename}: no components or nets found in Protel netlist")
    return b


def parse_pads(text: str, filename: str = "netlist.asc") -> Board:
    """PADS ASCII netlist: *PART* (REF DECAL or REF VALUE@DECAL) and *NET* / *SIGNAL* NAME + REF.PIN nodes."""
    b = Board(imported=[{"file": filename, "format": "PADS netlist"}])
    section = ""
    net = ""
    for raw in text.replace("\r", "").split("\n"):
        ln = raw.strip()
        if not ln or ln.startswith("!") and section == "":
            continue
        up = ln.upper()
        if up.startswith("*PART"):
            section = "part"
            continue
        if up.startswith("*NET*"):
            section = "net"
            continue
        if up.startswith("*SIGNAL*"):
            section = "net"
            net = ln.split(None, 1)[1].strip() if len(ln.split(None, 1)) > 1 else ""
            continue
        if up.startswith("*END*"):
            break
        if up.startswith("*"):
            section = "other"
            continue
        if section == "part":
            toks = ln.split()
            if toks:
                part = b.part(toks[0])
                if len(toks) > 1:
                    decal = toks[1]
                    if "@" in decal:
                        part.value, part.footprint = decal.split("@", 1)
                    else:
                        part.footprint = decal
        elif section == "net" and net:
            for node in ln.split():
                ref, pin = _split_node(node, ".")
                if ref and pin:
                    b.connect(net, ref, pin)
    if not b.parts:
        b.warnings.append(f"{filename}: no components or nets found in PADS netlist")
    return b


# ------------------------------------------------------------------ KiCad s-expression
def _sexpr(text: str) -> Any:
    tokens = re.findall(r'\(|\)|"(?:\\.|[^"\\])*"|[^\s()"]+', text)
    stack: List[List[Any]] = [[]]
    for t in tokens:
        if t == "(":
            stack.append([])
        elif t == ")":
            if len(stack) > 1:
                done = stack.pop()
                stack[-1].append(done)
        else:
            stack[-1].append(t[1:-1].replace('\\"', '"') if t.startswith('"') else t)
    return stack[0][0] if stack[0] else []


def _field(node: List[Any], key: str) -> str:
    for x in node[1:]:
        if isinstance(x, list) and x and x[0] == key:
            return str(x[1]) if len(x) > 1 else ""
    return ""


def parse_kicad(text: str, filename: str = "netlist.net") -> Board:
    """KiCad netlist (export (components (comp ...)) (nets (net (name ..) (node (ref ..) (pin ..) (pinfunction ..)))))."""
    b = Board(imported=[{"file": filename, "format": "KiCad netlist"}])
    root = _sexpr(text)
    for sec in root[1:] if isinstance(root, list) else []:
        if not isinstance(sec, list) or not sec:
            continue
        if sec[0] == "components":
            for comp in sec[1:]:
                if isinstance(comp, list) and comp and comp[0] == "comp":
                    part = b.part(_field(comp, "ref"))
                    part.value = _field(comp, "value")
                    part.footprint = _field(comp, "footprint").split(":")[-1]
                    for x in comp[1:]:
                        if isinstance(x, list) and x and x[0] == "fields":
                            for f in x[1:]:
                                if isinstance(f, list) and len(f) >= 3 and f[0] == "field":
                                    key = _field(f, "name").lower() if isinstance(f[1], list) else str(f[1]).lower()
                                    val = str(f[-1]) if not isinstance(f[-1], list) else ""
                                    if key in ("mpn", "manufacturer part", "manufacturer_part_number", "mfr. part #"):
                                        part.mpn = val
                                    elif key in ("lcsc", "lcsc part", "supplier part"):
                                        part.lcsc = val
        elif sec[0] == "nets":
            for net in sec[1:]:
                if isinstance(net, list) and net and net[0] == "net":
                    name = _field(net, "name").lstrip("/")
                    for node in net[1:]:
                        if isinstance(node, list) and node and node[0] == "node":
                            b.connect(name, _field(node, "ref"), _field(node, "pin"), _field(node, "pinfunction"))
    if not b.parts:
        b.warnings.append(f"{filename}: no components or nets found in KiCad netlist")
    return b

