        for f in p.root.rglob("*"):
            if not f.is_file():
                continue
            rel = f.relative_to(p.root)
            if rel.parts[0] in (HIDDEN_DIRS - {"builds"}) or rel.name in ("conversation.json", "trace.jsonl"):
                continue
            z.write(f, str(rel))
