"""Firmware file formats: read the program image out of an ELF or UF2, and write Intel HEX.

Pure Python, so every build can ship a .hex even when the target's own build only makes .uf2/.elf (Betaflight on
RP2350) and no objcopy is installed on the host. The image is the ELF's loadable segments at their load (flash)
addresses — exactly what objcopy -O ihex and the UF2 converter put on the chip.
"""

import struct
from pathlib import Path
from typing import List, Optional, Tuple

Segment = Tuple[int, bytes]  # (load address, bytes)


def elf_segments(data: bytes) -> Tuple[List[Segment], int]:
    """Loadable segments (PT_LOAD with file bytes, at their physical/load address) and the entry point."""
    if data[:4] != b"\x7fELF" or data[4] != 1 or data[5] != 1:
        raise ValueError("not a 32-bit little-endian ELF file")
    entry, phoff = struct.unpack_from("<II", data, 24)
    phentsize, phnum = struct.unpack_from("<HH", data, 42)
    segs: List[Segment] = []
    for i in range(phnum):
        p_type, p_off, _vaddr, p_paddr, p_filesz = struct.unpack_from("<5I", data, phoff + i * phentsize)
        if p_type == 1 and p_filesz:
            segs.append((p_paddr, data[p_off:p_off + p_filesz]))
    if not segs:
        raise ValueError("ELF has no loadable segments")
    return sorted(segs), entry


def uf2_segments(data: bytes) -> Tuple[List[Segment], Optional[int]]:
    """Payload blocks of a UF2 file (merged where contiguous) and its family id."""
    if len(data) % 512:
        raise ValueError("UF2 size is not a multiple of 512")
    blocks, family = [], None
    for i in range(len(data) // 512):
        b = data[i * 512:(i + 1) * 512]
        m0, m1, flags, addr, size, _bno, _n, fam = struct.unpack_from("<8I", b, 0)
        if (m0, m1, struct.unpack_from("<I", b, 508)[0]) != (0x0A324655, 0x9E5D5157, 0x0AB16F30):
            raise ValueError(f"UF2 block {i} has bad magic numbers")
        if flags & 0x1:  # 'not main flash' blocks carry no program bytes
            continue
        if flags & 0x2000:
            family = fam
        blocks.append((addr, b[32:32 + size]))
    blocks.sort()
    merged: List[Segment] = []
    for addr, payload in blocks:
        if merged and merged[-1][0] + len(merged[-1][1]) == addr:
            merged[-1] = (merged[-1][0], merged[-1][1] + payload)
        else:
            merged.append((addr, payload))
    return merged, family


def to_ihex(segments: List[Segment], entry: Optional[int] = None, record: int = 16) -> str:
    """Intel HEX with extended linear address (type 04) records, optional start address (type 05), EOF."""
    def rec(rtype: int, addr16: int, payload: bytes) -> str:
        body = bytes([len(payload), (addr16 >> 8) & 0xFF, addr16 & 0xFF, rtype]) + payload
        return ":" + body.hex().upper() + f"{(-sum(body)) & 0xFF:02X}"

    lines, upper = [], None
    for base, data in segments:
        off = 0
        while off < len(data):
            addr = base + off
            if addr >> 16 != upper:
                upper = addr >> 16
                lines.append(rec(0x04, 0, upper.to_bytes(2, "big")))
            n = min(record, len(data) - off, 0x10000 - (addr & 0xFFFF))  # a record never crosses a 64 KB boundary
            lines.append(rec(0x00, addr & 0xFFFF, data[off:off + n]))
            off += n
    if entry is not None:
        lines.append(rec(0x05, 0, entry.to_bytes(4, "big")))
    lines.append(":00000001FF")
    return "\n".join(lines) + "\n"


def parse_ihex(text: str) -> Tuple[List[Segment], Optional[int]]:
    """Decode Intel HEX back into merged segments (used to check a .hex against its .elf/.uf2)."""
    upper, entry, chunks = 0, None, []
    for n, line in enumerate(text.split(), start=1):
        if not line.startswith(":"):
            raise ValueError(f"line {n}: not an Intel HEX record")
        raw = bytes.fromhex(line[1:])
        if sum(raw) & 0xFF:
            raise ValueError(f"line {n}: checksum error")
        length, addr, rtype, payload = raw[0], (raw[1] << 8) | raw[2], raw[3], raw[4:4 + raw[0]]
        if rtype == 0x00:
            chunks.append(((upper << 16) + addr, payload))
        elif rtype == 0x04:
            upper = int.from_bytes(payload, "big")
        elif rtype == 0x05:
            entry = int.from_bytes(payload, "big")
        elif rtype == 0x01:
            break
    chunks.sort()
    merged: List[Segment] = []
    for addr, payload in chunks:
        if merged and merged[-1][0] + len(merged[-1][1]) == addr:
            merged[-1] = (merged[-1][0], merged[-1][1] + payload)
        else:
            merged.append((addr, payload))
    return merged, entry


def elf_to_hex(elf_path: Path, hex_path: Path) -> bool:
    try:
        segs, entry = elf_segments(Path(elf_path).read_bytes())
        Path(hex_path).write_text(to_ihex(segs, entry), encoding="ascii", newline="\n")
        return True
    except (OSError, ValueError, struct.error):
        return False

embedforge/toolchain/pio.py:
"""Real firmware toolchain: PlatformIO-driven cross-compilation producing .elf/.bin/.hex.

Nothing here is simulated: boards come from PlatformIO's board registry, compilation uses the
vendor GCC toolchain + SDK packages, and the .hex is produced with the toolchain's objcopy.
"""

import hashlib
import json
import os
import re
import subprocess
import sys
import time
from dataclasses import dataclass, field, asdict
from pathlib import Path
from typing import Callable, Dict, List, Optional, Any

from embedforge.core.config import config
from embedforge.core.logger import logger

LineSink = Optional[Callable[[str], None]]

_DIAG_RE = re.compile(r"^(?P<file>[^\s:][^:\n]*?):(?P<line>\d+):(?:(?P<col>\d+):)?\s*(?P<sev>fatal error|error|warning):\s*(?P<msg>.+)$")
_LD_RE = re.compile(r"(undefined reference to .+|multiple definition of .+|region `.+' overflowed.+|cannot find .+)")
_MEM_RE = re.compile(r"^(RAM|Flash):\s*\[[^\]]*\]\s*([\d.]+)%\s*\(used (\d+) bytes from (\d+) bytes\)")


def core_dir() -> Path:
    """Project-local PlatformIO home so toolchains are cached once and never touch global state."""
    p = Path(os.getenv("PLATFORMIO_CORE_DIR") or (Path(config.workspace_root) / ".pio_core"))
    p.mkdir(parents=True, exist_ok=True)
    return p


# The project's own sources (never the framework) are compiled with GCC's bug-finding warnings on: they change no
# generated code, and verify turns the classes that mark run-time misbehaviour into errors (see BUG_WARNINGS).
STRICT_WARNINGS = "-Wall -Wextra -Wshadow -Wformat=2 -Wnull-dereference -Wduplicated-cond -Wlogical-op"

# GCC warning classes that mean the program can misbehave when it runs (not style): verify reports them as errors
BUG_WARNINGS = re.compile(r"\[-W(uninitialized|maybe-uninitialized|array-bounds|stringop-\w+|shift-count-\w+|shift-overflow\S*|"
                          r"shift-negative-value|overflow|return-type|sequence-point|format\S*|null-dereference|type-limits|"
                          r"duplicated-cond|logical-op|div-by-zero|int-in-bool-context|tautological-compare|misleading-indentation|"
                          r"implicit-function-declaration|incompatible-pointer-types|int-conversion|dangling-\w+|return-local-addr|"
                          r"free-nonheap-object|use-after-free|address|enum-compare|aggressive-loop-optimizations|"
                          r"restrict|nonnull|bool-compare|sizeof-pointer-\w+|memset-\w+|class-memaccess)\]")


def _env() -> Dict[str, str]:
    env = dict(os.environ)
    env["PLATFORMIO_CORE_DIR"] = str(core_dir())
    env["PLATFORMIO_DISABLE_PROGRESSBAR"] = "true"
    env["PLATFORMIO_NO_ANSI"] = "true"
    env["PLATFORMIO_SETTING_ENABLE_TELEMETRY"] = "no"
    env["PYTHONIOENCODING"] = "utf-8"
    env["PLATFORMIO_BUILD_SRC_FLAGS"] = (env.get("PLATFORMIO_BUILD_SRC_FLAGS", "") + " " + STRICT_WARNINGS).strip()
    return env


def _pio_cmd(args: List[str]) -> List[str]:
    return [sys.executable, "-m", "platformio", *args]


# PlatformIO platforms that are not in the default registry. Only these URLs are ever installed
# automatically; MCU part-number prefixes map to the platform that supports them. `family` is the registry
# MCU name to list boards by when the exact part (e.g. RP2354B) has no board of its own.
VENDOR_PLATFORMS: Dict[str, Dict[str, Any]] = {
    "arterytekat32": {
        "url": "https://github.com/ArteryTek/platform-arterytekat32.git",
        "prefixes": ("AT32",),
        "vendor": "ArteryTek",
        "framework": "at32firmlib",
        "official": True,
    },
    # RP2350 / RP2354 are not supported by PlatformIO's official raspberrypi platform (RP2040 only). This fork with
    # Earle Philhower's Arduino-Pico core is the de-facto PlatformIO route; enabled at the user's request.
    "rp2350": {
        "url": "https://github.com/maxgerhardt/platform-raspberrypi.git",
        "prefixes": ("RP2350", "RP2354", "PICO2"),
        "vendor": "community (maxgerhardt / Arduino-Pico)",
        "framework": "arduino",
        "family": "rp2350",
        "official": False,
        "use_url": True,  # its installed name 'raspberrypi' collides with the official RP2040-only platform
        "note": ("RP2354A/RP2354B are the RP2350A (QFN-60, 30 GPIO) / RP2350B (QFN-80, 48 GPIO) with 2 MB of in-package "
                 "flash (https://www.raspberrypi.com/news/rp2350-a4-rp2354-and-a-new-hacking-challenge/). There is no "
                 "RP2354 board definition: pick an RP2350B board for an RP2354B (e.g. weact_rp2350b) or an RP2350A board "
                 "for an RP2354A, and pass options=['board_upload.maximum_size = 2097152'] to init_project."),
    },
}


def vendor_platform_for(query: str) -> Optional[str]:
    """Return the vendor platform key whose MCU prefixes match `query` (e.g. 'AT32F421' -> 'arterytekat32')."""
    q = re.sub(r"[^A-Z0-9]", "", query.upper())
    for name, spec in VENDOR_PLATFORMS.items():
        if any(q.startswith(p) or p in q for p in spec["prefixes"]):
            return name
    return None


def _platform_source(d: Path) -> str:
    """Where an installed platform came from: git origin, PlatformIO's install record, or its manifest."""
    gitcfg = d / ".git" / "config"
    if gitcfg.is_file():
        m = re.search(r'\[remote "origin"\][^\[]*?url\s*=\s*(\S+)', gitcfg.read_text(encoding="utf-8", errors="ignore"))
        if m:
            return m.group(1)
    for rec, getter in ((d / ".piopm", lambda j: (j.get("spec") or {}).get("uri", "")),
                        (d / "platform.json", lambda j: (j.get("repository") or {}).get("url", ""))):
        if rec.is_file():
            try:
                src = getter(json.loads(rec.read_text(encoding="utf-8")))
            except Exception:
                src = ""
            if src:
                return src
    return ""


def _norm_url(u: str) -> str:
    return re.sub(r"^git\+", "", u.strip().lower()).removesuffix("/").removesuffix(".git")


def _installed_platform_dir(spec: Dict[str, Any]) -> Optional[Path]:
    """Installed platform that came from the spec URL (names can collide: the RP2350 fork is also 'raspberrypi')."""
    base = core_dir() / "platforms"
    if not base.is_dir():
        return None
    want = _norm_url(spec["url"])
    for d in base.iterdir():
        if d.is_dir() and _norm_url(_platform_source(d)) == want:
            return d
    return None


def platform_installed(name: str) -> bool:
    spec = VENDOR_PLATFORMS.get(name)
    return _installed_platform_dir(spec) is not None if spec else (core_dir() / "platforms" / name).is_dir()


def vendor_platform_name(name: str) -> Optional[str]:
    """PlatformIO's own name for an installed vendor platform (what `pio boards` reports as `platform`)."""
    spec = VENDOR_PLATFORMS.get(name)
    d = _installed_platform_dir(spec) if spec else None
    if d is None:
        return None
    try:
        return json.loads((d / "platform.json").read_text(encoding="utf-8")).get("name")
    except Exception:
        return None


def _run_streaming(cmd: List[str], cwd: Optional[Path], on_line: LineSink, timeout_s: int) -> tuple:
    """Run a command, stream merged stdout/stderr lines, and kill it if it exceeds `timeout_s` even when silent."""
    import threading

    lines: List[str] = []
    try:
        proc = subprocess.Popen(
            cmd, cwd=str(cwd) if cwd else None, env=_env(), stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
            text=True, encoding="utf-8", errors="replace", bufsize=1,
        )
    except Exception as e:
        return -1, [f"Could not launch: {e}"], False
    timed_out = {"v": False}

    def _kill() -> None:
        timed_out["v"] = True
        proc.kill()

    watchdog = threading.Timer(timeout_s, _kill)
    watchdog.daemon = True
    watchdog.start()
    try:
        assert proc.stdout is not None
        for raw in proc.stdout:
            line = raw.rstrip("\r\n")
            lines.append(line)
            if on_line:
                on_line(line)
        proc.wait()
    finally:
        watchdog.cancel()
    if timed_out["v"]:
        lines.append(f"Timed out after {timeout_s}s.")
    return proc.returncode, lines, timed_out["v"]


def install_platform(name: str, on_line: LineSink = None, timeout_s: int = 1800) -> Dict[str, Any]:
    """Install an allow-listed vendor platform into the project-local PlatformIO core."""
    spec = VENDOR_PLATFORMS.get(name)
    if spec is None:
        return {"ok": False, "error": f"'{name}' is not an allow-listed vendor platform."}
    if platform_installed(name):
        return {"ok": True, "already_installed": True}
    code, lines, timed_out = _run_streaming(_pio_cmd(["pkg", "install", "-g", "-p", spec["url"]]), None, on_line, timeout_s)
    ok = code == 0 and not timed_out
    if ok:
        cache = core_dir() / "boards_cache.json"
        if cache.exists():
            cache.unlink()
    logger.log_event("PIO_PLATFORM", f"install {name}: ok={ok}")
    return {"ok": ok, "error": "" if ok else "\n".join(lines[-15:])}


def install_project_packages(project_dir: Path, on_line: LineSink = None, timeout_s: int = 1800) -> Dict[str, Any]:
    """Download the project's platform, toolchain and SDK framework without compiling (so SDK headers are searchable)."""
    code, lines, timed_out = _run_streaming(_pio_cmd(["pkg", "install", "-d", str(project_dir)]), project_dir, on_line, timeout_s)
    ok = code == 0 and not timed_out
    logger.log_event("PIO_PKG", f"install for {project_dir.name}: ok={ok}")
    return {"ok": ok, "error": "" if ok else "\n".join(lines[-15:])}


def is_available() -> bool:
    try:
        r = subprocess.run(_pio_cmd(["--version"]), capture_output=True, text=True, timeout=60, env=_env())
        return r.returncode == 0
    except Exception:
        return False


# ---------------------------------------------------------------- boards
def _board_registry(max_age_s: int = 86400) -> List[Dict[str, Any]]:
    """Full PlatformIO board registry, cached on disk (the raw list is ~1.5k boards)."""
    cache = core_dir() / "boards_cache.json"
    if cache.exists() and time.time() - cache.stat().st_mtime < max_age_s:
        try:
            return json.loads(cache.read_text(encoding="utf-8"))
        except Exception:
            pass
    r = subprocess.run(_pio_cmd(["boards", "--json-output"]), capture_output=True, text=True, timeout=300, env=_env(), encoding="utf-8", errors="replace")
    if r.returncode != 0:
        raise RuntimeError(f"pio boards failed: {r.stderr.strip()[:400]}")
    try:
        data = json.loads(r.stdout or "[]")
    except json.JSONDecodeError as e:
        raise RuntimeError(f"Could not parse board list: {e}")
    cache.write_text(json.dumps(data), encoding="utf-8")
    return data


def list_boards(query: str = "", limit: int = 25) -> List[Dict[str, Any]]:
    """Search the PlatformIO board registry (real data: MCU, clock, RAM/flash, frameworks)."""
    data = _board_registry()
    norm = lambda s: re.sub(r"[^a-z0-9]", "", str(s).lower())
    q = [norm(t) for t in re.split(r"[\s,/]+", query) if norm(t)]
    out = []
    for b in data:
        hay = norm(" ".join(str(b.get(k, "")) for k in ("id", "name", "mcu", "vendor", "platform")))
        if q and not all(t in hay for t in q):
            continue
        score = sum(1 for t in q if t in hay) + (3 if q and q[0] in (norm(b.get("id", "")), norm(b.get("mcu", ""))) else 0)
        out.append({
            "id": b.get("id"), "name": b.get("name"), "vendor": b.get("vendor"), "platform": b.get("platform"),
            "mcu": b.get("mcu"), "fcpu_hz": b.get("fcpu"), "ram_bytes": b.get("ram"), "flash_bytes": b.get("rom"),
            "frameworks": b.get("frameworks", []), "_score": score,
        })
    if not out and len(q) > 1:
        # e.g. "AT32F421 custom ESC": fall back to the tokens that look like part numbers
        parts = [t for t in q if re.search(r"\d", t) and re.search(r"[a-z]", t)]
        if parts and len(parts) < len(q):
            return list_boards(" ".join(parts), limit)
    out.sort(key=lambda x: (-x["_score"], len(x["id"] or "")))
    for o in out:
        o.pop("_score", None)
    return out[:limit]


# ---------------------------------------------------------------- build
@dataclass
class Diagnostic:
    severity: str
    file: str
    line: int
    message: str

    def public(self) -> Dict[str, Any]:
        return asdict(self)


@dataclass
class BuildResult:
    ok: bool
    env: str = ""
    duration_s: float = 0.0
    diagnostics: List[Diagnostic] = field(default_factory=list)
    flash_used: int = 0
    flash_total: int = 0
    ram_used: int = 0
    ram_total: int = 0
    artifacts: Dict[str, str] = field(default_factory=dict)
    log_tail: str = ""
    error: str = ""

    def public(self) -> Dict[str, Any]:
        d = asdict(self)
        d["diagnostics"] = [x.public() for x in self.diagnostics]
        return d


def parse_diagnostics(lines: List[str]) -> List[Diagnostic]:
    out: List[Diagnostic] = []
    seen = set()
    for ln in lines:
        ln = ln.rstrip()
        m = _DIAG_RE.match(ln)
        if m:
            sev = "error" if "error" in m.group("sev") else "warning"
            key = (m.group("file"), m.group("line"), m.group("msg"))
            if key in seen:
                continue
            seen.add(key)
            out.append(Diagnostic(sev, m.group("file").replace("\\", "/"), int(m.group("line")), m.group("msg").strip()))
            continue
        m = _LD_RE.search(ln)
        if m and ln not in seen:
            seen.add(ln)
            out.append(Diagnostic("error", "<linker>", 0, m.group(1).strip()))
        elif ln.startswith("Error:") and ln not in seen:
            seen.add(ln)
            out.append(Diagnostic("error", "platformio.ini", 0, ln[6:].strip()))
    return out


def _objcopy_candidates() -> List[Path]:
    pk = core_dir() / "packages"
    if not pk.is_dir():
        return []
    return sorted(pk.glob("toolchain-*/bin/*objcopy*"))


def make_hex(elf: Path, out_hex: Path) -> bool:
    """Convert ELF -> Intel HEX using the toolchain's objcopy (tries each installed toolchain)."""
    for oc in _objcopy_candidates():
        try:
            r = subprocess.run([str(oc), "-O", "ihex", str(elf), str(out_hex)], capture_output=True, text=True, timeout=60)
            if r.returncode == 0 and out_hex.exists() and out_hex.stat().st_size > 0:
                return True
        except Exception:
            continue
    return False


def _parse_env_name(project_dir: Path) -> str:
    ini = project_dir / "platformio.ini"
    if ini.exists():
        m = re.search(r"^\[env:([^\]]+)\]", ini.read_text(encoding="utf-8"), re.M)
        if m:
            return m.group(1).strip()
    return ""


def build(project_dir: Path, on_line: LineSink = None, timeout_s: int = 1500) -> BuildResult:
    """Run a real PlatformIO build and collect .elf/.bin/.hex plus structured diagnostics."""
    project_dir = Path(project_dir).resolve()
    t0 = time.time()
    env_name = _parse_env_name(project_dir)
    if not env_name:
        return BuildResult(ok=False, error="platformio.ini missing or has no [env:...] section. Call init_project first.")
    code, lines, timed_out = _run_streaming(_pio_cmd(["run", "-d", str(project_dir)]), project_dir, on_line, timeout_s)
    if code not in (0, -1) and not timed_out and any("CreateProcess: No such file or directory" in ln for ln in lines[-400:]):
        # Windows sometimes refuses to start a freshly unpacked compiler (antivirus scan in progress): one clean retry
        if on_line:
            on_line("Compiler could not be started (Windows file lock); retrying the build once…")
        code, lines, timed_out = _run_streaming(_pio_cmd(["run", "-d", str(project_dir)]), project_dir, on_line, timeout_s)
    if code == -1:
        return BuildResult(ok=False, env=env_name, error=lines[0] if lines else "Could not launch PlatformIO")
    res = BuildResult(ok=code == 0 and not timed_out, env=env_name, duration_s=round(time.time() - t0, 1))
    if timed_out:
        res.error = f"Build timed out after {timeout_s}s."
    res.diagnostics = parse_diagnostics(lines)
    for ln in lines:
        m = _MEM_RE.match(ln.strip())
        if m:
            used, total = int(m.group(3)), int(m.group(4))
            if m.group(1) == "RAM":
                res.ram_used, res.ram_total = used, total
            else:
                res.flash_used, res.flash_total = used, total
    res.log_tail = "\n".join(lines[-60:])
    if res.ok:
        bdir = project_dir / ".pio" / "build" / env_name
        for ext in ("elf", "bin", "hex", "uf2"):
            p = bdir / f"firmware.{ext}"
            if p.exists():
                res.artifacts[ext] = str(p)
        if "hex" not in res.artifacts and "elf" in res.artifacts:
            from embedforge.toolchain.fwformat import elf_to_hex
            hex_path = bdir / "firmware.hex"
            if make_hex(Path(res.artifacts["elf"]), hex_path) or elf_to_hex(Path(res.artifacts["elf"]), hex_path):
                res.artifacts["hex"] = str(hex_path)
        if "hex" not in res.artifacts:
            res.error = "Build succeeded but no .hex could be produced for this target (see .bin/.elf)."
    elif not res.diagnostics:
        res.error = "Build failed; see log tail."
    logger.log_event("BUILD", f"{env_name}: ok={res.ok} flash={res.flash_used}/{res.flash_total} artifacts={list(res.artifacts)}")
    return res


CPPCHECK_FLAGS = "--addon=misra --enable=warning,style,performance,portability --inline-suppr"


def check(project_dir: Path, timeout_s: int = 600) -> Dict[str, Any]:
    """cppcheck (with its MISRA C:2012 add-on) on the project's own sources through `pio check`; PlatformIO installs the
    tool on first use. Returns {"ok", "defects": [{severity, category, id, file (project-relative), line, message}], "error"}."""
    project_dir = Path(project_dir).resolve()
    code, lines, timed_out = _run_streaming(_pio_cmd(["check", "-d", str(project_dir), "--skip-packages", "--json-output",
                                                      "--flags", CPPCHECK_FLAGS]), project_dir, None, timeout_s)
    text = "\n".join(lines)
    start = text.find('[{"env"')
    if timed_out or start < 0:
        return {"ok": False, "defects": [], "error": "static analysis timed out" if timed_out else
                (lines[-1] if lines else "pio check produced no report")[:300]}
    try:
        report = json.loads(text[start:text.rindex("]") + 1])
    except ValueError as e:
        return {"ok": False, "defects": [], "error": f"unreadable pio check report: {e}"}
    defects, seen = [], set()
    for env in report:
        for d in env.get("defects") or []:
            try:
                rel = str(Path(d.get("file", "")).resolve().relative_to(project_dir)).replace("\\", "/")
            except ValueError:
                continue                       # a framework file: not the project's code
            key = (d.get("id"), rel, d.get("line"), d.get("message"))
            if key in seen:                    # cppcheck reports a header's defect once per file that includes it
                continue
            seen.add(key)
            defects.append({"severity": d.get("severity", ""), "category": d.get("category", ""), "id": d.get("id", ""),
                            "file": rel, "line": int(d.get("line") or 0), "message": str(d.get("message", ""))[:300]})
    return {"ok": True, "defects": defects}


def file_sha256(path: str) -> str:
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1 << 16), b""):
            h.update(chunk)
    return h.hexdigest()


def framework_roots(framework: str = "") -> List[Path]:
    """Installed SDK package roots; narrowed to the project's framework when one is given and installed."""
    pk = core_dir() / "packages"
    if not pk.is_dir():
        return []
    roots = sorted(pk.glob("framework-*"))
    fw = re.sub(r"[^a-z0-9]", "", (framework or "").lower())
    if fw:
        mine = [r for r in roots if re.sub(r"[^a-z0-9]", "", r.name.lower()).startswith("framework" + fw)]
        if mine:
            return mine
    return roots

embedforge/toolchain/wsl.py:
"""Run Linux build steps through WSL (used for firmware projects with their own make-based build, e.g. Betaflight).

Commands run as the default WSL user inside the configured distro, never with sudo. Output is streamed
line by line, and a watchdog kills the command if it exceeds its timeout even when it prints nothing.
"""

import os
import re
import shlex
import shutil
import subprocess
from pathlib import PureWindowsPath
from typing import Callable, List, Optional, Tuple

from embedforge.toolchain.pio import _run_streaming

LineSink = Optional[Callable[[str], None]]
DISTRO = os.getenv("EMBEDFORGE_WSL_DISTRO", "Ubuntu")


def wsl_exe() -> Optional[str]:
    return shutil.which("wsl.exe") or shutil.which("wsl")


def available() -> Tuple[bool, str]:
    """(ok, detail): whether the configured distro exists and can run bash."""
    exe = wsl_exe()
    if not exe:
        return False, "WSL is not installed (wsl.exe not found)."
    try:
        r = subprocess.run([exe, "-d", DISTRO, "-e", "bash", "-c", "echo ok"], capture_output=True, timeout=120)
    except Exception as e:
        return False, f"WSL did not start: {e}"
    out = r.stdout.decode("utf-8", "replace").strip()
    if r.returncode != 0 or out != "ok":
        err = (r.stderr or r.stdout).decode("utf-16-le" if b"\x00" in (r.stderr or r.stdout) else "utf-8", "replace")
        return False, f"WSL distro '{DISTRO}' is not usable: {err.strip()[:300]}"
    return True, DISTRO


def to_wsl_path(win_path: str) -> str:
    """C:\\Users\\x\\proj -> /mnt/c/Users/x/proj"""
    p = PureWindowsPath(win_path)
    drive = p.drive.rstrip(":").lower()
    rest = "/".join(p.parts[1:])
    return f"/mnt/{drive}/{rest}" if drive else str(win_path).replace("\\", "/")


def run(script: str, on_line: LineSink = None, timeout_s: int = 3600) -> Tuple[int, List[str], bool]:
    """Run a bash script in the distro. Returns (exit code, output lines, timed_out)."""
    exe = wsl_exe()
    if not exe:
        return -1, ["WSL is not installed."], False
    # -e runs bash directly; '--' would first pass the command line through the default shell, expanding $vars early
    cmd = [exe, "-d", DISTRO, "-e", "bash", "-lc", script]
    return _run_streaming(cmd, None, on_line, timeout_s)


def q(s: str) -> str:
    """Shell-quote a value for the bash script."""
    return shlex.quote(str(s))


_SAFE_NAME = re.compile(r"^[A-Za-z0-9_\-]{1,40}$")


def safe_name(name: str) -> bool:
    return bool(_SAFE_NAME.match(name or ""))

embedforge/truth/betaflight_rp2350.py:
"""Pin-capability rules for Betaflight board configs on RP2350A/RP2350B (and RP2354A/B, the same dies).

A Betaflight config can name any pin, but the RP2350 drivers only route a peripheral to specific GPIOs and silently
ignore the rest (the board then boots without a gyro, SD card or UART). These tables were read from the pinned
Betaflight 2026.6.2 source and are checked deterministically against config.h:

  src/platform/PICO/bus_spi_pico.c         SPI SCK/SDI(MISO)/SDO(MOSI) pin lists
  src/platform/PICO/bus_i2c_pico.c         I2C: SDA % 4 == 0 + 2*n, SCL % 4 == 1 + 2*n
  src/platform/PICO/uart/uart_hw.c         UART TX/RX pin lists
  src/platform/PICO/adc_pico.c             ADC: GPIO26-29 (RP2350A), GPIO40-47 (RP2350B)
  src/platform/PICO/dshot_pico.c           DShot on one PIO block: 4 motors, all within GPIO0-31 or GPIO16-47
"""

import re
from typing import Dict, List, Optional, Tuple

SOURCE = "Betaflight 2026.6.2 src/platform/PICO"

SPI_PINS = {
    0: {"SCK": {2, 6, 18, 22, 34, 38}, "SDI": {0, 4, 16, 20, 32, 36}, "SDO": {3, 7, 19, 23, 35, 39}},
    1: {"SCK": {10, 14, 26, 30, 42, 46}, "SDI": {8, 12, 24, 28, 40, 44}, "SDO": {11, 15, 27, 31, 43, 47}},
}
UART_PINS = {
    0: {"TX": {0, 2, 12, 14, 16, 18, 28, 30, 32, 34, 44, 46}, "RX": {1, 3, 13, 15, 17, 19, 29, 31, 33, 35, 45, 47}},
    1: {"TX": {4, 6, 8, 10, 20, 22, 24, 26, 36, 38, 40, 42}, "RX": {5, 7, 9, 11, 21, 23, 25, 27, 37, 39, 41, 43}},
}
ADC_PINS = {"RP2350A": set(range(26, 30)), "RP2350B": set(range(40, 48))}
MAX_GPIO = {"RP2350A": 29, "RP2350B": 47}
MAX_DSHOT_MOTORS = 4

_DEFINE = re.compile(r"^\s*#\s*define\s+([A-Z0-9_]+)\s+(PA(\d{1,2})|NONE)\b", re.M)


def _pins(text: str) -> Dict[str, Tuple[int, int]]:
    """define name -> (gpio, line) for every '#define X PAn' (NONE skipped)."""
    out = {}
    for m in _DEFINE.finditer(text):
        if m.group(3) is not None:
            out[m.group(1)] = (int(m.group(3)), text.count("\n", 0, m.start()) + 1)
    return out


def check_config(text: str, target: str) -> List[Dict[str, object]]:
    """Return findings {severity, code, line, message, suggestion} for pins the RP2350 drivers cannot use."""
    if target not in MAX_GPIO:
        return []
    pins = _pins(text)
    out: List[Dict[str, object]] = []

    def bad(line: int, msg: str, fix: str) -> None:
        out.append({"severity": "ERROR", "code": "BF_PIN_CAPABILITY", "line": line, "message": msg,
                    "suggestion": fix + f" (pin tables: {SOURCE})."})

    for name, (gpio, line) in pins.items():
        if gpio > MAX_GPIO[target]:
            bad(line, f"{name} = PA{gpio}: {target} has GPIO0-{MAX_GPIO[target]} only.", "Use a pin that exists on this package")
            continue
        m = re.fullmatch(r"SPI([01])_(SCK|SDI|SDO|MISO|MOSI)_PIN", name)
        if m:
            role = {"MISO": "SDI", "MOSI": "SDO"}.get(m.group(2), m.group(2))
            legal = {p for p in SPI_PINS[int(m.group(1))][role] if p <= MAX_GPIO[target]}
            if gpio not in legal:
                bad(line, f"{name} = PA{gpio} cannot carry SPI{m.group(1)} {role}.", f"Legal pins: {', '.join(f'PA{p}' for p in sorted(legal))}")
            continue
        m = re.fullmatch(r"UART([01])_(TX|RX)_PIN", name)
        if m:
            legal = {p for p in UART_PINS[int(m.group(1))][m.group(2)] if p <= MAX_GPIO[target]}
            if gpio not in legal:
                bad(line, f"{name} = PA{gpio} cannot carry UART{m.group(1)} {m.group(2)}.", f"Legal pins: {', '.join(f'PA{p}' for p in sorted(legal))}")
            continue
        m = re.fullmatch(r"I2C([01])_(SDA|SCL)_PIN", name)
        if m:
            want = 2 * int(m.group(1)) + (0 if m.group(2) == "SDA" else 1)
            if gpio % 4 != want:
                bad(line, f"{name} = PA{gpio}: I2C{m.group(1)} {m.group(2)} must be on a GPIO with number % 4 == {want}.",
                    "Swap SDA/SCL or use the other I2C instance")
            continue
        if re.fullmatch(r"ADC_\w+_PIN", name) and gpio not in ADC_PINS[target]:
            lo, hi = min(ADC_PINS[target]), max(ADC_PINS[target])
            bad(line, f"{name} = PA{gpio} is not an ADC pin on {target}.", f"Use PA{lo}-PA{hi}")

    motors = sorted((int(re.search(r"\d+", n).group()), g, ln) for n, (g, ln) in pins.items() if re.fullmatch(r"MOTOR\d+_PIN", n))
    if len(motors) > MAX_DSHOT_MOTORS:
        bad(motors[MAX_DSHOT_MOTORS][2], f"{len(motors)} motor pins defined; the RP2350 DShot driver supports {MAX_DSHOT_MOTORS}.",
            "Remove MOTOR5_PIN and above")
    if motors:
        gp = [g for _, g, _ in motors]
        if not (max(gp) <= 31 or min(gp) >= 16):
            bad(motors[0][2], f"Motor pins PA{min(gp)}..PA{max(gp)} span more than one PIO window.",
                "All DShot motor pins must lie within GPIO0-31 or within GPIO16-47")
    return out


def summary(text: str, target: str) -> Optional[str]:
    n = len(_pins(text))
    return f"{n} pin assignments checked against {target} peripheral pin tables" if target in MAX_GPIO else None

embedforge/truth/flow.py:
"""Static flow extraction for embedded drivers: what a function does on the bus, in order, without running it.

Given C/C++ sources, `FlowModel.trace(entry)` walks `entry` statement by statement, inlines calls into project functions,
evaluates constants (macros, enums, const globals, local buffers) and records every bus transfer and delay it reaches:

    write  addr=0x76 reg=0x7E data=[0xB6]          (i2c_write_blocking(i2c0, ADDR, (uint8_t[]){CMD, SOFTRESET}, 2, false))
    delay  >= 2000 us                               (sleep_ms(2))
    read   addr=0x76 reg=0x31 len=21                (write of [0x31] followed by a read of 21 bytes)

Bus primitives of the common HALs are built in (pico-sdk, Arduino Wire, STM32 HAL, ESP-IDF, Zephyr, Bosch-API style
function pointers). Each event says whether it always runs on the path (`guaranteed`) or only inside an if/loop.
Nothing is executed: this is constant propagation over the source text, so values that depend on runtime data stay
symbolic and are reported as unresolved rather than guessed.
"""

from __future__ import annotations

import math
import re
from dataclasses import dataclass, field, replace
from pathlib import Path
from typing import Any, Callable, Dict, Iterable, List, Optional, Sequence, Tuple, Union

SOURCE_EXTS = {".c", ".h", ".cpp", ".hpp", ".cc", ".ino"}
MAX_DEPTH = 10
MAX_EVENTS = 4000

# ------------------------------------------------------------------ values


@dataclass(frozen=True)
class Sym:
    """A value the static walk cannot know (runtime data, struct fields, unknown externals)."""
    text: str

    def __repr__(self) -> str:
        return f"<{self.text}>"


@dataclass(frozen=True)
class Part:
    """An integer of which only some bits are known, as a read-modify-write leaves it: (v & ~0x3F) | 0x0B has bits 0..5
    known (0x0B) and keeps the register's other bits."""
    mask: int    # the known bits
    value: int   # their values (no bits outside mask)

    def __repr__(self) -> str:
        return f"<bits {self.value:#x} of {self.mask:#x}>"


_WORD = 0xFFFFFFFF


def _partial(op: str, a: Any, b: Any) -> Any:
    """& / | of an unknown value (or a Part) with a constant: the bits the constant decides become known."""
    k, u = (a, b) if is_int(a) else (b, a)
    if not is_int(k) or not isinstance(u, (Sym, Part, RxByte)):
        return None
    mask, value = (u.mask, u.value) if isinstance(u, Part) else (0, 0)
    k &= _WORD
    if op == "&":   # bits cleared by the constant are known 0, known bits keep their value where the constant has 1s
        return Part((mask | (~k & _WORD)) & _WORD, value & k)
    return Part((mask | k) & _WORD, (value | k) & _WORD)   # |: bits set by the constant are known 1


class Arr:
    """A byte/int array (local buffer, compound literal or initializer list). Mutable, shared by reference."""

    def __init__(self, items: List[Any]):
        self.items = list(items)

    def __repr__(self) -> str:
        return f"Arr({self.items})"


@dataclass(frozen=True)
class Obj:
    """A named struct/object (global or local) whose fields the walk tracks: &the_sensor, dev->write = &i2c_write."""
    name: str

    def __repr__(self) -> str:
        return self.name


def _non_null(v: Any) -> bool:
    """A pointer the walk knows is not NULL: into a buffer, to a named object, or to a function."""
    return isinstance(v, (Ptr, Arr, Obj)) or (isinstance(v, Sym) and v.text.startswith("fn:"))


def obj_key(v: Any) -> Optional[str]:
    if isinstance(v, Obj):
        return v.name
    if isinstance(v, Sym):
        return v.text
    if isinstance(v, Ptr) and v.offset == 0 and len(v.arr.items) == 1 and isinstance(v.arr.items[0], (Sym, Obj)):
        return obj_key(v.arr.items[0])
    # a pointer into (or an array decaying to its first) struct of an array of structs: p->reg, cfg->reg
    if isinstance(v, Ptr) and 0 <= v.offset < len(v.arr.items) and isinstance(v.arr.items[v.offset], Obj):
        return v.arr.items[v.offset].name
    if isinstance(v, Arr) and v.items and isinstance(v.items[0], Obj):
        return v.items[0].name
    return None


@dataclass
class Ptr:
    arr: Arr
    offset: int = 0

    def get(self, n: Optional[int]) -> List[Any]:
        items = self.arr.items[self.offset:]
        return items if n is None else items[:n]


Value = Union[int, float, Sym, Arr, Ptr, str, None]


def is_int(v: Any) -> bool:
    return isinstance(v, int) and not isinstance(v, bool)


def _c_div(a: int, b: int) -> int:
    """C integer division truncates toward zero (Python's // floors)."""
    q = abs(a) // abs(b)
    return q if (a >= 0) == (b >= 0) else -q


_INT_TYPES = [   # (regex over the type text, bits, signed)
    (r"\b(uint8_t|unsigned\s+char|byte|u8|BYTE|uint8|uint_least8_t|uint_fast8_t|bool|_Bool|boolean)\b", 8, False),
    (r"\b(int8_t|s8|int8|signed\s+char|int_least8_t|int_fast8_t)\b", 8, True),
    (r"\bchar\b", 8, False),   # plain char is unsigned on ARM (RP2040/RP2350, STM32)
    (r"\b(uint16_t|unsigned\s+short|u16|WORD|uint16|uint_least16_t|word)\b", 16, False),
    (r"\b(int16_t|s16|int16|short|int_least16_t)\b", 16, True),
    (r"\b(uint64_t|u64|uint64|unsigned\s+long\s+long)\b", 64, False),
    (r"\b(int64_t|s64|int64|long\s+long)\b", 64, True),
    (r"\b(uint32_t|u32|DWORD|uint32|unsigned\s+long|unsigned\s+int|unsigned|size_t|uint_fast16_t|uint_fast32_t|uintptr_t)\b", 32, False),
    (r"\b(int32_t|s32|int32|long|int|signed|int_fast16_t|int_fast32_t|ssize_t)\b", 32, True),
]


def c_type_kind(type_text: str) -> Optional[Tuple[str, int, bool]]:
    """('float', 64, True) / ('int', bits, signed) for a C arithmetic type, None for anything else (struct, pointer)."""
    if "*" in type_text:
        return None
    if re.search(r"\b(float|double|float32_t|float64_t)\b", type_text):
        return ("float", 64, True)
    for rx, bits, signed in _INT_TYPES:
        if re.search(rx, type_text):
            return ("int", bits, signed)
    return None


def c_convert(type_text: str, v: Any) -> Any:
    """The value C stores when `v` is converted to the type: floats truncate toward zero, integers wrap."""
    if isinstance(v, Part):   # (uint8_t)((v & ~0x3F) | 0x0B): the bits above the type's width are known 0
        kind = c_type_kind(type_text)
        if kind is not None and kind[0] != "float" and not kind[2]:
            m = (1 << kind[1]) - 1
            return Part((v.mask & m) | (~m & _WORD), v.value & m)
        return v
    if not isinstance(v, (int, float)) or isinstance(v, bool):
        return v
    kind = c_type_kind(type_text)
    if kind is None:
        return v
    if kind[0] == "float":
        return float(v)
    if isinstance(v, float):
        if not math.isfinite(v):
            return v
        v = int(v)
    bits, signed = kind[1], kind[2]
    if re.search(r"\b(bool|_Bool|boolean)\b", type_text):
        return int(bool(v))
    v &= (1 << bits) - 1
    return v - (1 << bits) if signed and v >> (bits - 1) else v


def as_bytes(v: Any, n: Any) -> List[Any]:
    """The first n items a buffer argument points to (symbolic items stay symbolic)."""
    count = n if is_int(n) else None
    if isinstance(v, Ptr):
        return v.get(count)
    if isinstance(v, Arr):
        return v.items if count is None else v.items[:count]
    if is_int(v) and count == 1:  # &single_byte
        return [v]
    return [Sym(f"buf:{v!r}")] if count is None else [Sym(f"buf:{v!r}[{i}]") for i in range(min(count, 64))]


# ------------------------------------------------------------------ events


@dataclass
class Event:
    kind: str                      # write | read | delay
    addr: Any = None               # bus address (int) or Sym / None (SPI or unknown)
    reg: Any = None                # register address after normalisation
    data: List[Any] = field(default_factory=list)
    length: Any = None
    delay_us: Any = None
    file: str = ""
    line: int = 0
    chain: Tuple[str, ...] = ()
    guaranteed: bool = True        # False when inside if/else/switch or a loop that may not run
    bus: str = "i2c"
    note: str = ""
    sites: Tuple[int, ...] = ()    # call-site lines from the entry function down to the primitive
    assumed: str = ""              # a delay whose length rests on an assumption the project does not state (tick rate)
    word: int = 1                  # bytes per register (2 for TI's 16-bit registers): a write's data are then register
                                   # values, one per register, and a read's length is still in bytes
    extra: int = 0                 # bytes of a write left over after its whole registers (a register written in part)

    @property
    def entry_line(self) -> int:
        return self.sites[0] if self.sites else self.line

    def public(self) -> Dict[str, Any]:
        def fmt(v: Any) -> Any:
            return f"0x{v:02X}" if is_int(v) else (repr(v) if v is not None else None)
        via = " > ".join(f"{c}:{s}" if k < len(self.sites) else c for k, (c, s) in enumerate(zip(self.chain, list(self.sites) + [0] * len(self.chain))))
        d = {"kind": self.kind, "file": self.file, "line": self.line, "entry_line": self.entry_line, "via": via, "guaranteed": self.guaranteed}
        if self.kind == "delay":
            d["delay_us"] = self.delay_us if is_int(self.delay_us) else repr(self.delay_us)
        else:
            d.update(addr=fmt(self.addr), reg=fmt(self.reg), bus=self.bus)
            if self.kind == "write":
                d["data"] = [f"0x{x:0{2 * self.word}X}" if is_int(x) else fmt(x) for x in self.data]
                if self.extra:
                    d["partial_bytes"] = self.extra
            else:
                d["length"] = self.length if is_int(self.length) else repr(self.length)
        if self.note:
            d["note"] = self.note
        return d

    def describe(self) -> str:
        p = self.public()
        if self.kind == "delay":
            return f"delay {p['delay_us']} us" + (f" ({self.note})" if self.note.startswith("vTaskDelay") else "")
        if self.kind == "write":
            return f"write {p['reg']} <- {', '.join(str(x) for x in p['data'])}"
        return f"read {p['reg']} x{p['length']}"


# ------------------------------------------------------------------ lexer

_TOKEN_RE = re.compile(r"""
    (?P<ws>[ \t\r\f\v]+)
  | (?P<nl>\n)
  | (?P<num>0[xX][0-9A-Fa-f']+[uUlL]*|0[bB][01']+[uUlL]*|\d[\d']*\.\d*(?:[eE][+-]?\d+)?[fFlL]?|\d[\d']*(?:[eE][+-]?\d+)?[uUlLfF]*|\.\d+(?:[eE][+-]?\d+)?[fF]?)
  | (?P<id>[A-Za-z_]\w*)
  | (?P<str>"(?:\\.|[^"\\\n])*")
  | (?P<chr>'(?:\\.|[^'\\\n])+')
  | (?P<op>::|->|\+\+|--|<<=|>>=|<<|>>|<=|>=|==|!=|&&|\|\||\+=|-=|\*=|/=|%=|&=|\|=|\^=|\.\.\.|[{}()\[\];,.?:~!%^&*+\-=<>|/\#])
  | (?P<other>.)
""", re.X)


@dataclass
class Tok:
    kind: str
    text: str
    line: int
    cond: bool = False   # inside a preprocessor branch whose condition is unknown at analysis time


def _strip_comments(src: str) -> str:
    """Replace comments with spaces (keeping newlines), leave strings/chars intact."""
    out, i, n = [], 0, len(src)
    while i < n:
        c = src[i]
        if c == "/" and i + 1 < n and src[i + 1] == "/":
            j = src.find("\n", i)
            j = n if j < 0 else j
            out.append(" " * (j - i))
            i = j
        elif c == "/" and i + 1 < n and src[i + 1] == "*":
            j = src.find("*/", i + 2)
            j = n if j < 0 else j + 2
            out.append("".join("\n" if ch == "\n" else " " for ch in src[i:j]))
            i = j
        elif c in "\"'":
            j = i + 1
            while j < n and src[j] != c and src[j] != "\n":
                j += 2 if src[j] == "\\" else 1
            out.append(src[i:j + 1])
            i = j + 1
        else:
            out.append(c)
            i += 1
    return "".join(out)


def tokenize(text: str, first_line: int = 1) -> List[Tok]:
    toks, line = [], first_line
    for m in _TOKEN_RE.finditer(text):
        kind = m.lastgroup
        if kind == "nl":
            line += 1
            continue
        if kind == "ws":
            continue
        toks.append(Tok(kind, m.group(), line))
    return toks


def parse_number(text: str) -> Union[int, float, None]:
    t = text.replace("'", "")
    t2 = re.sub(r"[uUlL]+$", "", t)
    try:
        if t2.lower().startswith("0x"):
            return int(t2, 16)
        if t2.lower().startswith("0b"):
            return int(t2[2:], 2)
        if re.fullmatch(r"0[0-7]+", t2):
            return int(t2, 8)
        if re.fullmatch(r"\d+", t2):
            return int(t2)
        return float(re.sub(r"[fFlL]$", "", t2))
    except ValueError:
        return None


_ESC = {"n": 10, "t": 9, "r": 13, "0": 0, "\\": 92, "'": 39, '"': 34, "a": 7, "b": 8, "f": 12, "v": 11}


def parse_char(text: str) -> Optional[int]:
    body = text[1:-1]
    if not body:
        return None
    if body[0] != "\\":
        return ord(body[0])
    if body[1:2] in ("x", "X"):
        try:
            return int(body[2:], 16)
        except ValueError:
            return None
    if body[1:].isdigit():
        return int(body[1:], 8)
    return _ESC.get(body[1:2])


# ------------------------------------------------------------------ source model


@dataclass
class Function:
    name: str
    params: List[str]
    body: List[Tok]
    file: str
    line: int
    init: List[Tuple[str, List[Tok]]] = field(default_factory=list)   # C++ constructor initializer list: member(expr)
    cls: str = ""                                                      # owning class for methods
    refs: Tuple[int, ...] = ()                                         # indexes of C++ reference parameters (T &x)
    ptypes: Tuple[str, ...] = ()                                       # value type per parameter ('' = not converted)
    rtype: str = ""                                                    # value type of the return value
    static: bool = False                                               # file-local (C 'static'): other files cannot call it


@dataclass
class Macro:
    params: Optional[List[str]]  # None = object-like
    body: List[Tok]


def _unit(file: str) -> str:
    """The translation unit whose own macros, constants and static functions a file sees: each C/C++ source is one, all
    .ino files of a sketch are one (Arduino joins them); a header is '' (what it defines is visible everywhere)."""
    low = file.lower()
    if low.endswith(".ino"):
        return "<sketch>"
    return file if low.endswith((".c", ".cc", ".cpp", ".cxx")) else ""


_KEYWORDS = {"if", "else", "for", "while", "do", "switch", "case", "default", "return", "break", "continue", "goto",
             "sizeof", "struct", "union", "enum", "typedef", "static", "const", "volatile", "extern", "inline",
             "unsigned", "signed", "void", "char", "short", "int", "long", "float", "double", "bool", "_Bool",
             "class", "namespace", "template", "typename", "public", "private", "protected", "virtual", "operator",
             "new", "delete", "this", "true", "false", "nullptr", "NULL", "auto", "register", "constexpr", "using"}
_TYPE_WORDS = {"unsigned", "signed", "const", "volatile", "char", "short", "int", "long", "float", "double", "bool",
               "_Bool", "void", "struct", "enum", "union", "static", "register", "auto", "constexpr", "size_t", "ssize_t"}
_TYPE_RE = re.compile(r"^(u?int(8|16|32|64)_t|u?int_(least|fast)(8|16|32|64)_t|uintptr_t|intptr_t|size_t|ssize_t|byte|uint|u8|u16|u32|s8|s16|s32|BYTE|WORD|DWORD|uint8|uint16|uint32|int8|int16|int32|TickType_t|BaseType_t|UBaseType_t)$")


def _looks_type(tokens: Sequence[Tok], known_types: set) -> bool:
    """`(uint8_t)` / `(const uint8_t *)` / `(struct foo *)` — a cast, not a parenthesised expression."""
    if not tokens:
        return False
    seen_name = False
    bracket = False
    for t in tokens:
        if t.kind == "id" and (t.text in _TYPE_WORDS or _TYPE_RE.match(t.text) or t.text in known_types):
            seen_name = True
        elif t.kind == "op" and t.text in ("*", "&", "::"):
            continue
        elif seen_name and t.text in ("[", "]"):   # (uint8_t[]){...} / (uint8_t[2]){...}: a compound literal's array type
            bracket = t.text == "["
            continue
        elif bracket and t.kind == "num":
            continue
        elif t.kind == "id" and seen_name is False and tokens[0].text in ("struct", "enum", "union"):
            seen_name = True
        else:
            return False
    return seen_name


def _match(tokens: List[Tok], i: int, open_: str = "(", close: str = ")") -> int:
    """Index of the token closing the bracket opened at tokens[i]."""
    depth = 0
    for j in range(i, len(tokens)):
        t = tokens[j].text
        if t == open_:
            depth += 1
        elif t == close:
            depth -= 1
            if depth == 0:
                return j
    return len(tokens) - 1


def _split_args(tokens: List[Tok]) -> List[List[Tok]]:
    out, cur, depth = [], [], 0
    for t in tokens:
        if t.text in ("(", "[", "{"):
            depth += 1
        elif t.text in (")", "]", "}"):
            depth -= 1
        if t.text == "," and depth == 0:
            out.append(cur)
            cur = []
        else:
            cur.append(t)
    if cur or out:
        out.append(cur)
    return out


SDK_CONSTANTS = {   # values fixed by the SDKs, so `== HAL_OK` and `(addr << 1) | I2C_MASTER_READ` evaluate
    "HAL_OK": "0", "HAL_ERROR": "1", "HAL_BUSY": "2", "HAL_TIMEOUT": "3", "ESP_OK": "0", "ESP_FAIL": "-1",
    "I2C_MASTER_WRITE": "0", "I2C_MASTER_READ": "1", "I2C_MASTER_ACK": "0", "I2C_MASTER_NACK": "1",
    "I2C_MASTER_LAST_NACK": "2", "I2C_MEMADD_SIZE_8BIT": "1", "I2C_MEMADD_SIZE_16BIT": "2",
    "LOW": "0", "HIGH": "1", "pdTRUE": "1", "pdFALSE": "0", "pdPASS": "1", "pdFAIL": "0",
}


_FREERTOS_HZ_RE = re.compile(r"^\s*CONFIG_FREERTOS_HZ\s*=\s*(\d+)", re.M)
ASSUMED_TICK_HZ = 1000   # when a project does not state its tick rate: the fastest common rate, where pdMS_TO_TICKS waits longest


def stated_tick_hz(root: Path) -> Optional[int]:
    """The FreeRTOS tick rate an ESP-IDF project's configuration states (CONFIG_FREERTOS_HZ in its sdkconfig, else in
    sdkconfig.defaults), or None."""
    root = Path(root)
    try:
        found = [p for p in root.glob("sdkconfig*") if p.is_file() and not p.name.endswith(".old")]
    except OSError:
        return None
    for p in sorted(found, key=lambda p: (p.name.startswith("sdkconfig.defaults"), p.name)):
        try:
            m = _FREERTOS_HZ_RE.search(p.read_text(encoding="utf-8", errors="ignore"))
        except OSError:
            continue
        if m and int(m.group(1)) > 0:
            return int(m.group(1))
    return None


class FlowModel:
    """All functions, macros, enums and constant globals of a set of C/C++ sources."""

    def __init__(self, files: Dict[str, str], tick_hz: Optional[int] = None):
        self.functions: Dict[str, List[Function]] = {}
        self.macros: Dict[str, Macro] = {}
        self.consts: Dict[str, List[Tok]] = {}       # enum members and const globals: name -> expression tokens
        self.global_arrays: Dict[str, List[Tok]] = {}
        self.global_sizes: Dict[str, List[Tok]] = {}   # NAME[N] declared at file scope: name -> N tokens
        self.fnptr_fields: Dict[str, List[str]] = {}  # struct field name -> project functions assigned to it
        self.types: set = set()
        self._defined = {m for text in files.values() for m in re.findall(r"^\s*#\s*define\s+([A-Za-z_]\w*)", text, re.M)}
        self.classes = {m for text in files.values() for m in re.findall(r"\b(?:class|struct)\s+([A-Za-z_]\w*)\s*(?::[^{;]*)?\{", text)}
        self.global_objects: Dict[str, Tuple[str, List[List[Tok]]]] = {}   # name -> (class, constructor argument tokens)
        self.defaults: Dict[str, Dict[int, List[Tok]]] = {}                 # function -> {param index: default value tokens}
        self.global_vars: Dict[str, Tuple[Optional[List[Tok]], Optional[List[Tok]]]] = {}   # name -> (array size, initializer)
        self.global_types: Dict[str, str] = {}
        self.global_type_text: Dict[str, str] = {}   # name -> full declared type ('unsigned int', 'float')
        self.field_types: Dict[str, Optional[str]] = {}   # struct/class member -> declared type (None when ambiguous)
        # what a source file defines for itself (macros, enum members, const globals and tables): two drivers in one
        # project may both say `#define I2C_ADDR` or `static const uint8_t init_tbl[]`; each file sees its own
        self.unit_macros: Dict[str, Dict[str, Macro]] = {}
        self.unit_consts: Dict[str, Dict[str, List[Tok]]] = {}
        self.unit_arrays: Dict[str, Dict[str, List[Tok]]] = {}
        self.struct_fields: Dict[str, List[str]] = {}   # struct tag / typedef name -> member names in order
        self.var_structs: Dict[str, List[str]] = {}     # variable declared with an unnamed struct -> its member names
        self.global_files: Dict[str, str] = {}          # file-scope variable -> the file that defines it
        self._file = ""
        for name, text in sorted(files.items()):
            self._file = name
            self._load(name, text)
        self._file = ""
        for name, value in SDK_CONSTANTS.items():   # SDK headers are not in the project: their status/flag values are
            if name not in self.macros and name not in self.consts:
                self.macros[name] = Macro(None, tokenize(value))
        # FreeRTOS tick rate: the project's configuration (sdkconfig), else its own FreeRTOSConfig.h, else assumed
        if tick_hz is None:
            for name in ("configTICK_RATE_HZ", "CONFIG_FREERTOS_HZ"):
                v = Evaluator(self, {}, ()).eval([Tok("id", name, 0)]) if name in self.macros else None
                if is_int(v) and v > 0:
                    tick_hz = v
                    break
        self.tick_assumed = tick_hz is None
        self.tick_hz: int = tick_hz or ASSUMED_TICK_HZ
        for name, value in (("configTICK_RATE_HZ", str(self.tick_hz)), ("CONFIG_FREERTOS_HZ", str(self.tick_hz)),
                            ("portTICK_PERIOD_MS", f"( 1000 / {self.tick_hz} )"), ("portTICK_RATE_MS", f"( 1000 / {self.tick_hz} )")):
            if name not in self.macros:
                self.macros[name] = Macro(None, tokenize(value))
        # registers wider than a byte, from the register map (registers.apply_words): bus address (None: a device whose
        # address the walk cannot tell) -> register -> (bytes, most significant byte first)
        self.words: Dict[Any, Dict[int, Tuple[int, bool]]] = {}

    def word_at(self, addr: Any, reg: Any) -> Tuple[int, bool]:
        """(bytes per register, MSB first) of register `reg` of the device at bus address `addr`; (1, True) for a byte."""
        if not self.words or not is_int(reg):
            return 1, True
        table = self.words.get(addr) if is_int(addr) and addr in self.words else self.words.get(None)
        return (table or {}).get(reg, (1, True))

    def byte_slot(self, addr: Any, reg: int, k: int) -> Tuple[int, int, int, bool]:
        """Byte k of a transfer that starts at register `reg`: (its register, its byte index there, that register's
        bytes, MSB first). Registers follow one another (the pointer moves on after each whole register)."""
        r = reg
        while True:
            n, msb = self.word_at(addr, r)
            if k < n or n <= 0:
                return r, k, n, msb
            k -= n
            r += 1

    def to_words(self, addr: Any, reg: Any, data: List[Any]) -> Tuple[List[Tuple[Any, Any]], int]:
        """A write's data bytes as (register, value) pairs, one per register, and the bytes left over (a register only
        partly written). Bytes of one register combine into its value; a byte known only in part (a read-modify-write)
        keeps the bits it knows."""
        if not is_int(reg) or self.word_at(addr, reg)[0] == 1:
            return [((reg + k) if is_int(reg) else reg, v) for k, v in enumerate(data)], 0
        out: List[Tuple[Any, Any]] = []
        k, r = 0, reg
        while k < len(data):
            n, msb = self.word_at(addr, r)
            chunk = data[k:k + n]
            if len(chunk) < n:
                return out, len(chunk)
            mask = value = 0
            for j, b in enumerate(chunk):
                shift = 8 * (n - 1 - j) if msb else 8 * j
                if is_int(b):
                    mask, value = mask | (0xFF << shift), value | ((b & 0xFF) << shift)
                elif isinstance(b, Part):
                    mask, value = mask | ((b.mask & 0xFF) << shift), value | ((b.value & b.mask & 0xFF) << shift)
            full = (1 << (8 * n)) - 1
            out.append((r, value if mask == full else Part(mask | (~full & _WORD), value) if mask else Sym(f"word@{r}")))
            k, r = k + n, r + 1
        return out, 0

    @classmethod
    def from_dir(cls, root: Path, dirs: Iterable[str] = ("src", "include", "lib")) -> "FlowModel":
        files: Dict[str, str] = {}
        root = Path(root)
        for d in dirs:
            base = root / d
            if base.is_dir():
                for p in base.rglob("*"):
                    if p.is_file() and p.suffix.lower() in SOURCE_EXTS and ".pio" not in p.parts:
                        try:
                            files[str(p.relative_to(root)).replace("\\", "/")] = p.read_text(encoding="utf-8", errors="ignore")
                        except OSError:
                            continue
        return cls(files, stated_tick_hz(root))

    # ---------------------------------------------------------- loading
    def _load(self, name: str, text: str) -> None:
        text = _strip_comments(text.replace("\r\n", "\n"))
        # join backslash continuations, keeping one (empty) line per consumed line so line numbers stay true
        lines: List[str] = []
        pending = ""
        swallowed = 0
        for raw in text.split("\n"):
            if raw.endswith("\\"):
                pending += raw[:-1] + " "
                swallowed += 1
                continue
            lines.append(pending + raw)
            lines.extend([""] * swallowed)
            pending, swallowed = "", 0
        if pending:
            lines.append(pending)
        code_lines: List[str] = []
        cond_lines: set = set()
        stack: List[List[Any]] = []   # [state 'true'|'false'|'unknown', some_branch_taken (True/False/None=unknown)]
        directives = [(k, re.match(r"\s*#\s*(\w+)\s*(.*)$", ln)) for k, ln in enumerate(lines)]
        for k, raw in enumerate(lines):
            s = raw.strip()
            active = all(st[0] != "false" for st in stack)
            if s.startswith("#"):
                d = directives[k][1]
                directive, rest = (d.group(1), d.group(2).strip()) if d else ("", "")
                if directive in ("if", "ifdef", "ifndef"):
                    state = self._pp_state(directive, rest, lines, k) if active else "false"
                    stack.append([state, {"true": True, "false": False}.get(state)])
                elif directive == "elif" and stack:
                    prev_taken = stack[-1][1]
                    if prev_taken is True:
                        stack[-1][0] = "false"
                    else:
                        st = self._pp_state("if", rest, lines, k)
                        stack[-1][0] = "unknown" if (prev_taken is None and st != "false") else st
                        stack[-1][1] = True if st == "true" and prev_taken is False else (None if st == "unknown" or prev_taken is None else prev_taken)
                elif directive == "else" and stack:
                    prev_taken = stack[-1][1]
                    stack[-1][0] = "false" if prev_taken is True else ("true" if prev_taken is False else "unknown")
                elif directive == "endif" and stack:
                    stack.pop()
                elif directive == "define" and active:
                    self._define(rest)
                code_lines.append("")
            else:
                code_lines.append(raw if active else "")
                if active and any(st[0] == "unknown" for st in stack):
                    cond_lines.add(k + 1)
        toks = tokenize("\n".join(code_lines))
        if cond_lines:
            for tk in toks:
                if tk.line in cond_lines:
                    tk.cond = True
        self._scan(name, toks)

    def _pp_state(self, directive: str, rest: str, lines: List[str], k: int) -> str:
        """'true' / 'false' / 'unknown' for a conditional, using only what the project itself defines."""
        name = rest.split()[0] if rest.split() else ""
        if directive in ("ifdef", "ifndef"):
            nxt = next((ln.strip() for ln in lines[k + 1:k + 4] if ln.strip()), "")
            if directive == "ifndef" and re.match(rf"#\s*define\s+{re.escape(name)}\b", nxt):
                return "true"   # include guard / overridable default
            if name in self._defined:
                return "true" if directive == "ifdef" else "false"
            return "unknown"
        expr = re.sub(r"\bdefined\s*\(\s*(\w+)\s*\)|\bdefined\s+(\w+)",
                      lambda m: "1" if (m.group(1) or m.group(2)) in self._defined else "__UNKNOWN__", rest)
        if "__UNKNOWN__" in expr:
            return "unknown"
        v = Evaluator(self, {}, (), file=self._file).eval(tokenize(expr))
        if is_int(v):
            return "true" if v else "false"
        return "unknown"

    def _define(self, rest: str) -> None:
        m = re.match(r"([A-Za-z_]\w*)(\((.*?)\))?\s*(.*)$", rest)
        if not m:
            return
        name, params = m.group(1), m.group(3)
        if m.group(2) is not None and rest[len(name)] == "(":  # function-like: '(' immediately after the name
            plist = [p.strip() for p in params.split(",") if p.strip()]
            self._own(self.unit_macros, self.macros, name, Macro(plist, tokenize(m.group(4))))
        else:
            body = rest[len(name):].strip()
            self._own(self.unit_macros, self.macros, name, Macro(None, tokenize(body)))

    def _own(self, per_unit: Dict[str, Dict[str, Any]], shared: Dict[str, Any], name: str, value: Any) -> None:
        """Record a definition of the file being loaded: a source file's own table, plus the shared one (a header's
        definitions only go there; a source file's go there only if no other file defined the name first)."""
        unit = _unit(self._file)
        if unit:
            per_unit.setdefault(unit, {})[name] = value
            shared.setdefault(name, value)
        else:
            shared[name] = value

    def symbol(self, name: str, file: str = "") -> Tuple[str, Any]:
        """('macro', Macro) / ('const', tokens) / ('array', tokens) / ('', None): what `name` means in `file`, its own
        definitions before the rest of the project's."""
        unit = _unit(file)
        for kind, table in (("macro", self.unit_macros), ("const", self.unit_consts), ("array", self.unit_arrays)):
            v = table.get(unit, {}).get(name) if unit else None
            if v is not None:
                return kind, v
        for kind, shared in (("macro", self.macros), ("const", self.consts), ("array", self.global_arrays)):
            if name in shared:
                return kind, shared[name]
        return "", None

    def macro(self, name: str, file: str = "") -> Optional[Macro]:
        kind, v = self.symbol(name, file)
        return v if kind == "macro" else None

    def _scan(self, fname: str, toks: List[Tok], cls: str = "") -> None:
        i, n = 0, len(toks)
        depth_stack: List[str] = []   # 'scope' (namespace/class/extern) or 'other'
        while i < n:
            t = toks[i]
            if t.text == "{":
                # function definition?  ... name ( params ) [qualifiers] {
                j = i - 1
                while j >= 0 and toks[j].kind == "id" and toks[j].text in ("const", "override", "noexcept", "final", "volatile"):
                    j -= 1
                if j >= 0 and toks[j].text == ")":
                    k = j
                    depth = 0
                    while k >= 0:
                        if toks[k].text == ")":
                            depth += 1
                        elif toks[k].text == "(":
                            depth -= 1
                            if depth == 0:
                                break
                        k -= 1
                    name_i = k - 1
                    init: List[Tuple[str, List[Tok]]] = []
                    ctor = self._ctor_params_end(toks, name_i) if name_i >= 1 and toks[name_i - 1].text in (",", ":") else None
                    if ctor is not None:   # Class::Class(params) : a(x), b(y) {  — the group before '{' is an initializer
                        for item in _split_args(toks[ctor + 2:j + 1]):
                            if len(item) >= 3 and item[0].kind == "id" and item[1].text in ("(", "{"):
                                init.append((item[0].text, item[2:-1]))
                        j, k = ctor, ctor
                        depth = 0
                        while k >= 0:
                            if toks[k].text == ")":
                                depth += 1
                            elif toks[k].text == "(":
                                depth -= 1
                                if depth == 0:
                                    break
                            k -= 1
                        name_i = k - 1
                    if name_i >= 0 and toks[name_i].kind == "id" and toks[name_i].text not in _KEYWORDS:
                        name = toks[name_i].text
                        owner = cls
                        if name_i >= 2 and toks[name_i - 1].text == "::" and toks[name_i - 2].kind == "id":
                            owner = toks[name_i - 2].text
                        if owner:
                            name = f"{owner}::{name}"
                        end = _match(toks, i, "{", "}")
                        params = self._params(toks[k + 1:j])
                        refs = tuple(n2 for n2, p in enumerate(_split_args(toks[k + 1:j])) if any(x.text == "&" for x in p) and not any(x.text == "(" for x in p))
                        fn = Function(name, params, toks[i + 1:end], fname, toks[name_i].line, init, owner, refs,
                                      self._param_types(toks[k + 1:j]), self._return_type(toks, name_i),
                                      not owner and self._is_static(toks, name_i))
                        self.functions.setdefault(name.split("::")[-1], []).append(fn)
                        if "::" in name:
                            self.functions.setdefault(name, []).append(fn)
                        self._scan_fnptr_assignments(fn.body)
                        i = end + 1
                        continue
                prev = toks[i - 1].text if i else ""
                # enum body (also C++ 'enum class Reg : uint8_t {')
                head = [x.text for x in toks[max(0, i - 6):i]]
                if "enum" in head and all(x not in (";", "}", "{", ")", "=") for x in head[head.index("enum"):]):
                    end = _match(toks, i, "{", "}")
                    self._enum(toks[i + 1:end])
                    self._typedef_name(toks, end)
                    i = end + 1
                    continue
                if prev == "=":  # initializer at file scope: const uint8_t tbl[] = { ... };  or a vtable { .read = f, ... }
                    end = _match(toks, i, "{", "}")
                    self._scan_fnptr_assignments(toks[i:end + 1])
                    i = end + 1
                    continue
                if "struct" in head or "union" in head or "class" in head:
                    end = _match(toks, i, "{", "}")
                    self._typedef_name(toks, end)
                    kw = next((k2 for k2 in range(i - 1, max(-1, i - 6), -1) if toks[k2].text in ("class", "struct", "union")), None)
                    owner = toks[kw + 1].text if kw is not None and kw + 1 < i and toks[kw + 1].kind == "id" else cls
                    members = self._fields(toks[i + 1:end])
                    if "struct" in head and members:   # field order: struct tag, typedef name, or the variable declared with it
                        if kw is not None and kw + 1 < i and toks[kw + 1].kind == "id":
                            self.struct_fields[toks[kw + 1].text] = members
                        after = toks[end + 1] if end + 1 < n and toks[end + 1].kind == "id" else None
                        if after is not None:
                            (self.struct_fields if "typedef" in head else self.var_structs)[after.text] = members
                    # class bodies may contain inline methods: scan inside, as methods of that class
                    self._scan(fname, toks[i + 1:end], owner if "class" in head or "struct" in head else cls)
                    i = end + 1
                    continue
                depth_stack.append("scope")
                i += 1
                continue
            if t.text == "}":
                if depth_stack:
                    depth_stack.pop()
                i += 1
                continue
            if t.text == "typedef":
                semi = self._find_semicolon(toks, i)
                seg = toks[i:semi]
                if seg and seg[-1].kind == "id" and "{" not in [x.text for x in seg]:
                    self.types.add(seg[-1].text)
                if "{" not in [x.text for x in seg]:
                    i = semi + 1
                    continue
            prev_text = toks[i - 1].text if i else ";"
            # declaration with default arguments:  BMP388(uint8_t addr = BMP388_ADDR);  /  void f(int x = 5);  and a
            # definition in the class body, which is the first declaration:  T(uint8_t a = ADDR) : _a(a) {}
            if t.kind == "id" and t.text not in _KEYWORDS and i + 1 < n and toks[i + 1].text == "(":
                close = _match(toks, i + 1)
                if close + 1 < n and toks[close + 1].text in (";", "{", ":") and any(x.text == "=" for x in toks[i + 2:close]):
                    defaults = {}
                    for idx, part in enumerate(_split_args(toks[i + 2:close])):
                        texts_p = [x.text for x in part]
                        if "=" in texts_p:
                            defaults[idx] = part[texts_p.index("=") + 1:]
                    qual = f"{cls}::{t.text}" if cls else t.text
                    self.defaults.setdefault(qual, {}).update(defaults)
            # global object of a project class:  BMP388 bmp(0x76);  /  BMP388 bmp;  /  static BMP388 bmp{0x76};
            if (not cls and t.kind == "id" and t.text in self.classes and i + 1 < n and toks[i + 1].kind == "id"
                    and (prev_text in (";", "}", "{") or (i >= 1 and toks[i - 1].text == "static"))):
                after = toks[i + 2].text if i + 2 < n else ";"
                if after in ("(", "{"):
                    close = _match(toks, i + 2, after, ")" if after == "(" else "}")
                    args = _split_args(toks[i + 3:close])
                    if close + 1 < n and toks[close + 1].text == ";" and not any(a and a[0].kind == "id" and (a[0].text in _TYPE_WORDS or _TYPE_RE.match(a[0].text)) for a in args):
                        self.global_objects[toks[i + 1].text] = (t.text, args)
                        i = close + 2
                        continue
                elif after == ";":
                    self.global_objects[toks[i + 1].text] = (t.text, [])
                    i += 3
                    continue
            # file-scope variables:  static double par[14];  float t_lin = 0;  struct calib cal;  int a, b;
            if (not cls and t.kind == "id" and prev_text in (";", "}", "{") and t.text not in
                    ("typedef", "return", "enum", "namespace", "using", "template", "extern", "class", "const", "constexpr", "if", "for", "while")):
                semi = self._find_semicolon(toks, i)
                seg = toks[i:semi]
                texts_seg = [x.text for x in seg]
                eq = texts_seg.index("=") if "=" in texts_seg else len(seg)
                head_txt = texts_seg[:eq]
                if len(seg) >= 2 and "(" not in head_txt and "{" not in head_txt and "const" not in head_txt and "operator" not in head_txt:
                    type_name = next((x.text for x in seg if x.kind == "id" and x.text not in ("static", "volatile", "struct", "unsigned", "signed", "register")), "")
                    seg_type = ""
                    for k2, part in enumerate(_split_args(seg)):
                        ptexts = [x.text for x in part]
                        peq = ptexts.index("=") if "=" in ptexts else len(part)
                        decl = part[:peq]
                        if not decl:
                            continue
                        lb = next((k3 for k3, x in enumerate(decl) if x.text == "["), None)
                        name_tok = decl[lb - 1] if lb else decl[-1]
                        if name_tok.kind != "id" or (k2 == 0 and len(decl) < 2):
                            continue
                        size = None
                        if lb is not None:
                            rb = _match(decl, lb, "[", "]")
                            size = decl[lb + 1:rb]
                        self.global_vars[name_tok.text] = (size, part[peq + 1:] if peq < len(part) else None)
                        self.global_types[name_tok.text] = type_name
                        self.global_files[name_tok.text] = fname
                        if k2 == 0:
                            name_at = next((k3 for k3, x in enumerate(seg) if x is name_tok), 0)
                            seg_type = " ".join(x.text for x in seg[:name_at] if x.text not in ("static", "volatile", "struct"))
                        self.global_type_text[name_tok.text] = seg_type
            if t.text == "[" and i >= 2 and toks[i - 1].kind == "id" and toks[i - 2].kind == "id":
                rb = _match(toks, i, "[", "]")
                if rb + 1 < n and toks[rb + 1].text in (";", "="):
                    self.global_sizes.setdefault(toks[i - 1].text, toks[i + 1:rb])
            # const globals: [static] const <type> NAME = expr ;  and arrays NAME[] = { ... };  (only at statement start,
            # which includes right after `public:`: the TMP117 driver's first class member, its I2C address, was lost)
            after_access = prev_text == ":" and i >= 2 and toks[i - 2].text in ("public", "private", "protected")
            if t.kind == "id" and t.text in ("const", "constexpr", "static") and (prev_text in (";", "}", "{") or after_access):
                semi = self._find_semicolon(toks, i)
                seg = toks[i:semi]
                texts_seg = [x.text for x in seg]
                if "=" in texts_seg and not any(x in ("(", "{") for x in texts_seg[:texts_seg.index("=")]):
                    eq = [x.text for x in seg].index("=")
                    lhs = seg[:eq]
                    if lhs and lhs[-1].text == "]":
                        lb = max(k for k, x in enumerate(lhs) if x.text == "[")
                        if lb > 0 and lhs[lb - 1].kind == "id":
                            self._own(self.unit_arrays, self.global_arrays, lhs[lb - 1].text, seg[eq + 1:])
                    elif lhs and lhs[-1].kind == "id" and any(x.text in ("const", "constexpr") for x in lhs):
                        self._own(self.unit_consts, self.consts, lhs[-1].text, seg[eq + 1:])
                    self._scan_fnptr_assignments(seg)   # const vtables: { .read = bmp388_read_i2c, ... }
                    i = semi + 1
                    continue
            i += 1

    def _fields(self, body: List[Tok]) -> List[str]:
        """Member declarations of a struct/class body (depth 0, not methods): uint16_t par_t1; int8_t a, b; float x[3];
        Returns the member names in declaration order (what a positional initializer { a, b } fills)."""
        seg: List[Tok] = []
        names: List[str] = []
        depth = 0
        for tk in body:
            if tk.text in ("{", "("):
                depth += 1
            elif tk.text in ("}", ")"):
                depth -= 1
            if depth == 0 and tk.text == ";":
                names += self._field_decl(seg)
                seg = []
            elif depth == 0 and tk.text == ":" and seg and seg[-1].text in ("public", "private", "protected"):
                seg = []
            elif depth >= 0:
                seg.append(tk)
        return names

    def _field_decl(self, seg: List[Tok]) -> List[str]:
        texts = [x.text for x in seg]
        if not seg or any(x in texts for x in ("(", "{", "typedef", "using", "friend", "enum", "return")):
            return []
        parts = _split_args(seg)
        first = parts[0]
        cut = next((k for k, x in enumerate(first) if x.text in ("[", "=", ":")), len(first))
        if cut < 2 or first[cut - 1].kind != "id":
            return []
        type_text = " ".join(x.text for x in first[:cut - 1] if x.text not in ("static", "volatile", "const", "mutable", "struct", "union"))
        if not type_text:
            return []
        names = [first[cut - 1].text] + [next((x.text for x in p if x.kind == "id"), "") for p in parts[1:]]
        for nm in names:
            if not nm:
                continue
            prev = self.field_types.get(nm, type_text)
            self.field_types[nm] = type_text if prev == type_text else None   # same name, different types: unknown
        return [nm for nm in names if nm]

    def struct_of(self, type_text: str) -> Optional[List[str]]:
        """Member names, in order, of the struct type named in a declaration's type ('const reg_val_t', 'struct cfg')."""
        return next((self.struct_fields[w] for w in type_text.split() if w in self.struct_fields), None)

    @staticmethod
    def _ctor_params_end(toks: List[Tok], name_i: int) -> Optional[int]:
        """For `Class::Class(params) : a(x), b(y) {` called with name_i at an initializer's member name: the index of
        the ')' closing the constructor's own parameter list, or None if this is not an initializer list."""
        m = name_i - 1
        while m >= 1:
            if toks[m].text == ":":
                return m - 1 if toks[m - 1].text == ")" else None
            if toks[m].text != ",":
                return None
            close = m - 1
            if close < 0 or toks[close].text not in (")", "}"):
                return None
            opener = "(" if toks[close].text == ")" else "{"
            depth, q = 0, close
            while q >= 0:
                if toks[q].text == toks[close].text:
                    depth += 1
                elif toks[q].text == opener:
                    depth -= 1
                    if depth == 0:
                        break
                q -= 1
            m = q - 2   # the token before that initializer's member name
        return None

    @staticmethod
    def _find_semicolon(toks: List[Tok], i: int) -> int:
        depth = 0
        for j in range(i, len(toks)):
            x = toks[j].text
            if x in ("(", "[", "{"):
                depth += 1
            elif x in (")", "]", "}"):
                depth -= 1
            elif x == ";" and depth <= 0:
                return j
        return len(toks) - 1

    def _typedef_name(self, toks: List[Tok], end: int) -> None:
        if end + 1 < len(toks) and toks[end + 1].kind == "id":
            self.types.add(toks[end + 1].text)

    def _enum(self, body: List[Tok]) -> None:
        nxt = 0
        for item in _split_args(body):
            if not item or item[0].kind != "id":
                continue
            if len(item) >= 3 and item[1].text == "=":
                self._own(self.unit_consts, self.consts, item[0].text, item[2:])
                v = Evaluator(self, {}, (), file=self._file).eval(item[2:])
                nxt = v + 1 if is_int(v) else nxt + 1
            else:
                self._own(self.unit_consts, self.consts, item[0].text, [Tok("num", str(nxt), item[0].line)])
                nxt += 1

    def _params(self, toks: List[Tok]) -> List[str]:
        names = []
        for p in _split_args(toks):
            ids = [t for t in p if t.kind == "id" and t.text not in _TYPE_WORDS]
            if not p or (len(p) == 1 and p[0].text == "void"):
                continue
            # 'uint8_t buf[]', 'const uint8_t *data', 'int (*cb)(int)'
            if any(t.text == "(" for t in p) and len(ids) >= 1:
                inner = [t for t in p if t.kind == "id"]
                names.append(inner[1].text if len(inner) > 1 else inner[0].text)
                continue
            core = [t for t in p if t.text not in ("[", "]") and t.kind != "num"]
            if "=" in [t.text for t in core]:
                core = core[:[t.text for t in core].index("=")]
            last = [t for t in core if t.kind == "id"]
            names.append(last[-1].text if last else f"_{len(names)}")
        return names

    @staticmethod
    def _param_types(toks: List[Tok]) -> Tuple[str, ...]:
        """The value type of each parameter ('int8_t' for 'int8_t raw'); '' for pointers, arrays, references and
        function pointers, which are not converted. Aligned with _params."""
        out = []
        for p in _split_args(toks):
            if not p or (len(p) == 1 and p[0].text == "void"):
                continue
            texts = [t.text for t in p]
            if any(x in texts for x in ("*", "&", "[", "(", "...")):
                out.append("")
                continue
            words = [t.text for t in p if t.kind == "id"][:-1]   # without the parameter's name
            out.append(" ".join(w for w in words if w not in ("const", "volatile", "register")))
        return tuple(out)

    @staticmethod
    def _is_static(toks: List[Tok], name_i: int) -> bool:
        """`static [inline] <type> [*] name(`: the function is local to its file."""
        k = name_i - 1
        while k >= 0 and (toks[k].kind == "id" or toks[k].text in ("*", "&")):
            if toks[k].text == "static":
                return True
            k -= 1
        return False

    @staticmethod
    def _return_type(toks: List[Tok], name_i: int) -> str:
        """The declared return value type of the function whose name is at name_i ('' for pointers / unknown)."""
        k = name_i - 1
        if k >= 1 and toks[k].text == "::":   # Class::method
            k -= 2
        words = []
        while k >= 0 and (toks[k].kind == "id" or toks[k].text in ("*", "&")):
            if toks[k].text in ("*", "&"):
                return ""
            words.append(toks[k].text)
            k -= 1
        words = [w for w in reversed(words) if w not in ("static", "inline", "extern", "const", "volatile", "constexpr",
                                                         "virtual", "IRAM_ATTR", "__attribute__")]
        return " ".join(words)

    def _scan_fnptr_assignments(self, body: List[Tok]) -> None:
        """`dev.write = &i2c_write;`, `dev->delay_us = user_delay;` and vtable initializers `.read = bmp388_read_i2c,`:
        remember which project functions a field may point to."""
        for k in range(len(body) - 3):
            if body[k].text in (".", "->") and body[k + 1].kind == "id" and body[k + 2].text == "=":
                j = k + 3
                if j < len(body) and body[j].text == "&":
                    j += 1
                if j < len(body) and body[j].kind == "id" and j + 1 < len(body) and body[j + 1].text in (";", ",", "}"):
                    cands = self.fnptr_fields.setdefault(body[k + 1].text, [])
                    if body[j].text not in cands:
                        cands.append(body[j].text)

    def fnptr_candidates(self, field: str) -> List[str]:
        """Project functions stored in a field of this name, I2C implementations first (then the rest, as written)."""
        cands = [c for c in self.fnptr_fields.get(field, []) if c in self.functions]
        return sorted(cands, key=lambda c: (0 if "i2c" in c.lower() else 1 if "spi" not in c.lower() else 2))

    # ---------------------------------------------------------- api
    def function(self, name: str, file: str = "") -> Optional[Function]:
        """The function `name` as code in `file` calls it: the file's own definition, else one other files can see (not
        static, or static in a header), else any."""
        cands = self.functions.get(name) or self.functions.get(name.split("::")[-1])
        if not cands:
            return None
        if len(cands) > 1:
            unit = _unit(file)
            cands = ([f for f in cands if unit and _unit(f.file) == unit]
                     or [f for f in cands if not f.static or not _unit(f.file)] or cands)
        return max(cands, key=lambda f: len(f.body))  # prefer the definition over a stub

    def caller_context(self, entry: str, entry_lists: Iterable[List[str]]) -> Optional[Tuple[List[Any], Dict[str, Any], Dict[Tuple[str, str], Any], Any]]:
        """What the program hands `entry` the first time it calls it: walk each list of entry points (main, setup + loop,
        tasks) until that call and keep its arguments, globals and struct fields (`dm388_init(&dev)` after main filled
        dev.addr). None when no entry point calls it."""
        target = self.function(entry)
        if target is None:
            return None
        for entries in entry_lists:
            if target.name in entries:
                continue
            w = Walker(self)
            w.capture = target.name
            try:
                for obj_name, (cls, ctor_args) in self.global_objects.items():
                    w.construct(obj_name, cls, ctor_args)
                for e in entries:
                    fn = self.function(e)
                    if fn is not None:
                        w.call(fn, [Sym(p) for p in fn.params], (), guaranteed=True)
            except _Captured:
                return w.captured
            except RecursionError:
                continue
        return None

    def trace(self, entry: str, args: Optional[List[Any]] = None, assume: Optional[Dict[str, Any]] = None,
              context: Optional[Tuple[List[Any], Dict[str, Any], Dict[Tuple[str, str], Any], Any]] = None,
              probe: Optional[Dict[int, int]] = None, spi_dummy: int = 0) -> "Trace":
        """Walk `entry`. `assume` fixes what the caller would provide: {'dev.intf': 1} sets a field of a parameter,
        {'addr': 0x76} a parameter's value. `context` (from caller_context) is what the program's own call passes.
        `probe`: the register values a healthy part returns (see run), so the code's checks on them are decided."""
        fn = self.function(entry)
        if fn is None:
            return Trace(entry, [], [f"function '{entry}' not found in the project sources"], found=False)
        w = Walker(self)
        w.probe = probe
        w.spi_dummy = spi_dummy
        for obj_name, (cls, ctor_args) in self.global_objects.items():   # global constructors run before main/setup
            w.construct(obj_name, cls, ctor_args)
        this = None
        if context is not None:
            args = list(context[0]) if args is None else args
            w.globals.update(context[1])
            w.fields.update(context[2])
            this = context[3]
        call_args = list(args or [])
        for k, p in enumerate(fn.params):
            if k >= len(call_args):
                call_args.append(Obj(f"<{p}>") if any(a.startswith(p + ".") for a in (assume or {})) else Sym(p))
        for key, value in (assume or {}).items():
            if "." in key:
                base, fld = key.split(".", 1)
                w.fields[(f"<{base}>", fld)] = value
            elif key in fn.params:
                call_args[fn.params.index(key)] = value
        w.call(fn, call_args, (), guaranteed=True, this=this)
        w.spi_flush()
        return Trace(entry, normalize(w.events, self), w.notes, found=True, opaque=sorted(w.opaque))

    def run(self, entries: List[str], probe: Optional[Dict[int, int]] = None, spi_dummy: int = 0) -> "Walker":
        """Walk several entry functions in order on one shared state (setup() then loop(), as the Arduino core does).
        In probe mode a device read returns the `probe` byte of each register, so the code's arithmetic runs on concrete
        data and the walker's `values` hold every number it computes. Without a probe, read bytes stay symbolic but
        remember their register (shifts and masks applied to them are in obs_shifts / obs_masks). `spi_dummy`: bytes an
        SPI read returns before the register data (Bosch BMP388/BMI160 send one dummy byte, most parts none)."""
        w = Walker(self)
        w.probe = probe
        w.spi_dummy = spi_dummy
        for obj_name, (cls, ctor_args) in self.global_objects.items():
            w.construct(obj_name, cls, ctor_args)
        for entry in entries:
            fn = self.function(entry)
            if fn is not None and len(w.events) < MAX_EVENTS:
                w.call(fn, [Sym(p) for p in fn.params], (), guaranteed=True)
        w.spi_flush()
        w.events = normalize(w.events, self)
        return w


@dataclass
class Trace:
    entry: str
    events: List[Event]
    notes: List[str]
    found: bool = True
    opaque: List[str] = field(default_factory=list)

    def ops(self) -> List[Event]:
        return [e for e in self.events if e.kind in ("write", "read")]


# ------------------------------------------------------------------ expression evaluation


MAX_ITER = 256   # iterations of one loop with known bounds
_SHIFTED_RX = re.compile(r"^\(?<?rx@0x[0-9A-F]+(\[\d+:\d+\])?<<\d+")   # (msb << 8) ...: the other half of `(msb << 8) | lsb`


@dataclass(frozen=True)
class RxByte:
    """A byte read from a device register (unknown value, known origin): lets the analysis see how the code assembles
    multi-byte values and which status bits it tests. In a register wider than a byte (TI's 16-bit registers) it is
    the byte holding bits pos+7..pos."""
    reg: int
    dev: Optional[int] = None   # bus address of the device, when known
    pos: int = 0                # the register bit this byte's bit 0 is (8: the high byte of a 16-bit register)
    width: int = 8              # the register's width in bits

    def __repr__(self) -> str:
        return f"rx@0x{self.reg:02X}" + (f"[{self.pos + 7}:{self.pos}]" if self.width > 8 else "")


@dataclass(frozen=True, repr=False)
class RxWord(Sym):
    """Bytes of one wide register put together by the code ((hi << 8) | lo): which byte went where. `whole` when every
    byte is in and sits at its own bit position, i.e. the value is the register's value."""
    reg: int = 0
    dev: Optional[int] = None
    width: int = 16
    pieces: Tuple[Tuple[int, int], ...] = ()   # (bit position of the byte in the register, bit position the code put it at)

    def __repr__(self) -> str:
        return f"<{self.text}>"

    @property
    def whole(self) -> bool:
        return sorted(p for p, _ in self.pieces) == list(range(0, self.width, 8)) and all(p == s for p, s in self.pieces)


def _rx_pieces(v: Any) -> Optional[Tuple[int, Optional[int], int, Tuple[Tuple[int, int], ...]]]:
    """(register, device, width, pieces) of a byte or bytes read from one wide register; None for anything else."""
    if isinstance(v, RxByte) and v.width > 8:
        return v.reg, v.dev, v.width, ((v.pos, 0),)
    if isinstance(v, RxWord):
        return v.reg, v.dev, v.width, v.pieces
    return None


class _Break(Exception):
    pass


class _Continue(Exception):
    pass


class _Captured(Exception):
    """The walk reached the function it was asked to find the inputs of (FlowModel.caller_context)."""


class _Return(Exception):
    def __init__(self, value: Any):
        self.value = value


class Evaluator:
    """Constant-propagating expression evaluator with a call hook."""

    def __init__(self, model: FlowModel, env: Dict[str, Any], chain: Tuple[str, ...], walker: Optional["Walker"] = None,
                 guaranteed: bool = True, file: str = ""):
        self.m, self.env, self.chain, self.w, self.guaranteed, self.file = model, env, chain, walker, guaranteed, file
        self._macro_depth = 0

    # Pratt parser over a token list
    def eval(self, toks: List[Tok]) -> Any:
        if not toks:
            return None
        self.toks, self.i = self._expand(toks), 0
        try:
            v = self._expr(0)
        except (IndexError, ZeroDivisionError, ValueError, OverflowError, TypeError, RecursionError):
            return Sym(" ".join(t.text for t in toks)[:80])
        return v

    def _expand(self, toks: List[Tok], depth: int = 0) -> List[Tok]:
        """Expand function-like macros (object-like ones are resolved lazily as identifiers)."""
        if depth > 8:
            return toks
        out: List[Tok] = []
        i = 0
        changed = False
        while i < len(toks):
            t = toks[i]
            mac = self.m.macro(t.text, self.file) if t.kind == "id" else None
            if mac and mac.params is not None and i + 1 < len(toks) and toks[i + 1].text == "(":
                end = _match(toks, i + 1)
                args = _split_args(toks[i + 2:end])
                sub = {p: (args[k] if k < len(args) else []) for k, p in enumerate(mac.params)}
                if mac.params and mac.params[-1] == "...":
                    sub["__VA_ARGS__"] = sum(([Tok("op", ",", t.line)] + a for a in args[len(mac.params) - 1:]), [])[1:]
                body = []
                for bt in mac.body:
                    if bt.kind == "id" and bt.text in sub:
                        body.extend(Tok(x.kind, x.text, t.line) for x in sub[bt.text])
                    elif bt.text == "#":
                        continue
                    else:
                        body.append(Tok(bt.kind, bt.text, t.line))
                out.append(Tok("op", "(", t.line))
                out.extend(body)
                out.append(Tok("op", ")", t.line))
                i = end + 1
                changed = True
            else:
                out.append(t)
                i += 1
        return self._expand(out, depth + 1) if changed else out

    def _peek(self, k: int = 0) -> Optional[Tok]:
        j = self.i + k
        return self.toks[j] if 0 <= j < len(self.toks) else None

    def _next(self) -> Tok:
        t = self.toks[self.i]
        self.i += 1
        return t

    _BIN = {"||": 1, "&&": 2, "|": 3, "^": 4, "&": 5, "==": 6, "!=": 6, "<": 7, ">": 7, "<=": 7, ">=": 7,
            "<<": 8, ">>": 8, "+": 9, "-": 9, "*": 10, "/": 10, "%": 10}
    _ASSIGN = {"=", "+=", "-=", "*=", "/=", "%=", "&=", "|=", "^=", "<<=", ">>="}

    def _expr(self, min_prec: int) -> Any:
        left = self._unary()
        while True:
            t = self._peek()
            if t is None:
                return left
            if t.text == "," and min_prec == 0:
                self._next()
                left = self._expr(0)  # comma operator: value of the last operand
                continue
            if t.text in self._ASSIGN and min_prec == 0:
                self._next()
                right = self._expr(0)
                return right
            if t.text == "?" and min_prec <= 0:
                self._next()
                a = self._expr(0)
                if self._peek() is not None and self._peek().text == ":":
                    self._next()
                b = self._expr(0)
                if is_int(left):
                    return a if left else b
                return a if a == b else Sym("ternary")
            prec = self._BIN.get(t.text)
            if prec is None or prec <= min_prec - 1 or prec < min_prec:
                return left
            self._next()
            right = self._expr(prec + 1)
            if self.w is not None:
                self.w.observe(t.text, left, right, self.file, t.line)
            left = self._binop(t.text, left, right)

    @staticmethod
    def _binop(op: str, a: Any, b: Any) -> Any:
        # pointer arithmetic: buf + 3, p - 1, 2 + p point into the same buffer
        if op in ("+", "-") and isinstance(a, (Ptr, Arr)) and is_int(b):
            arr, off = (a.arr, a.offset) if isinstance(a, Ptr) else (a, 0)
            return Ptr(arr, off + (b if op == "+" else -b))
        if op == "+" and is_int(a) and isinstance(b, (Ptr, Arr)):
            arr, off = (b.arr, b.offset) if isinstance(b, Ptr) else (b, 0)
            return Ptr(arr, off + a)
        # bytes of a wide register put together: (rx[15:8] << 8) | rx[7:0] is the register's value, other placements
        # are recorded as they are (registers.py reports a swapped byte order)
        if op == "<<" and is_int(b) and 0 <= b < 32 and _rx_pieces(a) is not None:
            reg, dev, width, pieces = _rx_pieces(a)
            return RxWord(f"{a!r}<<{b}", reg, dev, width, tuple((p, s + b) for p, s in pieces))
        if op in ("|", "+") and _rx_pieces(a) is not None and _rx_pieces(b) is not None and _rx_pieces(a)[:3] == _rx_pieces(b)[:3]:
            reg, dev, width, pieces = _rx_pieces(a)
            return RxWord(f"{a!r}{op}{b!r}", reg, dev, width, pieces + _rx_pieces(b)[3])
        if op in ("<<", ">>") and isinstance(a, Part) and is_int(b) and 0 <= b < 32:   # (cfg >> 8) of a read-modify-write
            if op == "<<":
                return Part(((a.mask << b) | ((1 << b) - 1)) & _WORD, (a.value << b) & _WORD)
            return Part((a.mask >> b) | (~(_WORD >> b) & _WORD), a.value >> b)
        if op in ("&", "|"):   # read-modify-write: the bits a constant decides stay known
            p = _partial(op, a, b)
            if p is not None:
                return p
        # a buffer, object or function is a non-null pointer: true in && / || / !, and never == NULL. Bosch's
        # null_ptr_check (dev->read == NULL with dev->read = i2c_read) otherwise left init's failure path open, and the
        # calibration it read was lost where the paths met
        if op in ("&&", "||") and (_non_null(a) or _non_null(b)):
            a = 1 if _non_null(a) else a
            b = 1 if _non_null(b) else b
        if op in ("==", "!=") and ((_non_null(a) and is_int(b) and b == 0) or (_non_null(b) and is_int(a) and a == 0)):
            return int(op == "!=")
        if not (isinstance(a, (int, float)) and isinstance(b, (int, float))):
            if op == "&&" and (a == 0 or b == 0):
                return 0
            if op == "||" and ((is_int(a) and a) or (is_int(b) and b)):
                return 1
            return Sym(f"{a!r}{op}{b!r}")
        try:
            r = {"||": lambda: int(bool(a) or bool(b)), "&&": lambda: int(bool(a) and bool(b)), "|": lambda: int(a) | int(b),
                 "^": lambda: int(a) ^ int(b), "&": lambda: int(a) & int(b), "==": lambda: int(a == b), "!=": lambda: int(a != b),
                 "<": lambda: int(a < b), ">": lambda: int(a > b), "<=": lambda: int(a <= b), ">=": lambda: int(a >= b),
                 "<<": lambda: int(a) << int(b), ">>": lambda: int(a) >> int(b), "+": lambda: a + b, "-": lambda: a - b,
                 "*": lambda: a * b, "/": lambda: (_c_div(a, b) if is_int(a) and is_int(b) else a / b), "%": lambda: (a - b * _c_div(a, b) if is_int(a) and is_int(b) else math.fmod(a, b))}[op]()
            return r
        except (ZeroDivisionError, ValueError, OverflowError):
            return Sym(f"{a}{op}{b}")

    def _unary(self) -> Any:
        t = self._peek()
        if t is None:
            return None
        if t.text in ("-", "+", "~", "!"):
            self._next()
            v = self._unary()
            if isinstance(v, (int, float)):
                return {"-": -v, "+": v, "~": ~int(v), "!": int(not v)}[t.text]
            if t.text == "!" and _non_null(v):   # !dev->read with dev->read = i2c_read
                return 0
            return Sym(f"{t.text}{v!r}")
        if t.text in ("++", "--"):   # ++i: the variable changes, the value is the new one
            self._next()
            nxt = self._peek()
            v = self._unary()
            if nxt is not None and nxt.kind == "id" and nxt.text in self.env and self._peek(-1) is nxt and isinstance(v, (int, float, Ptr)):
                v = self._binop("+" if t.text == "++" else "-", v, 1)
                self.env[nxt.text] = v
            return v
        if t.text == "&":
            self._next()
            nxt = self._peek()
            name = nxt.text if nxt is not None and nxt.kind == "id" else None
            follow = self._peek(1)
            if name and follow is not None and follow.text == "[":   # &buf[k]: a pointer into buf, not a copy of one byte
                base = self.env.get(name)
                if base is None and self.w is not None and name in self.m.global_vars:
                    base = self.w.global_value(name)
                close = _match(self.toks, self.i + 1, "[", "]")
                after = self.toks[close + 1] if close + 1 < len(self.toks) else None
                if isinstance(base, (Arr, Ptr)) and (after is None or after.text not in ("[", ".", "->")):
                    idx = Evaluator(self.m, self.env, self.chain, self.w, self.guaranteed, self.file).eval(self.toks[self.i + 2:close])
                    if is_int(idx):
                        self.i = close + 1
                        return self._binop("+", base, idx)
            v = self._unary()
            if isinstance(v, (Arr, Ptr, Obj)):
                return v
            if isinstance(v, Sym) and v.text.startswith("fn:"):
                return v
            if name and (follow is None or follow.text not in (".", "->", "[")):
                if name not in self.env and isinstance(v, Sym):
                    return Obj(name)  # &global_struct
                home = self.env if name in self.env else (self.w.globals if self.w is not None and name in self.w.globals else None)
                if home is not None:
                    # &scalar: a one-element buffer (also a handle for field access). What a call writes into it flows
                    # back into the variable when the call returns (Walker.on_call).
                    cell = Arr([v])
                    if self.w is not None:
                        self.w._addr_cells.append((home, name, cell, v))
                    if not isinstance(v, Sym):
                        home[name] = Sym(f"{name}@")   # its address escapes: whatever is called may write it
                    return Ptr(cell, 0)
            if isinstance(v, Sym) and follow is not None and follow.text in (".", "->"):
                return Obj(v.text)  # &a.b / &dev->cfg: an object handle for that field path
            return Ptr(Arr([v]), 0)
        if t.text == "*":
            self._next()
            v = self._unary()
            if isinstance(v, Ptr):
                items = v.get(1)
                return items[0] if items else Sym("*ptr")
            if isinstance(v, Arr):
                return v.items[0] if v.items else Sym("*arr")
            return Sym(f"*{v!r}")
        if t.text == "sizeof":
            self._next()
            if self._peek() is not None and self._peek().text == "(":
                start = self.i
                end = _match(self.toks, self.i)
                inner = self.toks[start + 1:end]
                self.i = end + 1
                # sizes are counted in elements of the array they measure, so sizeof(a) / sizeof(a[0]) is a's length
                if len(inner) >= 4 and inner[0].kind == "id" and inner[1].text == "[" and _match(inner, 1, "[", "]") == len(inner) - 1:
                    arr = self.env.get(inner[0].text)
                    if isinstance(arr, Arr) or inner[0].text in self.m.global_vars or inner[0].text in self.m.global_arrays:
                        return 1
                if len(inner) == 1 and inner[0].kind == "id":
                    v = self.env.get(inner[0].text)
                    if v is None and self.w is not None and inner[0].text in self.m.global_vars:
                        v = self.w.global_value(inner[0].text)
                    if isinstance(v, Arr):
                        return len(v.items)
                    name = inner[0].text
                    if name in self.m.global_sizes:
                        size = Evaluator(self.m, {}, self.chain).eval(self.m.global_sizes[name])
                        if is_int(size):
                            return size
                    if name in self.m.global_arrays:
                        arr = self.m_const(name, 0)
                        if isinstance(arr, Arr):
                            return len(arr.items)
                    if name in ("uint8_t", "int8_t", "char", "unsigned char", "byte"):
                        return 1
                    if name in ("uint16_t", "int16_t", "short"):
                        return 2
                    if name in ("uint32_t", "int32_t", "int", "float"):
                        return 4
                return Sym("sizeof")
            nxt, br = self._peek(), self._peek(1)
            if nxt is not None and nxt.kind == "id" and br is not None and br.text == "[":   # sizeof a[0]: one element
                end = _match(self.toks, self.i + 1, "[", "]")
                if isinstance(self.env.get(nxt.text), Arr) or nxt.text in self.m.global_vars or nxt.text in self.m.global_arrays:
                    self.i = end + 1
                    return 1
            v = self._unary()
            return len(v.items) if isinstance(v, Arr) else Sym("sizeof")
        if t.text == "(":
            end = _match(self.toks, self.i)
            inner = self.toks[self.i + 1:end]
            if _looks_type(inner, self.m.types):
                self.i = end + 1
                nxt = self._peek()
                if nxt is not None and nxt.text == "{":  # compound literal (uint8_t[]){a, b}
                    return self._postfix(self._init_list())
                v = self._unary()
                return self._cast(inner, v)
            self._next()
            v = self._expr(0)
            if self._peek() is not None and self._peek().text == ")":
                self._next()
            return self._postfix(v)
        if t.text == "{":
            return self._postfix(self._init_list())
        return self._postfix(self._primary())

    @staticmethod
    def _cast(type_toks: List[Tok], v: Any) -> Any:
        return c_convert(" ".join(t.text for t in type_toks), v)

    def _init_list(self) -> Arr:
        end = _match(self.toks, self.i, "{", "}")
        items = []
        for part in _split_args(self.toks[self.i + 1:end]):
            if not part:
                continue
            if len(part) > 2 and part[0].text == "[":  # designated [i] = v
                close = next(k for k, x in enumerate(part) if x.text == "]")
                part = part[close + 2:]
            items.append(Evaluator(self.m, self.env, self.chain, self.w, self.guaranteed, self.file).eval(part))
        self.i = end + 1
        return Arr(items)

    def _primary(self) -> Any:
        t = self._next()
        if t.kind == "num":
            return parse_number(t.text)
        if t.kind == "chr":
            return parse_char(t.text)
        if t.kind == "str":
            return Arr([ord(c) for c in t.text[1:-1]] + [0])
        if t.kind == "id":
            # C++ casts: static_cast<uint8_t>(x)
            if t.text in ("static_cast", "reinterpret_cast", "const_cast") and self._peek() is not None and self._peek().text == "<":
                close = next((k for k in range(self.i, len(self.toks)) if self.toks[k].text == ">"), None)
                if close is not None and close + 1 < len(self.toks) and self.toks[close + 1].text == "(":
                    type_toks = self.toks[self.i + 1:close]
                    end = _match(self.toks, close + 1)
                    v = Evaluator(self.m, self.env, self.chain, self.w, self.guaranteed, self.file).eval(self.toks[close + 2:end])
                    self.i = end + 1
                    return self._cast(type_toks, v) if t.text == "static_cast" else v
            # call?
            if self._peek() is not None and self._peek().text == "(":
                end = _match(self.toks, self.i)
                args = _split_args(self.toks[self.i + 1:end])
                self.i = end + 1
                bound = self.env.get(t.text)
                if isinstance(bound, Sym) and bound.text.startswith("fn:"):   # call through a function-pointer variable
                    return self._call(bound.text[3:], None, args, t)
                return self._call(t.text, None, args, t)
            # namespaced name a::b
            if self._peek() is not None and self._peek().text == "::" and self._peek(1) is not None:
                self._next()
                nxt = self._next()
                if self._peek() is not None and self._peek().text == "(":
                    end = _match(self.toks, self.i)
                    args = _split_args(self.toks[self.i + 1:end])
                    self.i = end + 1
                    return self._call(nxt.text, t.text, args, nxt)
                return self._lookup(nxt.text)
            return self._lookup(t.text)
        if t.text == ")":
            return None
        return Sym(t.text)

    def _lookup(self, name: str) -> Any:
        if name in self.env:
            return self.env[name]
        if name in ("true",):
            return 1
        if name in ("false", "NULL", "nullptr"):
            return 0
        here = self.w.this() if self.w is not None else None
        if name == "this" and here is not None:
            return here[0]
        if here is not None and name not in self.m.macros and name not in self.m.consts and name not in self.m.functions \
                and name not in self.m.global_arrays and name not in self.m.global_objects:
            key = obj_key(here[0])
            if (key, name) in self.w.fields or name not in self.m.global_vars:
                return self.w.fields.get((key, name), Sym(f"{key}.{name}"))   # a member of the current object
        if name in self.m.global_objects:
            return Obj(name)
        if self.w is not None and name in self.m.global_vars:
            return self.w.global_value(name)
        return self.m_const(name, 0)

    def m_const(self, name: str, depth: int) -> Any:
        if depth > 12:
            return Sym(name)
        kind, found = self.m.symbol(name, self.file)
        if kind == "macro" and found.params is None:
            if not found.body:
                return Sym(name)
            ev = Evaluator(self.m, {}, self.chain, None, True, self.file)
            ev._macro_depth = depth + 1
            v = ev.eval(found.body)
            return v if v is not None else Sym(name)
        if kind == "const":
            v = Evaluator(self.m, {}, self.chain, None, True, self.file).eval(found)
            return v if v is not None else Sym(name)
        if kind == "array":
            v = Evaluator(self.m, {}, self.chain, None, True, self.file).eval(found)
            return v if isinstance(v, Arr) else Sym(name)
        if name in self.m.functions or name in _PRIMITIVES:
            return Sym(f"fn:{name}")   # a function used as a value (callback, function pointer)
        return Sym(name)

    def _postfix(self, v: Any) -> Any:
        # the variable the value was read from, while no subscript or member has been applied: i++ updates it
        prev = self._peek(-1)
        var = prev.text if prev is not None and prev.kind == "id" and prev.text in self.env else None
        while True:
            t = self._peek()
            if t is None:
                return v
            if t.text in ("++", "--") and var is not None:
                self._next()
                if isinstance(v, (int, float, Ptr)):
                    self.env[var] = self._binop("+" if t.text == "++" else "-", v, 1)   # the value stays the old one
                var = None
                continue
            var = None
            if t.text == "[":
                end = _match(self.toks, self.i, "[", "]")
                idx = Evaluator(self.m, self.env, self.chain, self.w, self.guaranteed, self.file).eval(self.toks[self.i + 1:end])
                self.i = end + 1
                if isinstance(v, Arr) and is_int(idx) and 0 <= idx < len(v.items):
                    v = v.items[idx]
                elif isinstance(v, Ptr) and is_int(idx):
                    items = v.get(None)
                    v = items[idx] if 0 <= idx < len(items) else Sym("ptr[]")
                else:
                    v = Sym(f"{v!r}[{idx!r}]")
                continue
            if t.text in (".", "->"):
                self._next()
                member = self._next()
                if self._peek() is not None and self._peek().text == "(":
                    end = _match(self.toks, self.i)
                    args = _split_args(self.toks[self.i + 1:end])
                    self.i = end + 1
                    v = self._call(member.text, v, args, member, arrow=t.text)
                    continue
                key = obj_key(v)
                if key is not None and self.w is not None and (key, member.text) in self.w.fields:
                    v = self.w.fields[(key, member.text)]
                elif key is not None:
                    v = Sym(f"{key}.{member.text}")
                else:
                    v = Sym(f"{v!r}{t.text}{member.text}")
                continue
            if t.text in ("++", "--"):
                self._next()
                continue
            if t.text == "(" and isinstance(v, Sym) and v.text.startswith("fn:"):
                end = _match(self.toks, self.i)
                args = _split_args(self.toks[self.i + 1:end])
                self.i = end + 1
                v = self._call(v.text[3:], None, args, t)
                continue
            return v

    def _call(self, name: str, obj: Any, arg_toks: List[List[Tok]], tok: Tok, arrow: str = "") -> Any:
        if self.w is None:
            helper = _CONST_HELPERS.get(name) if obj is None else None
            if helper is not None:  # constant helpers inside macro bodies: #define REG_CONFIG _u(0xF5)
                args = [Evaluator(self.m, self.env, self.chain, None, self.guaranteed, self.file).eval(a) for a in arg_toks]
                return helper(None, args, self, tok.line)
            return Sym(f"{name}()")
        return self.w.on_call(name, obj, arg_toks, self, tok.line, arrow)


# ------------------------------------------------------------------ statement walker


class Walker:
    def __init__(self, model: FlowModel):
        self.m = model
        self.events: List[Event] = []
        self.notes: List[str] = []
        self.opaque: set = set()
        self._wire: Dict[str, Tuple[Any, List[Any]]] = {}   # object -> (addr, bytes) for Arduino Wire transactions
        self._stack: List[str] = []
        self._sites: List[int] = []
        self.fields: Dict[Tuple[str, str], Any] = {}        # (object, field) -> value, e.g. ('the_sensor', 'write') -> fn
        self._frames: List[Dict[str, bool]] = []
        self._this: List[Tuple[Any, str]] = []              # (object, class) of the method being walked
        self._iterating = 0                                 # > 0 inside an iterated loop: break/continue are live
        self.probe: Optional[Dict[int, int]] = None         # register -> byte the device returns (probe mode)
        self.spi_dummy = 0                                  # bytes an SPI read returns before the data (FlowModel.run)
        self.ptr: Dict[Any, int] = {}                       # bus address -> register pointer last written
        self._rxq: Dict[str, List[Any]] = {}                # Arduino Wire: bytes waiting for Wire.read()
        self._spitx: List[Any] = []                         # Arduino SPI: bytes of the open transaction (until CS/end)
        self._spi_at: Optional[Tuple[Any, int]] = None      # (evaluator, line) of its first transfer
        self._cmdlinks: Dict[str, List[Tuple[Any, ...]]] = {}   # ESP-IDF legacy i2c_cmd_handle_t -> queued operations
        self._cmd_n = 0
        self.obs_shifts: List[Tuple[RxByte, int, str, int]] = []  # (read byte, left shift, file, line): how bytes are assembled
        self.obs_masks: List[Tuple[RxByte, int, str, int]] = []   # (read byte, mask, file, line): which bits are tested
        self.obs_compares: List[Tuple[RxByte, int, str, int]] = []   # (read byte, constant, file, line): == / != tests
        self.outputs: List[Tuple[Any, int]] = []            # numbers the code prints (Serial.print, printf, ...)
        self.globals: Dict[str, Any] = {}                   # file-scope variables written during the walk
        self.values: List[Tuple[Any, str, str]] = []        # probe mode: every number the code computes (value, file:line, where)
        self.regs_written: Dict[Any, Dict[int, int]] = {}   # device -> register -> last value written (probe read-back)
        self._ltypes: Dict[Tuple[str, str], str] = {}      # (function, local) -> declared type
        self._last_env: Dict[str, Any] = {}
        self._addr_cells: List[Tuple[Dict[str, Any], str, Arr, Any]] = []   # (&x passed to a call): where x lives, its cell
        self._opaque_n = 0                                                  # calls into code the walk cannot see
        self.capture = ""                                                   # stop at the first call of this function and
        self.captured: Optional[Tuple[List[Any], Dict[str, Any], Dict[Tuple[str, str], Any], Any]] = None   # keep its inputs

    def note_value(self, v: Any, file: str, line: int, where: str) -> None:
        if self.probe is not None and isinstance(v, (int, float)) and not isinstance(v, bool) and len(self.values) < 20000:
            self.values.append((v, f"{file}:{line}", where))

    def rx(self, reg: Any, k: int, dev: Any = None) -> Any:
        """The value of byte k of a read that started at register `reg`: in probe mode the probe byte (or, for a register
        the probe does not set, the last value the code wrote there), otherwise a byte that remembers its register."""
        if not is_int(reg):
            return Sym("rx")
        r, j, n, msb = self.m.byte_slot(dev, reg, k)
        pos = (8 * (n - 1 - j) if msb else 8 * j) if n > 1 else 0
        if self.probe is not None:   # a wide register's probe value is the whole register: this byte is part of it
            v = self.probe[r] if r in self.probe else self.regs_written.get(repr(dev), {}).get(r, 0)
            return (v >> pos) & 0xFF if n > 1 else v
        return RxByte(r, dev if is_int(dev) else None, pos, 8 * n)

    def global_value(self, name: str) -> Any:
        """A file-scope variable: zero-initialised (as C does) or from its initializer, created on first use."""
        if name not in self.globals:
            size_toks, init_toks = self.m.global_vars[name]
            file = self.m.global_files.get(name, "")
            members = self.m.var_structs.get(name) or self.m.struct_of(self.m.global_type_text.get(name, ""))
            if init_toks and members and init_toks[0].text == "{":
                v = self.struct_value(name, members, init_toks, size_toks is not None, file)
            elif init_toks:
                v = Evaluator(self.m, {}, (), None, True, file).eval(init_toks)
                v = Arr(list(v.items)) if isinstance(v, Arr) else v
            elif size_toks is not None:
                size = Evaluator(self.m, {}, (), None).eval(size_toks) if size_toks else 0
                v = Arr([0] * (size if is_int(size) and 0 <= size <= 4096 else 0))
            else:
                kind = c_type_kind(self.m.global_type_text.get(name, ""))
                v = Obj(name) if kind is None else (0.0 if kind[0] == "float" else 0)
            self.globals[name] = v
        return self.globals[name]

    def struct_value(self, key: str, members: List[str], init: List[Tok], is_array: bool, file: str,
                     env: Optional[Dict[str, Any]] = None, chain: Tuple[str, ...] = ()) -> Any:
        """A struct (or array of structs) from its brace initializer: positional `{reg, val}` and designated
        `{ .addr = 0x76 }` members; members it does not name are 0, as in C. Each struct is an Obj whose fields the walk
        tracks (`cfg[1].val`, `dev.addr`)."""
        if not init or init[0].text != "{":
            return Evaluator(self.m, env or {}, chain, self, True, file).eval(init)
        inner = init[1:_match(init, 0, "{", "}")]
        if is_array:
            items = [x for x in _split_args(inner) if x]
            return Arr([self.struct_value(f"{key}[{k}]", members, item, False, file, env, chain) for k, item in enumerate(items)])
        for m in members:
            self.fields[(key, m)] = 0
        pos = 0
        for item in _split_args(inner):
            if not item:
                continue
            if len(item) >= 4 and item[0].text == "." and item[1].kind == "id" and item[2].text == "=":
                member, expr = item[1].text, item[3:]
                pos = members.index(member) + 1 if member in members else pos
            elif pos < len(members):
                member, expr = members[pos], item
                pos += 1
            else:
                break
            v = Evaluator(self.m, env or {}, chain, self, True, file).eval(expr)
            self.fields[(key, member)] = c_convert(self.m.field_types.get(member) or "", v)
        return Obj(key)

    def this(self) -> Optional[Tuple[Any, str]]:
        return self._this[-1] if self._this else None

    def construct(self, obj_name: str, cls: str, arg_toks: List[List[Tok]]) -> None:
        """Run a global object's constructor (member initializer list, then body) before the entry function, as the
        C++ runtime does: BMP388 bmp(0x76); -> fields bmp._addr = 0x76."""
        ctor = self.m.function(f"{cls}::{cls}")
        ev = Evaluator(self.m, {}, (f"{cls}::{cls}",), self, True, ctor.file if ctor else "")
        args = [ev.eval(a) for a in arg_toks]
        if ctor is None:
            return
        self.call(ctor, args, (), True, this=(Obj(obj_name), cls))

    # ---------------------------------------------------------- uncertain control flow
    _MISSING = object()

    @staticmethod
    def _same(a: Any, b: Any) -> bool:
        if a is b:
            return True
        if type(a) is not type(b) or isinstance(a, (Arr, Ptr)):
            return False
        return a == b

    def _uncertain(self, bodies: List[List[Tok]], env: Dict[str, Any], chain, file: str, may_skip: bool, loop: bool = False) -> None:
        """Run bodies of which at most one (or, for a loop, an unknown number) executes. Afterwards a variable or struct
        field keeps its value only if every path agrees; otherwise it becomes unknown (a 'phi' of the paths)."""
        base_env, base_fields = dict(env), dict(self.fields)
        outcomes: List[Tuple[Dict[str, Any], Dict[Tuple[str, str], Any]]] = []
        for body in bodies:
            e = dict(base_env)
            self.fields = dict(base_fields)
            self._run(body, e, chain, False, file, loop=loop)
            outcomes.append((e, self.fields))
        if may_skip:
            outcomes.append((base_env, base_fields))
        merged_env: Dict[str, Any] = {}
        for k in set().union(*(o[0].keys() for o in outcomes)):
            vals = [o[0].get(k, self._MISSING) for o in outcomes]
            first = vals[0]
            merged_env[k] = first if all(self._same(first, v) for v in vals[1:]) and first is not self._MISSING else Sym(f"phi:{k}")
        merged_fields: Dict[Tuple[str, str], Any] = {}
        for k in set().union(*(o[1].keys() for o in outcomes)):
            vals = [o[1].get(k, self._MISSING) for o in outcomes]
            first = vals[0]
            merged_fields[k] = first if all(self._same(first, v) for v in vals[1:]) and first is not self._MISSING else Sym(f"phi:{k[0]}.{k[1]}")
        env.clear()
        env.update(merged_env)
        self.fields = merged_fields

    # ---------------------------------------------------------- functions
    def call(self, fn: Function, args: List[Any], chain: Tuple[str, ...], guaranteed: bool, this: Optional[Tuple[Any, str]] = None) -> Any:
        if len(self._stack) >= MAX_DEPTH or fn.name in self._stack:
            self.notes.append(f"stopped at {' > '.join(chain + (fn.name,))} (recursion/depth limit)")
            return Sym(f"{fn.name}()")
        if self.capture and fn.name == self.capture and self._stack:
            self.captured = (list(args), dict(self.globals), dict(self.fields), this)
            raise _Captured()
        defaults = self.m.defaults.get(fn.name) or self.m.defaults.get(fn.name.split("::")[-1]) or {}
        env = {p: (args[k] if k < len(args) else
                   (Evaluator(self.m, {}, chain, None, True, fn.file).eval(defaults[k]) if k in defaults else Sym(p)))
               for k, p in enumerate(fn.params)}
        for k, p in enumerate(fn.params):   # an argument takes its parameter's type: f(int16_t raw) called with a uint16_t
            if k < len(fn.ptypes) and fn.ptypes[k]:
                env[p] = c_convert(fn.ptypes[k], env[p])
                self._ltypes[(fn.name, p)] = fn.ptypes[k]
        if this is None and fn.cls and self.this() and self.this()[1] == fn.cls:
            this = self.this()   # an unqualified call to another method of the same object
        self._stack.append(fn.name)
        self._frames.append({"may_return": False})
        if this is not None:
            self._this.append(this)
        try:
            key = obj_key(this[0]) if this is not None else None
            for member, expr in fn.init:   # constructor initializer list
                if key is not None:
                    if not [t for t in expr if t.text not in ("{", "}")]:
                        # value-initialised: _nvm_calib() / _calib{}. A struct member stays an object its fields are
                        # written into (storing 'nothing' as its value lost every later _nvm_calib.x = ... in the BMP388
                        # driver); a scalar is 0
                        mtype = self.m.field_types.get(member) or ""
                        if not self.m.struct_of(mtype) and re.search(r"\b(u?int\d*_t|int|long|short|char|bool|float|double|size_t)\b", mtype):
                            self.fields[(key, member)] = 0.0 if re.search(r"float|double", mtype) else 0
                        continue
                    self.fields[(key, member)] = Evaluator(self.m, env, chain + (fn.name,), self, guaranteed, fn.file).eval(expr)
            self.block(fn.body, env, chain + (fn.name,), guaranteed, fn.file)
            value = None
        except _Return as r:
            value = r.value
        finally:
            self._stack.pop()
            frame = self._frames.pop()
            if this is not None:
                self._this.pop()
            self._last_env = env
        # a return inside an uncertain branch means the caller cannot know which value comes back
        if frame["may_return"]:
            return Sym(f"{fn.name}()")
        value = c_convert(fn.rtype, value)   # int16_t f() { return (b[0] << 8) | b[1]; } returns a signed value
        self.note_value(value, fn.file, fn.line, f"{fn.name}() returns")
        return value

    def block(self, toks: List[Tok], env: Dict[str, Any], chain: Tuple[str, ...], guaranteed: bool, file: str) -> None:
        i, n = 0, len(toks)
        while i < n and len(self.events) < MAX_EVENTS:
            i = self.statement(toks, i, env, chain, guaranteed, file)

    def statement(self, toks: List[Tok], i: int, env: Dict[str, Any], chain: Tuple[str, ...], guaranteed: bool, file: str) -> int:
        t = toks[i]
        if t.cond:
            guaranteed = False   # depends on a #if the analysis cannot decide
        ev = lambda g: Evaluator(self.m, env, chain, self, g, file)  # noqa: E731
        if t.text == "{":
            end = _match(toks, i, "{", "}")
            self.block(toks[i + 1:end], env, chain, guaranteed, file)
            return end + 1
        if t.text == ";":
            return i + 1
        if t.kind == "id" and t.text in ("case", "default"):
            j = i
            while j < len(toks) and toks[j].text != ":":
                j += 1
            return j + 1
        if t.kind == "id" and t.text == "if":
            end = _match(toks, i + 1)
            cond = ev(guaranteed).eval(toks[i + 2:end])
            j = end + 1
            then_end = self._stmt_end(toks, j)
            has_else = then_end < len(toks) and toks[then_end].text == "else"
            else_end = self._stmt_end(toks, then_end + 1) if has_else else then_end
            if is_int(cond):  # constant condition: only the live branch
                if cond:
                    self._run(toks[j:then_end], env, chain, guaranteed, file)
                elif has_else:
                    self._run(toks[then_end + 1:else_end], env, chain, guaranteed, file)
            else:
                bodies = [toks[j:then_end]] + ([toks[then_end + 1:else_end]] if has_else else [])
                self._uncertain(bodies, env, chain, file, may_skip=not has_else)
            return else_end
        if t.kind == "id" and t.text in ("while", "for", "switch"):
            end = _match(toks, i + 1)
            head = toks[i + 2:end]
            body_end = self._stmt_end(toks, end + 1)
            body = toks[end + 1:body_end]
            if t.text == "for":
                parts = self._split_semis(head)
                if parts and parts[0]:
                    self._expr_stmt(parts[0], env, chain, guaranteed, file)
                cond_toks = parts[1] if len(parts) > 1 else []
                step_toks = parts[2] if len(parts) > 2 else []
                self._loop(body, cond_toks, step_toks, env, chain, guaranteed, file, counted=True)
            elif t.text == "while":
                self._loop(body, head, [], env, chain, guaranteed, file, counted=False)
            else:
                self._switch(ev(guaranteed).eval(head), body, env, chain, guaranteed, file)
            return body_end
        if t.kind == "id" and t.text == "do":
            body_end = self._stmt_end(toks, i + 1)
            j = body_end
            cond_toks: List[Tok] = []
            if j < len(toks) and toks[j].text == "while":
                end = _match(toks, j + 1)
                cond_toks = toks[j + 2:end]
                j = end + 1
            self._loop(toks[i + 1:body_end], cond_toks, [], env, chain, guaranteed, file, counted=False, do_first=True)
            return j + 1 if j < len(toks) and toks[j].text == ";" else j
        if t.kind == "id" and t.text == "return":
            semi = self._semi(toks, i)
            val = ev(guaranteed).eval(toks[i + 1:semi]) if semi > i + 1 else None
            if guaranteed:
                raise _Return(val)
            if self._frames:
                self._frames[-1]["may_return"] = True
            return semi + 1
        if t.kind == "id" and t.text in ("break", "continue") and guaranteed and self._iterating:
            raise _Break() if t.text == "break" else _Continue()
        if t.kind == "id" and t.text in ("break", "continue", "goto"):
            return self._semi(toks, i) + 1
        semi = self._semi(toks, i)
        self._expr_stmt(toks[i:semi], env, chain, guaranteed, file)
        return semi + 1

    def _switch(self, sel: Any, body: List[Tok], env, chain, guaranteed: bool, file: str) -> None:
        """A known selector runs from its case label (or default) to the first break, falling through like C; an
        unknown one makes each case a path that may run."""
        inner = body[1:-1] if body and body[0].text == "{" else body
        labels: List[Tuple[int, Any]] = []
        depth = 0
        for k, x in enumerate(inner):
            if x.text in ("(", "[", "{"):
                depth += 1
            elif x.text in (")", "]", "}"):
                depth -= 1
            elif depth == 0 and x.kind == "id" and x.text in ("case", "default"):
                colon = next((c for c in range(k + 1, len(inner)) if inner[c].text == ":"), len(inner))
                val = "default" if x.text == "default" else Evaluator(self.m, env, chain, None, guaranteed, file).eval(inner[k + 1:colon])
                labels.append((k, val))
        if is_int(sel):
            start = next((k for k, v in labels if is_int(v) and v == sel), None)
            if start is None:
                start = next((k for k, v in labels if v == "default"), None)
            if start is None:
                return
            self._iterating += 1   # break ends the switch
            try:
                self.block(inner[start:], env, chain, guaranteed, file)
            except _Break:
                pass
            finally:
                self._iterating -= 1
            return
        bodies = []
        for k, _v in labels:   # each case up to its first break
            depth, stop = 0, len(inner)
            for c in range(k, len(inner)):
                x = inner[c].text
                if x in ("(", "[", "{"):
                    depth += 1
                elif x in (")", "]", "}"):
                    depth -= 1
                elif depth == 0 and x == "break":
                    stop = c
                    break
            bodies.append(inner[k:stop])
        self._uncertain(bodies or [inner], env, chain, file, may_skip=True)

    def _run(self, toks: List[Tok], env, chain, guaranteed, file, loop: bool = False) -> None:
        try:
            self.block(toks, env, chain, guaranteed, file)
        except _Return:
            if guaranteed and not loop:
                raise
        except (_Break, _Continue):
            if not loop:
                raise

    def _loop(self, body: List[Tok], cond_toks: List[Tok], step_toks: List[Tok], env, chain, guaranteed: bool, file: str,
              counted: bool, do_first: bool = False) -> None:
        """Iterate while the condition is known (counted loops always; while/do loops in probe mode, where device
        reads are concrete). An unknown condition walks the body once as a path that may or may not run."""
        ev = Evaluator(self.m, env, chain, self, guaranteed, file)
        iterate = counted or self.probe is not None
        n = 0
        while True:
            if not (do_first and n == 0):
                cond = ev.eval(cond_toks) if cond_toks else 1
                if not is_int(cond) or (not iterate and n == 0):
                    if n == 0:   # unknown (or not iterated): one possible pass
                        if is_int(cond) and cond == 0:
                            return
                        if is_int(cond) and cond:
                            self._run(body, env, chain, guaranteed, file, loop=True)
                        else:
                            self._uncertain([body], env, chain, file, may_skip=True, loop=True)
                    return
                if not cond:
                    return
            if n >= MAX_ITER or len(self.events) >= MAX_EVENTS:
                self.notes.append(f"loop at {file}:{(body[0].line if body else 0)} did not end within {MAX_ITER} iterations")
                return
            self._iterating += 1
            try:
                self.block(body, env, chain, guaranteed, file)
            except _Break:
                return
            except _Continue:
                pass
            except _Return:
                raise
            finally:
                self._iterating -= 1
            if step_toks:
                self._expr_stmt(step_toks, env, chain, guaranteed, file)
            n += 1
            if not iterate:
                return

    @staticmethod
    def _semi(toks: List[Tok], i: int) -> int:
        depth = 0
        for j in range(i, len(toks)):
            x = toks[j].text
            if x in ("(", "[", "{"):
                depth += 1
            elif x in (")", "]", "}"):
                depth -= 1
                if depth < 0:
                    return j
            elif x == ";" and depth == 0:
                return j
        return len(toks)

    def _stmt_end(self, toks: List[Tok], j: int) -> int:
        """Index just past the statement starting at toks[j]."""
        if j >= len(toks):
            return j
        t = toks[j]
        if t.text == "{":
            return _match(toks, j, "{", "}") + 1
        if t.text == "if":
            end = _match(toks, j + 1)
            then_end = self._stmt_end(toks, end + 1)
            if then_end < len(toks) and toks[then_end].text == "else":
                return self._stmt_end(toks, then_end + 1)
            return then_end
        if t.text in ("while", "for", "switch"):
            end = _match(toks, j + 1)
            return self._stmt_end(toks, end + 1)
        if t.text == "do":
            b = self._stmt_end(toks, j + 1)
            if b < len(toks) and toks[b].text == "while":
                end = _match(toks, b + 1)
                return end + 2
            return b
        return self._semi(toks, j) + 1

    @staticmethod
    def _split_semis(toks: List[Tok]) -> List[List[Tok]]:
        out, cur, depth = [], [], 0
        for t in toks:
            if t.text in ("(", "[", "{"):
                depth += 1
            elif t.text in (")", "]", "}"):
                depth -= 1
            if t.text == ";" and depth == 0:
                out.append(cur)
                cur = []
            else:
                cur.append(t)
        out.append(cur)
        return out

    def _expr_stmt(self, toks: List[Tok], env: Dict[str, Any], chain, guaranteed: bool, file: str) -> None:
        """Declarations and expressions: track local variables and buffers, and evaluate calls in order."""
        if not toks:
            return
        parts = _split_args(toks)
        if len(parts) > 1 and not self._is_decl(toks):   # comma expression (a loop step 'i++, p++'): each part in order
            for part in parts:
                self._expr_stmt(part, env, chain, guaranteed, file)
            return
        texts = [t.text for t in toks]
        # i++ / ++i / i-- / --i as a statement (loop steps); a pointer steps to the next element
        if len(toks) == 2 and ("++" in texts or "--" in texts):
            name_tok = toks[0] if toks[1].text in ("++", "--") else toks[1]
            op = toks[1].text if toks[1].text in ("++", "--") else toks[0].text
            if name_tok.kind == "id":
                cur = Evaluator(self.m, env, chain, self, guaranteed, file).eval([name_tok])
                nxt = Evaluator._binop("+" if op == "++" else "-", cur, 1) if isinstance(cur, (int, float, Ptr)) else Sym(name_tok.text)
                self._assign([name_tok], nxt, env, chain, guaranteed, file)
                return
        ev = Evaluator(self.m, env, chain, self, guaranteed, file)
        # declarations:  [qualifiers] type name [N] = init , name2 = init2 ;
        if self._is_decl(toks):
            decl_start = self._decl_names_start(toks)
            decl_type = " ".join(x.text for x in toks[:decl_start] if x.text not in ("static", "const", "volatile", "register", "constexpr", "struct"))
            fn_name = chain[-1] if chain else ""
            type_ptr = any(x.text == "*" for x in toks[:decl_start])   # 'uint8_t *p = ...': the '*' ends up in the type part
            for n_part, part in enumerate(_split_args(toks[decl_start:])):
                if not part:
                    continue
                pt = [x.text for x in part]
                name_tok = next((x for x in part if x.kind == "id" and x.text not in _TYPE_WORDS and x.text != "const"), None)
                if name_tok is None:
                    continue
                name = name_tok.text
                ptr_decl = ("*" in pt[:pt.index(name)] if name in pt else False) or (type_ptr and n_part == 0)
                if not ptr_decl:
                    self._ltypes[(fn_name, name)] = decl_type
                members = self.m.struct_of(decl_type) if not ptr_decl else None
                if "=" in pt and members and pt[pt.index("=") + 1:pt.index("=") + 2] == ["{"]:
                    eq = pt.index("=")   # a struct, or an array of structs, from a brace initializer
                    env[name] = self.struct_value(name, members, part[eq + 1:], "[" in pt[:eq], file, env, chain)
                    continue
                if "=" in pt:
                    eq = pt.index("=")
                    val = Evaluator(self.m, env, chain, self, guaranteed, file).eval(part[eq + 1:])
                    if not ptr_decl and "[" not in pt[:eq]:
                        val = c_convert(decl_type, val)
                        self.note_value(val, file, name_tok.line, name)
                    if "[" in pt[:eq] and is_int(val):
                        val = Arr([val])
                    if ptr_decl and isinstance(val, (Arr, Ptr)):   # const uint8_t *p = buf: points into buf, no copy
                        env[name] = val if isinstance(val, Ptr) else Ptr(val, 0)
                        continue
                    if isinstance(val, Arr):
                        size = self._array_size(part[:eq], env)
                        if is_int(size) and size > len(val.items):
                            val.items.extend([0] * (size - len(val.items)))
                        val = Arr(list(val.items))  # each declaration owns its buffer
                    env[name] = val
                elif "[" in pt:
                    size = self._array_size(part, env)
                    env[name] = Arr([Sym(f"{name}[{k}]") for k in range(size if is_int(size) and size <= 1024 else 0)])
                else:
                    env[name] = Sym(name)
            return
        # assignment to a local: name = expr / name[idx] = expr / name op= expr
        for k, x in enumerate(texts):
            if x in Evaluator._ASSIGN and self._depth_at(toks, k) == 0:
                lhs, rhs = toks[:k], toks[k + 1:]
                val = Evaluator(self.m, env, chain, self, guaranteed, file).eval(rhs)
                if x != "=":   # the left side through the walker too: globals and members are known there
                    cur = Evaluator(self.m, env, chain, self, guaranteed, file).eval(lhs)
                    val = Evaluator._binop(x[:-1], cur, val)
                self._assign(lhs, val, env, chain, guaranteed, file)
                return
        ev.eval(toks)

    @staticmethod
    def _depth_at(toks: List[Tok], k: int) -> int:
        d = 0
        for t in toks[:k]:
            if t.text in ("(", "[", "{"):
                d += 1
            elif t.text in (")", "]", "}"):
                d -= 1
        return d

    def _assign(self, lhs: List[Tok], val: Any, env, chain, guaranteed, file) -> None:
        fn_name = chain[-1] if chain else ""
        if len(lhs) == 1 and lhs[0].kind == "id":
            name = lhs[0].text
            here = self.this()
            if name not in env and here is not None and ((obj_key(here[0]), name) in self.fields or name not in self.m.global_vars):
                val = c_convert(self.m.field_types.get(name) or "", val)
                self.fields[(obj_key(here[0]), name)] = val   # a member of the current object: _addr = addr;
            elif name not in env and name in self.m.global_vars:
                val = c_convert(self.m.global_type_text.get(name, ""), val)
                self.globals[name] = val
            else:
                val = c_convert(self._ltypes.get((fn_name, name), ""), val)
                env[name] = val
            self.note_value(val, file, lhs[0].line, name)
            return
        if len(lhs) >= 4 and lhs[0].kind == "id" and lhs[1].text == "[" and lhs[-1].text == "]":
            arr = env.get(lhs[0].text)
            if arr is None and lhs[0].text in self.m.global_vars:
                arr = self.global_value(lhs[0].text)
            elif arr is None and self.this() is not None:
                arr = self.fields.get((obj_key(self.this()[0]), lhs[0].text))
            idx = Evaluator(self.m, env, chain, self, guaranteed, file).eval(lhs[2:-1])
            target = arr.arr if isinstance(arr, Ptr) else arr
            base = arr.offset if isinstance(arr, Ptr) else 0
            name = lhs[0].text
            elem_type = (self._ltypes.get((fn_name, name)) if name in env else
                         self.m.global_type_text.get(name) if name in self.m.global_vars else self.m.field_types.get(name)) or ""
            val = c_convert(elem_type, val)
            if isinstance(target, Arr) and is_int(idx):
                j = base + idx
                if 0 <= j < 4096:
                    while len(target.items) <= j:
                        target.items.append(Sym("uninit"))
                    target.items[j] = val
            self.note_value(val, file, lhs[0].line, f"{name}[{idx!r}]")
            return
        if lhs and lhs[0].text == "*" and len(lhs) == 2 and lhs[1].kind == "id":
            p = env.get(lhs[1].text)
            if isinstance(p, Ptr) and p.offset < len(p.arr.items):
                p.arr.items[p.offset] = val
            return
        # struct field:  base.f = v  /  base->f = v   (function pointers, interface selectors, addresses)
        k = len(lhs) - 2
        if k >= 1 and lhs[-1].kind == "id" and lhs[k].text in (".", "->") and self._depth_at(lhs, k) == 0:
            base = Evaluator(self.m, env, chain, self, guaranteed, file).eval(lhs[:k])
            if len(lhs[:k]) == 1 and lhs[0].kind == "id" and lhs[0].text not in env and isinstance(base, Sym) and base.text == lhs[0].text:
                base = Obj(lhs[0].text)   # an unknown global struct (a member path like obj._calib keeps its key)
            key = obj_key(base)
            if key is not None:
                val = c_convert(self.m.field_types.get(lhs[-1].text) or "", val)
                self.fields[(key, lhs[-1].text)] = val
                self.note_value(val, file, lhs[-1].line, f"{key}.{lhs[-1].text}")
                return
        # anything else: evaluate for side effects (calls), value not tracked
        Evaluator(self.m, env, chain, self, guaranteed, file).eval(lhs)

    def _is_decl(self, toks: List[Tok]) -> bool:
        k = 0
        while k < len(toks) and toks[k].kind == "id" and toks[k].text in ("static", "const", "volatile", "register", "auto", "constexpr", "unsigned", "signed", "struct", "enum", "union"):
            k += 1
        if k >= len(toks) or toks[k].kind != "id":
            return False
        first = toks[k].text
        is_type = (first in _TYPE_WORDS or bool(_TYPE_RE.match(first)) or first in self.m.types or first.endswith("_t")
                   or first in self.m.struct_fields)   # a struct's name is a type, with or without 'struct' (C++)
        if not is_type:
            return False
        rest = toks[k + 1:]
        while rest and rest[0].text in ("*", "&", "const"):
            rest = rest[1:]
        return bool(rest) and rest[0].kind == "id"

    @staticmethod
    def _decl_names_start(toks: List[Tok]) -> int:
        k = 0
        while k < len(toks) and (toks[k].kind == "id" and (toks[k].text in _TYPE_WORDS or toks[k].text.endswith("_t") or bool(_TYPE_RE.match(toks[k].text))) or toks[k].text in ("*", "&")):
            k += 1
        # one more type name (typedef'd struct etc.) when another identifier follows it, directly or after '*' / '&':
        # 'struct inner *p = &dev->q' declares p (Bosch's parse_calib_data), not 'inner'
        j = k + 1
        while j < len(toks) and toks[j].text in ("*", "&"):
            j += 1
        if k + 1 < len(toks) and toks[k].kind == "id" and j < len(toks) and toks[j].kind == "id":
            k += 1
        while k < len(toks) and toks[k].text in ("*", "&"):
            k += 1
        return k

    def _array_size(self, toks: List[Tok], env) -> Any:
        texts = [t.text for t in toks]
        if "[" not in texts:
            return None
        lb = texts.index("[")
        rb = _match(toks, lb, "[", "]")
        if rb == lb + 1:
            return None
        return Evaluator(self.m, env, (), None).eval(toks[lb + 1:rb])

    # ---------------------------------------------------------- calls
    def on_call(self, name: str, obj: Any, arg_toks: List[List[Tok]], ev: Evaluator, line: int, arrow: str) -> Any:
        mark, opaque_before = len(self._addr_cells), self._opaque_n
        try:
            return self._on_call(name, obj, arg_toks, ev, line, arrow)
        finally:
            # variables passed by address (&x): take what the callee stored; if it stored nothing and everything it called
            # is known, x keeps its value; an unknown callee may have written it, so it stays unknown
            for home, var, cell, before in self._addr_cells[mark:]:
                now = cell.items[0] if cell.items else before
                if now is not before:
                    home[var] = now
                elif self._opaque_n == opaque_before:
                    home[var] = before
            del self._addr_cells[mark:]

    def _on_call(self, name: str, obj: Any, arg_toks: List[List[Tok]], ev: Evaluator, line: int, arrow: str) -> Any:
        prim = _PRIMITIVES.get(name)
        args = [Evaluator(self.m, ev.env, ev.chain, self, ev.guaranteed, ev.file).eval(a) for a in arg_toks]
        if name in _PRINT_FUNCS and (obj is not None or name in ("printf", "sprintf", "snprintf", "printk") or name.startswith(("ESP_LOG", "LOG_"))):
            for a in args:
                if isinstance(a, (int, float)) and not isinstance(a, bool):
                    self.outputs.append((a, line))
                    self.note_value(a, ev.file, line, f"printed by {name}()")
            if name in ("print", "println", "printf", "printk") or name.startswith(("ESP_LOG", "LOG_")):
                return 1
        if obj is not None:
            # a function pointer the walk saw being stored in this object's field: dev->write = &i2c_write
            key = obj_key(obj)
            fv = self.fields.get((key, name)) if key is not None else None
            if isinstance(fv, Sym) and fv.text.startswith("fn:"):
                fn = self.m.function(fv.text[3:], ev.file)
                if fn is not None and fn.name not in self._stack:
                    return self._inline(fn, args, ev, line)
        if obj is not None and name in _SPI_METHODS and "spi" in repr(obj).lower():
            return self._spi_call(name, args, ev, line)
        if obj is not None and name in _WIRE_METHODS and not (name in ("write", "read") and arrow == "->" and len(args) >= 3) and not (name == "read" and args):
            return self._wire_call(name, obj, args, ev, line)
        if obj is not None:
            # otherwise: a project function some code stores in a field of that name (vtable, Bosch-style callbacks) —
            # unless we are already inside one of them, in which case this call is the layer below (e.g. Adafruit BusIO)
            cands = self.m.fnptr_candidates(name)
            if cands and not any(self.m.function(c) is not None and self.m.function(c).name in self._stack for c in cands):
                fn = self.m.function(cands[0])
                if fn is not None:
                    if len(cands) > 1:
                        self.notes.append(f"{name}() could be {', '.join(cands)}; followed {cands[0]}")
                    return self._inline(fn, args, ev, line)
            # a method of a project class:  bmp.begin()  /  this->readRegister(...)
            owner = self.m.global_objects.get(key, (None,))[0] if key is not None else None
            if owner is None and isinstance(obj, Obj) and self.this() and obj == self.this()[0]:
                owner = self.this()[1]
            method = self.m.function(f"{owner}::{name}") if owner else None
            if method is not None and method.cls != owner:
                method = None   # same short name in another class
            if method is not None and method.name not in self._stack:
                return self._inline(method, args, ev, line, this=(obj if isinstance(obj, Obj) else Obj(key or "obj"), method.cls), arg_toks=arg_toks)
            first_is_buffer = bool(args) and isinstance(args[0], (Ptr, Arr))
            if name in ("write", "write_then_read", "read") and len(args) >= 2 and (first_is_buffer or name == "write_then_read"):
                return _BUSIO_STYLE(self, name, args, ev, line)   # Adafruit BusIO: write(buf, len, stop, prefix, prefix_len)
            if name in _FNPTR_STYLE and len(args) >= 2:
                return _FNPTR_STYLE[name](self, args, ev, line)   # Bosch callbacks: write(reg, data, len, intf_ptr)
            fn = self.m.function(name, ev.file)
            if fn is not None and fn.params and len(fn.params) == len(args):
                return self._inline(fn, args, ev, line)
            self.opaque.add(f"{name}()")
            self._opaque_n += 1
            _opaque_fill(name, args)
            return Sym(f"{name}()")
        fn = self.m.function(name, ev.file)
        here = self.this()
        if here is not None:   # unqualified call inside a method: prefer the method of the same class
            fn = self.m.function(f"{here[1]}::{name}") or fn
        # the project's own definition is what runs, also under a name an SDK uses (its delay_ms(), its
        # i2c_write(reg, buf, len)); inside that definition the same name is the SDK's (Sensor::delay calling delay)
        if fn is not None and (prim is None or fn.name not in self._stack):
            return self._inline(fn, args, ev, line, arg_toks=arg_toks)
        if prim is not None:
            return prim(self, args, ev, line)
        self.opaque.add(f"{name}()")
        self._opaque_n += 1
        _opaque_fill(name, args)
        return Sym(f"{name}()")

    def _inline(self, fn: Function, args: List[Any], ev: Evaluator, line: int, this: Optional[Tuple[Any, str]] = None,
                arg_toks: Optional[List[List[Tok]]] = None) -> Any:
        self._sites.append(line)
        try:
            return self.call(fn, args, ev.chain, ev.guaranteed, this=this)
        finally:
            self._sites.pop()
            # C++ reference parameters: the caller's variable now holds what the callee left in it
            callee_env = self._last_env
            for k in fn.refs:
                at = arg_toks[k] if arg_toks and k < len(arg_toks) else None
                if at and len(at) == 1 and at[0].kind == "id" and k < len(fn.params):
                    val = callee_env.get(fn.params[k], Sym(f"{at[0].text}@ref"))
                    self._assign(at, val, ev.env, ev.chain, ev.guaranteed, ev.file)

    def emit(self, ev: Evaluator, line: int, **kw: Any) -> None:
        if kw.get("kind") == "write" and kw.get("reg") is None and kw.get("data") and is_int(kw["data"][0]):
            first = kw["data"][0]   # the register a following read starts at (SPI: bit 7 is the read flag)
            self.ptr[repr(kw.get("addr"))] = first & 0x7F if kw.get("bus") == "spi" else first
        spi_read_cmd = kw.get("bus") == "spi" and kw.get("reg") is None and kw.get("data") and is_int(kw["data"][0]) and kw["data"][0] & 0x80
        if kw.get("kind") == "write" and self.probe is not None and not spi_read_cmd:   # an SPI read command writes nothing
            data, reg = list(kw.get("data") or []), kw.get("reg")
            if reg is None and data and is_int(data[0]):
                reg, data = (data[0] & 0x7F if kw.get("bus") == "spi" else data[0]), data[1:]
            if is_int(reg):
                mem = self.regs_written.setdefault(repr(kw.get("addr")), {})
                for r, v in self.m.to_words(kw.get("addr"), reg, data[:64])[0]:   # whole values of wide registers
                    if is_int(r) and is_int(v):
                        mem[r] = v & ((1 << (8 * self.m.word_at(kw.get("addr"), r)[0])) - 1)
        if len(self.events) < MAX_EVENTS:
            self.events.append(Event(file=ev.file, line=line, chain=ev.chain, guaranteed=ev.guaranteed, sites=tuple(self._sites), **kw))

    def observe(self, op: str, a: Any, b: Any, file: str, line: int) -> None:
        """How the code uses bytes read from registers: shifts (assembling multi-byte values) and masks (testing bits).
        A wide register's value, once its bytes are put together in place (RxWord.whole), counts as the register."""
        def reg_value(v: Any) -> bool:
            return isinstance(v, RxByte) or isinstance(v, RxWord) and v.whole
        if op in ("==", "!=") and (reg_value(a) and is_int(b) or reg_value(b) and is_int(a)):
            rx_, c = (a, b) if reg_value(a) else (b, a)
            self.obs_compares.append((rx_, c, file, line))   # e.g. chip_id != 0x50: the value the code expects
        if op == "<<" and isinstance(a, RxByte) and is_int(b):
            self.obs_shifts.append((a, b, file, line))
        elif op == "&" and (reg_value(a) and is_int(b) or reg_value(b) and is_int(a)):
            rx_, m = (a, b) if reg_value(a) else (b, a)
            full = (1 << rx_.width) - 1 if isinstance(rx_, RxWord) else 0xFF
            # a mask that tests bits; not a complement that keeps the other bits in a read-modify-write (v & ~0x07)
            # nor an all-bits mask (id & 0xFF)
            if m > 0 and (m & full) != full:
                self.obs_masks.append((rx_, m, file, line))
        elif op in ("|", "+"):
            for x, other in ((a, b), (b, a)):
                if isinstance(x, RxByte) and isinstance(other, Sym) and _SHIFTED_RX.match(other.text):
                    self.obs_shifts.append((x, 0, file, line))   # the low byte of an assembled value: (msb << 8) | lsb

    # Arduino SPI: transfer() clocks one byte out and one in; a transaction runs from chip-select low (or
    # beginTransaction) to chip-select high (or endTransaction) and is emitted as one SPI transfer
    def _spi_byte(self, v: Any) -> Any:
        k = len(self._spitx)
        self._spitx.append(v)
        first = self._spitx[0]
        if k > 0 and is_int(first) and first & 0x80:   # a read: data after the command byte and any dummy bytes
            idx = k - 1 - self.spi_dummy
            if idx >= 0:
                return self.rx(first & 0x7F, idx, None)
        return Sym("rx")

    def spi_flush(self) -> None:
        if self._spitx and self._spi_at is not None:
            ev, line = self._spi_at
            self.emit(ev, line, kind="write", data=list(self._spitx), length=len(self._spitx), bus="spi", note="SPI")
        self._spitx, self._spi_at = [], None

    def _spi_call(self, name: str, args: List[Any], ev: Evaluator, line: int) -> Any:
        if name in ("beginTransaction", "endTransaction"):
            self.spi_flush()
            return None
        if self._spi_at is None:
            self._spi_at = (ev, line)
        if len(args) >= 2 and isinstance(args[0], (Arr, Ptr)):   # transfer(buf, n): in place, rx overwrites tx
            dst, off = _buf_slot(args[0])
            n = args[1]
            if dst is not None and is_int(n) and 0 <= n <= 4096:
                while len(dst.items) < off + n:
                    dst.items.append(Sym("uninit"))
                for k in range(n):
                    dst.items[off + k] = self._spi_byte(dst.items[off + k])
            return None
        if name == "transfer16" and args:
            v = args[0]
            hi = self._spi_byte((v >> 8) & 0xFF if is_int(v) else Sym("tx"))
            lo = self._spi_byte(v & 0xFF if is_int(v) else Sym("tx"))
            return (hi << 8) | lo if is_int(hi) and is_int(lo) else Sym("rx16")
        return self._spi_byte(args[0] if args else 0)

    def _wire_call(self, name: str, obj: Any, args: List[Any], ev: Evaluator, line: int) -> Any:
        key = repr(obj)
        if name == "readBytes" and args:   # Wire.readBytes(buf, n): n queued bytes into buf
            dst, off = _buf_slot(args[0])
            n = args[1] if len(args) > 1 else None
            q = self._rxq.get(key) or []
            if dst is not None and is_int(n) and 0 <= n <= 4096:
                while len(dst.items) < off + n:
                    dst.items.append(Sym("uninit"))
                for k in range(n):
                    dst.items[off + k] = q.pop(0) if q else Sym("rx")
            return n if is_int(n) else Sym("n")
        if name == "beginTransmission":
            self._wire[key] = (args[0] if args else None, [])
            return None
        if name == "write" and key in self._wire:
            addr, buf = self._wire[key]
            if len(args) >= 2:
                buf.extend(as_bytes(args[0], args[1]))
            elif args:
                v = args[0]
                buf.extend(v.items[:-1] if isinstance(v, Arr) and v.items and v.items[-1] == 0 else (as_bytes(v, None) if isinstance(v, (Arr, Ptr)) else [v]))
            return 1
        if name == "endTransmission":
            addr, buf = self._wire.pop(key, (None, []))
            self.emit(ev, line, kind="write", addr=addr, data=list(buf), length=len(buf), note="Wire")
            return 0
        if name == "requestFrom":
            addr = args[0] if args else None
            n = args[1] if len(args) > 1 else None
            reg = self.ptr.get(repr(addr))
            self._rxq[key] = [self.rx(reg, k, addr) for k in range(n)] if is_int(n) and 0 < n <= 512 else []
            self.emit(ev, line, kind="read", addr=addr, length=n, note="Wire")
            return n if is_int(n) else Sym("n")
        if name == "read":
            q = self._rxq.get(key)
            return q.pop(0) if q else Sym("rx")
        if name == "available":
            return len(self._rxq.get(key) or []) if key in self._rxq else Sym("available")
        return Sym(f"{name}()")


# ------------------------------------------------------------------ HAL primitives


def _us(v: Any, scale: int) -> Any:
    return int(v * scale) if isinstance(v, (int, float)) else (Sym(f"{v!r}*{scale}") if v is not None else None)


def _delay(scale: int):
    def h(w: Walker, a: List[Any], ev: Evaluator, line: int) -> Any:
        w.emit(ev, line, kind="delay", delay_us=_us(a[0] if a else None, scale))
        return None
    return h


def _ret(n: Any, ok: Optional[int]) -> Any:
    """What a bus call returns on success: pico-sdk the byte count, HAL / ESP-IDF / Zephyr a status where 0 is success
    (so `if (i2c_write_dt(...)) return -EIO;` is not an error path that is always taken)."""
    if ok is not None:
        return ok
    return n if is_int(n) else Sym("ret")


def _write_buf(addr_i: int, buf_i: int, len_i: int, bus: str = "i2c", addr_shift: int = 0, ok: Optional[int] = None):
    def h(w: Walker, a: List[Any], ev: Evaluator, line: int) -> Any:
        addr = a[addr_i] if addr_i >= 0 and addr_i < len(a) else None
        if is_int(addr) and addr_shift:
            addr >>= addr_shift
        n = a[len_i] if len_i < len(a) else None
        w.emit(ev, line, kind="write", addr=addr, data=as_bytes(a[buf_i] if buf_i < len(a) else None, n), length=n, bus=bus)
        return _ret(n, ok)
    return h


def taint(v: Any, n: Any = None, w: Optional["Walker"] = None, reg: Any = None, dev: Any = None) -> None:
    """A read fills its destination with device data: bytes that remember their register (or, in probe mode, the
    probe's bytes). Nothing about their value is known at build time."""
    target, base = (v.arr, v.offset) if isinstance(v, Ptr) else ((v, 0) if isinstance(v, Arr) else (None, 0))
    if target is None:
        return
    if is_int(n) and len(target.items) < base + n <= base + 4096:
        target.items.extend([Sym("uninit")] * (base + n - len(target.items)))
    end = len(target.items) if not is_int(n) else min(len(target.items), base + n)
    for k in range(base, end):
        target.items[k] = w.rx(reg, k - base, dev) if w is not None else Sym("rx")


def _read_buf(addr_i: int, len_i: int, bus: str = "i2c", addr_shift: int = 0, dst_i: int = 2, ok: Optional[int] = None):
    def h(w: Walker, a: List[Any], ev: Evaluator, line: int) -> Any:
        addr = a[addr_i] if addr_i >= 0 and addr_i < len(a) else None
        if is_int(addr) and addr_shift:
            addr >>= addr_shift
        n = a[len_i] if len_i < len(a) else None
        if dst_i < len(a):
            taint(a[dst_i], n, w, w.ptr.get(repr(addr)), addr)
        w.emit(ev, line, kind="read", addr=addr, length=n, bus=bus)
        return _ret(n, ok)
    return h


def _mem_write(addr_i: int, reg_i: int, buf_i: int, len_i: int, addr_shift: int = 0, bus: str = "i2c"):
    def h(w: Walker, a: List[Any], ev: Evaluator, line: int) -> Any:
        addr = a[addr_i] if addr_i >= 0 and addr_i < len(a) else None
        if is_int(addr) and addr_shift:
            addr >>= addr_shift
        n = a[len_i] if len_i < len(a) else None
        w.emit(ev, line, kind="write", addr=addr, reg=a[reg_i] if reg_i < len(a) else None,
               data=as_bytes(a[buf_i] if buf_i < len(a) else None, n), length=n, bus=bus, note="mem")
        return 0
    return h


def _mem_read(addr_i: int, reg_i: int, len_i: int, addr_shift: int = 0, bus: str = "i2c", dst_i: Optional[int] = None):
    def h(w: Walker, a: List[Any], ev: Evaluator, line: int) -> Any:
        addr = a[addr_i] if addr_i >= 0 and addr_i < len(a) else None
        if is_int(addr) and addr_shift:
            addr >>= addr_shift
        d = dst_i if dst_i is not None else (len_i - 1)
        if 0 <= d < len(a):
            taint(a[d], a[len_i] if len_i < len(a) else None, w, a[reg_i] if reg_i < len(a) else None, addr)
        w.emit(ev, line, kind="read", addr=addr, reg=a[reg_i] if reg_i < len(a) else None,
               length=a[len_i] if len_i < len(a) else None, bus=bus, note="mem")
        return 0
    return h


def _reg_write_byte(addr_i: int, reg_i: int, val_i: int):
    def h(w: Walker, a: List[Any], ev: Evaluator, line: int) -> Any:
        addr = a[addr_i] if addr_i >= 0 and addr_i < len(a) else None
        w.emit(ev, line, kind="write", addr=addr, reg=a[reg_i] if reg_i < len(a) else None,
               data=[a[val_i] if val_i < len(a) else None], length=1, note="mem")
        return 0
    return h


def _write_read(addr_i: int, wbuf_i: int, wlen_i: int, rlen_i: int, bus: str = "i2c"):
    def h(w: Walker, a: List[Any], ev: Evaluator, line: int) -> Any:
        addr = a[addr_i] if addr_i >= 0 and addr_i < len(a) else None
        wn = a[wlen_i] if wlen_i < len(a) else None
        w.emit(ev, line, kind="write", addr=addr, data=as_bytes(a[wbuf_i] if wbuf_i < len(a) else None, wn), length=wn, bus=bus)
        if rlen_i - 1 < len(a):
            first = as_bytes(a[wbuf_i] if wbuf_i < len(a) else None, 1)
            taint(a[rlen_i - 1], a[rlen_i] if rlen_i < len(a) else None, w, first[0] if first else None, addr)
        w.emit(ev, line, kind="read", addr=addr, length=a[rlen_i] if rlen_i < len(a) else None, bus=bus)
        return 0
    return h


def _reg_read_byte(addr_i: int, reg_i: int, dst_i: int):
    """Zephyr i2c_reg_read_byte(dev, addr, reg, &value): one register byte into *value."""
    def h(w: Walker, a: List[Any], ev: Evaluator, line: int) -> Any:
        addr = a[addr_i] if 0 <= addr_i < len(a) else None
        reg = a[reg_i] if reg_i < len(a) else None
        if dst_i < len(a):
            taint(a[dst_i], 1, w, reg, addr)
        w.emit(ev, line, kind="read", addr=addr, reg=reg, length=1, note="mem")
        return 0
    return h


def _spi_fill(w: Walker, v: Any, n: Any, skip: int, reg: Any) -> None:
    """Fill an SPI receive buffer: `skip` junk bytes (the command byte's slot, then the part's dummy bytes), then the
    register data from `reg` on."""
    dst, off = _buf_slot(v)
    if dst is None:
        return
    if is_int(n) and n <= skip:
        taint(Ptr(dst, off), n)
        return
    taint(Ptr(dst, off + skip), n - skip if is_int(n) else None, w, reg)
    if skip:
        taint(Ptr(dst, off), skip)


def _spi_transfer(tx_i: int, rx_i: Optional[int], len_i: int, ok: Optional[int] = None):
    """An SPI write, or a full-duplex transfer that also fills rx. The byte clocked in while the command byte goes out is
    junk (and any dummy byte the part sends); after a read command (bit 7 set) the rest is the register data."""
    def h(w: Walker, a: List[Any], ev: Evaluator, line: int) -> Any:
        n = a[len_i] if len_i < len(a) else None
        tx = as_bytes(a[tx_i] if tx_i < len(a) else None, n)
        w.emit(ev, line, kind="write", data=tx, length=n, bus="spi")
        if rx_i is not None and rx_i < len(a):
            first = tx[0] if tx else None
            if is_int(first) and first & 0x80:
                _spi_fill(w, a[rx_i], n, 1 + w.spi_dummy, first & 0x7F)
            else:
                taint(a[rx_i], n)
        return _ret(n, ok)
    return h


def _spi_read(dst_i: int, len_i: int, ok: Optional[int] = None):
    """spi_read_blocking / HAL_SPI_Receive: the data of the register the previous write pointed at (after any dummy byte)."""
    def h(w: Walker, a: List[Any], ev: Evaluator, line: int) -> Any:
        n = a[len_i] if len_i < len(a) else None
        if dst_i < len(a):
            _spi_fill(w, a[dst_i], n, w.spi_dummy, w.ptr.get(repr(None)))
        w.emit(ev, line, kind="read", length=n, bus="spi")
        return _ret(n, ok)
    return h


def _vtask_delay(w: Walker, a: List[Any], ev: Evaluator, line: int) -> Any:
    """vTaskDelay(n) / osDelay(n): the task wakes at the n-th tick from now, and the call comes part-way through a tick, so
    only n - 1 whole tick periods are certain (vTaskDelay(1) can return almost at once)."""
    n = a[0] if a else None
    hz = w.m.tick_hz
    if isinstance(n, float) and math.isfinite(n):
        n = int(n)
    if is_int(n):
        assumed = f"the project does not state its FreeRTOS tick rate; {hz} Hz assumed" if w.m.tick_assumed else ""
        w.emit(ev, line, kind="delay", delay_us=max(0, n - 1) * 1_000_000 // hz,
               note=f"vTaskDelay({n}) at {hz} Hz: at least {max(0, n - 1)} whole tick(s)", assumed=assumed)
    else:
        w.emit(ev, line, kind="delay", delay_us=Sym(f"ticks({n!r})") if n is not None else None)
    return None


def _ms_to_ticks(w: Walker, a: List[Any], ev: Evaluator, line: int) -> Any:
    """pdMS_TO_TICKS(ms) = ms * configTICK_RATE_HZ / 1000 in integer arithmetic: at 100 Hz, 2 ms is 0 ticks."""
    ms = a[0] if a else None
    if isinstance(ms, (int, float)) and not isinstance(ms, bool) and math.isfinite(ms):
        return int(ms) * w.m.tick_hz // 1000
    return Sym(f"pdMS_TO_TICKS({ms!r})")


def _k_sleep(w: Walker, a: List[Any], ev: Evaluator, line: int) -> Any:
    w.emit(ev, line, kind="delay", delay_us=a[0] if a else None)
    return None


def _pure(fn):
    def h(w: "Walker", a: List[Any], ev: "Evaluator", line: int) -> Any:
        try:
            return fn(*a) if a and all(isinstance(x, (int, float)) for x in a) else Sym("expr")
        except (TypeError, ValueError, OverflowError):
            return Sym("expr")
    return h


