def _buf_slot(v: Any) -> Tuple[Optional[Arr], int]:
    if isinstance(v, Ptr):
        return v.arr, v.offset
    if isinstance(v, Arr):
        return v, 0
    return None, 0


_READ_ONLY_CALLS = {"memcmp", "strlen", "strnlen", "strcmp", "strncmp", "strchr", "crc8", "crc16", "crc32", "atoi", "strtol"}
_FRESH_ELEM = re.compile(r"^\w+\[\d+\]$")


def _opaque_fill(name: str, args: List[Any]) -> None:
    """An unknown function handed a buffer that holds no data yet (zero-initialised or never written) is most likely
    filling it — a receive buffer (Wire.readBytes, a vendor read API): afterwards its bytes are unknown, not still zero,
    so a check such as `if (id != 0x60) return false;` is not decided by the initializer."""
    if name in _READ_ONLY_CALLS:
        return
    for a in args:
        dst, off = _buf_slot(a)
        items = dst.items[off:] if dst is not None else []
        if items and all((isinstance(x, Sym) and (x.text == "uninit" or _FRESH_ELEM.match(x.text))) or
                         (is_int(x) and x == 0) for x in items):
            taint(a, None)


def _memcpy(w: Walker, a: List[Any], ev: Evaluator, line: int) -> Any:
    """memcpy/memmove(dst, src, n) between byte buffers the walk tracks (other destinations become unknown)."""
    if len(a) < 3:
        return Sym("memcpy()")
    (dst, d0), (src, s0), n = _buf_slot(a[0]), _buf_slot(a[1]), a[2]
    if dst is not None and src is not None and is_int(n) and 0 <= n <= 4096:
        items = [src.items[s0 + k] if s0 + k < len(src.items) else Sym("uninit") for k in range(n)]
        while len(dst.items) < d0 + n:
            dst.items.append(Sym("uninit"))
        dst.items[d0:d0 + n] = items
    elif dst is not None:
        taint(a[0], n)
    return a[0]


def _memset(w: Walker, a: List[Any], ev: Evaluator, line: int) -> Any:
    if len(a) < 3:
        return Sym("memset()")
    (dst, d0), v, n = _buf_slot(a[0]), a[1], a[2]
    if dst is not None and is_int(n) and 0 <= n <= 4096:
        while len(dst.items) < d0 + n:
            dst.items.append(0)
        for k in range(n):
            dst.items[d0 + k] = (v & 0xFF) if is_int(v) else Sym("memset")
    return a[0]


_PRIMITIVES.update({"memcpy": _memcpy, "memmove": _memcpy, "memset": _memset})


def _fnptr_write(w: Walker, a: List[Any], ev: Evaluator, line: int) -> Any:
    # Bosch API: write(reg_addr, const uint8_t *data, uint32_t len, void *intf_ptr)
    n = a[2] if len(a) > 2 else None
    w.emit(ev, line, kind="write", reg=a[0], data=as_bytes(a[1], n), length=n, note="fnptr")
    return 0


def _fnptr_read(w: Walker, a: List[Any], ev: Evaluator, line: int) -> Any:
    if len(a) > 1:
        taint(a[1], a[2] if len(a) > 2 else None, w, a[0])
    w.emit(ev, line, kind="read", reg=a[0], length=a[2] if len(a) > 2 else None, note="fnptr")
    return 0


def _fnptr_delay_us(w: Walker, a: List[Any], ev: Evaluator, line: int) -> Any:
    w.emit(ev, line, kind="delay", delay_us=a[0] if a else None, note="fnptr")
    return None


_FNPTR_STYLE = {"write": _fnptr_write, "read": _fnptr_read, "delay_us": _fnptr_delay_us,
                "delay_ms": lambda w, a, ev, line: (w.emit(ev, line, kind="delay", delay_us=_us(a[0] if a else None, 1000), note="fnptr"), None)[1]}


def _BUSIO_STYLE(w: Walker, name: str, a: List[Any], ev: Evaluator, line: int) -> Any:
    """Adafruit_BusIO: dev->write(buf, len, stop, prefix, prefix_len), dev->write_then_read(wbuf, wlen, rbuf, rlen), dev->read(buf, len)."""
    if name == "write":
        data = as_bytes(a[0], a[1] if len(a) > 1 else None)
        if len(a) >= 5:
            data = as_bytes(a[3], a[4]) + data
        w.emit(ev, line, kind="write", data=data, length=len(data), note="busio")
    elif name == "write_then_read":
        wb = as_bytes(a[0], a[1] if len(a) > 1 else None)
        w.emit(ev, line, kind="write", data=wb, length=a[1] if len(a) > 1 else None, note="busio")
        if len(a) > 2:
            taint(a[2], a[3] if len(a) > 3 else None, w, wb[0] if wb else None)
        w.emit(ev, line, kind="read", length=a[3] if len(a) > 3 else None, note="busio")
    else:   # read(buf, len): the register the previous write pointed at
        taint(a[0], a[1] if len(a) > 1 else None, w, w.ptr.get(repr(None)))
        w.emit(ev, line, kind="read", length=a[1] if len(a) > 1 else None, note="busio")
    return 1


# ------------------------------------------------------------------ normalisation


def normalize(events: List[Event], model: Optional["FlowModel"] = None) -> List[Event]:
    """Raw bus transfers -> register operations.

    * a write of [reg, data...] is a register write;
    * a write of [reg] immediately followed by a read of the same device is a register read;
    * on SPI, bit 7 of the first byte marks a read (Bosch convention) and the register is the low 7 bits;
    * on a device with registers wider than a byte (model.words), a write's data become register values, one per
      register, in the byte order on record.
    """
    out = _normalize(events)
    if model is None or not model.words:
        return out
    for k, e in enumerate(out):
        if e.kind in ("write", "read") and is_int(e.reg) and e.word == 1 and model.word_at(e.addr, e.reg)[0] > 1:
            n = model.word_at(e.addr, e.reg)[0]
            if e.kind == "write":
                pairs, extra = model.to_words(e.addr, e.reg, e.data)
                out[k] = replace(e, data=[v for _, v in pairs], word=n, extra=extra)
            else:
                out[k] = replace(e, word=n)
    return out


def _normalize(events: List[Event]) -> List[Event]:
    out: List[Event] = []
    i = 0
    while i < len(events):
        e = events[i]
        if e.kind == "write" and e.reg is None:
            first = e.data[0] if e.data else None
            rest = e.data[1:]
            nxt = events[i + 1] if i + 1 < len(events) else None
            spi_read = e.bus == "spi" and is_int(first) and first & 0x80
            # on SPI the read flag (bit 7) makes a register byte a read; a register byte without it followed by a read
            # is still read as one, marked: the device takes it as a write command (verify reports it)
            unflagged = e.bus == "spi" and len(e.data) == 1 and is_int(first) and not first & 0x80
            if (len(e.data) == 1 or spi_read) and nxt is not None and nxt.kind == "read" and nxt.reg is None and (nxt.addr == e.addr or nxt.addr is None or e.addr is None):
                reg = first & 0x7F if spi_read else first
                out.append(Event("read", addr=e.addr, reg=reg, length=nxt.length, file=e.file, line=e.line, chain=e.chain,
                                 guaranteed=e.guaranteed and nxt.guaranteed, bus=e.bus,
                                 note="spi_no_read_flag" if unflagged else e.note, sites=e.sites))
                i += 2
                continue
            if spi_read:
                out.append(Event("read", addr=e.addr, reg=first & 0x7F, length=max(0, len(e.data) - 1), file=e.file, line=e.line,
                                 chain=e.chain, guaranteed=e.guaranteed, bus=e.bus, note=e.note, sites=e.sites))
                i += 1
                continue
            reg = first & 0x7F if (e.bus == "spi" and is_int(first)) else first
            out.append(Event("write", addr=e.addr, reg=reg, data=rest, length=len(rest), file=e.file, line=e.line,
                             chain=e.chain, guaranteed=e.guaranteed, bus=e.bus, note=e.note, sites=e.sites))
            i += 1
            continue
        out.append(e)
        i += 1
    return out


def _write_readings(e: Event) -> List[List[Tuple[Any, Any]]]:
    """The ways a write event can be read as (register, value) pairs: consecutive registers (auto-increment), and with an
    odd number of data bytes >= 3 also register/value pairs (reg0 v0 reg1 v1 ..., Bosch multi-register writes). Data of
    wide registers (e.word > 1) are register values already: one reading."""
    if e.kind != "write":
        return []
    consecutive = [((e.reg + k) if is_int(e.reg) else e.reg, v) for k, v in enumerate(e.data)]
    if len(e.data) >= 3 and len(e.data) % 2 == 1 and e.word == 1:
        return [consecutive, [(e.reg, e.data[0])] + [(e.data[k], e.data[k + 1]) for k in range(1, len(e.data) - 1, 2)]]
    return [consecutive]


def write_reading(e: Event, mapped: Optional[Callable[[int], bool]] = None) -> Optional[List[Tuple[Any, Any]]]:
    """The one reading of a write event, or None while it is ambiguous. With a register map (`mapped(r)`: r is a register
    of that device) the reading whose registers are all in the map wins when the other's are not."""
    readings = _write_readings(e)
    if len(readings) <= 1:
        return readings[0] if readings else []
    if mapped is None:
        return None
    fits = [all(is_int(r) and mapped(r) for r, _ in rd) for rd in readings]
    return readings[fits.index(True)] if fits.count(True) == 1 else None


def writes_of(e: Event, mapped: Optional[Callable[[int], bool]] = None) -> List[Tuple[Any, Any]]:
    """(register, value) pairs a write event stands for: its one reading, or every pair of every reading while ambiguous."""
    one = write_reading(e, mapped)
    return one if one is not None else [p for rd in _write_readings(e) for p in rd]

embedforge/truth/knowledge.py:
"""The project's requirements memory: every rule sentence ('must', 'should', 'before', 'wait', 'only'...) of the
datasheet sections the code depends on becomes a numbered requirement, kept in requirements.json across runs.

A requirement is covered when a recorded truth item (a fact, register, layout, burst, formula, sequence or constraint)
quotes text inside it; otherwise the agent resolves it explicitly: implemented (the code does it; said how) or
not_applicable (why: a board-level rule, a feature the code does not use). verify fails while one is open, so every
rule the datasheet states for what the code does is considered, not just the ones a keyword search happened to reach.
This is the requirements-traceability practice of certified development (DO-178C, ISO 26262), for one part's datasheet."""

import json
import re
import threading
from dataclasses import asdict, dataclass, field
from pathlib import Path
from typing import Any, Dict, Iterable, List, Optional, Tuple

from embedforge.core.files import load_json, write_atomic

STATUSES = ("open", "covered", "implemented", "not_applicable")


@dataclass
class Requirement:
    id: str
    source_id: str
    section: str          # '3.10.1 Data register shadowing'
    text: str
    start: int            # span of the sentence in the source text
    end: int
    status: str = "open"
    refs: List[str] = field(default_factory=list)   # truth items that quote it (covered)
    reason: str = ""                                # how the code implements it / why it does not apply
    review: Dict[str, str] = field(default_factory=dict)   # the independent reviewer's verdict on the claim
    ref: str = ""                                   # the record the agent cites for an 'implemented' claim
    disputes: int = 0                               # how often the reviewer disagreed with a claim about it


class Requirements:
    """requirements.json next to ledger.json."""

    def __init__(self, root: Path):
        self.path = Path(root) / "requirements.json"
        self._lock = threading.Lock()
        self.items: Dict[str, Requirement] = {}
        for r in load_json(self.path, []):
            try:
                self.items[r["id"]] = Requirement(**r)
            except (TypeError, KeyError):
                pass

    def _save(self) -> None:
        write_atomic(self.path, json.dumps([asdict(r) for r in self.items.values()], indent=1))

    def sync(self, source_id: str, found: Iterable[Tuple[str, str, int, int]]) -> List[Requirement]:
        """Add the requirements (section, text, start, end) of a source not yet on record; returns them all."""
        out = []
        with self._lock:
            known = {(r.source_id, r.start, r.end): r for r in self.items.values()}
            for section, text, a, b in found:
                r = known.get((source_id, a, b))
                if r is None:
                    rid = f"REQ-{max([int(k.split('-')[1]) for k in self.items] + [0]) + 1:03d}"
                    r = self.items[rid] = Requirement(rid, source_id, section, text, a, b)
                    known[(source_id, a, b)] = r
                out.append(r)
            self._save()
        return out

    def cover(self, spans: Dict[str, List[Tuple[int, int, str]]]) -> None:
        """Mark requirements a truth item quotes as covered (spans: source -> (start, end, truth id)). An explicit
        implemented / not_applicable stays."""
        with self._lock:
            for r in self.items.values():
                refs = sorted({ref for a, b, ref in spans.get(r.source_id, []) if a < r.end and r.start < b})
                if r.status in ("open", "covered"):
                    r.status, r.refs = ("covered", refs) if refs else ("open", [])
                elif refs:
                    r.refs = refs
            self._save()

    def resolve(self, items: List[Dict[str, Any]]) -> Dict[str, Any]:
        """[{id, status: implemented | not_applicable, reason}]: the agent's explicit decision for each."""
        done, rejected = [], []
        with self._lock:
            for it in items[:60]:
                it = it if isinstance(it, dict) else {}
                rid = re.sub(r"^\s*REQ[-_ ]?0*(\d+)\s*$", lambda m: f"REQ-{int(m.group(1)):03d}", str(it.get("id") or ""), flags=re.I)
                status = str(it.get("status") or "").strip().lower().replace(" ", "_").replace("-", "_")
                reason = str(it.get("reason") or "").strip()
                r = self.items.get(rid)
                if r is None:
                    rejected.append({"id": rid or "?", "error": "no such requirement (coding_brief lists them)"})
                elif status not in ("implemented", "not_applicable"):
                    rejected.append({"id": rid, "error": "status must be 'implemented' or 'not_applicable' (a requirement a "
                                                         "record quotes is covered by itself)"})
                elif len(reason) < 12:
                    rejected.append({"id": rid, "error": "reason: say how the code does it (file/function) or why it does "
                                                         "not apply (e.g. 'board-level: pull-ups are on the schematic')"})
                else:
                    r.status, r.reason, r.review = status, reason[:300], {}   # a new claim needs a new review
                    r.ref = str(it.get("ref") or "").strip().upper()[:20]
                    done.append(f"{rid} {status}")
            self._save()
        out: Dict[str, Any] = {"ok": bool(done), "resolved": done}
        if rejected:
            out["rejected"] = rejected
        return out

    def set_reviews(self, reviews: Dict[str, Dict[str, str]]) -> None:
        with self._lock:
            for rid, rv in reviews.items():
                r = self.items.get(rid)
                if r is None or r.status not in ("implemented", "not_applicable"):
                    continue
                r.review = rv
                if rv.get("verdict") == "disagree":
                    r.disputes += 1
            self._save()

    def disputed(self) -> List[Requirement]:
        return [r for r in self.items.values() if r.status in ("implemented", "not_applicable")
                and r.review.get("verdict") == "disagree"]

    def counts(self) -> Dict[str, int]:
        c = {s: 0 for s in STATUSES}
        for r in self.items.values():
            c[r.status] = c.get(r.status, 0) + 1
        return c


def truth_spans(root: Path, store: Any, ledger: Any) -> Dict[str, List[Tuple[int, int, str]]]:
    """Where in each source the recorded truth is quoted: source -> [(start, end, truth id)]."""
    from embedforge.truth.ledger import anchor_pieces
    from embedforge.truth.registers import RegisterBook
    from embedforge.truth.sequences import SequenceBook
    quotes: List[Tuple[str, str, str]] = [(f.source_id, f.quote, f.id) for f in ledger.facts.values()]
    book = RegisterBook(root)
    for r in book.registers.values():
        quotes += [(r.source_id, r.quote, r.id)] + ([(r.source_id, r.reset_quote, r.id)] if r.reset_quote else [])
    quotes += [(x.source_id, x.quote, x.id) for x in list(book.layouts.values()) + list(book.bursts.values()) + list(book.formulas.values())]
    quotes += [(c.source_id, q, c.id) for c in book.constraints.values() for q in c.quotes]
    quotes += [(s.source_id, s.order_quote, s.id) for s in SequenceBook(root).items.values()]
    out: Dict[str, List[Tuple[int, int, str]]] = {}
    for sid, q, ref in quotes:
        src = store.get(sid)
        if src is None or not q:
            continue
        for a, b in anchor_pieces(q, src.text) or []:
            out.setdefault(sid, []).append((a, b, ref))
    return out

embedforge/truth/ledger.py:
"""Fact Ledger: the deterministic gate that makes 'zero hallucination' enforceable.

A fact can only enter the ledger if:
  1. it cites a source that exists in the Source Store,
  2. its `quote` appears VERBATIM in that source's text (whitespace/case-insensitive), and
  3. its `value` appears INSIDE that quote.

The LLM therefore cannot create a fact from its own weights: it has to point at real text.
"""

import json
import re
import threading
import unicodedata
from dataclasses import dataclass, asdict
from pathlib import Path
from typing import Dict, List, Optional, Tuple, Any

from embedforge.core.files import load_json, write_atomic
from embedforge.truth.source_store import SourceStore
from embedforge.truth.trust import TrustTier, is_authoritative

MIN_QUOTE_CHARS = 12
MAX_QUOTE_CHARS = 600

_DASHES = dict.fromkeys(map(ord, "\u2010\u2011\u2012\u2013\u2014\u2212"), "-")
_QUOTES = {ord("\u2018"): "'", ord("\u2019"): "'", ord("\u201c"): '"', ord("\u201d"): '"'}
# super/subscript digits are the digits (I\u00b2C is I2C; a PDF's 2\u00b3\u2070 and a model's 2^30 both squash to 230)
_SCRIPT_DIGITS = {**{ord(c): str(i) for i, c in enumerate("\u2070\u00b9\u00b2\u00b3\u2074\u2075\u2076\u2077\u2078\u2079")}, **{ord(c): str(i) for i, c in enumerate("\u2080\u2081\u2082\u2083\u2084\u2085\u2086\u2087\u2088\u2089")}}
# PDF equations come out in Unicode's mathematical letters and digits ('234\u00b5\ud835\udc5d\ud835\udc5d + \ud835\udc5d\ud835\udc5d\ud835\udc5d\ud835\udc5d_\ud835\udc52\ud835\udc52' in the BMP388's conversion-time
# formula): to a reader, and so to a quote, they are the plain letters; the bullet and dot operators are one mark
_MATH = {cp: unicodedata.normalize("NFKC", chr(cp)) for cp in range(0x1D400, 0x1D800)
         if len(unicodedata.normalize("NFKC", chr(cp))) == 1 and unicodedata.normalize("NFKC", chr(cp)) != chr(cp)}
_MATH.update({ord("\u2219"): "\u00b7", ord("\u22c5"): "\u00b7"})
# the letters alone, one character for one, for showing a source (offsets into it stay valid)
MATH_FOLD = {cp: c for cp, c in _MATH.items() if 0x1D400 <= cp < 0x1D800}


def _squash(s: str) -> str:
    """Whitespace-free, case-folded form used for robust verbatim-quote containment."""
    s = s.replace("\u00ad", "").replace("\ufb01", "fi").replace("\ufb02", "fl").replace("\u00b5", "\u03bc")   # micro sign = Greek mu
    s = s.replace("\u00d7", "x")   # the BMP388's tables print '\u00d78 \u00d71'; models type 'x8 x1' (12 rejected quotes)
    s = s.translate(_DASHES).translate(_QUOTES).translate(_SCRIPT_DIGITS).translate(_MATH)
    # Markdown table/emphasis markup from the PDF converter ('| Bit 5..4 | mode |', '**Table 40**', '<br>') is layout,
    # not text: a quote matches with or without it
    s = re.sub(r"</?(?:mark|u|sup|sub|b|i|em|strong)>|<br\s*/?>|\*\*|[|`^]", " ", s)   # 2<sup>osr_p</sup> = 2^osr_p
    # quote marks carry no meaning and PDFs use curly ones the model often drops: Register 0x1B “PWR_CTRL”; nor do
    # backslashes (escaping left in a quote, '\"CONFIG\"'; a C macro's line continuation '#define X \' in a header)
    # (final sigma: 'ΔΣ'.lower() is 'δς' but 'Σ'.lower() is 'σ' — one form, so a text squashes the same in pieces)
    return re.sub(r"[\s\"'`´\\]+", "", s).lower().replace("ς", "σ")


_MARKUP = re.compile(r"</?(?:mark|u|sup|sub|b|i|em|strong)>|<br\s*/?>|\*\*|[|`^]")
_DROP = re.compile(r"[\s\"'`´\\]")
_PRE = {ord("­"): "", ord("ﬁ"): "fi", ord("ﬂ"): "fl", ord("µ"): "μ", ord("×"): "x", **_DASHES, **_QUOTES, **_SCRIPT_DIGITS, **_MATH}


def _squash_map(s: str) -> Tuple[str, List[int]]:
    """_squash(s), and for each of its characters the index in s it came from (used on small pieces of a source)."""
    chars: List[Tuple[str, int]] = []
    for i, c in enumerate(s):
        chars.extend((r, i) for r in c.translate(_PRE))
    t = "".join(c for c, _ in chars)
    kept: List[Tuple[str, int]] = []
    pos = 0
    for m in _MARKUP.finditer(t):
        kept.extend(chars[pos:m.start()])
        pos = m.end()
    kept.extend(chars[pos:])
    out: List[Tuple[str, int]] = []
    for c, i in kept:
        if not _DROP.match(c):
            out.extend((x, i) for x in c.lower().replace("ς", "σ"))
    return "".join(c for c, _ in out), [i for _, i in out]


class _Index:
    """A source text in squashed form, and the way back from a squashed span to the original text. The text is
    squashed in line-aligned pieces, so the per-character map is only built for the piece a match falls in: a 5 MB
    reference manual costs one fast _squash, not a 5-million-step Python loop and a 190 MB index."""

    PIECE = 4000

    def __init__(self, text: str):
        starts, i = [0], self.PIECE
        while i < len(text):
            j = text.find("\n", i)
            if j < 0:
                break
            starts.append(j + 1)
            i = j + 1 + self.PIECE
        # pieces end at line breaks, which no squashed markup spans, so the pieces squash like the whole text
        pieces = [_squash(text[a:b]) for a, b in zip(starts, starts[1:] + [len(text)])]
        self.text, self.s = text, "".join(pieces)
        self.orig = starts + [len(text)]
        self.sq = [0]
        for p in pieces:
            self.sq.append(self.sq[-1] + len(p))
        self._maps: Dict[Tuple[int, int], List[int]] = {}

    def span(self, i: int, j: int) -> Optional[Tuple[int, int]]:
        """Original (start, end) of squashed characters i..j-1."""
        import bisect
        k = bisect.bisect_right(self.sq, i) - 1
        m = bisect.bisect_right(self.sq, j - 1) - 1
        key = (k, m)
        if key not in self._maps:
            s, idx = _squash_map(self.text[self.orig[k]:self.orig[m + 1]])
            self._maps[key] = idx if s == self.s[self.sq[k]:self.sq[m + 1]] else []
        idx = self._maps[key]
        if not idx:
            return None
        return self.orig[k] + idx[i - self.sq[k]], self.orig[k] + idx[j - 1 - self.sq[k]] + 1


_INDEXES: "Dict[str, _Index]" = {}


def _index(text: str) -> _Index:
    hit = _INDEXES.pop(text, None)   # keyed by the text itself (equality, not just hash); most recent last
    if hit is None:
        hit = _Index(text)
        while len(_INDEXES) >= 8:
            _INDEXES.pop(next(iter(_INDEXES)))
    _INDEXES[text] = hit
    return hit


def _word(ch: str) -> bool:
    return ch.isalnum() or ch == "_"


def bounded(text: str, a: int, b: int, first: str, last: str) -> bool:
    """A match a..b of a quote whose squashed form starts with `first` and ends with `last` does not begin or end inside
    a word or number of the text."""
    return not (_word(first) and a > 0 and _word(text[a - 1])) and not (_word(last) and b < len(text) and _word(text[b]))


def anchor(quote: str, text: str) -> Optional[Tuple[int, int]]:
    """Where a quote stands in the source text: (start, end) of the first occurrence that begins and ends on word
    boundaries — '2 ms after power-on' is not a quote of 'wait 12 ms after power-on'. None when it is not there."""
    q = _squash(quote)
    if not q:
        return None
    ix = _index(text)
    pos = ix.s.find(q)
    while pos >= 0:
        sp = ix.span(pos, pos + len(q))
        if sp is not None and bounded(text, sp[0], sp[1], q[0], q[-1]):
            return sp
        pos = ix.s.find(q, pos + 1)
    return None


_ESC_LITERAL = re.compile(r"\\u([0-9a-fA-F]{4})|\\[nrt]|\\([\"'\\/])")
GAP = re.compile(r"\s*(?:…|\.{3,}|\[\.\.\.\])\s*")
GAP_MIN_PIECE = 8      # squashed characters in each piece of a quote with omissions
GAP_MAX_SKIP = 1500    # squashed characters a '…' may stand for


def unescape_literals(q: str) -> str:
    """Literal '\\u2013' / '\\n' / '\\"' left in a quote by double JSON escaping are the characters they stand for (the
    BMP388 fix-up run quoted 'Register 0x1C \\"OSR\\"' seven times)."""
    return _ESC_LITERAL.sub(lambda m: chr(int(m.group(1), 16)) if m.group(1) else m.group(2) or " ", q or "")


def anchor_pieces(quote: str, text: str) -> Optional[List[Tuple[int, int]]]:
    """Source spans of a quote that may omit text with '…' / '...' / '[...]' between verbatim pieces: each piece at least
    GAP_MIN_PIECE characters, on word boundaries, in order, each within GAP_MAX_SKIP of the one before. A quote
    without omissions is one piece (anchor)."""
    pieces = [p for p in GAP.split(quote) if _squash(p)]
    if len(pieces) <= 1:
        sp = anchor(quote, text)
        return [sp] if sp else None
    sq = [_squash(p) for p in pieces]
    if min(len(p) for p in sq) < GAP_MIN_PIECE:
        return None
    ix = _index(text)

    def place(k: int, lo: int, hi: int) -> Optional[List[Tuple[int, int]]]:
        pos = ix.s.find(sq[k], lo)
        while 0 <= pos <= hi:
            sp = ix.span(pos, pos + len(sq[k]))
            if sp is not None and bounded(text, sp[0], sp[1], sq[k][0], sq[k][-1]):
                if k + 1 == len(sq):
                    return [sp]
                end = pos + len(sq[k])
                rest = place(k + 1, end, end + GAP_MAX_SKIP)
                if rest is not None:
                    return [sp] + rest
            pos = ix.s.find(sq[k], pos + 1)
        return None
    return place(0, 0, len(ix.s))


def quote_mismatch(quote: str, text: str) -> str:
    """For a quote that is not verbatim in the text: where it departs from the source and what the source says there,
    so the model can fix that one spot instead of guessing again ('' when no useful part of it matches)."""
    ix = _index(text)
    for piece in GAP.split(unescape_literals(quote)):
        q, qmap = _squash_map(piece)
        if len(q) < GAP_MIN_PIECE or ix.s.find(q) >= 0:
            continue
        lo, hi = 0, len(q)                 # longest start of this piece that the source contains
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if ix.s.find(q[:mid]) >= 0:
                lo = mid
            else:
                hi = mid - 1
        if lo < 12:
            return f"Its start {piece.strip()[:60]!r} is not in the source."
        pos = ix.s.find(q[:lo])
        sp = ix.span(pos, pos + lo)
        if sp is None:
            return ""
        start = max(sp[0], sp[1] - 50)
        if start > sp[0]:                  # from a word's start, not mid-word
            start += len(re.match(r"\S*", text[start:sp[1]]).group())
        said = re.sub(r"\s+", " ", text[start:sp[1]]).strip()
        source_next = re.sub(r"\s+", " ", text[sp[1]:sp[1] + 90]).strip()
        quote_next = re.sub(r"\s+", " ", piece[qmap[lo]:qmap[lo] + 60]).strip()
        return (f"It matches the source up to {said!r}; then the quote has {quote_next!r} "
                f"where the source has {source_next!r}. Copy that part exactly, or write … where you leave text out.")
    return ""


_UNIT_NAMES = {"s": "s", "sec": "s", "second": "s", "seconds": "s", "ms": "ms", "msec": "ms", "millisecond": "ms",
               "milliseconds": "ms", "us": "us", "µs": "us", "μs": "us", "usec": "us", "microsecond": "us", "microseconds": "us",
               "ns": "ns", "nanoseconds": "ns", "hz": "Hz", "khz": "kHz", "mhz": "MHz", "v": "V", "mv": "mV", "a": "A", "ma": "mA",
               "µa": "uA", "μa": "uA", "ua": "uA", "°c": "°C", "c": "°C"}
_UNIT_AFTER = re.compile(r"^[\s|]{0,4}(µs|μs|us|ms|ns|sec|s|[kKM]?Hz|mV|V|mA|[µμu]A|A|°C)(?![A-Za-z])")


def norm_unit(unit: str) -> str:
    u = (unit or "").strip()
    if u in ("MHz", "mHz"):   # mega vs milli: case matters here
        return "MHz" if u == "MHz" else "mHz"
    return _UNIT_NAMES.get(u.lower(), u)


TIME_UNITS = ("s", "ms", "us", "ns")


def units_after(text: str, value: str) -> List[str]:
    """The units written right after each occurrence of the value in text ('2 ms', '| 2 | ms |'), normalised, in order:
    a row can state the same number twice ('VDD = 3 V | 3 | ms')."""
    out: List[str] = []
    for form, rx, _conf in value_variants(value):
        if form not in ("number", "decimal"):
            continue
        for m in re.finditer(rx, text.lower().translate(_DASHES)):
            u = _UNIT_AFTER.match(text[m.end():m.end() + 12])
            if u and norm_unit(u.group(1)) not in out:
                out.append(norm_unit(u.group(1)))
    return out


def unit_after(text: str, value: str, kinds: Optional[Tuple[str, ...]] = None) -> Optional[str]:
    """The first unit written right after the value (of the given kinds, e.g. TIME_UNITS), or None."""
    return next((u for u in units_after(text, value) if kinds is None or u in kinds), None)


def parse_int(value: str) -> Optional[int]:
    v = str(value).strip().lower().replace("_", "")
    try:
        if v.startswith("0x"):
            return int(v, 16)
        if v.startswith("0b"):
            return int(v, 2)
        if re.fullmatch(r"-?\d+", v):
            return int(v, 10)
        if re.fullmatch(r"[0-9][0-9a-f]*h", v):   # 0Fh / 0117h, the TI datasheet notation
            return int(v[:-1], 16)
    except ValueError:
        return None
    return None


def value_variants(value: str) -> List[Tuple[str, str, str]]:
    """Regexes (form, regex, confidence) under which `value` may legitimately appear in a datasheet."""
    v = str(value).strip()
    n = parse_int(v)
    out: List[Tuple[str, str, str]] = []
    if n is not None and v.lower().startswith("0x"):
        h = format(n, "x")
        out.append(("hex-prefixed", rf"(?<![0-9a-z])0x0*{h}(?![0-9a-z])", "STRICT"))
        # TI writes register addresses and values as 0Fh / 00h / 0117h (Bosch writes 0x0F): leading zeros allowed
        out.append(("hex-suffix", rf"(?<![0-9a-z])0*{h}h(?![0-9a-z])", "STRICT"))
        out.append(("hex-quoted", rf"h'0*{h}'", "STRICT"))
        if 0 < n < 0x80:   # a 7-bit I2C address as TI's tables print it: the address bits, then x for the R/W bit
            out.append(("address-bits", rf"(?<![0-9a-z]){format(n, '07b')}x(?![0-9a-z])", "STRICT"))   # 1001000x = 0x48
        out.append(("hex-bare", rf"(?<![0-9a-z.]){h.zfill(2)}(?![0-9a-z.])", "LOOSE"))
        out.append(("decimal", rf"(?<![0-9a-z.]){n}(?![0-9a-z.])", "LOOSE"))
        if n > 0:
            b = format(n, "b")
            out.append(("binary", rf"(?<![0-9a-z])(?:0b|b)?{b}b?(?![0-9a-z])", "LOOSE"))
    elif n is not None and v.lower().startswith("0b"):
        # a field value from a register table: '0b11' is written 011 / 0b011 / 11b there (the BMP388's CONFIG iir_filter)
        b = format(n, "b")
        out.append(("binary-prefixed", rf"(?<![0-9a-z])0b0*{b}(?![0-9a-z])", "STRICT"))
        out.append(("binary-padded", rf"(?<![0-9a-z.])0+{b}b?(?![0-9a-z.])" if n else r"(?<![0-9a-z.])0{2,}b?(?![0-9a-z.])", "STRICT"))
        out.append(("binary-bare", rf"(?<![0-9a-z._]){b}b?(?![0-9a-z._])", "LOOSE"))
    elif n is not None:
        out.append(("number", rf"(?<![0-9a-z.]){n}(?![0-9]|\.\d)", "STRICT"))
    else:
        try:
            float(v)
            out.append(("number", rf"(?<![0-9a-z]){re.escape(v)}(?![0-9])", "STRICT"))
        except ValueError:
            if re.fullmatch(r"(?i)(gpio|gp|p[a-k])\d+", v):  # pin names: GPIO4 must not match inside GPIO41
                out.append(("pin", rf"(?<![0-9a-z]){re.escape(v.lower())}(?![0-9])", "STRICT"))
            else:   # words, with whatever whitespace the PDF put between them ('commands \nare ignored')
                out.append(("text", r"\s+".join(re.escape(w) for w in v.lower().split()), "STRICT"))
    return out


def value_in_text(value: str, text: str) -> Optional[Tuple[str, str]]:
    low = text.lower().translate(_DASHES)
    negative = str(value).strip().startswith("-")
    for form, rx, conf in value_variants(value):
        for m in re.finditer(rx, low):
            k = m.start()
            # '-40 °C' states minus forty, not 40; a range ('1-40', '0x00-0x7F', '1.71 V -3.6 V') still states 40 / 3.6
            if not negative and k > 0 and low[k - 1] == "-" and not _RANGE_BEFORE.search(low[max(0, k - 14):k - 1]):
                continue
            return form, conf
    return None


_RANGE_BEFORE = re.compile(r"(?:\d|0x[0-9a-f]+)\s*(?:[a-zµμ°%]{1,3})?\s*$")


@dataclass
class Fact:
    id: str
    subject: str
    property: str
    value: str
    unit: str
    source_id: str
    source_url: str
    tier: str
    quote: str
    match_form: str
    confidence: str  # STRICT | LOOSE
    authoritative: bool

    def public(self) -> Dict[str, Any]:
        return asdict(self)


class FactLedger:
    def __init__(self, root: Path, store: SourceStore):
        self.path = Path(root) / "ledger.json"
        self.store = store
        self._lock = threading.Lock()
        self.facts: Dict[str, Fact] = {}
        self._load()

    def _load(self) -> None:
        for item in load_json(self.path, []):   # a ledger that does not parse is kept aside, not overwritten
            try:
                f = Fact(**item)
                self.facts[f.id] = f
            except Exception:
                pass

    def _save(self) -> None:
        write_atomic(self.path, json.dumps([f.public() for f in self.facts.values()], indent=2))

    @property
    def _retired_path(self) -> Path:
        return self.path.with_name("ledger_retired.json")

    def _next_id(self) -> str:
        """Ids are never reused, even after a fact is retired."""
        ids = list(self.facts)
        if self._retired_path.exists():
            try:
                ids += [r.get("id", "") for r in json.loads(self._retired_path.read_text(encoding="utf-8"))]
            except Exception:
                pass
        nums = [int(i.split("-")[1]) for i in ids if re.fullmatch(r"FACT-\d+", i)]
        return f"FACT-{max(nums + [0]) + 1:03d}"

    def retire(self, fact_id: str, reason: str) -> bool:
        """Take a fact out of use (e.g. a pin recorded under the wrong define). It stays on record in ledger_retired.json;
        code still citing it then fails verify with UNKNOWN_FACT_TAG."""
        with self._lock:
            f = self.facts.pop(fact_id, None)
            if f is None:
                return False
            retired = []
            if self._retired_path.exists():
                try:
                    retired = json.loads(self._retired_path.read_text(encoding="utf-8"))
                except Exception:
                    retired = []
            retired.append({**f.public(), "retired_reason": reason})
            write_atomic(self._retired_path, json.dumps(retired, indent=2))
            self._save()
            return True

    # ---------- recording ----------
    def record(
        self, subject: str, prop: str, value: Any, source_id: str, quote: str, unit: str = ""
    ) -> Dict[str, Any]:
        """Validate and record a fact. Returns {ok, fact|error, warnings}."""
        value = str(value).strip()
        quote = unescape_literals(quote or "").strip()
        subject = (subject or "").strip()
        prop = (prop or "").strip()
        if not (subject and prop and value):
            return {"ok": False, "error": "subject, property and value are all required."}
        src = self.store.get(source_id)
        if src is None:
            return {"ok": False, "error": f"Unknown source_id '{source_id}'. Use web_search/fetch_document first."}
        if len(_squash(quote)) < MIN_QUOTE_CHARS:
            return {"ok": False, "error": f"Quote too short (<{MIN_QUOTE_CHARS} chars). Quote the full sentence/table row."}
        if len(quote) > MAX_QUOTE_CHARS:
            return {"ok": False, "error": f"Quote too long (>{MAX_QUOTE_CHARS} chars). Quote only the relevant row/sentence."}
        spans = anchor_pieces(quote, src.text)
        if spans is None:
            if _squash(quote) in _squash(src.text):
                return {"ok": False, "error": (f"REJECTED: the quote starts or ends inside a word or number of {source_id} (e.g. "
                                               "'2 ms' inside '12 ms'). Quote whole words and numbers.")}
            return {
                "ok": False,
                "error": (
                    f"REJECTED: quote does not appear verbatim in {source_id}. Facts must be copied "
                    "exactly from the source text (use read_source to get exact text). Text may be left out only with "
                    "'…' between verbatim pieces that stand close together, in order."
                ),
            }
        # the value is checked in the source's own text of the quoted pieces, not in the model's copy or the omitted text
        stated_text = " … ".join(src.text[a:b] for a, b in spans)
        match = value_in_text(value, stated_text)
        # '78.09 ms' from a table whose unit is in the column header ('Measurement time[ms]'): the number is the value
        num_unit = re.fullmatch(r"([-+]?\d+(?:[.,]\d+)?(?:[eE][-+]?\d+)?)\s*([A-Za-zµμ°%Ω][A-Za-zµμ°%Ω/]{0,5})", value)
        if match is None and num_unit and (not unit or norm_unit(unit) == norm_unit(num_unit.group(2))):
            match = value_in_text(num_unit.group(1), stated_text)
            if match is not None:
                value, unit = num_unit.group(1), unit or num_unit.group(2)
        if match is None:
            several = re.search(r"\d[^,;]*[,;]|\band\b|\bor\b", value)
            return {
                "ok": False,
                "error": f"REJECTED: value '{value}' does not appear inside the quoted text, so the quote does not support it."
                         + (" One value per fact: the number in value, its unit in unit (value '7.96', unit 'ms'); "
                            "record_facts records several at once." if several or num_unit else ""),
            }
        form, conf = match
        stated_units = units_after(stated_text, value) if unit else []
        if stated_units and norm_unit(unit) not in stated_units and norm_unit(unit) in set(_UNIT_NAMES.values()) | {"mHz"}:
            return {"ok": False, "error": f"REJECTED: the quote gives {value} {stated_units[0]}, not {value} {unit}."}
        tier = TrustTier(src.tier)
        warnings: List[str] = []
        if src.kind == "figure":
            warnings.append(f"Source {source_id} is a vision model's transcription of a datasheet figure, not the datasheet's "
                            f"words; the fact is recorded but NOT authoritative. Quote the datasheet text where it says the same.")
        elif not is_authoritative(tier):
            warnings.append(f"Source {source_id} is {tier.value}; fact is recorded but NOT authoritative.")
        if conf == "LOOSE":
            warnings.append(f"Value matched loosely ({form}); double-check the register/number meaning in the quote.")

        with self._lock:
            for ex in self.facts.values():
                if ex.subject.lower() == subject.lower() and ex.property.lower() == prop.lower():
                    if ex.value.lower() == value.lower() and ex.source_id == source_id:
                        return {"ok": True, "fact": ex.public(), "warnings": ["Duplicate; existing fact returned."]}
                    if str(ex.value).lower() != value.lower():
                        warnings.append(f"CONFLICT with {ex.id} ({ex.value}) for the same property.")
            fid = self._next_id()
            fact = Fact(
                id=fid, subject=subject, property=prop, value=value, unit=unit, source_id=source_id,
                source_url=src.url, tier=tier.value, quote=quote, match_form=form, confidence=conf,
                authoritative=is_authoritative(tier),
            )
            self.facts[fid] = fact
            self._save()
        return {"ok": True, "fact": fact.public(), "warnings": warnings}

    # ---------- queries ----------
    def get(self, fact_id: str) -> Optional[Fact]:
        return self.facts.get(fact_id)

    def find(self, subject: str = "", prop: str = "") -> List[Fact]:
        s, p = subject.lower(), prop.lower()
        return [f for f in self.facts.values() if (not s or s in f.subject.lower()) and (not p or p in f.property.lower())]

    def conflicts(self) -> List[Tuple[Fact, Fact]]:
        seen: Dict[Tuple[str, str], Fact] = {}
        out = []
        for f in self.facts.values():
            key = (f.subject.lower(), f.property.lower())
            if key in seen and seen[key].value.lower() != f.value.lower():
                out.append((seen[key], f))
            seen.setdefault(key, f)
        return out

    def int_values(self) -> Dict[int, List[str]]:
        """Map integer value -> fact ids (for literal justification in the verifier)."""
        m: Dict[int, List[str]] = {}
        for f in self.facts.values():
            n = parse_int(f.value)
            if n is not None:
                m.setdefault(n, []).append(f.id)
        return m

embedforge/truth/pdf_markdown.py:
"""Datasheet PDF -> Markdown for the datasheet analyzer.

pymupdf4llm turns the PDF into Markdown with headings and tables (tables are taken as HTML, whose row/col spans are then
expanded into plain Markdown rows, so every register row states its own size and sign). Two things it cannot do by itself:

* Encrypted datasheets (Bosch PDFs are AES-encrypted with an empty user password): PyMuPDF opens them directly.
* Equations: Word exports math in a Math font (Cambria Math) whose ToUnicode table is often broken, so the text layer
  says '𝑃𝑃𝑃𝑃𝑃𝑃_𝑇𝑇1' for 'PAR_T1', and the layout model drops the region. The glyph ids are still right: they are decoded
  through the font's own character map (the embedded font, another embedded subset, or the installed system font, whose
  MATH table also names the big parentheses and brackets), and the 2-D layout is turned back into a linear formula:
  numerator over denominator on baselines above and below the equation's '=' line become '(a) / (b)', smaller raised
  runs become '^' exponents:
      PAR_P1 = (NVM_PAR_P1 - 2^14) / 2^20
  Reconstructed formulas are inserted after the text they follow on the page, marked as reconstructed. Prose that
  carries inline math is rewritten from the decoded characters of its layout box ('T_conv = total conversion time').
"""

from __future__ import annotations

import html
import os
import re
import struct
import unicodedata
from dataclasses import dataclass
from html.parser import HTMLParser
from pathlib import Path
from typing import Dict, List, Optional, Tuple

MAX_LAYOUT_PAGES = 150   # the layout model is slow (about 0.7 s/page); longer manuals use the plain Markdown path

_MATH_ALNUM = (0x1D400, 0x1D7FF)
_DASHES = dict.fromkeys(map(ord, "\u2212\u2010\u2011\u2012\u2013\u2014"), "-")


# ------------------------------------------------------------------ HTML tables -> Markdown


class _TableParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.rows: List[List[Tuple[str, int, int]]] = []
        self._cell: Optional[List[str]] = None
        self._span = (1, 1)

    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        if tag == "tr":
            self.rows.append([])
        elif tag in ("td", "th"):
            self._cell = []
            self._span = (max(1, int(a.get("rowspan") or 1)), max(1, int(a.get("colspan") or 1)))
        elif tag == "br" and self._cell is not None:
            self._cell.append(" ")

    def handle_endtag(self, tag):
        if tag in ("td", "th") and self._cell is not None:
            if not self.rows:
                self.rows.append([])
            text = re.sub(r"\s+", " ", "".join(self._cell)).strip()
            self.rows[-1].append((text, *self._span))
            self._cell = None

    def handle_data(self, data):
        if self._cell is not None:
            self._cell.append(data)


def html_table_to_markdown(table_html: str) -> str:
    """One HTML table -> a Markdown table; a cell spanning rows/columns is repeated in each, so rows stand alone."""
    p = _TableParser()
    p.feed(table_html)
    grid: Dict[Tuple[int, int], str] = {}
    width = 0
    for r, row in enumerate(p.rows):
        c = 0
        for text, rs, cs in row:
            while (r, c) in grid:
                c += 1
            for dr in range(rs):
                for dc in range(cs):
                    grid[(r + dr, c + dc)] = text
            c += cs
            width = max(width, c)
    nrows = max((r for r, _ in grid), default=-1) + 1
    if not nrows or not width:
        return ""

    def cell(s: str) -> str:
        return s.replace("|", "\\|")
    lines = []
    for r in range(nrows):
        lines.append("| " + " | ".join(cell(grid.get((r, c), "")) for c in range(width)) + " |")
        if r == 0:
            lines.append("|" + "---|" * width)
    return "\n".join(lines)


def html_tables_to_markdown(md: str) -> str:
    return re.sub(r"<table>.*?</table>", lambda m: "\n" + html_table_to_markdown(m.group(0)) + "\n", md, flags=re.S)


# ------------------------------------------------------------------ math glyph decoding


def _ttc_face(data: bytes, index: int) -> bytes:
    """One face of a TrueType collection as a standalone font buffer: the face's table directory moved to offset 0
    (table offsets in a TTC are absolute, so the tables stay valid)."""
    if data[:4] != b"ttcf":
        return data
    num = struct.unpack(">I", data[8:12])[0]
    offs = struct.unpack(f">{num}I", data[12:12 + 4 * num])
    o = offs[index]
    ntab = struct.unpack(">H", data[o + 4:o + 6])[0]
    directory = data[o:o + 12 + 16 * ntab]
    return directory + data[len(directory):]


def _font_dirs() -> List[Path]:
    dirs = [Path(os.environ.get("WINDIR", r"C:\Windows")) / "Fonts", Path.home() / "AppData/Local/Microsoft/Windows/Fonts",
            Path("/usr/share/fonts"), Path("/usr/local/share/fonts"), Path.home() / ".fonts", Path("/Library/Fonts"),
            Path("/System/Library/Fonts"), Path.home() / "Library/Fonts"]
    return [d for d in dirs if d.is_dir()]


def _family(base: str) -> str:
    return re.sub(r"[^a-z0-9]", "", base.split("+", 1)[-1].lower())


_SYSTEM_MAPS: Dict[str, Optional[Dict[int, int]]] = {}


def _reverse_cmap(font) -> Dict[int, int]:
    rev: Dict[int, int] = {}
    for cp in font.valid_codepoints():
        g = font.has_glyph(cp)
        if g:
            rev.setdefault(g, cp)
    return rev


def _math_variants(face: bytes, rev: Dict[int, int]) -> Dict[int, int]:
    """gid -> codepoint for the size variants and assembly parts of stretchy glyphs (big parentheses, brackets,
    radicals), read from the font's OpenType MATH table: they have no cmap entry of their own."""
    def u16(o: int) -> int:
        return struct.unpack(">H", face[o:o + 2])[0]

    def coverage(o: int) -> List[int]:
        if u16(o) == 1:
            return [u16(o + 4 + 2 * i) for i in range(u16(o + 2))]
        out: List[int] = []
        for i in range(u16(o + 2)):
            start, end = u16(o + 4 + 6 * i), u16(o + 6 + 6 * i)
            out.extend(range(start, end + 1))
        return out

    out: Dict[int, int] = {}
    try:
        math = next((struct.unpack(">I", face[12 + 16 * i + 8:12 + 16 * i + 12])[0] for i in range(u16(4))
                     if face[12 + 16 * i:12 + 16 * i + 4] == b"MATH"), None)
        if math is None:
            return out
        mv = math + u16(math + 8)
        for cov_off, count_at, first in ((u16(mv + 2), mv + 6, mv + 10), (u16(mv + 4), mv + 8, mv + 10 + 2 * u16(mv + 6))):
            if not cov_off:
                continue
            for i, base in enumerate(coverage(mv + cov_off)[:u16(count_at)]):
                cp = rev.get(base)
                if cp is None:
                    continue
                con = mv + u16(first + 2 * i)
                for k in range(u16(con + 2)):
                    out.setdefault(u16(con + 4 + 4 * k), cp)
                if u16(con):   # a glyph assembly: its parts (top, extender, bottom) stand for the same character
                    asm = con + u16(con)
                    for k in range(u16(asm + 4)):
                        out.setdefault(u16(asm + 6 + 10 * k), cp)
    except (struct.error, IndexError):
        pass
    return out


def _system_map(family: str) -> Optional[Dict[int, int]]:
    """gid -> codepoint of an installed font with this family name (e.g. Cambria Math inside cambria.ttc)."""
    if family in _SYSTEM_MAPS:
        return _SYSTEM_MAPS[family]
    import pymupdf
    found = None
    stem = family[:5]
    for d in _font_dirs():
        for f in sorted(d.rglob("*")):
            if f.suffix.lower() not in (".ttf", ".ttc", ".otf") or stem not in f.name.lower().replace(" ", ""):
                continue
            try:
                data = f.read_bytes()
                faces = struct.unpack(">I", data[8:12])[0] if data[:4] == b"ttcf" else 1
                for i in range(faces):
                    face = _ttc_face(data, i)
                    font = pymupdf.Font(fontbuffer=face)
                    if _family(font.name.replace(" Regular", "")) == family:
                        found = _reverse_cmap(font)
                        for g, cp in _math_variants(face, found).items():
                            found.setdefault(g, cp)
                        break
            except Exception:
                continue
            if found:
                break
        if found:
            break
    _SYSTEM_MAPS[family] = found
    return found


class GlyphDecoder:
    """Per document: for each Math font, gid -> codepoint from its own cmap, another embedded subset of the same family,
    or the installed font."""

    def __init__(self, doc):
        self.doc = doc
        self.maps: Dict[str, Optional[Dict[int, int]]] = {}
        self._embedded: Dict[str, Dict[int, int]] = {}
        self.blocks: Dict[str, Dict[str, int]] = {}

    def _embedded_map(self, family: str) -> Dict[int, int]:
        if family not in self._embedded:
            rev: Dict[int, int] = {}
            import pymupdf
            seen = set()
            for pno in range(min(len(self.doc), 400)):
                for xref, _ext, _typ, base, *_ in self.doc.get_page_fonts(pno):
                    if xref in seen or _family(base) != family:
                        continue
                    seen.add(xref)
                    try:
                        buf = self.doc.extract_font(xref)[3]
                        if buf:
                            for g, cp in _reverse_cmap(pymupdf.Font(fontbuffer=buf)).items():
                                rev.setdefault(g, cp)
                    except Exception:
                        continue
            self._embedded[family] = rev
        return self._embedded[family]

    def map_for(self, font_name: str) -> Optional[Dict[int, int]]:
        fam = _family(font_name)
        if fam not in self.maps:
            # the installed font keeps the original glyph numbering that Identity-H subsets use; another embedded subset
            # may have been renumbered, so it only fills gaps
            m = dict(_system_map(fam) or {})
            for g, cp in self._embedded_map(fam).items():
                m.setdefault(g, cp)
            self.maps[fam] = m or None
        return self.maps[fam]

    # Letter blocks of glyph variants that have no cmap entry (script-size letters in Cambria Math are 26 consecutive
    # glyphs). Their position is learnt by vote over the document: every unmapped glyph proposes 'gid - index of the
    # letter the text layer reports'; the text layer is right often enough (first letters of words) that the true block
    # start wins, while its wrong reports scatter.
    def letter(self, font_name: str, gid: int) -> Optional[str]:
        fam = _family(font_name)
        if fam not in self.blocks:
            self._learn_blocks(fam)
        for case, base in self.blocks.get(fam, {}).items():
            if 0 <= gid - base < 26:
                return chr(ord("a" if case == "lower" else "A") + gid - base)
        return None

    def _learn_blocks(self, fam: str) -> None:
        from collections import Counter
        m = self.maps.get(fam) or {}
        votes = {"lower": Counter(), "upper": Counter()}
        for pno in range(min(len(self.doc), 400)):
            try:
                spans = self.doc[pno].get_texttrace()
            except Exception:
                continue
            for span in spans:
                if _family(span.get("font", "")) != fam:
                    continue
                for u, g, *_ in span.get("chars") or []:
                    if g == -1 or g in m:
                        continue
                    c = _norm(chr(u))[:1]
                    if c.isascii() and c.isalpha():
                        votes["lower" if c.islower() else "upper"][g - (ord(c.lower()) - ord("a"))] += 1
        found = {}
        for case, cnt in votes.items():
            if cnt:
                base, n = cnt.most_common(1)[0]
                if n >= 3 and n >= 0.2 * sum(cnt.values()):
                    found[case] = base
        self.blocks[fam] = found


# ------------------------------------------------------------------ formula layout


@dataclass
class Run:
    text: str
    x0: float
    x1: float
    base: float   # baseline y
    size: float
    raw: str = ""   # what the PDF's text layer says for it (garbled for broken math fonts)


_OPS = {"⁡": "", "⁢": "*", "×": "*", "⋅": "*", "∙": "*", "·": "*", "∗": "*", "÷": "/"}


def _norm(s: str) -> str:
    s = unicodedata.normalize("NFKC", s).translate(_DASHES)
    for a, b in _OPS.items():
        s = s.replace(a, b)
    return s


def _is_math_text(s: str) -> bool:
    return any(_MATH_ALNUM[0] <= ord(c) <= _MATH_ALNUM[1] for c in s)


def page_math_glyphs(page, decoder: GlyphDecoder) -> List[Run]:
    """The page's math-font glyphs, each decoded through the font's real character map; glyph variants with no map
    entry are decoded from their letter block, anchored on the first letter of the word, which the text layer reports
    correctly even when the rest is garbled."""
    glyphs: List[Run] = []
    for span in page.get_texttrace():
        font = span.get("font", "")
        chars = span.get("chars") or []
        if "math" not in font.lower() and not _is_math_text("".join(chr(c[0]) for c in chars)):
            continue
        m = decoder.map_for(font) or {}
        size = span["size"]
        word: List[Tuple[Run, int]] = []
        for u, g, origin, bbox in chars:
            if g == -1 and word:
                word[-1][0].raw += chr(u)   # extra code points of one glyph's ToUnicode entry
                continue
            word.append((Run("", bbox[0], bbox[2], origin[1], size, chr(u)), g))
        # the text layer is broken when different glyphs report the same letter (PAR -> 𝑃𝑃𝑃) or one glyph reports a
        # letter twice (c -> 𝑐𝑐)
        seen: Dict[str, int] = {}
        broken = any(len(r.raw) >= 2 and r.raw[0].isalpha() and r.raw == r.raw[0] * len(r.raw) for r, _ in word)
        for r, g in word:
            c = r.raw[:1]
            if c.isalpha() and seen.setdefault(c, g) != g:
                broken = True
        local: Dict[str, int] = {}   # too rare to vote on (e.g. one capital subscript): anchor on the word's first letter
        for r, g in word:
            if g in m:
                r.text = chr(m[g])
            elif not broken:
                r.text = r.raw.replace("�", "")   # a working text layer: trust it
            else:
                r.text = decoder.letter(font, g) or ""
                hint = _norm(r.raw[:1])
                if not r.text and hint.isascii() and hint.isalpha():
                    case = "lower" if hint.islower() else "upper"
                    base = local.setdefault(case, g - (ord(hint.lower()) - ord("a")))
                    if 0 <= g - base < 26:
                        r.text = chr(ord("a" if case == "lower" else "A") + g - base)
                r.text = r.text or "?"
        glyphs.extend(r for r, _ in word)
    return glyphs


def page_math_runs(page, decoder: GlyphDecoder) -> List[Run]:
    """The page's math text as runs: decoded glyphs on the same baseline and size, close together (a word gap becomes
    a space)."""
    glyphs = page_math_glyphs(page, decoder)

    def occupied(a: float, b: float, base: float, size: float) -> bool:
        """Another glyph (an index, a stacked fraction) sits in the gap between two glyphs of a line."""
        return any(a - 0.5 <= h.x0 and h.x1 <= b + 0.5 and abs(h.base - base) > 0.5 and abs(h.base - base) < size
                   for h in glyphs)
    runs: List[Run] = []
    for gl in sorted(glyphs, key=lambda r: (round(r.base, 0), r.x0)):
        cur = runs[-1] if runs else None
        gap = gl.x0 - cur.x1 if cur else 0.0
        if (cur and abs(gl.base - cur.base) < 0.5 and abs(gl.size - cur.size) < 0.5 and -0.5 < gap < 0.9 * gl.size
                and not (gap > 0.5 and occupied(cur.x1, gl.x0, gl.base, gl.size))):
            sep = " " if gl.x0 - cur.x1 > 0.22 * gl.size else ""
            cur.text += sep + gl.text
            cur.raw += gl.raw
            cur.x1 = max(cur.x1, gl.x1)
        else:
            runs.append(Run(gl.text, gl.x0, gl.x1, gl.base, gl.size, gl.raw))
    for r in runs:
        r.text = _norm(r.text)
    return [r for r in runs if r.text.strip()]


def _atom(s: str) -> str:
    s = s.strip()
    simple = re.fullmatch(r"[\w.]+(\^\(?-?[\w.]+\)?)?", s) or (s.startswith("(") and s.endswith(")") and s.count("(") == 1)
    return s if simple else f"({s})"


def _attach_scripts(runs: List[Run]) -> List[Run]:
    """Smaller runs right after a run become its exponent (raised) or index (lowered): 2^(osr_p), T_conv."""
    if not runs:
        return []
    big = max(r.size for r in runs)
    full = [Run(r.text, r.x0, r.x1, r.base, r.size, r.raw) for r in runs if r.size >= 0.85 * big]
    small = sorted((r for r in runs if r.size < 0.85 * big), key=lambda r: (round(r.base), r.x0))
    groups: List[Run] = []
    for s in small:   # adjacent small runs on one baseline form one script
        g = groups[-1] if groups else None
        if g and abs(g.base - s.base) < 0.5 and 0 <= s.x0 - g.x1 < 0.6 * s.size:
            g.text += (" " if s.x0 - g.x1 > 0.25 * s.size else "") + s.text
            g.x1 = s.x1
        else:
            groups.append(Run(s.text, s.x0, s.x1, s.base, s.size, s.raw))
    for s in groups:
        base = min((f for f in full if -0.5 * f.size <= s.x0 - f.x1 <= 0.6 * f.size and abs(f.base - s.base) < f.size),
                   key=lambda f: abs(s.x0 - f.x1), default=None)
        t = s.text.strip()
        if base is None:
            full.append(Run(t, s.x0, s.x1, s.base, big, s.raw))
            continue
        piece = t if re.fullmatch(r"-?[\w.]+", t) else f"({t})"
        base.text += ("^" if s.base < base.base - 0.1 * base.size else "_") + piece
        base.x1 = max(base.x1, s.x1)
    return full


def formulas_from_runs(runs: List[Run]) -> List[Tuple[float, float, str]]:
    """(top y, x0, linear formula) for each equation: a line with '=' and what is stacked above and below it."""
    full = sorted(_attach_scripts(runs), key=lambda r: r.base)
    bands: List[List[Run]] = []
    for r in full:
        if bands and r.base - max(x.base for x in bands[-1]) <= 1.2 * r.size:
            bands[-1].append(r)
        else:
            bands.append([r])
    out: List[Tuple[float, float, str]] = []
    for band in bands:
        band.sort(key=lambda r: r.x0)
        eqs: List[List[Run]] = []
        for r in band:   # equations side by side: split at wide horizontal gaps
            if eqs and r.x0 - max(x.x1 for x in eqs[-1]) <= 2.5 * r.size:
                eqs[-1].append(r)
            else:
                eqs.append([r])
        for eq in eqs:
            for part in _split_equations(eq):
                out.append((min(r.base - r.size for r in part), min(r.x0 for r in part), _linearize(part)))
    return out


def _split_equations(eq: List[Run]) -> List[List[Run]]:
    """Several equations close together on one row: cut at the widest gap before each further '='."""
    eqs_signs = sorted((r for r in eq if "=" in r.text), key=lambda r: r.x0)
    if len(eqs_signs) < 2:
        return [eq]
    items = sorted(eq, key=lambda r: r.x0)
    cuts = []
    for prev, cur in zip(eqs_signs, eqs_signs[1:]):
        best, at = -1.0, None
        reach = 0.0
        for a, b in zip(items, items[1:]):
            reach = max(reach, a.x1)
            if prev.x1 <= b.x0 <= cur.x0 and b.x0 - reach > best:
                best, at = b.x0 - reach, b.x0
        if at is not None:
            cuts.append(at)
    parts: List[List[Run]] = []
    edges = [float("-inf")] + cuts + [float("inf")]
    for lo, hi in zip(edges, edges[1:]):
        part = [r for r in eq if lo <= r.x0 < hi]
        if part:
            parts.append(part)
    return parts


def _clusters(runs: List[Run], size: float, gap: float = 1.0) -> List[List[Run]]:
    out: List[List[Run]] = []
    for r in sorted(runs, key=lambda r: r.x0):
        if out and r.x0 - max(x.x1 for x in out[-1]) <= gap * size:
            out[-1].append(r)
        else:
            out.append([r])
    return out


def _linearize(eq: List[Run]) -> str:
    size = max(r.size for r in eq)
    with_eq = [r for r in eq if "=" in r.text]
    if with_eq:
        main = with_eq[0].base
    else:
        main = max({round(r.base, 1) for r in eq}, key=lambda b: sum(len(r.text) for r in eq if abs(r.base - b) < 0.3 * size))
    mains = [r for r in eq if abs(r.base - main) < 0.3 * size]
    above = [r for r in eq if r.base < main - 0.3 * size]
    below = [r for r in eq if r.base > main + 0.3 * size]
    tokens: List[Tuple[float, str]] = [(r.x0, r.text) for r in mains]
    used = set()
    below_groups = _clusters(below, size, gap=0.4)   # touching pieces only: two fractions' denominators stay apart
    for num in _clusters(above, size):   # a fraction: numerator above, denominator below the same horizontal range
        x0, x1 = min(r.x0 for r in num), max(r.x1 for r in num)
        # the whole denominator, also when it is wider than the numerator: 1 over 'T_conv [μs] * 10^6'
        den = [r for grp in below_groups if any(r.x1 > x0 - 0.5 * size and r.x0 < x1 + 0.5 * size for r in grp)
               for r in grp if id(r) not in used]
        used |= {id(r) for r in den}
        n = " ".join(r.text for r in sorted(num, key=lambda r: r.x0))
        if den:
            d = " ".join(r.text for r in sorted(den, key=lambda r: r.x0))
            tokens.append((x0, f"{_atom(n)} / {_atom(d)}"))
        else:
            tokens.append((x0, n))
    for b in below:
        if id(b) not in used:
            tokens.append((b.x0, b.text))
    text = " ".join(t for _, t in sorted(tokens))
    text = re.sub(r"\s*=\s*", " = ", text)
    text = re.sub(r"\(\s+", "(", text)
    text = re.sub(r"\s+\)", ")", text)
    text = re.sub(r"(?<=[\w)])\s*([+\-*])\s*(?=[\w(])", r" \1 ", text)
    return re.sub(r"\s+", " ", text).strip()


def page_formulas(page, decoder: GlyphDecoder) -> Tuple[List[Tuple[float, float, str]], Dict[str, str]]:
    """(equations on the page, {garbled text-layer string: decoded text} for inline math in the prose)."""
    runs = page_math_runs(page, decoder)
    fixes = {r.raw: r.text for r in runs if r.raw and r.raw != r.text and len(r.raw) >= 2}
    eqs = [f for f in formulas_from_runs(runs) if "=" in f[2] and len(f[2]) >= 5]
    return eqs, fixes


Char = Tuple[str, float, float, Tuple[float, float, float, float]]   # text, size, baseline y, bbox


def page_lines(page, decoder: GlyphDecoder) -> List[List[Char]]:
    """The page's text lines, character by character, with every math-font glyph replaced by its decoded character
    (matched by position: texttrace knows the glyph ids, rawdict the line structure)."""
    at: Dict[Tuple[float, float], str] = {}
    for gl in page_math_glyphs(page, decoder):
        at.setdefault((round(gl.x0, 1), round(gl.base, 1)), _norm(gl.text))
    lines: List[List[Char]] = []
    for b in page.get_text("rawdict").get("blocks", []):
        for ln in b.get("lines", []):
            chars: List[Char] = []
            used = set()
            for sp in ln.get("spans", []):
                for ch in sp.get("chars", []):
                    key = (round(ch["bbox"][0], 1), round(ch["origin"][1], 1))
                    if key in at:
                        if key in used:   # one glyph whose text layer gives several characters
                            continue
                        used.add(key)
                        c = at[key]
                    elif _is_math_text(ch["c"]):
                        continue
                    else:
                        c = ch["c"]
                    chars.append((c, sp["size"], ch["origin"][1], tuple(ch["bbox"])))
            if chars:
                lines.append(chars)
    return lines


def _render_line(chars: List[Char]) -> str:
    """One line of text; smaller characters raised or lowered from the line's baseline become ^exponent / _index."""
    vis = [c for c in chars if c[0].strip()]
    if not vis:
        return ""
    main = max(c[1] for c in vis)
    bases = sorted(c[2] for c in vis if c[1] >= 0.85 * main)
    mid = bases[len(bases) // 2] if bases else vis[0][2]
    groups: List[Tuple[str, str]] = []
    for c, size, base, _ in chars:
        kind = ""
        if c.strip() and size < 0.85 * main:
            kind = "^" if base < mid - 0.1 * main else "_" if base > mid + 0.1 * main else ""
        if groups and groups[-1][0] == kind:
            groups[-1] = (kind, groups[-1][1] + c)
        else:
            groups.append((kind, c))
    return "".join(t if not k else k + (t if re.fullmatch(r"[\w.\-]+", t) else f"({t})") for k, t in groups)


def _inside(c: Char, bbox, pad: float = 0.0) -> bool:
    cx, cy = (c[3][0] + c[3][2]) / 2, (c[3][1] + c[3][3]) / 2
    return bbox[0] - pad <= cx <= bbox[2] + pad and bbox[1] - pad <= cy <= bbox[3] + pad


def _line_owners(lines: List[List[Char]], boxes: List[dict]) -> List[int]:
    """For each line, the layout box holding most of its characters (boxes overlap at their edges; the smaller box
    wins a tie), or -1."""
    owners = []
    for ln in lines:
        best, key = -1, (0, 0.0)
        for i, b in enumerate(boxes):
            x0, y0, x1, y1 = b["bbox"]
            n = sum(_inside(c, b["bbox"]) for c in ln) or sum(_inside(c, b["bbox"], 1.0) for c in ln) / 1000
            k = (n, -(x1 - x0) * (y1 - y0))
            if n and k > key:
                best, key = i, k
        owners.append(best)
    return owners


def _box_text(lines: List[List[Char]], owners: List[int], index: int) -> str:
    out = [_render_line(ln) for ln, o in zip(lines, owners) if o == index]
    return re.sub(r"\s+", " ", " ".join(out)).strip()


_NOT_TEXT = ("table", "picture", "page-header", "page-footer")
_FORMULA_NOTE = "*Formulas (reconstructed from the PDF's equation glyphs):*"


def _formula_anchor(boxes: List[dict], top: float, x0: float) -> int:
    """The layout box a reconstructed formula goes after: the text box it sits in, else the nearest one above it."""
    text = [(i, b) for i, b in enumerate(boxes)
            if b.get("class") not in _NOT_TEXT + ("formula",) and b["pos"][1] > b["pos"][0]]
    px, py = x0 + 2, top + 2
    inside = [i for i, b in text if b["bbox"][0] - 2 <= px <= b["bbox"][2] + 2 and b["bbox"][1] - 2 <= py <= b["bbox"][3] + 2]
    if inside:
        return inside[-1]
    above = [(b["bbox"][3], i) for i, b in text if b["bbox"][3] <= top + 2]
    return max(above)[1] if above else -1


def _rebuild_page(md: str, boxes: List[dict], lines: List[List[Char]], formulas: List[Tuple[float, float, str]]) -> str:
    """pymupdf4llm's Markdown with each layout box that still carries garbled math glyphs rewritten from the page's
    decoded characters, and each reconstructed formula placed after the text it belongs to."""
    after: Dict[int, List[str]] = {}
    for top, x0, f in sorted(formulas):
        after.setdefault(_formula_anchor(boxes, top, x0), []).append(f)

    def note(fs: List[str]) -> str:
        return _FORMULA_NOTE + "\n\n" + "\n".join(f"`{f}`  " for f in fs)
    owners = _line_owners(lines, boxes)
    out: List[str] = []
    cur = 0
    for i, b in sorted(enumerate(boxes), key=lambda t: t[1]["pos"]):
        p0, p1 = b["pos"]
        if p0 < cur:
            continue
        out.append(md[cur:p0])
        seg = md[p0:p1]
        if _is_math_text(seg) and b.get("class") not in _NOT_TEXT:
            text = _box_text(lines, owners, i)
            lead = re.match(r"\s*(#+ +|[-*] +)?", seg).group(0)
            seg = (lead + text if text else re.sub(r"[\U0001D400-\U0001D7FF]+", "", seg.rstrip())) + seg[len(seg.rstrip()):]
        if i in after:
            seg = seg.rstrip() + "\n\n" + note(after[i]) + "\n\n"
        out.append(seg)
        cur = p1
    out.append(md[cur:])
    if -1 in after:
        out.append("\n\n" + note(after[-1]) + "\n")
    return "".join(out)


# ------------------------------------------------------------------ document


def _insert_formulas(md: str, page, formulas: List[Tuple[float, float, str]]) -> str:
    """Put the reconstructed equations after the page text that precedes them, or at the end of the page."""
    block = "\n".join(f"`{f}`  " for _, _, f in sorted(formulas))
    note = _FORMULA_NOTE + "\n\n" + block + "\n"
    top = min(y for y, _, _ in formulas)
    before = None
    for b in page.get_text("blocks"):
        y1, text = b[3], b[4]
        if y1 <= top + 1 and text.strip() and not _is_math_text(text) and (before is None or y1 > before[0]):
            before = (y1, text)
    if before:
        tail = re.sub(r"\s+", " ", before[1]).strip()[-40:]
        if len(tail) >= 12:
            flat = re.sub(r"\s+", " ", md)
            k = flat.find(tail)
            if k >= 0:
                need = len(re.sub(r"\s", "", flat[:k + len(tail)]))
                pos = seen = 0
                while pos < len(md) and seen < need:   # back from the whitespace-flattened text to the original
                    if not md[pos].isspace():
                        seen += 1
                    pos += 1
                end = md.find("\n\n", pos)
                end = len(md) if end < 0 else end
                return md[:end] + "\n\n" + note + md[end:]
    return md.rstrip() + "\n\n" + note


def pdf_to_markdown(data: bytes, max_pages: int = 600) -> Optional[str]:
    """Markdown of a PDF, or None when PyMuPDF / pymupdf4llm are not installed."""
    try:
        import pymupdf
        import pymupdf4llm
    except ImportError:
        return None
    doc = pymupdf.open(stream=data, filetype="pdf")
    if doc.needs_pass and not doc.authenticate(""):
        raise ValueError("the PDF is password protected")
    n = min(len(doc), max_pages)
    pages = list(range(n))
    if n > MAX_LAYOUT_PAGES:
        pymupdf4llm.use_layout(False)
        try:
            chunks = pymupdf4llm.to_markdown(doc, pages=pages, page_chunks=True, show_progress=False)
        finally:
            pymupdf4llm.use_layout(True)
    else:
        chunks = pymupdf4llm.to_markdown(doc, pages=pages, page_chunks=True, table_output="html", header=False,
                                         footer=False, show_progress=False)
    decoder = GlyphDecoder(doc)
    out: List[str] = []
    for k, ch in enumerate(chunks):
        out.append(f"<!-- PDF page {k + 1} -->\n\n{page_markdown(doc[k], ch, decoder).strip()}")
    return "\n\n".join(out) + "\n"


def page_markdown(page, chunk: dict, decoder: GlyphDecoder) -> str:
    """One page: pymupdf4llm's chunk with tables flattened, math decoded and formulas reconstructed."""
    md = chunk.get("text") or ""
    try:
        formulas, fixes = page_formulas(page, decoder)
    except Exception:
        formulas, fixes = [], {}
    boxes = chunk.get("page_boxes") or []
    placed = False
    if boxes and (formulas or _is_math_text(md)):
        try:   # the layout boxes say where each piece of Markdown is on the page
            md = _rebuild_page(md, boxes, page_lines(page, decoder) if _is_math_text(md) else [], formulas)
            placed = True
        except Exception:
            pass
    md = html_tables_to_markdown(md)
    for raw in sorted(fixes, key=len, reverse=True):   # inline math left in tables and pictures: the decoded text
        md = md.replace(raw, fixes[raw])
    if formulas and not placed:
        md = _insert_formulas(md, page, formulas)
    return _plain_markup(md)


_ITALIC = re.compile(r"(?<![\w\\])_([A-Za-z0-9][\w.\-/ ]{0,60}?[A-Za-z0-9.)])_(?![\w])")


def _plain_markup(md: str) -> str:
    """Markup that would end up in quotes and identifiers: italics around register names ('_press_xlsb_' reads as a
    different name) and the shading / underline tags of code boxes and captions."""
    md = re.sub(r"</?(?:mark|u)>", "", md)
    return _ITALIC.sub(r"\1", md)

embedforge/truth/pins.py:
"""Pins the code passes to calls (Wire.setSDA(16), pinMode(LED_PIN, OUTPUT), gpio_init(25)) are wiring claims, like a
`#define X_PIN`: verify traces each to a schematic fact, checks the function the call gives the pin (SDA, SCL, SCK, TX,
RX, CS) against the role the fact records, and on RP2040/RP2350 checks that the peripheral instance can reach that GPIO
(an I2C0 SDA must sit on a GPIO with number % 4 == 0; the chip silently routes nothing otherwise)."""

import re
from typing import Dict, List, Optional, Tuple

# call -> the role it gives its first argument ('' = a pin, no particular function)
PIN_CALLS: Dict[str, str] = {
    "setSDA": "SDA", "setSCL": "SCL", "setSCK": "SCK", "setCS": "CS", "setMISO": "RX", "setMOSI": "TX",
    "setRX": "RX", "setTX": "TX",
    "pinMode": "", "digitalWrite": "", "digitalRead": "", "analogRead": "", "analogWrite": "", "digitalPinToInterrupt": "",
    "tone": "", "noTone": "",
    "gpio_init": "", "gpio_put": "", "gpio_get": "", "gpio_set_dir": "", "gpio_set_function": "", "gpio_pull_up": "",
    "gpio_pull_down": "", "gpio_set_irq_enabled": "",
}
_CALL_RE = re.compile(r"(?:\b([A-Za-z_]\w*)\s*(?:\.|->)\s*)?\b(" + "|".join(PIN_CALLS) + r")\s*\(")

# the words a fact's property or a define's name uses for a pin's function, one role per family
_ROLE_WORDS = {"SDA": "SDA", "SCL": "SCL", "SCK": "SCK", "SCLK": "SCK", "CLK": "SCK", "MOSI": "TX", "SDO": "TX", "COPI": "TX",
               "TX": "TX", "TXD": "TX", "MISO": "RX", "SDI": "RX", "CIPO": "RX", "RX": "RX", "RXD": "RX", "CS": "CS",
               "NSS": "CS", "SS": "CS", "CSN": "CS"}

# Arduino-Pico (earlephilhower) objects -> RP2040/RP2350 peripheral instance
INSTANCES = {"I2C": {"Wire": 0, "Wire1": 1}, "SPI": {"SPI": 0, "SPI1": 1}, "UART": {"Serial1": 0, "Serial2": 1}}


def role_of(name: str) -> str:
    """'BMP388_SDA_PIN' -> 'SDA', 'GYRO_MISO_PIN' -> 'RX', 'LED_PIN' -> ''."""
    for w in re.split(r"[^A-Za-z0-9]+", str(name or "").upper()):
        if w in _ROLE_WORDS:
            return _ROLE_WORDS[w]
    return ""


def _first_arg(code: str, start: int) -> Tuple[str, int]:
    """The first argument of the call whose '(' is at code[start-1], and where the call ends."""
    depth, i = 0, start
    while i < len(code):
        c = code[i]
        if c in "([{":
            depth += 1
        elif c in ")]}":
            if depth == 0:
                break
            depth -= 1
        elif c == "," and depth == 0:
            break
        i += 1
    return code[start:i].strip(), i


def pin_args(code: str) -> List[Tuple[str, str, str]]:
    """(call, receiver, first argument) for each pin-taking call in one line of code (comments stripped)."""
    out = []
    for m in _CALL_RE.finditer(code):
        arg, _ = _first_arg(code, m.end())
        out.append((m.group(2), m.group(1) or "", arg))
    return out


def literal_pin(arg: str) -> Optional[int]:
    m = re.fullmatch(r"\(?\s*(?:\(\s*\w+\s*\)\s*)?(\d{1,3})[uU]?\s*\)?", arg)
    return int(m.group(1)) if m else None


def family(call: str, receiver: str) -> str:
    if call in ("setSDA", "setSCL"):
        return "I2C"
    if call in ("setSCK", "setCS", "setMISO", "setMOSI"):
        return "SPI"
    if call in ("setRX", "setTX"):
        r = receiver.lower()
        return "SPI" if "spi" in r else "UART" if re.search(r"serial|uart", r) else ""
    return ""


def rp_function(fam: str, gpio: int, rp2350: bool) -> Optional[Tuple[int, str]]:
    """(instance, role) that GPIO `gpio` carries for an I2C, SPI or UART on RP2040/RP2350 (datasheet GPIO function
    table; the pattern repeats over GPIO0-47 on the RP2350B)."""
    if fam == "I2C":
        return (gpio // 2) % 2, "SDA" if gpio % 2 == 0 else "SCL"
    if fam == "SPI":
        return (gpio // 8) % 2, {0: "RX", 1: "CS", 2: "SCK", 3: "TX"}[gpio % 4]
    if fam == "UART":
        if gpio % 4 >= 2 and not rp2350:   # the RP2350 adds TX/RX on the other two pins of each group (UART_AUX)
            return None
        return ((gpio // 4) ^ (gpio // 8)) & 1, "TX" if gpio % 2 == 0 else "RX"
    return None


def legal_pins(fam: str, inst: int, role: str, rp2350: bool, max_gpio: int) -> List[int]:
    return [g for g in range(max_gpio + 1) if rp_function(fam, g, rp2350) == (inst, role)]

embedforge/truth/refcode.py:
"""Manufacturer reference code: a part's official driver sources from the vendor's own GitHub organisation.

Datasheet PDFs often lose formulas in text extraction (fraction bars, superscripts), while the vendor's reference driver
states the same conversions as plain C (`temp_var = 0.00390625f; par_t1 = reg_par_t1 / temp_var;`). Only repositories
of organisations in trust.OFFICIAL_GITHUB_ORGS are searched, so what is stored is classified OFFICIAL_REPO.
"""

from __future__ import annotations

import re
from typing import Any, Callable, Dict, List, Optional

import httpx

from embedforge.truth.source_store import Source, SourceStore

API = "https://api.github.com"
# vendor organisations that publish device drivers (framework orgs are excluded: they are not the part's maker)
VENDOR_ORGS = ["boschsensortec", "STMicroelectronics", "tdk-invensense", "Sensirion", "Infineon", "analogdevicesinc",
               "nxp-mcuxpresso", "renesas", "NordicSemiconductor", "espressif", "microchip-pic-avr-solutions", "raspberrypi"]
_VENDOR_HINT = {"bosch": "boschsensortec", "bmp": "boschsensortec", "bme": "boschsensortec", "bmi": "boschsensortec",
                "bma": "boschsensortec", "bmm": "boschsensortec", "bhi": "boschsensortec", "st": "STMicroelectronics",
                "lsm": "STMicroelectronics", "lis": "STMicroelectronics", "lps": "STMicroelectronics", "vl53": "STMicroelectronics",
                "icm": "tdk-invensense", "mpu": "tdk-invensense", "sht": "Sensirion", "scd": "Sensirion", "sgp": "Sensirion",
                "sps": "Sensirion", "dps": "Infineon", "tle": "Infineon", "adxl": "analogdevicesinc", "ad7": "analogdevicesinc"}
MAX_FILE_BYTES = 400_000


def _terms(part: str) -> List[str]:
    """BMP388 -> BMP388, BMP38, BMP3 (vendors name repositories after the family)."""
    p = re.sub(r"[^A-Za-z0-9]", "", part or "")
    out = []
    while len(p) >= 4 or (len(p) >= 3 and not out):
        out.append(p)
        if not p[-1].isdigit():
            break
        p = p[:-1]
    return out[:4]


def _orgs_for(part: str, vendor: str) -> List[str]:
    v = (vendor or "").strip().lower()
    hinted = [o for k, o in _VENDOR_HINT.items() if v.startswith(k) or (part or "").lower().startswith(k)]
    rest = [o for o in VENDOR_ORGS if o not in hinted]
    return list(dict.fromkeys(hinted + rest))


def find_reference_code(store: SourceStore, part: str, vendor: str = "", get: Optional[Callable[..., Any]] = None,
                        max_files: int = 3) -> Dict[str, Any]:
    """Search the vendors' official GitHub organisations for a repository named after the part (or its family), store
    its main C sources and return them as sources to read_source."""
    get = get or (lambda url, **kw: httpx.get(url, timeout=25, follow_redirects=True,
                                              headers={"Accept": "application/vnd.github+json", "User-Agent": "EmbedForge"}, **kw))
    terms = _terms(part)
    if not terms:
        return {"found": False, "error": "give the part number, e.g. 'BMP388'"}
    orgs = _orgs_for(part, vendor)
    repos: List[Dict[str, Any]] = []
    for term in terms:
        for chunk in (orgs[:6], orgs[6:]):
            if not chunk:
                continue
            q = f"{term} in:name " + " ".join(f"org:{o}" for o in chunk)
            try:
                r = get(f"{API}/search/repositories", params={"q": q, "per_page": 5})
            except httpx.HTTPError as e:
                return {"found": False, "error": f"GitHub search failed: {e}"}
            if r.status_code != 200:
                return {"found": False, "error": f"GitHub search failed ({r.status_code}): {r.text[:160]}"}
            repos += [it for it in r.json().get("items", []) if it.get("owner", {}).get("login", "").lower() in {o.lower() for o in orgs}]
        if repos:
            break
    if not repos:
        return {"found": False, "note": f"No repository named after {part} in the vendors' official GitHub organisations "
                                        f"({', '.join(orgs[:6])}, ...). Use the datasheet, or web_search the vendor's site."}
    stored: List[Source] = []
    for repo in repos[:2]:
        full, branch = repo["full_name"], repo.get("default_branch") or "master"
        files: List[Dict[str, Any]] = []
        for sub in ("", "src", "driver", "drivers"):
            try:
                r = get(f"{API}/repos/{full}/contents/{sub}".rstrip("/"))
            except httpx.HTTPError:
                continue
            if r.status_code == 200 and isinstance(r.json(), list):
                files += [f for f in r.json() if f.get("type") == "file" and re.search(r"\.(c|h|cpp|hpp)$", f.get("name", ""), re.I)]
            if files:
                break
        fam = terms[-1].lower()
        files.sort(key=lambda f: (not f["name"].lower().startswith(fam), not f["name"].lower().endswith(".c"), -int(f.get("size") or 0)))
        for f in files[:max_files]:
            if int(f.get("size") or 0) > MAX_FILE_BYTES or not f.get("download_url"):
                continue
            try:
                raw = get(f["download_url"])
            except httpx.HTTPError:
                continue
            if raw.status_code == 200:
                url = f.get("html_url") or f"https://github.com/{full}/blob/{branch}/{f['path']}"
                stored.append(store.add(url, f"{full}/{f['path']} (manufacturer reference code)", raw.text, kind="code"))
        if len(stored) >= max_files:
            break
    if not stored:
        return {"found": False, "note": f"Found {repos[0]['full_name']} but could not download its sources."}
    return {"found": True, "repository": repos[0]["html_url"],
            "sources": [{"source_id": s.id, "url": s.url, "tier": s.tier, "chars": s.chars} for s in stored],
            "next": "read_source(source_id, '<what you need>', e.g. 'par_t1 temp_var' or 'compensate') for the conversions and "
                    "register handling; quote it in record_formula / record_registers like the datasheet."}

embedforge/truth/registers.py:
"""What the code MEANS, checked against the datasheet: register fields, multi-byte layouts, burst reads and formulas.

Facts and sequences prove that the right numbers appear in the right order. They cannot tell that 0x03 written to
PWR_CTRL means "sleep" when the datasheet's table says mode is bits 5..4, or that `data[0] << 16` puts the XLSB byte on
top. So the model also records, from verbatim datasheet text:

  * registers   — name, address and fields (bit positions, named values):  PWR_CTRL 0x1B: press_en bit 0, temp_en bit 1,
                  mode bits 5..4 {sleep: 0, forced: 1|2, normal: 3}
  * layouts     — how a multi-byte value is spread over registers:  UP = 0x04 | 0x05 << 8 | 0x06 << 16, unsigned
  * bursts      — registers that must be read in one transaction (data shadowing)
  * formulas    — the conversions the code must implement:  PAR_T1 = NVM_PAR_T1 / 2^-8;  T_LIN = ...

and verify checks the code statically (truth.flow, no simulation):

  * every register write is decoded into its fields; reserved bits and unnamed field values are reported;
  * a bit mask applied to a register byte must select defined fields (STATUS & 0x0C on a register whose flags are bits
    4..6 is an error);
  * every shift applied to a byte read from a layout register must be that byte's position in the layout;
  * reads that touch a burst range must read the whole range at once;
  * probe run: the code is walked with concrete bytes for the layout registers (two random sets); every recorded formula
    is evaluated on the same bytes and its result must be among the numbers the code computes.
"""

from __future__ import annotations

import ast
import json
import math
import random
import re
import threading
import unicodedata
from dataclasses import asdict, dataclass, field
from functools import lru_cache
from pathlib import Path
from typing import Any, Callable, Dict, Iterable, List, Optional, Tuple

from embedforge.core.files import load_json, write_atomic
from embedforge.truth.flow import FlowModel, Part, RxByte, RxWord, Walker, is_int, writes_of
from embedforge.truth.ledger import (GAP, FactLedger, _index, _squash, bounded, parse_int, quote_mismatch, unescape_literals,
                                     value_in_text)
from embedforge.truth.source_store import SourceStore

MAX_QUOTE = 2000
_ALNUM = re.compile(r"[^a-z0-9]")


def _alnum(s: str) -> str:
    return _ALNUM.sub("", (s or "").lower())


_GAP = GAP
_unescape = unescape_literals


@lru_cache(maxsize=8)
def _squashed(text: str, strip_comments: bool) -> str:
    if strip_comments:
        text = re.sub(r"/\*.*?\*/|//[^\n]*", " ", text, flags=re.S)
    return _squash(text)


def verbatim(quote: str, text: str) -> bool:
    """The quote is in the text, ignoring whitespace, case and quote marks; '…' / '...' may stand for omitted text between
    verbatim pieces (in order, close together), and C comments may be left out of a quoted code block."""
    q = _unescape(quote)
    variants = [(q, False)]
    if "/*" in text or "//" in text:
        variants.append((re.sub(r"/\*.*?\*/|//[^\n]*", " ", q, flags=re.S), True))
    for qq, strip in variants:
        parts = [_squash(p) for p in _GAP.split(qq) if _squash(p)]
        if not parts or (len(parts) > 1 and min(len(p) for p in parts) < 8):
            continue
        ix = None if strip else _index(text)   # word boundaries at both ends: '1B PWR_CTRL' is not a quote of '0x1B PWR_CTRL'
        tt = _squashed(text, strip) if strip else ix.s
        start = tt.find(parts[0])
        while start >= 0:
            pos, ok = start + len(parts[0]), True
            for p in parts[1:]:
                i = tt.find(p, pos)
                if i < 0 or i - pos > 1500:
                    ok = False
                    break
                pos = i + len(p)
            if ok and ix is not None:
                sp = ix.span(start, pos)
                ok = sp is not None and bounded(text, sp[0], sp[1], parts[0][0], parts[-1][-1])
            if ok:
                return True
            start = tt.find(parts[0], start + 1)
    return False


def _quote_ok(store: SourceStore, source_id: str, quote: str, what: str) -> Optional[str]:
    src = store.get(source_id)
    if src is None:
        return f"{what}: source_id {source_id!r} is not a stored source"
    if len(_squash(quote)) < 12:
        return f"{what}: quote too short — copy the full table rows / sentence from read_source"
    if len(quote) > MAX_QUOTE:
        return f"{what}: quote longer than {MAX_QUOTE} chars — quote only the rows that state it"
    if not verbatim(quote, src.text):
        where = quote_mismatch(quote, src.text)
        return f"{what}: quote is not verbatim in {source_id}. " + (where or "Copy it exactly from read_source.")
    return None


def table_passages(text: str, keys: List[str], want_bits: bool = True, limit: int = 2, size: int = 520) -> List[str]:
    """Verbatim windows of a source starting at the line where one of `keys` (register name or address) appears, best
    first: register descriptions with bit rows ('Table 40: Register 0x1B ... Bit 5..4 mode') before memory-map rows and
    the table of contents."""
    scored = []
    for key in [k for k in keys if k and len(k) >= 2]:
        if re.fullmatch(r"0x[0-9A-Fa-f]+", key):   # TI writes the address 0x01 as 01h (two digits: '0h' is a reset value)
            rxs = [rf"(?<![0-9A-Za-z]){re.escape(key)}(?![0-9A-Za-z])", rf"(?<![0-9A-Za-z]){int(key, 16):02X}h(?![0-9A-Za-z])"]
        else:
            rxs = [re.escape(key)]
        for m in (m for rx in rxs for m in re.finditer(rx, text, re.I)):
            a = text.rfind("\n", 0, m.start()) + 1
            if m.start() - a > 200:   # a PDF line that is a whole page (TI): start at the table caption or the key itself
                cap = [c for c in re.finditer(r"Table\s+\d+(?:[-.]\d+)*\.?\s", text[m.start() - 160:m.start()])]
                a = m.start() - 160 + cap[-1].start() if cap else m.start()
            window = text[a:a + size]
            if "....." in window[:200]:
                continue   # table of contents
            bits = bool(re.search(r"\bBit\s*\d", window) or re.search(r"\bBIT\s+FIELD\b|Field\s+Descriptions", window, re.I))
            if bits and want_bits:   # a field table: up to the next table's caption ('Table 7-7. Conversion ...', not
                nxt = re.search(r"\sTable\s+\d+(?:-\d+)?[.:]\s+[A-Z]", text[a + 60:a + 2400])   # 'see Table 7-7 for')
                window = text[a:a + 60 + nxt.start()] if nxt else text[a:a + 2400]
            score = (2 if bits or not want_bits else 0) + (1 if re.match(r"\s*Table\s+\d+", window) else 0)
            scored.append((-score, a, window))
    out: List[str] = []
    for _s, _a, w in sorted(scored):
        w = (w[:w.rfind("\n")] if "\n" in w[max(size, len(w)) // 3:] else w).strip()
        if w and all(w[:80] not in o for o in out):
            out.append(w)
        if len(out) >= limit:
            break
    return out


def layout_passages(text: str, addrs: List[int], limit: int = 3) -> List[str]:
    """Shortest verbatim spans (whole lines) that contain every address of a multi-byte value: its table rows."""
    pats = [re.compile(rf"(?<![0-9a-z])0x0*{a:x}(?![0-9a-z])", re.I) for a in addrs]
    if not pats:
        return []
    out: List[str] = []
    for m in pats[0].finditer(text):
        lo, hi = m.start(), m.end()
        ok = True
        for p in pats[1:]:
            near = [x for x in p.finditer(text, max(0, m.start() - 700), m.end() + 700)]
            if not near:
                ok = False
                break
            x = min(near, key=lambda x: abs(x.start() - m.start()))
            lo, hi = min(lo, x.start()), max(hi, x.end())
        if not ok or hi - lo > 900:
            continue
        a = text.rfind("\n", 0, lo) + 1
        b = text.find("\n", hi)
        span = text[a:b if b >= 0 else len(text)].strip()
        if "....." not in span and span not in out:
            out.append(span)
        if len(out) >= limit:
            break
    return sorted(out, key=len)


_ROW_RANGE = re.compile(r"(?<![0-9a-z])0x([0-9a-f]{1,4})(?![0-9a-z])[^\n<\[]{0,40}?([a-z][\w ]{1,30}?)\s*[<\[]\s*(\d+)\s*:\s*(\d+)\s*[>\]]", re.I)


@lru_cache(maxsize=8)
def row_ranges(text: str) -> Tuple[Tuple[int, str, int, int], ...]:
    """Register-content rows written as NAME<hi:lo> / NAME[hi:lo] next to their address ('0x32 NVM_PAR_T1<15:8>'):
    (address, normalised name, hi, lo). They state exactly which bytes make up a multi-byte value."""
    return tuple((int(m.group(1), 16), _alnum(m.group(2)), int(m.group(3)), int(m.group(4))) for m in _ROW_RANGE.finditer(text))


def _num(v: Any) -> Optional[int]:
    if is_int(v):
        return v
    if isinstance(v, str):
        s = v.strip().lower().replace("_", "")
        if re.fullmatch(r"[01]+b", s):
            return int(s[:-1], 2)
        return parse_int(s)
    return None


def _hex(v: int) -> str:
    return f"0x{v:02X}"


def _bits_in_quote(quote: str, hi: int, lo: int, fname: str = "") -> bool:
    """The field's bit position is stated in its own row: right before its name ('Bit 5..4 mode', '0 press_en') or right
    after it ('mode[5:4]', 'press_en (bit 0)'). A bit number elsewhere in the quote belongs to another row."""
    q = quote.translate(dict.fromkeys(map(ord, "\u2010\u2011\u2012\u2013\u2014\u2212"), "-")).lower()
    sep = r"\s*(?:\.\.\.?|:|-|to|…)\s*"
    spec = rf"{lo}" if hi == lo else rf"(?:{hi}{sep}{lo}|{lo}{sep}{hi})"
    before = re.compile(rf"(?:^|[^0-9a-z.])(?:bits?\s*|[\[<]\s*|[bd])?{spec}(?![0-9.])[\s|:\]>)\-]*$")
    after = re.compile(rf"^[\s:|(\[<\-=]*(?:bits?\s*|[bd])?{spec}(?![0-9])")
    for a, b in _name_spans(q, fname or ""):
        if before.search(q[max(0, a - 16):a]) or after.search(q[b:b + 16]):
            return True
    return False


def _stated_bits(quotes: List[str], fname: str) -> Optional[Tuple[int, int]]:
    """The bit position a quote states for a field in its own row ('Bit 4..0 odr_sel' -> (4, 0)), if any."""
    for q in quotes:
        low = q.lower().translate(dict.fromkeys(map(ord, "‐‑‒–—−"), "-"))
        for a, _b in _name_spans(low, fname):
            m = re.search(r"(?:^|[^0-9a-z.])(?:bits?\s*)?(\d{1,2})(?:\s*(?:\.\.\.?|:|-|to)\s*(\d{1,2}))?[\s|:\]>)\-]*$", low[max(0, a - 16):a])
            if m:
                h = int(m.group(1))
                l = int(m.group(2)) if m.group(2) else h
                return (max(h, l), min(h, l))
    return None


def _name_spans(quote: str, name: str) -> List[Tuple[int, int]]:
    """Where `name` occurs in the quote, ignoring case, spaces, underscores, hyphens and slashes inside it (TI names
    fields T/nA and DR/Alert; the TMP117 re-run was refused 15 times on them, typed T_nA, TnA and T/nA alike)."""
    chars = [re.escape(c) for c in name if c.isalnum()]
    if not chars:
        return []
    rx = r"(?<![A-Za-z0-9_])" + r"[\s_\-/]*".join(chars) + r"(?![A-Za-z0-9_])"   # a whole word: drdy is not drdy_press
    return [(m.start(), m.end()) for m in re.finditer(rx, quote, re.I)]


def _stated_addrs(text: str, name: str) -> set:
    """Addresses written right before a register's name, with only spacing, quote marks or table bars between them:
    'Register 0x1B “PWR_CTRL”', '| 0x1B | PWR_C TRL |' (table cells wrap names), '0x1B PWR_CTRL'."""
    chars = [re.escape(c) for c in name if c.isalnum()]
    if len(chars) < 3:
        return set()
    rx = (r"(?<![0-9A-Za-z])0x([0-9A-Fa-f]{1,4})(?![0-9A-Za-z])[\s|\"'“”‘’]{0,8}(?<![A-Za-z0-9_])"
          + r"[\s_\-]*".join(chars) + r"(?![A-Za-z0-9_])")
    return {int(m.group(1), 16) for m in re.finditer(rx, text, re.I)}


_REG_HEADER = re.compile(r"Register\s+(0x[0-9A-Fa-f]+)\b", re.I)


def own_section(quote: str, addr: int) -> str:
    """The part of a quote that describes the register at `addr`: a quote running from one register's table into the
    next ('Register 0x1B PWR_CTRL … Table 41: Register 0x1C OSR … Bit 5..3 osr_t') must not lend the other register's
    fields. Without a header for addr in the quote, all of it."""
    heads = [(m.start(), int(m.group(1), 16)) for m in _REG_HEADER.finditer(quote)]
    own = [s for s, a in heads if a == addr]
    if not own:
        return quote
    first = own[0]
    start = first if any(a != addr for s, a in heads if s < first) else 0
    end = next((s for s, a in heads if s > first and a != addr), len(quote))
    section = quote[start:end]
    # PDF text can put a table's rows after the next header ('Table 41: Register 0x1C OSR', '4.3.18 Register 0x1D ODR',
    # then OSR's 'Bit 2..0 osr_p' rows): a section with no bit rows of its own was cut wrong — keep the whole quote
    return section if re.search(r"\bBit\s*\d", section, re.I) else quote


def _value_forms(v: int, width: int) -> List[str]:
    forms = {str(v), f"0x{v:x}", f"0x{v:02x}", f"{v:x}h", format(v, f"0{width}b") if width <= 16 else "",
             "0b" + format(v, f"0{width}b") if width <= 16 else "", "0b" + format(v, "b")}
    return [f for f in forms if f]


_VAL = r"(?:0x[0-9a-f]+|0b[01]+|[0-9a-f]+h|[0-9]+)"
_VAL_SEP = r"\s*(?:/|,|\band\b|\bor\b)\s*"
_VAL_LIST = rf"{_VAL}(?:{_VAL_SEP}{_VAL})*"
_VALUE_BEFORE = re.compile(rf"(?:^|[^0-9a-z.])({_VAL_LIST})[\s|:=>\-,(]*$")
_VALUE_AFTER = re.compile(rf"^\s*(?:(?:mode|state|setting|value)\s*)?(?:=|:|\(|->|→)\s*({_VAL_LIST})(?![0-9a-z])")
_VALUE_AFTER_BARE = re.compile(rf"^\s*(?:(?:mode|state|setting|value)\s*)?[\s|]*({_VAL_LIST})(?![0-9a-z])")


def _value_near(quote: str, name: str, v: int, width: int, reach: int = 16) -> bool:
    """A named value is stated right next to its name: the value token(s) directly before it ('11 normal mode', '01 and 10
    Forced mode', '| 0xB6 | softreset') or after it with an assignment mark ('normal = 0b11', 'sleep: 00'), or bare after
    it when no value stands before the name ('Normal mode 11' at the start of a row). A value further away is a
    neighbouring row's: in '00 sleep mode 01/10 forced', 01 is forced's, not sleep's."""
    low = quote.lower()
    forms = {f.lower() for f in _value_forms(v, width)}

    def hit(m: Any) -> bool:
        return bool(m) and any(tok.strip() in forms for tok in re.split(_VAL_SEP, m.group(1)))
    for a, b in _name_spans(quote, name):
        before = _VALUE_BEFORE.search(low[max(0, a - reach):a])
        after = low[b:b + reach]
        if hit(before) or hit(_VALUE_AFTER.search(after)) or (not before and hit(_VALUE_AFTER_BARE.search(after))):
            return True
    return False


# ------------------------------------------------------------------ records


# which byte of a wide register goes first on the bus. A byte, not a bit: 'MSB first' alone is usually the bit order
_MSB_BYTE = r"(?:most[\s-]+significant|msb|high(?:er)?|upper)[\s-]*(?:data[\s-]+)?(?:bytes?|8[\s-]*bits|octets?)"
_LSB_BYTE = r"(?:least[\s-]+significant|lsb|low(?:er)?)[\s-]*(?:data[\s-]+)?(?:bytes?|8[\s-]*bits|octets?)"


def stated_byte_order(quote: str) -> str:
    """'msb_first' / 'lsb_first' when the quote says which byte of a register is sent first ('Register bytes are sent
    with the most significant byte first, followed by the least significant byte'), else ''."""
    q = re.sub(r"\s+", " ", unicodedata.normalize("NFKC", quote or "")).lower()
    found = set()
    for first, second, order in ((_MSB_BYTE, _LSB_BYTE, "msb_first"), (_LSB_BYTE, _MSB_BYTE, "lsb_first")):
        pats = (rf"\b{first}\b[^.;]{{0,40}}\bfirst\b",                                        # ... MSB byte (is sent) first
                rf"\bfirst\b[^.;]{{0,50}}\b(?:is|are)\b[^.;]{{0,25}}\b{first}",              # the first byte is the MSB
                rf"\b{first}\b[^.;]{{0,60}}\b(?:followed by|then|before)\b[^.;]{{0,30}}\b{second}",
                rf"\b{second}\b[^.;]{{0,60}}\b(?:after|follows)\b[^.;]{{0,30}}\b{first}")
        if any(re.search(p, q) for p in pats):
            found.add(order)
    return found.pop() if len(found) == 1 else ""


def _order_word(s: str) -> str:
    """byte_order as models write it ('MSB first', 'big-endian') -> 'msb_first' / 'lsb_first' / ''."""
    s = str(s or "").strip().lower()
    if re.search(r"msb|most|big|high", s):
        return "msb_first"
    if re.search(r"lsb|least|little|low", s):
        return "lsb_first"
    return ""


def _width_of(raw: Dict[str, Any]) -> int:
    """A register item's width in bits: 8 unless it says 16 / 24 / 32 ('16', 16, '16-bit')."""
    m = re.fullmatch(r"\s*(8|16|24|32)\s*(?:-?\s*bits?)?\s*", str(raw.get("width") if raw.get("width") is not None else ""), re.I)
    return int(m.group(1)) if m else 8


@dataclass
class FieldDef:
    name: str
    hi: int
    lo: int
    values: Dict[str, List[int]] = field(default_factory=dict)

    @property
    def width(self) -> int:
        return self.hi - self.lo + 1

    @property
    def mask(self) -> int:
        return ((1 << self.width) - 1) << self.lo

    def get(self, reg_value: int) -> int:
        return (reg_value & self.mask) >> self.lo

    def label(self) -> str:
        return f"{self.name} bit {self.lo}" if self.hi == self.lo else f"{self.name} bits {self.hi}..{self.lo}"

    def value_name(self, v: int) -> str:
        return next((n for n, vs in self.values.items() if v in vs), "")


@dataclass
class RegisterDef:
    id: str
    device: str
    name: str
    addr: int
    fields: List[FieldDef]
    source_id: str
    quote: str
    id_value: Optional[int] = None
    reset: Optional[int] = None        # the value after power-on / soft reset (the memory map's default column)
    reset_quote: str = ""
    width: int = 8                     # bits; 16 / 32 for parts whose registers are wider than a byte (TI's TMP117)
    byte_order: str = ""               # wide registers: 'msb_first' / 'lsb_first', the order of its bytes on the bus
    byte_order_quote: str = ""         # the datasheet sentence that says so

    @property
    def defined_mask(self) -> int:
        m = 0
        for f in self.fields:
            m |= f.mask
        return m

    @property
    def full(self) -> int:
        """Every bit of the register: 0xFF, 0xFFFF for a 16-bit register."""
        return (1 << self.width) - 1

    @property
    def nbytes(self) -> int:
        return max(1, self.width // 8)

    @property
    def modelled(self) -> bool:
        """verify can read its bytes: a byte, or a wide register with its byte order on record."""
        return self.width <= 8 or self.byte_order in ("msb_first", "lsb_first")

    def hexv(self, v: int) -> str:
        return f"0x{v:0{2 * self.nbytes}X}"

    def field(self, name: str) -> Optional[FieldDef]:
        key = _alnum(name)
        hit = next((f for f in self.fields if _alnum(f.name) == key), None)
        if hit is None and key and not re.search(r"\d", key):
            # the BMP388's OSR table prints osr_t as 'osr4_t' (a footnote mark in the name): a name without digits finds
            # the one field that is it with a single digit added; 'int2_lvl' never matches 'int1_lvl'
            def one_digit_more(n: str) -> bool:
                return len(n) == len(key) + 1 and any(n[i].isdigit() and n[:i] + n[i + 1:] == key for i in range(len(n)))
            near = [f for f in self.fields if one_digit_more(_alnum(f.name))]
            hit = near[0] if len(near) == 1 else None
        return hit

    def decode(self, v: int) -> str:
        parts = []
        for f in sorted(self.fields, key=lambda x: -x.lo):
            fv = f.get(v)
            nm = f.value_name(fv)
            parts.append(f"{f.name}={fv}" + (f" ({nm})" if nm else ""))
        extra = v & ~self.defined_mask & self.full
        if extra:
            parts.append(f"undefined bits {self.hexv(extra)}")
        return ", ".join(parts)


@dataclass
class LayoutPart:
    addr: int
    hi: int = 7
    lo: int = 0

    @property
    def width(self) -> int:
        return self.hi - self.lo + 1

    def text(self) -> str:
        return _hex(self.addr) + ("" if (self.hi, self.lo) == (7, 0) else f"[{self.hi}:{self.lo}]")


@dataclass
class LayoutDef:
    id: str
    device: str
    name: str
    parts: List[LayoutPart]   # least significant first
    signed: bool
    source_id: str
    quote: str

    @property
    def width(self) -> int:
        return sum(p.width for p in self.parts)

    def offset_of(self, k: int) -> int:
        return sum(p.width for p in self.parts[:k])

    def decode(self, byte_of: Callable[[int], int]) -> int:
        v = 0
        for k, p in enumerate(self.parts):
            v |= ((byte_of(p.addr) >> p.lo) & ((1 << p.width) - 1)) << self.offset_of(k)
        if self.signed and v >> (self.width - 1):
            v -= 1 << self.width
        return v

    def describe(self) -> str:
        terms = [p.text() + (f" << {self.offset_of(k)}" if self.offset_of(k) else "") for k, p in enumerate(self.parts)]
        return f"{self.name} = {' | '.join(terms)} ({'signed' if self.signed else 'unsigned'} {self.width}-bit)"


@dataclass
class ConstraintDef:
    """A rule the datasheet states over register settings, checked after every register write the code makes: e.g. in
    normal mode the conversion time must fit in the sampling period. `require` (and `when`, if given) are expressions
    over REGISTER.field names."""
    id: str
    device: str
    name: str
    require: str
    when: str
    source_id: str
    quotes: List[str]
    unit: str = ""


@dataclass
class BurstDef:
    id: str
    device: str
    name: str
    start: int
    end: int
    source_id: str
    quote: str


@dataclass
class FormulaDef:
    id: str
    device: str
    name: str
    steps: List[List[str]]   # [var, expression] in order; the formula's value is the last var
    source_id: str
    quote: str
    unit: str = ""

    def text(self) -> str:
        return "; ".join(f"{v} = {e}" for v, e in self.steps)


# ------------------------------------------------------------------ formula expressions

_FUNCS: Dict[str, Callable[..., float]] = {
    "pow": lambda a, b: float(a) ** float(b), "powf": lambda a, b: float(a) ** float(b), "sqrt": math.sqrt, "sqrtf": math.sqrt,
    "exp": math.exp, "expf": math.exp, "log": math.log, "logf": math.log, "log10": math.log10, "abs": abs, "fabs": abs,
    "fabsf": abs, "ldexp": lambda x, e: math.ldexp(float(x), int(e)),
}
_POW_HELPER = re.compile(r"pow\w*|\w+_pow\w*", re.I)   # a vendor's own power helper: Bosch's pow_bmp3(t_lin, 2)


def _func(name: str) -> Optional[Callable[..., float]]:
    n = name.lower()
    return _FUNCS.get(n) or (_FUNCS["pow"] if _POW_HELPER.fullmatch(n) else None)

_CAST_RE = re.compile(r"\(\s*(?:const\s+)?(?:float|double|u?int(?:8|16|32|64)_t|int|long|unsigned(?:\s+int|\s+long)?|signed)\s*\)")


def prep_expr(expr: str) -> str:
    """Datasheet/C notation -> the expression language: ^ is power, casts and struct prefixes (calib->par_t1) drop out,
    C number suffixes (0.5f, 16384UL) go, // is C integer division."""
    s = (expr or "").strip().rstrip(";")
    s = s.translate(dict.fromkeys(map(ord, "‐‑‒–—−"), "-")).replace("×", "*").replace("÷", "/").replace("·", "*")
    s = _CAST_RE.sub("", s)
    s = re.sub(r"\b[A-Za-z_]\w*\s*(?:->|\.)\s*(?=[A-Za-z_])", "", s)
    s = re.sub(r"(?<=[0-9.])([fF]|[uU]?[lL]{1,2}|[uU])\b", "", s)
    s = s.replace("^", "**")
    return s


def _parse(expr: str) -> ast.AST:
    tree = ast.parse(prep_expr(expr), mode="eval")
    for node in ast.walk(tree):
        ok = isinstance(node, (ast.Expression, ast.BinOp, ast.UnaryOp, ast.Name, ast.Load, ast.Call, ast.Add, ast.Sub, ast.Mult,
                               ast.Div, ast.FloorDiv, ast.Pow, ast.USub, ast.UAdd, ast.LShift, ast.RShift, ast.BitAnd, ast.BitOr, ast.Mod))
        ok = ok or (isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and not isinstance(node.value, bool))
        if isinstance(node, ast.Call) and not (isinstance(node.func, ast.Name) and _func(node.func.id) and not node.keywords):
            ok = False
        if not ok:
            raise ValueError(f"unsupported syntax '{ast.unparse(node) if hasattr(ast, 'unparse') else type(node).__name__}' "
                             "(use numbers, names, + - * / // ** >> << & | and pow/sqrt/exp/log/abs)")
    return tree


def _names(tree: ast.AST) -> List[str]:
    funcs = {id(n.func) for n in ast.walk(tree) if isinstance(n, ast.Call)}
    return [n.id.lower() for n in ast.walk(tree) if isinstance(n, ast.Name) and id(n) not in funcs]


def _constants(tree: ast.AST) -> List[Tuple[str, float, Optional[int]]]:
    """(text, value, power-of-two exponent or None) for the numbers a formula uses; 2**-8 counts as one constant."""
    out: List[Tuple[str, float, Optional[int]]] = []
    skip = set()
    for n in ast.walk(tree):
        if isinstance(n, ast.BinOp) and isinstance(n.op, ast.Pow) and isinstance(n.left, ast.Constant) and n.left.value == 2:
            e = n.right
            k = e.value if isinstance(e, ast.Constant) else (-e.operand.value if isinstance(e, ast.UnaryOp) and isinstance(e.op, ast.USub) and isinstance(e.operand, ast.Constant) else None)
            if isinstance(k, int):
                out.append((f"2^{k}", 2.0 ** k, k))
                skip.update({id(n.left), id(e), id(getattr(e, "operand", None))})
    for n in ast.walk(tree):
        if isinstance(n, ast.Constant) and id(n) not in skip and n.value not in (0, 1):
            v = float(n.value)
            e = math.log2(abs(v)) if v else 0.5
            out.append((repr(n.value), v, int(round(e)) if abs(e - round(e)) < 1e-12 and abs(e) >= 2 else None))
    return out


def _const_in_quote(quote: str, value: float, exp: Optional[int]) -> bool:
    """Is the constant stated in the quote? PDF text loses superscripts and fraction bars ('2−8' is 2^-8, '230' is 2^30),
    so a power of two may appear as 2^k, 2**k, 2-k, 2k (k written right after the 2) or as its decimal value."""
    q = re.sub(r"\s+", " ", quote.translate(dict.fromkeys(map(ord, "‐‑‒–—−"), "-"))).lower()
    q = re.sub(r"\s*(\^|\*\*)\s*", r"\1", q)
    nums = [float(x) for x in re.findall(r"(?<![0-9.])[0-9]+(?:\.[0-9]+)?(?:e-?[0-9]+)?", q)]
    if any(abs(x - value) <= 1e-9 * max(1.0, abs(value)) for x in nums):
        return True
    if exp is not None:
        k = str(exp)
        pats = [rf"2\^\(?{re.escape(k)}\)?", rf"2\*\*\(?{re.escape(k)}\)?", rf"1<<{k}(?![0-9])", rf"(?<![0-9])2{re.escape(k)}(?![0-9])"]
        if exp < 0:
            pats.append(rf"/ ?2\^?{-exp}(?![0-9])")
        else:
            pats.append(rf"(?<![0-9])2\^? ?- ?{k}(?![0-9])")   # x / 2^-k written as a fraction: multiplying by 2^k
        if any(re.search(p, q) for p in pats):
            return True
        if exp < 0 and any(abs(x - 2.0 ** -exp) <= 1e-9 * 2.0 ** -exp for x in nums):
            return True   # x * 2^-8 stated as x / 256
    return False


_STMT_LHS = re.compile(r"(?<![\w>.])((?:[A-Za-z_]\w*\s*(?:->|\.)\s*)*[A-Za-z_]\w*)\s*=(?!=)")
_PROSE_CUT = re.compile(r"\s(?:and|or|where|with|for|when|if|which|is|are|the|to|as|in|of|then|while|respectively)\b|[,;]\s")
_AMBIGUOUS_POW = re.compile(r"(?<![\w.^*])2(-?\d{1,2})(?![\w.])")   # '214' / '2-8': 2^14 / 2^-8 with the superscript lost


_SI_PREFIX = {"k": 1e3, "m": 1e-3, "μ": 1e-6, "u": 1e-6, "n": 1e-9}
_PREFIXED_UNIT = re.compile(r"(\d+(?:\.\d+)?)\s*([kmμun])\s*(?:°\s*[CF]|(?:s|V|A|W|Hz|Pa|g|bar|m|K|G)\b|Ω)")
_PER_COUNT = re.compile(r"\b(?:one|1|each)\s+(LSB|count|code|digit|step)\b[^.]{0,25}?(?:equals|=|is|corresponds to|represents)\s*[-+]?\d", re.I)


_OFFICIAL_TIERS = ("OFFICIAL_MANUFACTURER", "OFFICIAL_REPO")


def official_instead(store: SourceStore, source_id: str) -> List[str]:
    """The manufacturer's documents on record when `source_id` is an UNOFFICIAL one (the TMP117 fix-up took its
    temperature conversion from Adafruit's library header while TI's datasheet was stored): their ids, else []."""
    src = store.get(source_id)
    if src is None or src.tier != "UNOFFICIAL":
        return []
    return sorted(s.id for s in store.sources.values() if s.tier in _OFFICIAL_TIERS)


def _prefix_factors(quote: str) -> set:
    """Unit conversions the quote itself implies: TI's 'One LSB equals 7.8125 m°C' makes / 1000 (to °C) part of the
    formula, and 0.0078125 (the same number in °C) a constant of it; '5 µs' gives 1e6, 1e-6 and 5e-6. Only prefixes
    the quote puts on a number."""
    out = set()
    for m in _PREFIXED_UNIT.finditer(unicodedata.normalize("NFKC", quote or "")):
        f = _SI_PREFIX[m.group(2)]
        out |= {f, 1 / f, float(m.group(1)) * f}
    return out


def _quote_statements(quote: str) -> List[Tuple[str, str]]:
    """The formulas a quote itself states, as (assigned name, expression text): 'PAR_P1 = (NVM_PAR_P1 - 2^14) / 2^20' from
    a converted datasheet, 'calib_data->t_lin = partial_data2 + ...' from reference code. Text that does not parse
    cleanly (a lost fraction bar, prose, garbled math fonts) states nothing here."""
    import unicodedata
    q = unicodedata.normalize("NFKC", _unescape(quote))
    q = re.sub(r"<sup>(.*?)</sup>", r"^(\1)", q)
    q = re.sub(r"<sub>(.*?)</sub>", r"_\1", q)
    q = re.sub(r"</?\w+>", " ", q)
    q = re.sub(r"/\*.*?\*/|//[^\n]*", " ", q, flags=re.S)
    # Markdown bold around words ('**PAR_T1**'), never a power ('2**14', 'x**-8'); code spans; table bars
    q = re.sub(r"(?<![\w)])\*\*(?=[A-Za-z_])([^*\n]{1,80}?)(?<=[\w)])\*\*(?![\w(])", r"\1", q)
    q = re.sub(r"[`|]", " ", q)
    q = q.translate({ord("∙"): "*", ord("⋅"): "*", ord("·"): "*", ord("×"): "*", ord("÷"): "/"})
    marks = list(_STMT_LHS.finditer(q))
    out: List[Tuple[str, str]] = []
    for i, m in enumerate(marks):
        end = marks[i + 1].start() if i + 1 < len(marks) else len(q)
        rhs = q[m.end():end].split(";", 1)[0]
        for text in (rhs, rhs[:c.start()] if (c := _PROSE_CUT.search(rhs)) else None):
            text = re.sub(r"\s+", " ", text or "").strip().rstrip(".,:")
            if not text:
                continue
            try:
                _parse(text)
            except (SyntaxError, ValueError, RecursionError, MemoryError):
                continue
            out.append((re.sub(r"^.*(?:->|\.)\s*", "", m.group(1)).strip().lower(), text))
            break
    return out


def _variants(text: str) -> List[ast.AST]:
    """The expression, plus readings where '2k' / '2-k' is the power 2^k / 2^-k whose superscript the PDF lost, and where
    C code's '/' between integers is integer division (the steps write that as '//')."""
    spots = list(_AMBIGUOUS_POW.finditer(text))[:5]
    texts = []
    for mask in range(1 << len(spots)):
        t, shift = text, 0
        for j, sp in enumerate(spots):
            if mask >> j & 1:
                new = f"2^({sp.group(1)})"
                t = t[:sp.start() + shift] + new + t[sp.end() + shift:]
                shift += len(new) - (sp.end() - sp.start())
        texts.append(t)
    if "/" in text and "//" not in text:
        texts += [t.replace("/", "//") for t in texts]
    out = []
    for t in texts:
        try:
            out.append(_parse(t))
        except (SyntaxError, ValueError, RecursionError, MemoryError):
            pass
    return out


def formula_structure_problem(steps: List[Any], quote: str, name: str) -> Optional[str]:
    """A recorded formula must compute what the quote states, not merely reuse its numbers. On sample inputs, each step
    whose variable the quote assigns is compared with the quote's own expression for it (earlier quote statements feed
    later ones; the step's own inputs are the same on both sides), and the result must be what the quote computes: under
    the formula's name if the quote assigns that name, else one of the quote's values. '/ 2^8' recorded for a quote that
    says '/ 2^-8' is rejected, an algebraically equal rewrite ('* 2^8') is not. A quote with no parseable statement is left
    to the constant check."""
    import random
    stmts = _quote_statements(quote)
    if not stmts:
        return None
    parsed: List[Tuple[str, str, ast.AST]] = []
    try:
        for s in steps:
            s = re.sub(r"^\s*(?:[A-Za-z_]\w*\s*(?:->|\.)\s*)+(?=[A-Za-z_]\w*\s*=)", "", str(s).strip().rstrip(";"))
            m = _STEP_RE.match(s) or (_STEP_RE.match(f"{name} = {s}") if len(steps) == 1 else None)
            if not m:
                return None
            parsed.append((m.group(1).lower(), m.group(2).strip(), _parse(m.group(2))))
        qs = [(lhs, text, _parse(text), _variants(text)) for lhs, text in stmts]
    except (SyntaxError, ValueError, RecursionError, MemoryError):
        return None
    assigned = [v for v, _, _ in parsed]
    inputs = {n for _, _, t in parsed for n in _names(t)} - set(assigned)
    quote_names = {n for _, _, t, _ in qs for n in _names(t)} | {lhs for lhs, _, _, _ in qs}
    names = inputs | set(assigned) | quote_names
    bases = []
    for seed in (11, 23, 37):
        r = random.Random(seed)
        bases.append({n: float(r.randint(3, 4000)) for n in sorted(names)})

    def run(seq, base):   # sequential values: each statement sees the ones before it
        env, vals = dict(base), []
        for var, tree in seq:
            try:
                v = float(eval_expr(tree, env))
                env[var] = v
            except (ArithmeticError, ValueError, KeyError, TypeError, RecursionError):
                v = None
            vals.append((dict(env), v))
        return vals
    step_runs = [run([(v, t) for v, _, t in parsed], b) for b in bases]
    quote_runs = [run([(lhs, t) for lhs, _, t, _ in qs], b) for b in bases]

    def agrees(i: int, value_of, overrides_of) -> Optional[bool]:
        """Does some reading of quote statement i give the step's value on every sample? None: nothing comparable."""
        decided = False
        for variant in qs[i][3]:
            pairs = []
            for b, base in enumerate(bases):
                sv = value_of(b)
                env = dict(quote_runs[b][i - 1][0]) if i > 0 else dict(base)
                env.update(overrides_of(b))
                try:
                    qv = float(eval_expr(variant, env))
                except (ArithmeticError, ValueError, KeyError, TypeError, RecursionError):
                    continue
                if sv is not None and math.isfinite(sv) and math.isfinite(qv):
                    pairs.append((sv, qv))
            if pairs:
                decided = True
                if all(_close(a, b) for a, b in pairs):
                    return True
        return False if decided else None

    def env_before(b: int, k: int) -> Dict[str, float]:
        return step_runs[b][k - 1][0] if k > 0 else bases[b]
    seen: Dict[str, int] = {}
    compared_last = False
    for k, (var, text, tree) in enumerate(parsed):
        idxs = [i for i, (lhs, _, _, _) in enumerate(qs) if lhs == var]
        if not idxs:
            continue
        j = seen.get(var, 0)
        seen[var] = j + 1
        if j < len(idxs):
            idxs = [idxs[j]] + [i for i in idxs if i != idxs[j]]
        used = set(_names(tree)) | set(assigned[:k])   # what the step reads and what earlier steps made: same values in the quote
        res = [agrees(i, lambda b, k=k: step_runs[b][k][1],
                      lambda b, k=k, used=used: {n: v for n, v in env_before(b, k).items() if n in used}) for i in idxs]
        if any(r is True for r in res):
            compared_last = compared_last or k == len(parsed) - 1
            continue
        if any(r is False for r in res):
            lhs, qtext = qs[idxs[0]][0], qs[idxs[0]][1]
            return (f"step {k + 1} ({var} = {text}) does not compute what the quote states: {lhs} = {qtext}. Copy the "
                    "quote's expression — its operators, grouping and the signs of its exponents — not just its numbers.")
    if compared_last or not parsed:
        return None
    # the result itself, whatever the last step's variable is called
    named = [i for i, (lhs, _, _, _) in enumerate(qs) if lhs == name.lower()]
    pool = named or (list(range(len(qs))) if inputs & quote_names else [])
    if not pool:
        return None
    last = len(parsed) - 1
    res = [agrees(i, lambda b: step_runs[b][last][1], lambda b: {n: bases[b][n] for n in inputs}) for i in pool]
    if any(r is True for r in res) or not any(r is False for r in res):
        return None
    if named:
        return (f"the result ({parsed[-1][0]} = {parsed[-1][1]}) is not what the quote computes for {name}: "
                f"{qs[named[0]][0]} = {qs[named[0]][1]}. Copy the quote's expression.")
    return (f"the result ({parsed[-1][0]} = {parsed[-1][1]}) is none of the values the quote's formulas compute "
            f"({'; '.join(f'{l} = {t}' for l, t, _, _ in qs[:3])}). Copy the quote's expression, or quote the text that states this one.")


def eval_expr(tree: ast.AST, env: Dict[str, float]) -> float:
    def ev(n: ast.AST) -> Any:
        if isinstance(n, ast.Expression):
            return ev(n.body)
        if isinstance(n, ast.Constant):
            return n.value
        if isinstance(n, ast.Name):
            return env[n.id.lower()]
        if isinstance(n, ast.UnaryOp):
            v = ev(n.operand)
            return -v if isinstance(n.op, ast.USub) else v
        if isinstance(n, ast.Call):
            return _func(n.func.id)(*[ev(a) for a in n.args])
        a, b = ev(n.left), ev(n.right)
        op = n.op
        if isinstance(op, ast.Add):
            return a + b
        if isinstance(op, ast.Sub):
            return a - b
        if isinstance(op, ast.Mult):
            return a * b
        if isinstance(op, ast.Div):
            return a / b
        if isinstance(op, ast.FloorDiv):   # C integer division: truncates toward zero
            q = abs(int(a)) // abs(int(b))
            return q if (a >= 0) == (b >= 0) else -q
        if isinstance(op, ast.Mod):
            return math.fmod(a, b)
        if isinstance(op, ast.Pow):
            return a ** b
        if isinstance(op, ast.LShift):
            return int(a) << int(b)
        if isinstance(op, ast.RShift):
            return int(a) >> int(b)
        if isinstance(op, ast.BitAnd):
            return int(a) & int(b)
        if isinstance(op, ast.BitOr):
            return int(a) | int(b)
        raise ValueError("unsupported operator")
    return ev(tree)


# ------------------------------------------------------------------ constraint expressions
_FIELD_REF = re.compile(r"\b([A-Za-z_]\w*)\s*\.\s*([A-Za-z_]\w*)\b")
_RULE_NODES = (ast.Expression, ast.BoolOp, ast.And, ast.Or, ast.UnaryOp, ast.Not, ast.USub, ast.UAdd, ast.BinOp, ast.Add,
               ast.Sub, ast.Mult, ast.Div, ast.FloorDiv, ast.Mod, ast.Pow, ast.LShift, ast.RShift, ast.BitAnd, ast.BitOr,
               ast.Compare, ast.Lt, ast.LtE, ast.Gt, ast.GtE, ast.Eq, ast.NotEq, ast.Name, ast.Load)


@dataclass
class _Rule:
    tree: ast.AST
    refs: Dict[str, Tuple["RegisterDef", "FieldDef"]]   # variable -> the register field it reads
    names: Dict[str, int]                               # a field's named value used in the rule ('normal') -> its value


def _constraint_tree(text: str, regs: Dict[str, "RegisterDef"]) -> _Rule:
    """Parse a constraint: REGISTER.field names, a field's named values (PWR_CTRL.mode == normal), numbers, + - * / ^,
    comparisons and and / or / not (&&, ||, !). Nothing else (no calls), so a rule cannot run code."""
    s = str(text).replace("≤", "<=").replace("≥", ">=").replace("≠", "!=")
    s = s.translate(str.maketrans({"·": "*", "×": "*", "∙": "*", "−": "-"}))
    s = s.replace("&&", " and ").replace("||", " or ").replace("^", "**")
    s = re.sub(r"!(?!=)", " not ", s)
    refs: Dict[str, Tuple[RegisterDef, FieldDef]] = {}

    def ref(m: "re.Match[str]") -> str:
        reg = regs.get(m.group(1).lower())
        if reg is None:
            raise ValueError(f"{m.group(1)} is not a recorded register of this device (recorded: {', '.join(sorted(r.name for r in regs.values())) or 'none'})")
        f = reg.field(m.group(2))
        if f is None:
            raise ValueError(f"{reg.name} has no field {m.group(2)} on record (fields: {', '.join(x.name for x in reg.fields) or 'none'})")
        var = f"{reg.name}__{f.name}".lower()
        refs[var] = (reg, f)
        return var
    s = _FIELD_REF.sub(ref, s)
    if not refs:
        # Nemotron wrote require='18.69 <= 20' (one setting's measurement time against one data rate's period) again and
        # again: a rule is the datasheet's relation in the fields, true or false depending on what the code writes
        raise ValueError("name the register fields it depends on as REGISTER.field (e.g. OSR.osr_p, ODR.odr_sel). A "
                         "constraint is the datasheet's rule written in the fields, so verify can check any setting the "
                         "code writes: e.g. <conversion time as a formula of OSR.osr_p, OSR.osr_t, PWR_CTRL.press_en, "
                         "PWR_CTRL.temp_en> <= <sampling period as a formula of ODR.odr_sel>, with 2 ** field for "
                         "powers of two and the formula's numbers quoted. A number for one setting (18.69 <= 20) is a "
                         "fact, not a rule: record_fact it. load_skill('datasheet-rules') has a worked example")
    try:
        tree = ast.parse(s, mode="eval")
    except SyntaxError as e:
        raise ValueError(f"cannot parse {text!r}: {e.msg}")
    names: Dict[str, int] = {}
    for node in ast.walk(tree):
        ok = isinstance(node, _RULE_NODES) or (isinstance(node, ast.Constant) and isinstance(node.value, (int, float))
                                               and not isinstance(node.value, bool))
        if not ok:
            raise ValueError(f"unsupported syntax {type(node).__name__}: use numbers, REGISTER.field, + - * / ^, comparisons, and/or/not")
        if isinstance(node, ast.Name) and node.id not in refs:
            hits = {vs[0] for _r, f in refs.values() for n, vs in f.values.items() if n.lower() == node.id.lower() and len(vs) == 1}
            if len(hits) != 1:
                raise ValueError(f"unknown name {node.id}: use REGISTER.field or a named value of one of its fields")
            names[node.id.lower()] = hits.pop()
    return _Rule(tree, refs, names)


def _constraint_sanity(when: Optional[_Rule], req: _Rule, regs: Dict[str, "RegisterDef"]) -> str:
    """'' or why a recorded rule cannot be a datasheet rule. Nemotron 3 Super, pressed for a record verify checks,
    wrote 'when every setting is the Drone row: OSR.osr_p * 0 + OSR.osr_t * 0 + 18.69 <= 20' (true whatever the
    registers hold) and 'PWR_CTRL.mode == normal' with no condition (false from the chip's own reset on, so verify
    flagged the soft reset, and the run chased that for twenty steps)."""
    used = {reg.addr for reg, _f in req.refs.values()}
    rnd = random.Random(7)
    states = [{a: 0 for a in used}, {a: 0xFF for a in used}] + [{a: rnd.randrange(256) for a in used} for _ in range(30)]
    seen = set()
    for st in states:
        try:
            seen.add(bool(_eval_constraint(req, st)))
        except (KeyError, ZeroDivisionError, OverflowError, ValueError, TypeError):
            continue
        if len(seen) > 1:
            break
    if len(seen) == 1:
        return ("its require gives the same answer whatever the registers hold, so it checks nothing: write the rule "
                "as the datasheet states it in the register fields (e.g. when PWR_CTRL.mode == normal: <conversion time "
                "from OSR.osr_p, OSR.osr_t> <= <sampling period from ODR.odr_sel>), not one setting's numbers")
    if when is None:
        reset = {r.addr: r.reset for r in regs.values()}
        if used and all(reset.get(a) is not None for a in used):
            try:
                if not _eval_constraint(req, reset):
                    return ("with no `when`, the registers' reset values already break it, so the chip would violate it "
                            "on its own: give the condition the datasheet states it for (when=..., e.g. the mode the rule "
                            "applies in), or record it again from the quote")
            except (KeyError, ZeroDivisionError, OverflowError, ValueError, TypeError):
                pass
    return ""


def _eval_constraint(rule: _Rule, state: Dict[int, Optional[int]], regs: Any = None) -> Any:
    """The rule's value on register contents `state` (address -> byte); KeyError when a register it reads is unknown."""
    env: Dict[str, Any] = dict(rule.names)
    for var, (reg, f) in rule.refs.items():
        v = state.get(reg.addr)
        if v is None:
            raise KeyError(reg.name)
        env[var] = f.get(v)

    def ev(n: ast.AST) -> Any:
        if isinstance(n, ast.Expression):
            return ev(n.body)
        if isinstance(n, ast.BoolOp):
            vals = [ev(x) for x in n.values]
            return all(vals) if isinstance(n.op, ast.And) else any(vals)
        if isinstance(n, ast.UnaryOp) and isinstance(n.op, ast.Not):
            return not ev(n.operand)
        if isinstance(n, ast.Compare):
            left = ev(n.left)
            for op, right_node in zip(n.ops, n.comparators):
                right = ev(right_node)
                ok = {ast.Lt: left < right, ast.LtE: left <= right, ast.Gt: left > right, ast.GtE: left >= right,
                      ast.Eq: left == right, ast.NotEq: left != right}[type(op)]
                if not ok:
                    return False
                left = right
            return True
        if isinstance(n, ast.UnaryOp):
            v = ev(n.operand)
            return -v if isinstance(n.op, ast.USub) else v
        if isinstance(n, ast.BinOp):
            return _BINOPS[type(n.op)](ev(n.left), ev(n.right))
        if isinstance(n, ast.Name):
            return env[n.id.lower()]
        if isinstance(n, ast.Constant):
            return n.value
        raise ValueError(f"unsupported {type(n).__name__}")
    return ev(rule.tree)


_BINOPS: Dict[type, Callable[[Any, Any], Any]] = {
    ast.Add: lambda a, b: a + b, ast.Sub: lambda a, b: a - b, ast.Mult: lambda a, b: a * b, ast.Div: lambda a, b: a / b,
    ast.FloorDiv: lambda a, b: a // b, ast.Mod: lambda a, b: a % b, ast.Pow: lambda a, b: a ** b,
    ast.LShift: lambda a, b: int(a) << int(b), ast.RShift: lambda a, b: int(a) >> int(b),
    ast.BitAnd: lambda a, b: int(a) & int(b), ast.BitOr: lambda a, b: int(a) | int(b)}


def describe_state(rule: _Rule, state: Dict[int, Optional[int]]) -> str:
    """'PWR_CTRL.mode=3 (normal), OSR.osr_p=1, ODR.odr_sel=0' for the fields a rule reads."""
    parts = []
    for reg, f in rule.refs.values():
        v = state.get(reg.addr)
        fv = f.get(v) if v is not None else None
        nm = f.value_name(fv) if fv is not None else ""
        parts.append(f"{reg.name}.{f.name}={'?' if fv is None else fv}" + (f" ({nm})" if nm else ""))
    return ", ".join(dict.fromkeys(parts))


# ------------------------------------------------------------------ the book


_BURST_WORDS = re.compile(r"burst|single|one\s+(?:read|transaction|command)|consecutive|sequential|auto-?increment|multi-?byte|shadow", re.I)
_STEP_RE = re.compile(r"^\s*([A-Za-z_]\w*)\s*=(?!=)\s*(.+)$", re.S)
_CONST_ASSIGN = re.compile(r"\b([A-Za-z_]\w*)\s*=(?!=)\s*(-?\d+(?:\.\d+)?(?:[eE][-+]?\d+)?)[fFuUlL]*\s*;")


def _quote_constants(quote: str) -> Dict[str, str]:
    """Names the quoted code sets to a number (temp_var = 0.00390625f;), when it sets each to only one value."""
    seen: Dict[str, set] = {}
    for m in _CONST_ASSIGN.finditer(quote or ""):
        seen.setdefault(m.group(1).lower(), set()).add(m.group(2))
    return {n: next(iter(v)) for n, v in seen.items() if len(v) == 1}


_C_WORDS = {"double", "float", "int", "long", "short", "char", "unsigned", "signed", "const", "static", "return", "if", "else",
            "for", "while", "void", "struct", "sizeof", "uint8_t", "uint16_t", "uint32_t", "uint64_t", "int8_t", "int16_t",
            "int32_t", "int64_t"}


def _quote_names(quote: str, limit: int = 12) -> List[str]:
    """The variables a quoted piece of code uses (calib_data->par_t1, temp_var), for an error that asks for them."""
    code = re.sub(r"/\*.*?\*/|//[^\n]*", " ", quote or "", flags=re.S)
    if ";" not in code:   # prose (a datasheet's formula): its words are not variables
        return []
    out: List[str] = []
    for m in re.finditer(r"(?<![\w.>])[A-Za-z_]\w*(?:\s*(?:->|\.)\s*[A-Za-z_]\w*)*", code):
        n = re.sub(r"\s+", "", m.group())
        if code[m.end():].lstrip().startswith("(") or n.lower() in _C_WORDS or n in out:   # a function or macro call
            continue
        out.append(n)
    return out[:limit]


def _parse_part(raw: Any, width_of: Optional[Callable[[int], int]] = None) -> Optional[LayoutPart]:
    """A layout byte: '0x31', '0xE5[3:0]', {reg, bits}. `width_of(addr)`: the register's width (a part of a 16-bit
    register may use bits up to 15, and without bits it is the whole register)."""
    if isinstance(raw, dict):
        a = _num(raw.get("reg") or raw.get("addr") or raw.get("register"))
        bits = str(raw.get("bits") or "")
    else:
        m = re.fullmatch(r"\s*(0x[0-9A-Fa-f]+|[0-9A-Fa-f]+h|\d+)\s*(?:\[\s*(\d+)\s*(?::|\.\.)\s*(\d+)\s*\])?\s*", str(raw or ""))
        if not m:
            return None
        a = _num(m.group(1))
        bits = f"{m.group(2)}:{m.group(3)}" if m.group(2) else ""
    width = width_of(a) if width_of is not None and a is not None else 8
    bits = bits or f"{width - 1}:0"
    mb = re.fullmatch(r"\s*(\d+)\s*(?::|\.\.)\s*(\d+)\s*|\s*(\d+)\s*", bits)
    if a is None or not mb:
        return None
    hi, lo = (int(mb.group(1)), int(mb.group(2))) if mb.group(1) else (int(mb.group(3)), int(mb.group(3)))
    if hi < lo:
        hi, lo = lo, hi
    if hi >= width:
        return None
    return LayoutPart(a, hi, lo)


def _parse_bits(raw: Any) -> Optional[Tuple[int, int]]:
    s = str(raw if raw is not None else "").strip().lower().replace("bits", "").replace("bit", "").strip()
    m = re.fullmatch(r"(\d+)\s*(?::|\.\.|-|to)\s*(\d+)", s) or re.fullmatch(r"(\d+)", s)
    if not m:
        return None
    hi = int(m.group(1))
    lo = int(m.group(2)) if m.lastindex and m.lastindex > 1 else hi
    return (max(hi, lo), min(hi, lo)) if max(hi, lo) <= 31 else None


class RegisterBook:
    """registers.json next to ledger.json."""

    def __init__(self, root: Path):
        self.path = Path(root) / "registers.json"
        self._lock = threading.Lock()
        self.registers: Dict[str, RegisterDef] = {}
        self.layouts: Dict[str, LayoutDef] = {}
        self.bursts: Dict[str, BurstDef] = {}
        self.formulas: Dict[str, FormulaDef] = {}
        self.constraints: Dict[str, ConstraintDef] = {}
        d = load_json(self.path, {})   # a book that does not parse is kept aside, not overwritten
        if isinstance(d, dict):
            try:
                for r in d.get("registers", []):
                    r["fields"] = [FieldDef(**f) for f in r.get("fields", [])]
                    self.registers[r["id"]] = RegisterDef(**r)
                for l in d.get("layouts", []):
                    l["parts"] = [LayoutPart(**p) for p in l.get("parts", [])]
                    self.layouts[l["id"]] = LayoutDef(**l)
                for b in d.get("bursts", []):
                    self.bursts[b["id"]] = BurstDef(**b)
                for f in d.get("formulas", []):
                    self.formulas[f["id"]] = FormulaDef(**f)
                for c in d.get("constraints", []):
                    self.constraints[c["id"]] = ConstraintDef(**c)
            except (ValueError, TypeError, KeyError):
                pass

    def empty(self) -> bool:
        return not (self.registers or self.layouts or self.bursts or self.formulas or self.constraints)

    def _save(self) -> None:
        write_atomic(self.path, json.dumps({
            "registers": [asdict(r) for r in self.registers.values()], "layouts": [asdict(l) for l in self.layouts.values()],
            "bursts": [asdict(b) for b in self.bursts.values()], "formulas": [asdict(f) for f in self.formulas.values()],
            "constraints": [asdict(c) for c in self.constraints.values()]}, indent=1))

    # ---------------------------------------------------------- constraints
    def retire_constraint(self, cid: str, reason: str) -> Dict[str, Any]:
        """Take out a constraint verify reports as invalid (it stays on file in records_retired.json). A valid rule
        cannot be retired: one that flags the code is fixed in the code, not removed."""
        c = self.constraints.get(cid)
        if c is None:
            return {"ok": False, "error": f"no constraint {cid} on record"}
        regs_c = {r.name.lower(): r for r in self.registers.values() if r.device.lower() == c.device.lower()}
        try:
            why = _constraint_sanity(_constraint_tree(c.when, regs_c) if c.when else None, _constraint_tree(c.require, regs_c), regs_c)
        except ValueError as ex:
            why = str(ex)
        if not why:
            return {"ok": False, "error": (f"{cid} {c.name} is a valid rule that verify checks on the code, so it cannot be "
                                           "retired; if the code breaks it, fix the code; if the rule is mis-recorded, "
                                           f"record_constraint again under its name ({c.name}) from the datasheet's statement.")}
        with self._lock:
            self.constraints.pop(cid)
            self._save()
            path = self.path.with_name("records_retired.json")
            gone = load_json(path, [])
            write_atomic(path, json.dumps((gone if isinstance(gone, list) else []) +
                                          [{**asdict(c), "retired_reason": reason, "invalid_because": why}], indent=1))
        return {"ok": True, "retired": f"{cid} {c.name}", "invalid_because": why}

    def record_constraint(self, store: SourceStore, device: str, source_id: str, name: str, require: str, quotes: Any,
                          when: str = "", unit: str = "") -> Dict[str, Any]:
        """A datasheet rule over register settings (see ConstraintDef). Every REGISTER.field must be on record for the
        device, every number must be in a quote, and the rule must be decidable on the registers' reset values."""
        device, name = (device or "").strip(), (name or "").strip()
        if not device or not re.fullmatch(r"[A-Za-z_][\w-]{0,40}", name):
            return {"ok": False, "error": "device and name (e.g. 'normal_mode_timing') are required"}
        if str(when or "").strip().lower() in ("true", "always", "1", "none", "-"):
            when = ""   # a rule that always holds (models write when='true')
        quotes = [quotes] if isinstance(quotes, str) else [str(q) for q in (quotes or []) if str(q).strip()]
        if not quotes:
            return {"ok": False, "error": "quotes: the datasheet text that states the rule, verbatim (several passages allowed: "
                                          "e.g. the conversion-time formula and the sampling-period table)"}
        for q in quotes:
            err = _quote_ok(store, source_id, q, f"constraint {name}")
            if err:
                return {"ok": False, "error": err}
        regs = {r.name.lower(): r for r in self.registers.values() if r.device.lower() == device.lower()}
        trees: List[Optional[_Rule]] = []
        for label, text in (("when", when), ("require", require)):
            if label == "when" and not str(text or "").strip():
                trees.append(None)
                continue
            try:
                rule = _constraint_tree(str(text), regs)
            except ValueError as e:
                return {"ok": False, "error": f"{label}: {e}"}
            trees.append(rule)
            # PWR_CTRL.mode == 3: 3 is a value the register map already records for that field (normal), quoted there
            recorded = {v for _reg, f in rule.refs.values() for vs in f.values.values() for v in vs}
            for t, value, exp in _constants(rule.tree):
                unit_factor = exp is None and value > 0 and abs(math.log10(value) - round(math.log10(value))) < 1e-9
                if exp is None and value in recorded and label == "when":
                    continue
                # 5000 (us) for a quoted '5 ms': a quoted number in another unit, as 5 * 1000 already is
                if exp is None and value and any(_const_in_quote(q, value / 10.0 ** k, None) for k in (3, 6, 9, -3, -6, -9)
                                                 for q in quotes):
                    continue
                if not any(_const_in_quote(q, value, exp) for q in quotes) and not (value in (0, 1) and exp is None) \
                        and not unit_factor:   # 1000, 1e-6: a unit conversion (5 ms = 5 * 1000 us), not a datasheet claim
                    return {"ok": False, "error": f"{label}: the constant {t} is not in the quotes. Every number must come from the "
                                                  "quoted datasheet text (PDF math loses exponents: 2𝑜𝑠𝑟_𝑝 is 2^osr_p); "
                                                  "unit factors (1000, 1e-6) are allowed: 5 ms is 5 * 1000 us."}
        state = {r.addr: (r.reset if r.reset is not None else 0) for r in regs.values()}
        try:
            _eval_constraint(trees[1], state, regs)
        except (ValueError, KeyError, ZeroDivisionError, OverflowError) as e:
            return {"ok": False, "error": f"require cannot be evaluated: {e}"}
        why = _constraint_sanity(trees[0], trees[1], regs)
        if why:
            return {"ok": False, "error": f"constraint {name}: {why}."}
        with self._lock:
            old = next((c for c in self.constraints.values() if c.device.lower() == device.lower() and c.name.lower() == name.lower()), None)
            c = ConstraintDef(old.id if old else self._next(self.constraints, "CON"), device, name, str(require).strip(),
                              str(when or "").strip(), source_id, quotes, unit)
            self.constraints[c.id] = c
            self._save()
        missing = sorted(r.name for r in regs.values() if r.reset is None and r.name.lower() in
                         {n.split(".")[0].lower() for n in re.findall(r"[A-Za-z_]\w*\.[A-Za-z_]\w*", f"{when} {require}")})
        out = {"ok": True, "constraint": f"{c.id} {c.name}: " + (f"when {c.when}: " if c.when else "") + c.require,
               "next": "verify checks it after every register write the code makes, starting from the registers' reset values."}
        if missing:
            out["warning"] = (f"No reset value on record for {', '.join(missing)}: until the code writes them their value is "
                              "unknown and the rule cannot be checked. record_registers again with reset='0x..' and reset_quote "
                              "= the memory map row (e.g. '0x1D ODR 0x00 reserved odr_sel').")
        return out

    @staticmethod
    def _next(items: Dict[str, Any], prefix: str) -> str:
        return f"{prefix}-{max([int(k.split('-')[1]) for k in items] + [0]) + 1:03d}"

    # lookups
    def register_at(self, addr: int, device: str = "") -> Optional[RegisterDef]:
        return next((r for r in self.registers.values() if r.addr == addr and (not device or r.device.lower() == device.lower())), None)

    def layout_part(self, addr: int) -> List[Tuple[LayoutDef, int]]:
        return [(l, k) for l in self.layouts.values() for k, p in enumerate(l.parts) if p.addr == addr]

    def layout(self, name: str) -> Optional[LayoutDef]:
        return next((l for l in self.layouts.values() if l.name.lower() == name.lower()), None)

    def formula(self, name: str) -> Optional[FormulaDef]:
        return next((f for f in self.formulas.values() if f.name.lower() == name.lower()), None)

    def known_addresses(self) -> set:
        return {r.addr for r in self.registers.values()} | {p.addr for l in self.layouts.values() for p in l.parts}

    def _width_fn(self, device: str) -> Callable[[int], int]:
        """addr -> the width of the device's register there (8 when not on record as wider)."""
        def width(addr: int) -> int:
            r = self.register_at(addr, device)
            return r.width if r is not None else 8
        return width

    # ---------------------------------------------------------- recording
    def record_registers(self, store: SourceStore, ledger: Optional[FactLedger], device: str, source_id: str,
                         registers: List[Dict[str, Any]], bursts: Optional[List[Dict[str, Any]]] = None) -> Dict[str, Any]:
        device = (device or "").strip()
        if not device:
            return {"ok": False, "error": "device is required (the part, e.g. 'BMP388')"}
        recorded, rejected, notes = [], [], []
        for k, raw in enumerate((registers or [])[:60], start=1):
            raw = raw if isinstance(raw, dict) else {}
            dropped: List[str] = []
            res = self._one_register(store, ledger, device, str(raw.get("source_id") or source_id), raw, dropped)
            (recorded if isinstance(res, RegisterDef) else rejected).append(res if isinstance(res, RegisterDef) else
                                                                           {"register": raw.get("name") or f"#{k}", "error": res})
            if isinstance(res, RegisterDef):
                old = self.register_at(res.addr, device)
                if old is not None and old.reset is not None and raw.get("reset") in (None, ""):
                    res.reset, res.reset_quote = old.reset, old.reset_quote   # re-recorded fields keep the reset value
                err = self._reset_of(store, res, raw, str(raw.get("source_id") or source_id))
                if err:
                    notes.append(f"{res.name}: reset value not kept ({err})")
                values = [d for d in dropped if not d.startswith("@")]
                if values:
                    notes.append(f"{res.name}: kept without the value name(s) {', '.join(values)} (not stated next to the name in the quote)")
                if "@located" in dropped:
                    notes.append(f"{res.name}: your quote was not verbatim; the fields were checked against the datasheet's own "
                                 f"text for it instead: {res.quote[:120]!r}…")
        # the byte order of a part's wide registers is one statement in its datasheet: a register without its own quote
        # takes it from another register of the part (this call's or one on record); with none, verify could not read
        # the bytes the code sends and receives, so the register is not recorded
        for r in [r for r in recorded if r.width > 8 and not r.byte_order]:
            donor = next((x for x in recorded + list(self.registers.values()) if x.device.lower() == device.lower()
                          and x.width > 8 and x.byte_order), None)
            if donor is not None:
                r.byte_order, r.byte_order_quote = donor.byte_order, donor.byte_order_quote
                continue
            recorded.remove(r)
            rejected.append({"register": r.name, "error": (
                f"{r.name} is a {r.width}-bit register: give byte_order_quote, the datasheet sentence that says which of its "
                "bytes goes first on the bus (e.g. 'most significant byte first'). verify reads the bytes the code sends and "
                f"receives in that order; once one register of {device} has it, the others take it.")})
        out_b, rej_b = [], []
        for k, raw in enumerate((bursts or [])[:10], start=1):
            raw = raw if isinstance(raw, dict) else {}
            res = self._one_burst(store, device, str(raw.get("source_id") or source_id), raw)
            (out_b if isinstance(res, BurstDef) else rej_b).append(res if isinstance(res, BurstDef) else {"burst": raw.get("name") or f"#{k}", "error": res})
        with self._lock:
            for r in recorded:
                old = self.register_at(r.addr, device)
                r.id = old.id if old else self._next(self.registers, "REG")
                self.registers[r.id] = r
            for b in out_b:
                old = next((x for x in self.bursts.values() if x.device.lower() == device.lower() and x.name.lower() == b.name.lower()), None)
                b.id = old.id if old else self._next(self.bursts, "BURST")
                self.bursts[b.id] = b
            if recorded or out_b:
                self._save()
        out: Dict[str, Any] = {"ok": bool(recorded or out_b),
                               "recorded": [f"{r.id} {r.name} {_hex(r.addr)}: " + (", ".join(f.label() + (" {" + ", ".join(f"{n}={'|'.join(str(x) for x in vs)}" for n, vs in f.values.items()) + "}" if f.values else "") for f in r.fields) or "no fields")
                                            for r in recorded]}
        if out_b:
            out["bursts"] = [f"{b.id} {b.name}: {_hex(b.start)}..{_hex(b.end)} in one read" for b in out_b]
        if notes:
            out["notes"] = notes
        if rejected or rej_b:
            out["rejected"] = rejected + rej_b
            out["hint"] = ("Each register needs `quote` = its table text verbatim (name or address in it); each field's name and bit "
                           "number(s) must be in that quote or the field's own `quote`, and each named value must appear next to its "
                           "name (e.g. '11 normal mode' -> values {normal: '0b11'}). Recorded items are kept; resend only the rejected ones.")
        return out

    @staticmethod
    def _reset_of(store: SourceStore, reg: RegisterDef, raw: Dict[str, Any], source_id: str) -> Optional[str]:
        """reset / reset_quote of a register item: the quote (the memory map row, or the register's own quote) must be
        verbatim, name the register or its address, and contain the value."""
        if raw.get("reset") in (None, ""):
            return None
        v = parse_int(str(raw.get("reset")))
        if v is None or not 0 <= v <= reg.full:
            return ("reset must be the register's byte value, e.g. '0x00'" if reg.width == 8 else
                    f"reset must be the register's {reg.width}-bit value, e.g. '{reg.hexv(0)}'")
        q = str(raw.get("reset_quote") or reg.quote)
        err = _quote_ok(store, source_id, q, "reset_quote")
        if err:
            return err
        named = (value_in_text(_hex(reg.addr), q) or ("", ""))[1] == "STRICT"   # 0x1D, or TI's 1Dh
        if reg.name.lower() not in q.lower().replace("\n", "") and not named:
            return "the reset quote names neither the register nor its address"
        if not value_in_text(reg.hexv(v), q):
            return f"{reg.hexv(v)} is not in the reset quote"
        reg.reset, reg.reset_quote = v, q
        return None

    def _one_register(self, store: SourceStore, ledger: Optional[FactLedger], device: str, source_id: str, raw: Dict[str, Any],
                      dropped: Optional[List[str]] = None) -> Any:
        """Check a register against its quote; if the quote is not verbatim or does not state the fields, check the same
        claims against the datasheet's own text for that register (name/address). The claims are what must be true; a
        model that cannot copy a table exactly is not blocked, a wrong bit position still is."""
        res = self._check_register(store, ledger, device, source_id, raw, dropped)
        if isinstance(res, RegisterDef) or not isinstance(res, str):
            return res
        src = store.get(source_id)
        name = str(raw.get("name") or "").strip()
        addr = _num(raw.get("addr") if raw.get("addr") is not None else raw.get("address"))
        if src is None or not name or addr is None or re.search(r"required|overlap|does not fit|beyond|give name|must be a "
                                                                r"number|wider than a byte|byte_order", res):
            return res
        fields = []
        for f in raw.get("fields") or []:
            if isinstance(f, dict):
                fq = str(f.get("quote") or "")
                keep = fq and _quote_ok(store, str(f.get("source_id") or source_id), fq, "field") is None
                fields.append(dict(f, quote=fq if keep else ""))
        for passage in table_passages(src.text, [name, _hex(addr)], limit=4, size=900):
            d2: List[str] = []
            r2 = self._check_register(store, ledger, device, source_id, dict(raw, quote=passage, fields=fields), d2)
            if isinstance(r2, RegisterDef):
                if dropped is not None:
                    dropped.extend(d2 + ["@located"])
                return r2
        return res

    def _check_register(self, store: SourceStore, ledger: Optional[FactLedger], device: str, source_id: str, raw: Dict[str, Any],
                        dropped: Optional[List[str]] = None) -> Any:
        name = str(raw.get("name") or "").strip()
        addr = _num(raw.get("addr") if raw.get("addr") is not None else raw.get("address"))
        quote = re.sub(r"\s*(…|\.\.\.)\s*$", "", str(raw.get("quote") or ""))
        if not name or addr is None:
            return "name and addr (e.g. 'PWR_CTRL', '0x1B') are required"
        err = _quote_ok(store, source_id, quote, name)
        if err:
            return err
        if not (_name_spans(quote, name) or value_in_text(_hex(addr), quote)):
            return f"the quote mentions neither {name} nor {_hex(addr)}"
        # the address the datasheet gives this name ('Register 0x1B “PWR_CTRL”', '| 0x1B | PWR_CTRL |'): in the quote, else
        # anywhere in the source; a register quoted by name only cannot sit at another address
        src = store.get(source_id)
        stated = _stated_addrs(quote, name) or (_stated_addrs(src.text, name) if src is not None else set())
        if stated and addr not in stated:
            return f"the datasheet gives {name} at {', '.join(_hex(a) for a in sorted(stated))}, not {_hex(addr)}"
        reg_width = _width_of(raw)
        fields: List[FieldDef] = []
        for fr in (raw.get("fields") or [])[:24]:
            fr = fr if isinstance(fr, dict) else {}
            fname = str(fr.get("name") or "").strip()
            bits = _parse_bits(fr.get("bits"))
            if not fname or bits is None:
                return f"field {fname or '?'}: give name and bits ('0', '5:4')"
            hi, lo = bits
            if hi >= reg_width:
                return (f"field {fname}: bit {hi} is beyond an 8-bit register; for a 16-bit register (its memory map gives "
                        "4-hex-digit values, e.g. 8000h) give width: 16 in the register, or 32" if reg_width == 8 else
                        f"field {fname}: bit {hi} is beyond a {reg_width}-bit register")
            fq = re.sub(r"\s*(…|\.\.\.)\s*$", "", str(fr.get("quote") or ""))
            quotes = [own_section(quote, addr)]
            if fq:
                err = _quote_ok(store, str(fr.get("source_id") or source_id), fq, f"{name}.{fname}")
                if err:
                    return err
                quotes.append(fq)
            whole = (hi, lo) == (reg_width - 1, 0)   # the whole register: no position to check
            if whole:
                stated = _stated_bits(quotes, fname)
                if stated and stated != (reg_width - 1, 0):
                    return (f"field {fname}: the datasheet gives it bit {stated[1]}" if stated[0] == stated[1] else
                            f"field {fname}: the datasheet gives it bits {stated[0]}..{stated[1]}, not the whole register")
            if not whole and not any(_name_spans(q, fname) for q in quotes):
                key = _alnum(fname)
                printed = sorted({w for q in quotes for w in re.findall(r"[A-Za-z][\w]*", q)
                                  if len(_alnum(w)) == len(key) + 1 and any(_alnum(w)[i].isdigit() and _alnum(w)[:i] + _alnum(w)[i + 1:] == key
                                                                            for i in range(len(_alnum(w))))})
                return (f"field {fname}: its name is not in the quote(s)" +
                        (f"; the table prints it as {printed[0]} (a footnote mark in the name): record it as {printed[0]} — "
                         f"rules may still write {name}.{fname}, it finds {printed[0]}" if printed else ""))
            if not whole and not any(_bits_in_quote(q, hi, lo, fname) for q in quotes):
                return (f"field {fname}: bit {lo} is not stated in the quote(s)" if hi == lo else
                        f"field {fname}: bits {hi}..{lo} are not stated in the quote(s)")
            values: Dict[str, List[int]] = {}
            width = hi - lo + 1

            def fval(x: Any) -> Optional[int]:   # '11' for a 2-bit field is binary, as datasheet tables write it
                s = str(x).strip()
                if re.fullmatch(r"[01]+", s) and len(s) == width and width > 1:
                    return int(s, 2)
                return _num(x)
            for vname, vraw in (fr.get("values") or {}).items() if isinstance(fr.get("values"), dict) else []:
                vs = [fval(x) for x in (vraw if isinstance(vraw, list) else str(vraw).replace("|", ",").split(","))] if not is_int(vraw) else [vraw]
                if not vs or any(v is None for v in vs):
                    if dropped is not None:   # optional detail: keep the field without it
                        dropped.append(f"{fname}.{vname}")
                        continue
                    return f"field {fname}: value {vname!r} must be a number or list of numbers ('0b11', '3', ['0b01','0b10'])"
                if any(v >= (1 << (hi - lo + 1)) for v in vs):
                    return f"field {fname}: value {vname}={vs} does not fit in {hi - lo + 1} bit(s)"
                if not re.search(r"[A-Za-z]", str(vname)) or not any(all(_value_near(q, vname, v, hi - lo + 1) for v in vs) for q in quotes):
                    if dropped is not None:   # a value name is optional: keep the field, leave out what the quote does not show
                        dropped.append(f"{fname}.{vname}")
                        continue
                    return (f"field {fname}: value {vname}={'/'.join(format(v, f'0{hi - lo + 1}b') for v in vs)} is not stated next to "
                            f"'{vname}' in the quote(s)")
                values[vname] = vs
            fields.append(FieldDef(fname, hi, lo, values))
        masks = [f.mask for f in fields]
        if any(masks[i] & masks[j] for i in range(len(masks)) for j in range(i + 1, len(masks))):
            return "fields overlap: each bit belongs to one field"
        id_value = None
        if raw.get("id_value") not in (None, ""):
            iv = str(raw.get("id_value")).strip()
            fact = ledger.get(iv) if ledger is not None and iv.upper().startswith("FACT-") else None
            if fact is not None:
                id_value = _num(fact.value)
            else:
                id_value = _num(iv)
                backed = ledger is not None and id_value is not None and any(
                    f.subject.lower() == device.lower() and _num(str(f.value)) == id_value for f in ledger.facts.values())
                if id_value is None or not (value_in_text(_hex(id_value), quote) or backed):
                    return f"id_value {iv} must be a FACT id, a value already recorded as a fact for {device}, or appear in the register quote"
        if reg_width == 8 and ((id_value or 0) > 0xFF or _WIDE_ROW.search(quote)):
            return (f"{name} is wider than a byte (" + (f"its ID is {_hex(id_value)}" if (id_value or 0) > 0xFF else
                    f"its row gives the value {_WIDE_ROW.search(quote).group(0).split()[-1]}") +
                    "): record it with width: 16 (or 32) and byte_order_quote")
        byte_order, bo_quote = "", ""
        if reg_width > 8:
            bo_quote = re.sub(r"\s*(…|\.\.\.)\s*$", "", str(raw.get("byte_order_quote") or "")).strip()
            if bo_quote:
                err = _quote_ok(store, str(raw.get("byte_order_source_id") or source_id), bo_quote, "byte_order_quote")
                if err:
                    return err
                byte_order = stated_byte_order(bo_quote)
                if not byte_order:
                    return ("byte_order_quote must say which byte of a register goes first on the bus (e.g. '... most "
                            "significant byte first ...'); this one does not")
                said = _order_word(str(raw.get("byte_order") or ""))
                if said and said != byte_order:
                    return f"byte_order {raw.get('byte_order')!r} contradicts byte_order_quote, which says {byte_order.replace('_', ' ')}"
        return RegisterDef("", device, name, addr, fields, source_id, quote.strip(), id_value, width=reg_width,
                           byte_order=byte_order, byte_order_quote=bo_quote)

    def _one_burst(self, store: SourceStore, device: str, source_id: str, raw: Dict[str, Any]) -> Any:
        name = str(raw.get("name") or "data").strip()
        start, end = _num(raw.get("start")), _num(raw.get("end"))
        quote = str(raw.get("quote") or "")
        if start is None or end is None or end < start or end - start > 64:
            return "give start and end register addresses (e.g. '0x04', '0x09')"
        err = _quote_ok(store, source_id, quote, f"burst {name}")
        if err:
            return err
        if not _BURST_WORDS.search(quote):
            return "the quote must be the datasheet text that requires reading these registers in one burst/transaction"
        known = self.known_addresses()
        if start not in known or end not in known:
            return (f"{_hex(start)} and {_hex(end)} must be registers or layout bytes you recorded first "
                    "(record_registers / record_layouts) so the range is grounded in the datasheet")
        return BurstDef("", device, name, start, end, source_id, quote.strip())

    def record_layouts(self, store: SourceStore, device: str, source_id: str, layouts: List[Dict[str, Any]]) -> Dict[str, Any]:
        device = (device or "").strip()
        if not device:
            return {"ok": False, "error": "device is required (the part, e.g. 'BMP388')"}
        recorded, rejected = [], []
        for k, raw in enumerate((layouts or [])[:60], start=1):
            raw = raw if isinstance(raw, dict) else {}
            res = self._one_layout(store, device, str(raw.get("source_id") or source_id), raw)
            if isinstance(res, LayoutDef):
                recorded.append(res)
            else:
                rejected.append({"layout": raw.get("name") or f"#{k}", "error": res})
        with self._lock:
            for l in recorded:
                old = next((x for x in self.layouts.values() if x.device.lower() == device.lower() and x.name.lower() == l.name.lower()), None)
                l.id = old.id if old else self._next(self.layouts, "LAY")
                self.layouts[l.id] = l
            if recorded:
                self._save()
        out: Dict[str, Any] = {"ok": bool(recorded), "recorded": [f"{l.id} {l.describe()}" for l in recorded]}
        if rejected:
            out["rejected"] = rejected
            out["hint"] = ("`bytes` lists the registers LEAST significant first ('0x31' = bits 7..0, '0x32' = bits 15..8); a partial "
                           "byte is '0xE5[3:0]'. A register recorded with width 16 is listed once: ['0x00'] is the whole value. "
                           "The quote must contain every address and, if it says, the signedness.")
        return out

    @staticmethod
    def _after_addr(low: str, addr: int) -> str:
        out = []
        for m in re.finditer(rf"(?<![0-9a-z])0x0*{addr:x}(?![0-9a-z])", low):
            tail = low[m.end():m.end() + 90]
            nxt = re.search(r"(?<![0-9a-z])(?:\d+\s+)?0x[0-9a-f]+", tail)
            out.append(tail[:nxt.start()] if nxt else tail)
        return " ".join(out)

    _RANGE_AFTER = re.compile(r"<\s*(\d+)\s*:\s*(\d+)\s*>|\[\s*(\d+)\s*:\s*(\d+)\s*\]|_(\d+)_(\d+)\b")

    def _one_layout(self, store: SourceStore, device: str, source_id: str, raw: Dict[str, Any]) -> Any:
        res = self._check_layout(store, device, source_id, raw)
        src = store.get(source_id)
        if isinstance(res, LayoutDef) or src is None or not re.search(r"not verbatim|not in the quote|too short|longer than", str(res)):
            return res
        parts = [_parse_part(p, self._width_fn(device)) for p in self._layout_bytes(raw)]
        if not parts or any(p is None for p in parts):
            return res
        for passage in layout_passages(src.text, [p.addr for p in parts]):
            r2 = self._check_layout(store, device, source_id, dict(raw, quote=passage))
            if isinstance(r2, LayoutDef):
                return r2
            if not re.search(r"not verbatim|not in the quote|too short|longer than", str(r2)):
                return r2   # the datasheet's own rows contradict the claim: report that, not the quote problem
        return res

    @staticmethod
    def _layout_bytes(raw: Dict[str, Any]) -> List[Any]:
        parts = raw.get("bytes") or raw.get("parts") or raw.get("registers") or raw.get("addresses") or raw.get("regs") or []
        parts = list(parts) if isinstance(parts, (list, tuple)) else [x for x in re.split(r"[,\s]+", str(parts)) if x]
        order = str(raw.get("bytes_order") or raw.get("byte_order") or raw.get("order") or raw.get("endianness") or "").lower()
        if re.search(r"msb|big|high.*first", order):
            parts.reverse()   # stated most significant first
        return parts

    def _check_layout(self, store: SourceStore, device: str, source_id: str, raw: Dict[str, Any]) -> Any:
        name = str(raw.get("name") or "").strip()
        quote = re.sub(r"\s*(…|\.\.\.)\s*$", "", str(raw.get("quote") or ""))
        parts_raw = self._layout_bytes(raw)
        if not name or not parts_raw:
            return "give name and bytes (register addresses, least significant first)"
        parts = [_parse_part(p, self._width_fn(device)) for p in parts_raw]
        if any(p is None for p in parts):
            return ("each byte is a register address ('0x31') or a partial byte ('0xE5[3:0]'); a register of 16 bits "
                    "(recorded with width 16) is one part, '0x00' or '0x00[15:0]'")
        if len(parts) > 8:
            return "at most 8 bytes"
        width_at = self._width_fn(device)
        for i, a in enumerate(parts):   # a register listed twice: the TMP117 fix-up run gave ['0x00', '0x00'] for one
            for b in parts[i + 1:]:     # 16-bit register, a 32-bit value made of the same bits twice
                if a.addr == b.addr and a.lo <= b.hi and b.lo <= a.hi:
                    w = width_at(a.addr)
                    return (f"{_hex(a.addr)} is listed twice with the same bits. " +
                            (f"It is one {w}-bit register: list it once ('{_hex(a.addr)}' is bits {w - 1}..0 of the value)"
                             if w > 8 else "List each byte once, least significant first"))
        err = _quote_ok(store, source_id, quote, name)
        if err:
            return err
        low = quote.lower()
        for p in parts:
            hit = value_in_text(_hex(p.addr), quote)
            if hit is None or hit[1] != "STRICT":
                return f"register {_hex(p.addr)} is not in the quote (quote the rows that list each address)"
        signed = raw.get("signed")
        signed = str(signed).strip().lower() in ("true", "1", "yes", "signed") if signed is not None else False
        lay = LayoutDef("", device, name, parts, signed, source_id, quote.strip())
        # what the rows of these addresses say (text after each address up to the next one): size and sign
        rows = " ".join(self._after_addr(low, p.addr) for p in parts)
        local = rows if re.search(r"signed|\bbits?\b", rows) else low
        says_unsigned = "unsigned" in local
        says_signed = bool(re.search(r"(?<!un)signed", local))
        if says_unsigned and not says_signed and signed:
            return "the datasheet rows say unsigned but signed is true"
        if says_signed and not says_unsigned and not signed:
            return "the datasheet rows say signed but signed is false"
        if signed and not says_signed and not re.search(r"two'?s[\s-]*complement|2'?s[\s-]*complement", low):
            return ("nothing in the quote says the value is signed (\"signed\" / \"two's complement\"): quote the text that says so, "
                    "or record it unsigned")
        sizes = {int(x) for x in re.findall(r"(?<![\w.])(8|16|20|24|32)\s*-?\s*bits?\b", rows)}
        if sizes and lay.width not in sizes and len(sizes) == 1:
            return (f"the datasheet rows give {name} {sizes.pop()} bits, but the bytes listed make {lay.width} bits — list every "
                    "byte of the value")
        # where the datasheet writes content as NAME<hi:lo> next to each address, the bytes must be exactly those rows
        src = store.get(source_id)
        table = row_ranges(src.text) if src is not None else ()
        mine = {p.addr for p in parts}
        # the value's name must agree with what the datasheet's rows at these addresses hold (P9 is not P7)
        tag = re.search(r"([a-z])(\d+)$", _alnum(name))
        for a, nm, h, l in table:
            if a in mine:
                other = re.search(r"([a-z])(\d+)$", nm)
                if tag and other and tag.groups() != other.groups():
                    return (f"{_hex(a)} holds {nm.upper()} per the datasheet ({_hex(a)}<{h}:{l}>), not {name}: "
                            "take each value's addresses from its own rows")
                if _alnum(name) != nm:
                    # raw register content keeps the datasheet's name (NVM_PAR_T1); a converted value (PAR_T1) is a formula
                    shown = next((m.group(2).strip() for m in _ROW_RANGE.finditer(src.text) if int(m.group(1), 16) == a), nm.upper())
                    return (f"name this layout {shown.replace(' ', '')!r} as the datasheet does ({_hex(a)} {shown}<{h}:{l}>): it "
                            f"is the raw register content. A scaled or converted value is a record_formula on top of it.")
        for n in {nm for a, nm, h, l in table if a in mine}:
            nrows = {(a, h, l) for a, nm, h, l in table if nm == n and h - l == 7}
            if not nrows or not any(a in mine for a, _h, _l in nrows) or max(h for _a, h, _l in nrows) <= 7:
                continue   # one byte per name (ACC_X_LSB<7:0>): the name does not describe the whole value
            want = {a for a, _h, _l in nrows}
            if want != mine and all((p.hi, p.lo) == (7, 0) for p in parts):
                return (f"the datasheet lists {n.upper()} in {', '.join(f'{_hex(a)}<{h}:{l}>' for a, h, l in sorted(nrows, key=lambda r: r[2]))}; "
                        f"bytes must be exactly those, least significant first")
            for a, h, l in nrows:
                k = next(i for i, p in enumerate(parts) if p.addr == a)
                if lay.offset_of(k) != l:
                    return (f"the datasheet puts {_hex(a)} at bits {h}:{l} of {n.upper()}, but `bytes` puts it at bits "
                            f"{lay.offset_of(k) + 7}:{lay.offset_of(k)} — list bytes least significant first")
        # where the quote states the bit range of an address (e.g. '0x32 NVM_PAR_T1<15:8>'), the order must agree
        for k, p in enumerate(parts):
            for m in re.finditer(rf"(?<![0-9a-z])0x0*{p.addr:x}(?![0-9a-z])", low):
                tail = low[m.end():m.end() + 28]
                nxt = re.search(r"0x[0-9a-f]+", tail)
                tail = tail[:nxt.start()] if nxt else tail
                r = self._RANGE_AFTER.search(tail)
                if not r:
                    continue
                g = [int(x) for x in r.groups() if x is not None]
                hi, lo = max(g), min(g)
                if hi - lo + 1 == p.width and lo != lay.offset_of(k) and lay.width > 8:
                    return (f"the quote puts {_hex(p.addr)} at bits {hi}:{lo} of the value, but `bytes` puts it at bits "
                            f"{lay.offset_of(k) + p.width - 1}:{lay.offset_of(k)} — list bytes least significant first")
        return lay

    def record_formula(self, store: SourceStore, device: str, source_id: str, name: str, steps: Any, quote: str,
                       unit: str = "", inputs: Optional[Dict[str, str]] = None) -> Dict[str, Any]:
        device, name = (device or "").strip(), (name or "").strip()
        if not device or not re.fullmatch(r"[A-Za-z_]\w{0,40}", name):
            return {"ok": False, "error": "device and name (an identifier such as 'PAR_T1' or 'T_LIN') are required"}
        if isinstance(steps, str):
            steps = [s for s in re.split(r";\s*|\n", steps) if s.strip()]
        steps = [s for s in steps if not re.match(r"\s*return\b", str(s))] if isinstance(steps, list) else steps
        if isinstance(inputs, dict) and isinstance(steps, list):
            # a quote that names the value in words (TI: 'TEMPERATURE REGISTER VALUE (0.0078125 °C RESOLUTION)'): the
            # words joined by _ are its name in the steps
            inputs = dict(inputs)
            for k in [k for k in inputs if re.search(r"\s", str(k).strip())]:
                joined = re.sub(r"\s+", "_", str(k).strip())
                words = r"\s+".join(re.escape(w) for w in str(k).split())
                steps = [re.sub(rf"(?<![\w>.]){words}(?!\w)", joined, str(s), flags=re.I) for s in steps]
                inputs[joined] = inputs.pop(k)
        orig_steps = list(steps) if isinstance(steps, list) else []
        problem = self._binding_problem(store, device, inputs if isinstance(inputs, dict) else {})
        if problem:
            return {"ok": False, "error": problem}
        if isinstance(inputs, dict) and isinstance(steps, list):
            # the quote's own names (uncomp_temp, calib_data->par_t1) bound to recorded layouts/formulas (UT, PAR_T1)
            def bind(s: str) -> str:
                s = prep_expr(s) if "=" not in s else s.split("=", 1)[0] + "=" + prep_expr(s.split("=", 1)[1])
                for src_name, rec_name in inputs.items():
                    short = re.sub(r"^.*(?:->|\.)", "", str(src_name)).strip()
                    if re.fullmatch(r"[A-Za-z_]\w*", short) and re.fullmatch(r"[A-Za-z_]\w*", str(rec_name).strip()):
                        lhs, _, rhs = s.partition("=")
                        s = lhs + "=" + re.sub(rf"\b{re.escape(short)}\b", str(rec_name).strip(), rhs, flags=re.I) if rhs else s
                return s
            steps = [bind(str(s)) for s in steps]
        if not isinstance(steps, list) or not steps:
            return {"ok": False, "error": "steps: list of 'var = expression' strings, in order; the last var is the result"}
        quote = re.sub(r"\s*(…|\.\.\.)\s*$", "", str(quote or ""))
        err = _quote_ok(store, source_id, quote, f"formula {name}")
        if err:
            return {"ok": False, "error": err}
        official = official_instead(store, source_id)
        if official:
            src = store.get(source_id)
            return {"ok": False, "error": f"{source_id} is an UNOFFICIAL source ({src.url if src else ''}). A conversion verify checks "
                                          "the code against must come from the manufacturer: quote its formula, resolution or "
                                          f"LSB statement from {', '.join(official[:4])} (or its reference code: find_reference_code)."}
        known = {l.name.lower() for l in self.layouts.values() if l.device.lower() == device.lower()}
        known |= {f.name.lower() for f in self.formulas.values() if f.device.lower() == device.lower() and f.name.lower() != name.lower()}
        parsed: List[List[str]] = []
        defined: set = set()
        missing_consts: List[str] = []
        local_consts = _quote_constants(quote)
        uses_known = False
        for k, s in enumerate(steps[:40], start=1):
            s = str(s).strip().rstrip(";")
            s = re.sub(r"^\s*(?:[A-Za-z_]\w*\s*(?:->|\.)\s*)+(?=[A-Za-z_]\w*\s*=)", "", s)   # calib_data->t_lin = ... -> t_lin = ...
            m = _STEP_RE.match(s)
            if not m:
                if len(steps) == 1:
                    m = _STEP_RE.match(f"{name} = {s}")
                if not m:
                    return {"ok": False, "error": f"step {k}: write it as 'var = expression'"}
            var, expr = m.group(1), m.group(2)
            try:
                tree = _parse(expr)
            except (SyntaxError, ValueError) as e:
                return {"ok": False, "error": f"step {k} ({var}): {e}"}
            except (RecursionError, MemoryError):
                return {"ok": False, "error": f"step {k} ({var}): the expression is nested too deeply; split it into steps"}
            unknown = [n for n in _names(tree) if n not in defined and n not in known]
            for n in dict.fromkeys(u for u in unknown if u in local_consts):
                # the quoted code sets it to one number (temp_var = 0.00390625f;): that assignment is a step of its own
                parsed.append([n, local_consts[n]])
                defined.add(n)
            unknown = [n for n in unknown if n not in defined]
            if unknown:
                return {"ok": False, "error": f"step {k}: unknown name(s) {', '.join(sorted(set(unknown)))}. Every input must be a layout "
                                              f"(record_layouts) or a formula recorded before (known: {', '.join(sorted(known)) or 'none'}). "
                                              "Keep the quote's names and bind them with inputs={'" + sorted(set(unknown))[0] +
                                              "': '<recorded name>'}; a coefficient the code scales (par_t1 = NVM_PAR_T1 / 2^-8) "
                                              "is its own record_formula first."}
            for text, value, exp in _constants(tree):
                if not _const_in_quote(quote, value, exp) and not any(math.isclose(value, f) for f in _prefix_factors(quote)):
                    missing_consts.append(text)
            uses_known = uses_known or any(n in known for n in _names(tree))
            defined.add(var.lower())
            parsed.append([var, prep_expr(expr)])
        if not uses_known:
            return {"ok": False, "error": f"{name} uses no register value: a formula converts recorded layouts (or formulas "
                                          "built on them). A single number or time (a delay, a constant) is a fact: "
                                          "record_fact with its unit. A number the quoted code sets (temp_var = 0.00390625f;) "
                                          "needs no formula of its own: use it in the formula that needs it, with that line "
                                          "in its quote."}
        if parsed[-1][0].lower() != name.lower():
            parsed.append([name, parsed[-1][0]])
        foreign = self._names_not_in_quote(orig_steps, quote, inputs if isinstance(inputs, dict) else {})
        if foreign:
            names = _quote_names(quote)
            per = _PER_COUNT.search(unicodedata.normalize("NFKC", quote or ""))
            # 'One LSB equals 7.8125 m°C': the quote names the raw value only by its unit (a scale per count)
            per_hint = (f" This quote gives a scale per {per.group(1)}: that word is the raw value's name here, e.g. "
                        f"steps=['{name} = {per.group(1)} * <the quoted number, in your unit>'], inputs={{'{per.group(1)}': "
                        "'<the recorded layout>'}." if per else "")
            return {"ok": False, "error": f"{', '.join(foreign)} do(es) not appear in the quote. Write the steps with the quote's own "
                                          "names (e.g. calib_data->par_t1, uncomp_temp) and bind them to recorded layouts/formulas "
                                          "with inputs={...}: a value the quote uses must be the value it means, not a similar raw one."
                                          + (f" Names in this quote: {', '.join(names)}." if names else "") + per_hint}
        if missing_consts:
            return {"ok": False, "error": f"constant(s) {', '.join(sorted(set(missing_consts)))} are not in the quote. Quote the "
                                          "text that states the formula (the datasheet, or the manufacturer's reference code)."}
        problem = formula_structure_problem(orig_steps, quote, name)
        if problem:
            return {"ok": False, "error": problem}
        with self._lock:
            old = self.formula(name) if (self.formula(name) and self.formula(name).device.lower() == device.lower()) else None
            fid = old.id if old else self._next(self.formulas, "FRM")
            f = FormulaDef(fid, device, name, parsed, source_id, quote.strip(), unit)
            self.formulas[fid] = f
            self._save()
        return {"ok": True, "formula": f"{fid} {name}: {f.text()}" + (f" [{unit}]" if unit else "")}


    _RAW_MARK = re.compile(r"(?:^|[^a-z])(?:reg|raw|nvm|uncomp|adc)", re.I)

    def _binding_problem(self, store: SourceStore, device: str, inputs: Dict[str, Any]) -> str:
        """A quote's name may stand for a raw register value only if the quote marks it as raw: the datasheet's own row name
        (NVM_PAR_T1) or a raw-marked path (reg_calib_data->par_t1). `par_t1` alone is the converted coefficient."""
        for a, b in inputs.items():
            a_full, b_name = str(a).strip(), str(b).strip()
            short = re.sub(r"^.*(?:->|\.)", "", a_full).strip()
            lay = next((l for l in self.layouts.values() if l.name.lower() == b_name.lower() and l.device.lower() == device.lower()), None)
            if lay is None or _alnum(short) == _alnum(b_name):
                continue
            src = store.get(lay.source_id)
            rownames = {nm for _a, nm, _h, _l in row_ranges(src.text)} if src is not None else set()
            if _alnum(lay.name) in rownames and not self._RAW_MARK.search(a_full[: len(a_full) - len(short)] + " " + short):
                return (f"inputs: {a_full!r} is bound to the raw register content {lay.name}, but nothing in that name marks it "
                        f"as raw — in datasheet code {short} is normally the converted coefficient (e.g. {short.upper()} = "
                        f"{lay.name} / 2^n). Record that conversion with record_formula first (find_reference_code if the PDF "
                        "formula is garbled), or bind the quote's full raw name (e.g. 'reg_calib_data->" + short + "').")
        return ""

    @staticmethod
    def _names_not_in_quote(steps: List[Any], quote: str, inputs: Dict[str, Any]) -> List[str]:
        import unicodedata
        q = unicodedata.normalize("NFKC", _unescape(quote))
        garbled = any(0x1D400 <= ord(c) <= 0x1D7FF for c in _unescape(quote))
        qn = re.sub(r"\b[A-Za-z_]\w*\s*(?:->|\.)\s*(?=[A-Za-z_])", "", q)
        tags = {(m.group(1), m.group(2)) for m in re.finditer(r"([a-z])\1*(\d+)", q.lower())}
        defined: set = set()
        bound = {re.sub(r"^.*(?:->|\.)", "", str(k)).strip().lower() for k in inputs}
        out: List[str] = []
        for s in steps:
            lhs, eq, rhs = str(s).partition("=")
            if not eq:
                rhs, lhs = lhs, ""
            for n in re.findall(r"[A-Za-z_]\w*", re.sub(r"\b\w+\s*\(", " ", prep_expr(rhs))):
                if n.lower() in defined or n.lower() in _FUNCS or n in out:
                    continue
                if _name_spans(qn, n) or (n.lower() in bound and _name_spans(qn, n)):
                    continue
                words = [w for w in n.split("_") if w]
                if len(words) > 1 and re.search(r"(?<![A-Za-z0-9])" + r"[\s_]+".join(map(re.escape, words)) + r"(?![A-Za-z0-9])", q, re.I):
                    continue   # TEMPERATURE_REGISTER_VALUE: the quote's 'TEMPERATURE REGISTER VALUE'
                tag = re.search(r"([a-z])(\d+)$", _alnum(n))
                if garbled and tag and tag.groups() in tags:
                    continue   # PDF math glyphs: only the index (T1, P11) of a name survives
                out.append(n)
            if lhs.strip():
                defined.add(re.sub(r"^.*(?:->|\.)", "", lhs).strip().lower())
        return out


# ------------------------------------------------------------------ checking


@dataclass
class RegFinding:
    severity: str
    code: str
    file: str
    line: int
    message: str
    suggestion: str = ""


_ISR_RE = re.compile(r"(_IRQHandler|_ISR|_isr|_Callback|_callback|_cb|_handler)$")


def callbacks(model: FlowModel) -> List[str]:
    """Functions the program runs without calling them by name: tasks and threads (xTaskCreate(sensor_task, ...)),
    interrupt and timer callbacks (attachInterrupt(pin, isr, ...), HAL_*_Callback, *_IRQHandler)."""
    names = {n for n in model.functions if "::" not in n}
    called, referenced = set(), []
    for fns in model.functions.values():
        for fn in fns:
            b = fn.body
            for k, t in enumerate(b):
                if t.kind != "id" or t.text not in names or t.text == fn.name.split("::")[-1]:
                    continue
                nxt = b[k + 1].text if k + 1 < len(b) else ""
                prev = b[k - 1].text if k else ""
                if nxt == "(":
                    called.add(t.text)
                elif prev not in (".", "->") and t.text not in referenced:
                    referenced.append(t.text)   # used as a value: handed to an RTOS, a timer or an interrupt API
    out = [n for n in referenced if n not in called and n not in ("setup", "loop", "main", "app_main")]
    out += sorted(n for n in names if _ISR_RE.search(n) and n not in called and n not in out)
    return out[:12]


def entry_points(model: FlowModel) -> List[List[str]]:
    """Programs to walk: setup()+loop() (Arduino) or main/app_main, then the tasks and callbacks they hand to the RTOS or
    to interrupts; otherwise every function nothing else calls."""
    names = set(model.functions)
    extra = callbacks(model)
    if "setup" in names:
        return [["setup"] + (["loop"] if "loop" in names else []) + extra]
    for n in ("main", "app_main"):
        if n in names:
            return [[n] + extra]
    called = set()
    for fns in model.functions.values():
        for fn in fns:
            called |= {t.text for k, t in enumerate(fn.body[:-1]) if t.kind == "id" and fn.body[k + 1].text == "("}
    roots = sorted(n for n in names if "::" not in n and n not in called)
    return [[n] for n in roots[:20]]


_WRAPPER_RE = re.compile(r"^[a-z0-9]*?(?:i2c|spi|bus)?(?:read|write|rd|wr|get|set|xfer|transfer)"
                         r"(?:reg|regs|register|registers|byte|bytes|burst|block|data|buf|u8|u16|8|16)?$")


def _is_wrapper(name: str) -> bool:
    """A generic register-access helper (readRegister, write_reg, bmp3_get_regs, rd): its caller decides the register."""
    return bool(_WRAPPER_RE.match(name.split("::")[-1].lower().replace("_", "")))


def where(model: FlowModel, e: Any) -> Tuple[str, int]:
    """The line that decides a bus operation: the call in the nearest caller that is not a generic register helper
    (begin() line 164 for a write done through writeRegister()), or the primitive itself when it is called directly."""
    chain, sites = list(e.chain), list(e.sites)
    if not chain or not _is_wrapper(chain[-1]):
        return e.file, e.line
    for k in range(min(len(sites), len(chain) - 1) - 1, -1, -1):
        if not _is_wrapper(chain[k]):
            fn = model.function(chain[k])
            return (fn.file if fn else e.file), sites[k]
    return e.file, e.line


def _device_addrs(ledger: Optional[FactLedger], device: str) -> set:
    from embedforge.truth.verifier import address_value
    out = set()
    for f in (ledger.facts.values() if ledger is not None else []):
        n = address_value(f)
        if n is not None and f.subject.lower() == device.lower():
            out.add(n)
    return out


def _spi_dummy_fact(ledger: Optional[FactLedger], devices: List[str]) -> Optional[int]:
    """Dummy bytes an SPI read returns before the data, if the datasheet's statement of it is on record."""
    names = {d.lower() for d in devices}
    for f in (ledger.facts.values() if ledger is not None else []):
        if f.subject.lower() in names and re.search(r"dummy", f.property, re.I):
            n = parse_int(str(f.value))
            if n is not None and 0 <= n <= 4:
                return n
    return None


def _probe_vector(book: RegisterBook, seed: int, expects: Optional[Dict[int, int]] = None) -> Dict[int, int]:
    """Register bytes for a probe run: random layout bytes, ID registers at their ID (recorded, or the constant the code
    compares them with), status flags 'ready', error flags clear."""
    rnd = random.Random(seed)
    vec: Dict[int, int] = {}   # register -> its value (16 bits for a 16-bit register: the walk splits it into bytes)
    for l in book.layouts.values():
        for p in l.parts:
            reg = book.register_at(p.addr, l.device)
            vec.setdefault(p.addr, rnd.randrange(1 << (reg.width if reg is not None else 8)))
    for l in book.layouts.values():   # input 1: every value's top bit set (a signedness error shows); input 2: clear
        top = l.parts[-1]
        bit = 1 << top.hi
        vec[top.addr] = (vec[top.addr] | bit) if seed == 1 else (vec[top.addr] & ~bit)
        if seed == 1:   # and every byte's top bit: a byte buffer declared signed (int8_t) sign-extends only such bytes
            for p in l.parts:
                for b in range(7, p.hi + 1, 8):   # bit 7, 15, ...: the top bit of each byte of the register
                    if b >= p.lo:
                        vec[p.addr] |= 1 << b
    # an ID register reads its ID even when a layout covers it (the TMP117 fix-up recorded one for DEVICE_ID): a random
    # ID made the driver give up after its ID check, so the temperature conversion was never reached
    for r in book.registers.values():
        if r.id_value is not None:
            vec[r.addr] = r.id_value & r.full
        elif re.search(r"id|who_?am_?i", r.name, re.I) and (expects or {}).get(r.addr) is not None:
            vec[r.addr] = expects[r.addr] & r.full
    for r in book.registers.values():
        if r.addr in vec:
            continue
        v = 0
        for f in r.fields:
            if re.search(r"rdy|ready|drdy|done|complete|valid|avail|new_?data|data_?ready", f.name, re.I) and not re.search(r"err|fault|fail|ovf|overflow|busy|measuring", f.name, re.I):
                v |= f.mask
        if v:
            vec[r.addr] = v
    return vec


def _close(a: float, b: float) -> bool:
    if not (math.isfinite(a) and math.isfinite(b)):
        return False
    return abs(a - b) <= 1e-5 * max(abs(a), abs(b)) + 1e-300


def register_derived(book: RegisterBook) -> set:
    """Ids of the formulas whose value comes from register bytes: a layout, directly or through other formulas. The rest
    are constants (a scale factor, a delay) that only the formulas using them can check."""
    out: set = set()
    changed = True
    while changed:
        changed = False
        for f in book.formulas.values():
            if f.id in out:
                continue
            dev = f.device.lower()
            names = {l.name.lower() for l in book.layouts.values() if l.device.lower() == dev}
            names |= {g.name.lower() for g in book.formulas.values() if g.id in out and g.device.lower() == dev}
            text = " ".join(e for _, e in f.steps).lower()
            if any(re.search(rf"\b{re.escape(n)}\b", text) for n in names):
                out.add(f.id)
                changed = True
    return out


def evaluate_formulas(book: RegisterBook, vec: Dict[int, int]) -> Dict[str, float]:
    """Each formula's value on the probe input, keyed by formula id. Names resolve within the formula's own device: two
    parts on one board may both have a 'T' or a 'UT'."""
    out: Dict[str, float] = {}
    for dev in {f.device.lower() for f in book.formulas.values()}:
        env: Dict[str, float] = {l.name.lower(): float(l.decode(lambda a: vec.get(a, 0)))
                                 for l in book.layouts.values() if l.device.lower() == dev}
        pending = [f for f in book.formulas.values() if f.device.lower() == dev]
        for _ in range(len(pending) + 1):
            rest = []
            for f in pending:
                local = dict(env)
                try:
                    for var, expr in f.steps:
                        local[var.lower()] = float(eval_expr(_parse(expr), local))
                except KeyError:
                    rest.append(f)
                    continue
                except (ValueError, ZeroDivisionError, OverflowError, TypeError, SyntaxError):
                    continue
                env[f.name.lower()] = local[f.steps[-1][0].lower()]
                out[f.id] = env[f.name.lower()]
            if not rest or len(rest) == len(pending):
                break
            pending = rest
    return out


# a memory-map row that gives a register a 16-bit value: TI's '00h R 8000h Temp_Result', '0x01 R/W 0x0220'
_WIDE_ROW = re.compile(r"(?<![0-9A-Za-z])(?:0x)?[0-9A-Fa-f]{1,2}h?\s+(?:R/W|RW|R|W)\s+(?:0x[0-9A-Fa-f]{4}|[0-9A-Fa-f]{4}h)(?![0-9A-Za-z])")


def _unmodelled(r: "RegisterDef") -> bool:
    """A register verify cannot read byte by byte: wider than a byte (recorded so, a field above bit 7, a reset or ID
    value above 0xFF, a memory-map row with a 16-bit value) without the byte order that says how its bytes travel. The
    TMP117 cold run recorded its 16-bit registers as bytes, before width and byte order could be recorded."""
    if r.width > 8:
        return not r.modelled
    return (any(f.hi > 7 for f in r.fields) or (r.reset or 0) > 0xFF or (r.id_value or 0) > 0xFF
            or bool(_WIDE_ROW.search(r.quote or "")))


def bus_words(book: "RegisterBook", ledger: Optional[FactLedger]) -> Dict[Any, Dict[int, Tuple[int, bool]]]:
    """FlowModel.words for this register map: each part's wide registers under its bus address(es), and under None
    when that part is the only one with a register map (the walk may not resolve the address the code uses)."""
    per_dev: Dict[str, Dict[int, Tuple[int, bool]]] = {}
    for r in book.registers.values():
        if r.width > 8 and r.modelled:
            per_dev.setdefault(r.device.lower(), {})[r.addr] = (r.nbytes, r.byte_order == "msb_first")
    out: Dict[Any, Dict[int, Tuple[int, bool]]] = {}
    for dev, table in per_dev.items():
        for a in _device_addrs(ledger, dev):
            out.setdefault(a, {}).update(table)
    devices = {r.device.lower() for r in book.registers.values()} | {l.device.lower() for l in book.layouts.values()}
    if len(per_dev) == 1 and devices <= set(per_dev):
        out[None] = next(iter(per_dev.values()))
    return out


def apply_words(model: FlowModel, project_dir: Path, ledger: Optional[FactLedger]) -> "RegisterBook":
    """Tell the walk which registers are wider than a byte (and their byte order), from the register map."""
    book = RegisterBook(project_dir)
    model.words = bus_words(book, ledger)
    return book


def _without_unmodelled(book: "RegisterBook") -> Tuple[List["RegisterDef"], set]:
    """Take the parts with unmodelled wide registers out of the book (in memory): read byte by byte, their 16-bit
    configuration write became 'register 0x02 is not in the map'. Returns (those registers, their parts)."""
    bad = [r for r in book.registers.values() if _unmodelled(r)]
    skip = {r.device.lower() for r in bad}
    for coll in (book.registers, book.layouts, book.bursts, book.formulas, book.constraints):
        for k in [k for k, x in coll.items() if x.device.lower() in skip]:
            coll.pop(k)
    return bad, skip


def check_registers(project_dir: Path, ledger: Optional[FactLedger], model: Optional[FlowModel] = None) -> Tuple[Dict[str, Any], List[RegFinding]]:
    """Returns (summary for the verify report, findings)."""
    book = RegisterBook(project_dir)
    if book.empty():
        return {}, []
    model = model or FlowModel.from_dir(Path(project_dir))
    model.words = bus_words(book, ledger)
    findings: List[RegFinding] = []
    bad, skip = _without_unmodelled(book)
    if bad:
        for dev in sorted({r.device for r in bad}, key=str.lower):
            regs = [r for r in bad if r.device == dev]
            msg = (f"{dev}: {', '.join(f'{r.id} {r.name}' for r in regs)} {'is' if len(regs) == 1 else 'are'} wider than 8 bits "
                   "(the register map gives 16-bit values) but recorded without width and byte order, so verify cannot read "
                   f"{dev}'s register writes, reads and fields (constants, pins, order and timing are still checked).")
            findings.append(RegFinding("ERROR", "REGISTER_WIDTH_UNRECORDED", "", 0, msg,
                                       "record_registers again for these registers with width: 16 (or 32), their fields, and "
                                       "byte_order_quote: the datasheet sentence that says which byte of a register goes first "
                                       "on the bus."))
        if book.empty():
            return {"registers_skipped": " ".join(f.message for f in findings)}, findings
    devices = sorted({x.device for x in list(book.registers.values()) + list(book.layouts.values())}, key=str.lower)
    dev_addrs = {d: _device_addrs(ledger, d) for d in devices}
    all_addrs = set().union(*dev_addrs.values()) if dev_addrs else set()

    def mine(addr: Any) -> bool:   # an event/byte of a device this book describes
        return not all_addrs or not is_int(addr) or addr in all_addrs

    dev_of: Dict[int, set] = {}
    for d, addrs in dev_addrs.items():
        for a in addrs:
            dev_of.setdefault(a, set()).add(d.lower())

    def at(addr: Any) -> Optional[set]:
        """The devices traffic at this bus address talks to; None when it cannot tell (SPI, callbacks, unknown address)."""
        return dev_of.get(addr) if is_int(addr) else None

    def reg_at(r: int, addr: Any) -> Optional[RegisterDef]:   # the register map of the device at that address, not another part's
        devs = at(addr)
        return next((x for x in book.registers.values() if x.addr == r and (not devs or x.device.lower() in devs)), None)

    def parts_at(r: int, addr: Any) -> List[Tuple[LayoutDef, int]]:
        devs = at(addr)
        return [(l, k) for l, k in book.layout_part(r) if not devs or l.device.lower() in devs]

    stated_dummy = _spi_dummy_fact(ledger, devices)   # the datasheet's SPI dummy bytes, when recorded
    walkers: List[Tuple[List[str], Walker]] = []
    for entries in entry_points(model):
        try:
            walkers.append((entries, model.run(entries, spi_dummy=stated_dummy or 0)))
        except RecursionError:   # code that was not looked at must not pass as checked
            findings.append(RegFinding("ERROR", "REGISTER_CHECK_ERROR", "", 0,
                                       f"Tracing {' + '.join(entries)} exceeded the recursion limit, so its register use is unchecked.",
                                       "Report it to the user; flattening deeply nested code may help."))
    # SPI parts differ in whether a read returns a dummy byte before the data (Bosch BMP388/BMI160 do): judge the code
    # under both readings, and report a byte-level error only if it is wrong under both
    spi = any(e.bus == "spi" and e.kind == "read" for _, w in walkers for e in w.events)
    guess = spi and stated_dummy is None
    dummies = (0, 1) if guess else (stated_dummy or 0,)
    alt: List[Tuple[List[str], Walker]] = []
    if guess:
        for entries, _ in walkers:
            try:
                alt.append((entries, model.run(entries, spi_dummy=1)))
            except RecursionError:
                pass
    summary: Dict[str, Any] = {"entries": [" + ".join(e) for e, _ in walkers], "writes": [], "layouts": [], "formulas": []}
    used = {e.addr for _, w in walkers for e in w.events if is_int(e.addr)}
    if all_addrs and not used & all_addrs:
        all_addrs = set()   # the code talks to another address: judge all its device traffic (a wrong address must not hide errors)

    # 0. transfers that cut a wide register: a register of 16 bits takes its two bytes in one transfer; one byte written
    # (or read) is half a value, and what the part does with it is not what the code meant
    seen_t = set()
    for _, w in walkers:
        for e in w.events:
            if e.word <= 1 or not is_int(e.reg) or not mine(e.addr):
                continue
            short, last = e.extra, e.reg + len(e.data)   # a write: bytes past its whole registers
            if e.kind == "read":
                if not (is_int(e.length) and e.length > 0):
                    continue
                last, j, n, _msb = model.byte_slot(e.addr, e.reg, e.length - 1)
                short = (j + 1) % n
            reg = reg_at(last, e.addr)
            if reg is None or (e.file, e.line) in seen_t:
                continue
            if short:
                seen_t.add((e.file, e.line))
                wf, wl = where(model, e)
                findings.append(RegFinding("ERROR", "REG_TRANSFER_WIDTH", wf, wl,
                                           f"{'writes' if e.kind == 'write' else 'reads'} {short} byte(s) of {reg.name} ({_hex(reg.addr)}), "
                                           f"a {reg.width}-bit register of {reg.nbytes} bytes ({reg.id}: "
                                           f"{reg.byte_order.replace('_', ' ')}), so part of the value is " +
                                           ("missing from the write." if e.kind == "write" else "never read."),
                                           f"Transfer all {reg.nbytes} bytes of the register in one transaction, "
                                           f"{'most' if reg.byte_order == 'msb_first' else 'least'} significant byte first."))

    # 1. register writes, decoded
    seen_w, fieldless = set(), set()
    for _, w in walkers:
        for e in w.events:
            if e.kind != "write" or not mine(e.addr):
                continue
            for r, v in writes_of(e, lambda r, a=e.addr: reg_at(r, a) is not None or bool(parts_at(r, a))):
                if is_int(r) and isinstance(v, Part):   # read-modify-write: reserved bits it sets for certain
                    reg = reg_at(r, e.addr)
                    extra = v.value & v.mask & (reg.full & ~reg.defined_mask if reg is not None else 0)
                    if reg is not None and reg.fields and extra and (e.file, e.line, r) not in seen_w:
                        seen_w.add((e.file, e.line, r))
                        wf, wl = where(model, e)
                        findings.append(RegFinding("WARNING", "REG_RESERVED_BITS", wf, wl,
                                                   f"{reg.name} ({_hex(r)}) is written with bit(s) {reg.hexv(extra)} set, which no field of "
                                                   f"{reg.id} defines ({', '.join(f.label() for f in reg.fields)}).",
                                                   "Write only defined fields (reserved bits are usually kept or written 0)."))
                    continue
                if not (is_int(r) and is_int(v)):
                    continue
                reg = reg_at(r, e.addr)
                key = (e.file, e.line, r, v)
                if reg is None or key in seen_w:
                    continue
                seen_w.add(key)
                wf, wl = where(model, e)
                summary["writes"].append(f"{wf}:{wl} {reg.name} ({_hex(r)}) <- {reg.hexv(v)}: {reg.decode(v)}")
                if not reg.fields and r == e.reg and reg.id not in fieldless:
                    fieldless.add(reg.id)   # a record without fields would make every value it is written pass unchecked
                    findings.append(RegFinding("ERROR", "REG_FIELDS_MISSING", wf, wl,
                                               f"{reg.name} ({_hex(r)}) <- {reg.hexv(v)}, but {reg.id} records no fields, so what this "
                                               "value sets is unchecked.",
                                               "record_registers again for this register with its fields (name and bits from its "
                                               f"table; a whole-register value is one field with bits '{reg.width - 1}:0')."))
                extra = v & ~reg.defined_mask & reg.full
                if reg.fields and extra:
                    findings.append(RegFinding("WARNING", "REG_RESERVED_BITS", wf, wl,
                                               f"{reg.name} ({_hex(r)}) <- {reg.hexv(v)} sets bit(s) {reg.hexv(extra)} that no field of {reg.id} defines "
                                               f"({', '.join(f.label() for f in reg.fields)}).",
                                               "Write only defined fields (reserved bits are usually written 0), or record the missing field."))
                for f in reg.fields:
                    fv = f.get(v)
                    if f.values and not f.value_name(fv):
                        findings.append(RegFinding("WARNING", "REG_FIELD_VALUE", wf, wl,
                                                   f"{reg.name}.{f.name} = {fv} is none of its named values "
                                                   f"({', '.join(f'{n}={chr(124).join(str(x) for x in vs)}' for n, vs in f.values.items())}).",
                                                   "Use one of the datasheet's values for this field."))

    def bit_findings(ws: List[Tuple[List[str], Walker]]) -> List[RegFinding]:
        out: List[RegFinding] = []
        # 2. bit masks on bytes read from registers
        seen_m = set()
        for _, w in ws:
            for rx, mask, file, line in w.obs_masks:
                reg = reg_at(rx.reg, rx.dev)
                if reg is None or not reg.fields or not mine(rx.dev) or parts_at(rx.reg, rx.dev):
                    continue
                # a byte of a wide register tests the register's bits pos+7..pos; an assembled value tests them all
                m = (mask & 0xFF) << rx.pos if isinstance(rx, RxByte) else mask
                bad = m & ~reg.defined_mask & reg.full
                key = (rx.reg, mask, file, line)
                if bad and key not in seen_m:
                    seen_m.add(key)
                    part = (f" (its byte holding bits {rx.pos + 7}..{rx.pos}, so mask {_hex(mask)} is {reg.hexv(m)} in the register)"
                            if isinstance(rx, RxByte) and rx.width > 8 else "")
                    out.append(RegFinding("ERROR", "REG_MASK_UNDEFINED", file, line,
                                          f"{reg.name} ({_hex(reg.addr)}) is tested with mask {reg.hexv(mask) if not part else _hex(mask)}{part}, "
                                          f"but bit(s) {reg.hexv(bad)} are not defined there; its fields are "
                                          f"{', '.join(f.label() for f in reg.fields)} ({reg.id}).",
                                          f"Mask with the field's bits from the register map (e.g. {', '.join(f'{f.name} = {reg.hexv(f.mask)}' for f in reg.fields)})."))
        # 3a. bytes of a wide register put together: each byte where the byte order puts it ((msb << 8) | lsb for a part
        # that sends its most significant byte first); swapped, every value read is wrong
        seen_o = set()
        for _, w in ws:
            for rx, shift, file, line in w.obs_shifts:
                if not isinstance(rx, RxByte) or rx.width <= 8 or not mine(rx.dev) or (rx.reg, file, line) in seen_o:
                    continue
                reg = reg_at(rx.reg, rx.dev)
                if reg is None:
                    continue
                # where a layout takes bits of this register, it says where they go; else the register's own value
                wants = {lay.offset_of(k) + rx.pos - lay.parts[k].lo for lay, k in parts_at(rx.reg, rx.dev)
                         if lay.parts[k].lo <= rx.pos <= lay.parts[k].hi} or {rx.pos}
                if shift not in wants:
                    seen_o.add((rx.reg, file, line))
                    first = "most" if reg.byte_order == "msb_first" else "least"
                    out.append(RegFinding("ERROR", "REG_BYTE_ORDER", file, line,
                                          f"the byte of {reg.name} ({_hex(reg.addr)}) holding bits {rx.pos + 7}..{rx.pos} is put at bit "
                                          f"{shift}, so the {reg.width}-bit value is assembled with its bytes swapped. The datasheet "
                                          f"sends the {first} significant byte first ({reg.id}: {reg.byte_order_quote[:120]!r}).",
                                          f"Put each byte at its own position: the byte received {'first' if first == 'most' else 'second'} "
                                          f"goes to bits {reg.width - 1}..{reg.width - 8} (<< {reg.width - 8})."))
        # 3. shifts on bytes of multi-byte values
        seen_s = set()
        for _, w in ws:
            for rx, shift, file, line in w.obs_shifts:
                if not mine(rx.dev) or rx.width > 8:
                    continue
                parts = parts_at(rx.reg, rx.dev)
                for lay, k in parts:
                    p = lay.parts[k]
                    if (p.hi, p.lo) != (7, 0) or lay.width <= 8 and shift == 0:
                        continue
                    want = lay.offset_of(k)
                    key = (rx.reg, shift, file, line)
                    if shift != want and key not in seen_s and not any(sh == shift for l2, k2 in parts for sh in [l2.offset_of(k2)]):
                        seen_s.add(key)
                        out.append(RegFinding("ERROR", "LAYOUT_SHIFT", file, line,
                                              f"the byte read from {_hex(rx.reg)} is shifted left by {shift}, but in {lay.name} ({lay.id}) it is "
                                              f"bits {want + 7}..{want}: {lay.describe()}.",
                                              f"Assemble {lay.name} exactly as the layout says (that byte << {want})."))
        return out
    bits = bit_findings(walkers)
    if alt:
        other = {(f.code, f.file, f.line) for f in bit_findings(alt)}
        bits = [f for f in bits if (f.code, f.file, f.line) in other]
    findings += bits
    for lay in book.layouts.values():
        summary["layouts"].append(f"{lay.id} {lay.describe()}")
        twice = sorted({a.addr for i, a in enumerate(lay.parts) for b in lay.parts[i + 1:]
                        if a.addr == b.addr and a.lo <= b.hi and b.lo <= a.hi})
        if twice:   # recorded before record_layouts refused it: the same bits twice make a value of twice the width
            findings.append(RegFinding("ERROR", "LAYOUT_INVALID", "", 0,
                                       f"{lay.id} {lay.describe()}: {', '.join(_hex(a) for a in twice)} is listed twice with the "
                                       "same bits, so the value verify checks the code against is not the register's.",
                                       f"record_layouts again under the same name ({lay.name}), listing each register once "
                                       "(a 16-bit register is one entry: ['0x00'])."))

    # 4. burst reads
    for b in book.bursts.values():
        for _, w in walkers:
            for e in w.events:
                if e.kind != "read" or not is_int(e.reg) or not mine(e.addr) or (at(e.addr) and b.device.lower() not in at(e.addr)):
                    continue
                n = e.length if is_int(e.length) and e.length > 0 else 1
                last = model.byte_slot(e.addr, e.reg, n - 1)[0]   # registers, not bytes, for 16-bit registers
                if e.reg > b.end or last < b.start:
                    continue
                if not (e.reg <= b.start and last >= b.end):
                    findings.append(RegFinding("ERROR", "REG_BURST_SPLIT", *where(model, e),
                                               f"read of {_hex(e.reg)} x{n} touches {b.name} {_hex(b.start)}..{_hex(b.end)}, which the datasheet "
                                               f"requires to be read in one burst ({b.id}).",
                                               f"Read all {b.end - b.start + 1} bytes from {_hex(b.start)} in one transaction and take the values "
                                               "from that buffer."))
                    break

    # SPI reads must carry the read flag: without bit 7 the part takes the register byte as a write command
    seen_f = set()
    for _, w in walkers:
        for e in w.events:
            if e.kind == "read" and e.note == "spi_no_read_flag" and (e.file, e.line) not in seen_f:
                seen_f.add((e.file, e.line))
                findings.append(RegFinding("ERROR", "SPI_READ_FLAG", *where(model, e),
                                           f"register {_hex(e.reg)} is read over SPI without bit 7 (0x80) set in the register byte, so "
                                           "the part takes it as a write command.",
                                           "Send (reg | 0x80) to start an SPI read, as the datasheet's SPI protocol section requires."))

    # 4b. datasheet constraints over the register settings, after every write the code makes (from the reset values)
    if book.constraints:
        summary["constraints"] = []
        for c in book.constraints.values():
            regs_c = {r.name.lower(): r for r in book.registers.values() if r.device.lower() == c.device.lower()}
            try:
                when = _constraint_tree(c.when, regs_c) if c.when else None
                req = _constraint_tree(c.require, regs_c)
            except ValueError as ex:   # a register re-recorded without a field the rule names
                findings.append(RegFinding("ERROR", "CONSTRAINT_INVALID", "", 0, f"{c.id} {c.name}: {ex}",
                                           "record_constraint again with the fields now on record."))
                continue
            why = _constraint_sanity(when, req, regs_c)   # records made before this check, or reset values learnt since
            if why:
                findings.append(RegFinding("ERROR", "CONSTRAINT_INVALID", "", 0, f"{c.id} {c.name} ({c.require}): {why}.",
                                           f"record_constraint again under the same name ({c.name}) to replace it, from "
                                           "the datasheet's own statement of the rule; if the datasheet states no such "
                                           f"rule, retire_record('{c.id}', why)."))
                continue
            checked, bad = 0, None
            for _, w in walkers:
                state: Dict[int, Optional[int]] = {r.addr: r.reset for r in regs_c.values()}
                for e in w.events:
                    if e.kind != "write" or not mine(e.addr):
                        continue
                    hit = False
                    for r, v in writes_of(e, lambda r, a=e.addr: reg_at(r, a) is not None):
                        reg = reg_at(r, e.addr) if is_int(r) else None
                        if reg is None or reg.device.lower() != c.device.lower():
                            continue
                        if isinstance(v, Part):        # read-modify-write: only the bits it sets are known
                            old = state.get(r)
                            state[r] = None if old is None else (old & ~v.mask & reg.full) | (v.value & v.mask & reg.full)
                        elif is_int(v):
                            state[r] = v & reg.full
                        else:
                            state[r] = None
                        hit = True
                    if not hit:
                        continue
                    try:
                        if when is not None and not _eval_constraint(when, state):
                            checked += 1
                            continue
                        ok = bool(_eval_constraint(req, state))
                    except (KeyError, ZeroDivisionError, OverflowError, ValueError, TypeError):
                        continue                       # a register it reads is not known yet
                    checked += 1
                    if not ok and bad is None:   # the settings the rule reads, the `when` fields first
                        both = _Rule(req.tree, {**(when.refs if when else {}), **req.refs}, {})
                        bad = (e, describe_state(both, state))
            if bad is not None:
                e, st = bad
                wf, wl = where(model, e)
                summary["constraints"].append(f"{c.id} {c.name}: VIOLATED after {wf}:{wl}")
                findings.append(RegFinding("ERROR", "CONSTRAINT_VIOLATED", wf, wl,
                                           f"{c.id} {c.name}: after this write the settings are {st}"
                                           + (f", so {c.when}" if c.when else "") + f", and {c.require} is false.",
                                           "Change the order or the values so the rule holds after every write (datasheets "
                                           "usually want settings written in sleep mode, then the mode)."))
            elif checked:
                summary["constraints"].append(f"{c.id} {c.name}: holds after each of {checked} register writes")
            else:
                summary["constraints"].append(f"{c.id} {c.name}: not checked")
                findings.append(RegFinding("WARNING", "CONSTRAINT_UNCHECKED", "", 0,
                                           f"{c.id} {c.name}: the code never sets all the registers it reads, and their reset values "
                                           "are not on record, so it could not be checked.",
                                           "record_registers with reset (and reset_quote: the memory map row) for those registers."))

    # 5. formulas: probe runs with concrete register bytes. A formula quoted from an unofficial source while the
    # manufacturer's documents are on record (recorded before record_formula refused it) is not ground truth
    store = SourceStore(Path(project_dir))
    for f in book.formulas.values():
        official = official_instead(store, f.source_id)
        if official:
            src = store.get(f.source_id)
            findings.append(RegFinding("ERROR", "FORMULA_SOURCE_UNOFFICIAL", "", 0,
                                       f"{f.id} {f.name} is quoted from {f.source_id}, an UNOFFICIAL source ({src.url if src else ''}), "
                                       f"while the manufacturer's documents ({', '.join(official[:4])}) are on record.",
                                       f"record_formula again under the same name ({f.name}), quoting the manufacturer's formula, "
                                       "resolution or LSB statement."))
    if book.formulas:
        results: Dict[str, List[Optional[str]]] = {f.id: [] for f in book.formulas.values()}   # by id: names repeat across parts
        derived = register_derived(book)

        def same_dev(items: Any, f: FormulaDef) -> List[Any]:
            return [x for x in items if x.device.lower() == f.device.lower()]
        detail: Dict[str, str] = {}
        loc: Dict[str, Tuple[str, int]] = {}
        read_regs: set = set()
        sym_read = {model.byte_slot(e.addr, e.reg, k)[0] for _, w in walkers for e in w.events if e.kind == "read" and is_int(e.reg)
                    and mine(e.addr) for k in range(e.length if is_int(e.length) and 0 < e.length <= 512 else 1)}
        # values the code compares registers with (an ID); one byte of a wide register is not its value
        expects = {rx.reg: c for _, w in walkers for rx, c, _f, _l in w.obs_compares if rx.width <= 8 or isinstance(rx, RxWord)}
        for seed in (1, 2):
            vec = _probe_vector(book, seed, expects)
            expected = evaluate_formulas(book, vec)
            observed: List[Tuple[Any, str, str]] = []
            for entries, _ in walkers:
                for dummy in dummies:   # a formula matches if the code computes it under either SPI reading
                    try:
                        pw = model.run(entries, probe=vec, spi_dummy=dummy)
                    except RecursionError:
                        continue
                    observed += [v for v in pw.values if isinstance(v[0], (int, float))]
                    read_regs |= {model.byte_slot(e.addr, e.reg, k)[0] for e in pw.events if e.kind == "read" and is_int(e.reg)
                                  for k in range(e.length if is_int(e.length) and 0 < e.length <= 512 else 1)}
            for f in book.formulas.values():
                want = expected.get(f.id)
                if want is None:
                    results[f.id].append(None)
                    continue
                hit = next((o for o in observed if _close(float(o[0]), want)), None)
                results[f.id].append(f"{hit[1]} ({hit[2]})" if hit else "")
                if not hit and f.id not in detail:
                    inputs_used = [l for l in same_dev(book.layouts.values(), f) if re.search(rf"\b{re.escape(l.name.lower())}\b", " ".join(e for _, e in f.steps).lower())]
                    raw = []
                    for l in inputs_used:
                        rv = float(l.decode(lambda a: vec.get(a, 0)))
                        o = next((o for o in observed if _close(float(o[0]), rv)), None)
                        if o is not None:
                            raw.append(f"{l.name} = {rv:g} at {o[1]} ({o[2]})")
                            fl, _, ln = str(o[1]).rpartition(":")
                            loc.setdefault(f.id, (fl, int(ln) if ln.isdigit() else 0))
                    uses = [g for g in same_dev(book.formulas.values(), f) if g.name != f.name and re.search(rf"\b{re.escape(g.name.lower())}\b", " ".join(e for _, e in f.steps).lower())]
                    deps = [g.name for g in uses if g.id in derived]
                    consts = [f"{g.name} = {expected[g.id]:.10g}" for g in uses if g.id not in derived and g.id in expected]
                    detail[f.id] = (f"on probe input the formula gives {want:.7g}, a value the code never computes"
                                      + (f"; the code has the raw {'; '.join(raw[:2])} — the conversion is missing or different" if raw and len(f.steps) <= 2 else "")
                                      + (f" (with {', '.join(consts)})" if consts else "")
                                      + (f" (it uses {', '.join(deps)}: fix those first)" if deps else ""))
        for f in book.formulas.values():
            res = results[f.id]
            inputs = {p.addr for l in same_dev(book.layouts.values(), f) if l.name.lower() in " ".join(e for _, e in f.steps).lower() for p in l.parts}
            deps_read = not inputs or inputs & read_regs
            if f.id not in derived:   # a constant (temp_var = 1 / 2^8): the code may fold it into a literal anywhere
                users = [g.name for g in same_dev(book.formulas.values(), f) if g.id != f.id and
                         re.search(rf"\b{re.escape(f.name.lower())}\b", " ".join(e for _, e in g.steps).lower())]
                summary["formulas"].append(f"{f.id} {f.name}: a constant, not register data"
                                           + (f" (checked through {', '.join(users[:4])})" if users else ""))
                continue
            if all(r for r in res if r is not None) and any(res):
                summary["formulas"].append(f"{f.id} {f.name}: matches the code at {res[0]}")
            elif not deps_read and inputs & sym_read:
                # read when nothing is known about the part, never when it answers as the datasheet says: the code gives
                # up on a healthy part (an inverted ID check, a status test that fails on success)
                summary["formulas"].append(f"{f.id} {f.name}: not reached on a healthy part")
                findings.append(RegFinding("ERROR", "MEASUREMENT_UNREACHED", "", 0,
                                           f"{f.id} {f.name}: the code reads its registers ({', '.join(_hex(a) for a in sorted(inputs & sym_read))}) "
                                           "only when nothing is known about the part; when the part answers as the datasheet says "
                                           "(its ID, ready flags set, every transfer succeeding) the code stops before measuring.",
                                           "Check the conditions on the way to the measurement: the ID comparison, status and "
                                           "transfer checks, and early returns, against what the datasheet says the part returns."))
            elif not deps_read:
                summary["formulas"].append(f"{f.id} {f.name}: not observed (its registers are never read from {', '.join(summary['entries'])})")
                findings.append(RegFinding("WARNING", "FORMULA_UNOBSERVED", "", 0,
                                           f"{f.id} {f.name}: the walk of {', '.join(summary['entries']) or 'the program'} never reads its input "
                                           "registers, so the formula could not be compared with the code.",
                                           "Call the measurement code from setup()/loop()/main so it can be checked."))
            elif any(r is None for r in res):
                summary["formulas"].append(f"{f.id} {f.name}: could not be evaluated")
                findings.append(RegFinding("WARNING", "FORMULA_UNCHECKED", "", 0,
                                           f"{f.id} {f.name}: the recorded formula could not be evaluated on the probe input, so the "
                                           "code's conversion was not compared with it.",
                                           "Check that its inputs are recorded layouts or formulas; report it to the user if they are."))
            else:
                summary["formulas"].append(f"{f.id} {f.name}: MISMATCH")
                findings.append(RegFinding("ERROR", "FORMULA_MISMATCH", *loc.get(f.id, ("", 0)),
                                           f"{f.id} {f.text() if len(f.steps) == 1 else f.name}: {detail.get(f.id, 'matches only one of two probe inputs')}.",
                                           "Implement the recorded formula exactly (inputs from the layouts, constants and order of operations), "
                                           "or re-record the formula if the datasheet / reference code says otherwise."))

    # 5b. a wide data register (no fields but its whole value, not an ID) that the code puts together into a number is a
    # measurement: like a multi-byte value of 8-bit registers it needs a layout (is it signed?) and, through that, a
    # formula. On the TMP117 a driver reading the two's-complement temperature as unsigned otherwise passed
    seen_d = set()
    for _, w in walkers:
        for rx, _shift, file, line in w.obs_shifts:
            if not isinstance(rx, RxByte) or rx.width <= 8 or not mine(rx.dev) or parts_at(rx.reg, rx.dev):
                continue
            reg = reg_at(rx.reg, rx.dev)
            data = reg is not None and reg.id_value is None and (not reg.fields or [(f.hi, f.lo) for f in reg.fields] == [(reg.width - 1, 0)])
            if data and reg.id not in seen_d:
                seen_d.add(reg.id)
                findings.append(RegFinding("ERROR", "REG_LAYOUT_MISSING", file, line,
                                           f"the code puts {reg.name} ({_hex(reg.addr)}, {reg.width} bits, {reg.id}) together into a value, "
                                           "but no layout says how to read it (signed or not), so what the code computes from it is unchecked.",
                                           f"record_layouts for {reg.name}: bytes ['{_hex(reg.addr)}'] (the whole register) with signed as "
                                           "the datasheet describes it (two's complement), then record_formula for its conversion."))

    # 6. bytes of a part's recorded layouts that the code assembles into numbers (shifts them into place) feed a
    # conversion: without a formula recorded for that part, nothing checks it (the code could scale, offset or
    # compensate the values any way and still pass)
    assembled: Dict[str, Tuple[set, Tuple[str, int]]] = {}   # part -> (layout names assembled, where first)
    for _, w in walkers:
        for rx, _shift, file, line in w.obs_shifts:
            if not mine(rx.dev):
                continue
            for lay, _ in parts_at(rx.reg, rx.dev):
                assembled.setdefault(lay.device.lower(), (set(), (file, line)))[0].add(lay.name)
    converted = {f.device.lower() for f in book.formulas.values()}
    for dev, (names, at_) in sorted(assembled.items()):
        if dev not in converted:
            findings.append(RegFinding("ERROR", "FORMULA_MISSING", *at_,
                                       f"the code assembles {', '.join(sorted(names))} of {dev.upper()} into values, but no "
                                       "conversion formula was recorded for that part, so what the code computes from them is unchecked.",
                                       "record_formula for each conversion the datasheet gives (coefficient scaling, compensation, "
                                       "units). If the PDF's formulas are garbled, find_reference_code('<part>') stores the "
                                       "manufacturer's reference driver: quote its C code."))
    return summary, findings


def coverage_findings(project_dir: Path, ledger: Optional[FactLedger], model: FlowModel) -> List[RegFinding]:
    """Registers the code touches on a device that has a register map but are not in it: their meaning is unchecked."""
    book = RegisterBook(project_dir)
    if book.empty():
        return []
    model.words = bus_words(book, ledger)
    _bad, skip = _without_unmodelled(book)   # check_registers reports REGISTER_WIDTH_UNRECORDED for those parts
    if book.empty():
        return []
    out, seen = [], set()
    known = book.known_addresses() | {a for b in book.bursts.values() for a in range(b.start, b.end + 1)}
    per_dev: Dict[str, set] = {}   # a register of one part does not map the same address on another part
    for x in book.registers.values():
        per_dev.setdefault(x.device.lower(), set()).add(x.addr)
    for l in book.layouts.values():
        per_dev.setdefault(l.device.lower(), set()).update(p.addr for p in l.parts)
    for b in book.bursts.values():
        per_dev.setdefault(b.device.lower(), set()).update(range(b.start, b.end + 1))
    addrs, dev_of = set(), {}
    for d in {x.device for x in book.registers.values()} | {x.device for x in book.layouts.values()}:
        for a in _device_addrs(ledger, d):
            addrs.add(a)
            dev_of.setdefault(a, set()).add(d.lower())
    for entries in entry_points(model):
        try:
            w = model.run(entries)
        except RecursionError:
            continue
        for e in w.events:
            if e.kind not in ("read", "write") or (addrs and is_int(e.addr) and e.addr not in addrs):
                continue
            devs = dev_of.get(e.addr) if is_int(e.addr) else None
            mapped = set().union(*(per_dev.get(d, set()) for d in devs)) if devs else known
            regs = [r for r, _ in writes_of(e, mapped.__contains__)] if e.kind == "write" else ([e.reg] if is_int(e.reg) else [])
            for r in regs:
                if is_int(r) and r not in mapped and (r, e.kind, e.addr) not in seen:
                    seen.add((r, e.kind, e.addr))
                    out.append(RegFinding("ERROR", "REG_UNMAPPED", *where(model, e),
                                          f"the code {'writes' if e.kind == 'write' else 'reads'} register {_hex(r)}, which is not in the register map, "
                                          "so the meaning of its value is unchecked.",
                                          f"record_registers for {_hex(r)} (its fields from the datasheet table) or record_layouts if it holds data."))
    return out

embedforge/truth/robust.py:
"""Robustness rules a field failure teaches, checked on the code (comments stripped, one string per line):

  UNBOUNDED_WAIT   a loop that waits on hardware (a status bit, a bus call, Serial, a pin) with no timeout or retry
                   limit: when the condition never comes true (no USB host, sensor unplugged, bus stuck) the firmware
                   hangs there forever.
  RESULT_IGNORED   a call that reports failure (a bus transfer, or one of the project's own functions that returns an
                   error) whose result is thrown away (MISRA C:2012 Rule 17.7, CERT C ERR33-C): a failed transfer goes
                   unnoticed and stale bytes are used as data. A deliberate discard is written (void)f(...).
"""

import re
from typing import Dict, List, Optional, Set, Tuple

# bus transfers that return a status or a byte count (SPI blocking transfers on the pico-sdk cannot fail and return
# the length; ESP-IDF's i2c_master_read/write only queue a command whose result comes from i2c_master_cmd_begin)
READ_CALLS = ("requestFrom", "i2c_read_blocking", "i2c_read_timeout_us", "i2c_read_blocking_until", "HAL_I2C_Mem_Read",
              "HAL_I2C_Master_Receive", "i2c_master_read_from_device", "i2c_master_write_read_device",
              "i2c_master_transmit_receive", "i2c_master_receive", "i2c_burst_read_dt", "i2c_read_dt", "i2c_write_read_dt",
              "HAL_SPI_Receive", "HAL_SPI_TransmitReceive")
WRITE_CALLS = ("endTransmission", "i2c_write_blocking", "i2c_write_timeout_us", "i2c_write_blocking_until", "HAL_I2C_Mem_Write",
               "HAL_I2C_Master_Transmit", "i2c_master_write_to_device", "i2c_master_transmit", "i2c_master_cmd_begin",
               "i2c_reg_write_byte_dt", "i2c_burst_write_dt", "i2c_write_dt", "HAL_SPI_Transmit")

_TIME_BOUND = re.compile(r"\b(millis|micros|time_us_\d+|get_absolute_time|absolute_time_diff_us|time_reached|HAL_GetTick|"
                         r"xTaskGetTickCount|k_uptime_get\w*|esp_timer_get_time|timeout\w*|deadline|elapsed|expired?)\b", re.I)
_COUNT_WORDS = re.compile(r"\b\w*(tries|retries|retry|attempts?|count|counter|iterations?|loops?|spins?|guard)\w*\b", re.I)
_HW_WORDS = re.compile(r"\bSerial\d?\b|\b(digitalRead|gpio_get|gpio_get_all)\s*\(|\w*(read|Read|available|status|Status|ready|"
                       r"Ready|busy|Busy|transfer|Transfer|receive|Receive)\w*\s*\(|\b\w*(STATUS|status|DRDY|drdy|RDY|rdy|BUSY|"
                       r"busy|ready|READY|done|DONE|flag|FLAG)\w*\b")


def _block(code: str, i: int) -> Tuple[str, int]:
    """The balanced (...) or {...} starting at code[i], and the index after it."""
    open_, close = code[i], {"(": ")", "{": "}"}[code[i]]
    depth = 0
    for j in range(i, len(code)):
        if code[j] == open_:
            depth += 1
        elif code[j] == close:
            depth -= 1
            if depth == 0:
                return code[i + 1:j], j + 1
    return code[i + 1:], len(code)


def _body(code: str, i: int) -> Tuple[str, int]:
    """The statement or block after a loop header ending at code[i]."""
    while i < len(code) and code[i] in " \t\n":
        i += 1
    if i < len(code) and code[i] == "{":
        return _block(code, i)
    j = code.find(";", i)
    return (code[i:j], j + 1) if j >= 0 else (code[i:], len(code))


def _line_of(starts: List[int], pos: int) -> int:
    lo, hi = 0, len(starts) - 1
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if starts[mid] <= pos:
            lo = mid
        else:
            hi = mid - 1
    return lo + 1


def _bounded(cond: str, body: str) -> bool:
    text = cond + " " + body
    if _TIME_BOUND.search(text):
        return True
    if _COUNT_WORDS.search(text) and re.search(r"(<|<=|>|>=|==|!=)", text):
        return True
    # a counter stepped and compared: while (!ready() && n++ < 100), if (--n == 0) break;
    return bool(re.search(r"(\+\+|--)\s*\w+\s*(<|<=|>|>=|==|!=)|\w+\s*(\+\+|--)\s*(<|<=|>|>=|==|!=)|(<|<=|>|>=|==|!=)\s*\w+\s*(\+\+|--)", text))


def unbounded_waits(lines: List[str]) -> List[Tuple[int, str]]:
    """(line, message) for each loop waiting on hardware without a bound."""
    code = "\n".join(lines)
    starts = [0]
    for ln in lines:
        starts.append(starts[-1] + len(ln) + 1)
    out = []
    for m in re.finditer(r"\b(while|for)\s*\(", code):
        if m.group(1) == "while" and re.search(r"\}\s*$", code[:m.start()]) and \
                re.search(r"\bdo\s*\{[^{}]*(\{[^{}]*\}[^{}]*)*\}\s*$", code[max(0, m.start() - 4000):m.start()]):
            continue   # the tail of a do { } while (...): handled with its do
        cond, end = _block(code, m.end() - 1)
        if m.group(1) == "for":
            parts = cond.split(";")
            if len(parts) != 3 or parts[1].strip():
                continue                   # a counted for loop
            cond = ""
        body, _ = _body(code, end)
        if cond.strip() and cond.strip() not in ("1", "true", "TRUE"):
            waits = _HW_WORDS.search(cond)
            if waits and re.fullmatch(r"\s*[\w.\->]*available\s*\(\s*\)\s*(>\s*0\s*)?", cond) and re.search(r"\bread\s*\(", body):
                continue                   # while (Wire.available()) buf[i++] = Wire.read(): drains what arrived
        else:                              # while (1) / for (;;): a wait only if it breaks out on hardware state
            brk = re.search(r"\bif\s*\(([^;{]*)\)\s*(\{[^}]*)?\b(break|return)\b", body)
            waits = brk and _HW_WORDS.search(brk.group(1))
        if not waits or _bounded(cond, body):
            continue
        out.append((_line_of(starts, m.start()), _wait_message(cond)))
    for m in re.finditer(r"\bdo\s*\{", code):   # do { s = read_status(); } while (!(s & DRDY));
        body, end = _block(code, m.end() - 1)
        tail = re.match(r"\s*while\s*\(", code[end:])
        if not tail:
            continue
        cond, _ = _block(code, end + tail.end() - 1)
        hw = _HW_WORDS.search(cond) or (_HW_WORDS.search(body) and re.search(r"\b(" + "|".join(
            re.findall(r"([A-Za-z_]\w*)\s*=[^=]", body)) + r")\b", cond) if re.search(r"[A-Za-z_]\w*\s*=[^=]", body) else None)
        if hw and not _bounded(cond, body):
            out.append((_line_of(starts, m.start()), _wait_message(cond)))
    return sorted(out)


def _wait_message(cond: str) -> str:
    what = re.sub(r"\s+", " ", cond.strip() or "an endless loop")[:80]
    return (f"This loop waits on hardware ({what}) with no timeout or retry limit: if that never happens (no USB host "
            "attached, sensor missing or unpowered, bus stuck) the firmware hangs here forever.")


def _results(code: str, starts: List[int], names: Tuple[str, ...],
             owners: Optional[Dict[str, Tuple[str, Set[str]]]] = None) -> List[Tuple[int, str, str]]:
    """(line, call, how) for calls of `names` whose result is thrown away or put in a variable never read. `owners`:
    the project's own functions -> (class or '', that class's objects): `_wire.begin()` is not BMP388::begin()."""
    out = []
    rx = re.compile(r"(?:\b([A-Za-z_]\w*)\s*(?:\.|->)\s*)?\b(" + "|".join(map(re.escape, names)) + r")\s*\(")
    for m in rx.finditer(code):
        if m.start() > 0 and code[m.start() - 1] in ".>" and not m.group(1):
            continue
        cls, objs = (owners or {}).get(m.group(2), (None, set()))
        recv = m.group(1) or ""
        if cls is not None:
            if recv and recv != "this" and recv not in objs:
                continue                   # a same-named method of another object (Serial.begin, Wire.read)
            if not recv and cls and not re.search(rf"\b{re.escape(cls)}::\w+\s*\([^;{{]*\)\s*(const\s*)?\{{", code[:m.start()]):
                continue                   # a bare call outside that class's methods
        line = _line_of(starts, m.start())
        args, after = _block(code, m.end() - 1)
        before = code[starts[line - 1]:m.start()]
        if re.search(r"\(\s*void\s*\)\s*$", before):
            continue                       # (void)f(...): discarded on purpose
        # the rest of the enclosing block
        depth, j = 0, after
        while j < len(code):
            if code[j] == "{":
                depth += 1
            elif code[j] == "}":
                if depth == 0:
                    break
                depth -= 1
            j += 1
        rest = code[after:j]
        assigned = re.search(r"([A-Za-z_]\w*)\s*(?:\[[^\]]*\])?\s*=\s*(?:\([^()]*\)\s*)?$", before)
        if assigned and not re.search(r"(==|!=|<=|>=|\breturn\b|\bif\b|\?)", before):
            if not re.search(rf"\b{re.escape(assigned.group(1))}\b", rest):
                out.append((line, m.group(2), f"puts its result in {assigned.group(1)}, which is never read"))
        elif re.fullmatch(r"\s*", before) and re.match(r"\s*;", code[after:]):
            if m.group(2) == "requestFrom" and re.search(r"\bavailable\s*\(", rest):
                continue                   # Wire.requestFrom(...); while (Wire.available()) ...: checked by the count
            out.append((line, m.group(2), "result is ignored"))
    return out


_FUNC_DEF = re.compile(r"(?m)^[ \t]*(?:static\s+|inline\s+)*(bool|int|int8_t|int16_t|int32_t|esp_err_t|HAL_StatusTypeDef|"
                       r"status_t|err_t)\s+(?:([A-Za-z_]\w*)::)?([A-Za-z_]\w*)\s*\([^;{)]*\)\s*(?:const\s*)?\{")


def _status_functions(texts: Dict[str, List[str]]) -> Dict[str, Tuple[str, str]]:
    """The project's own functions that report failure -> (how, class or '' for a free function): bool functions that
    can return false, int/status functions that can return a negative number or an error constant, and functions that
    return such a status as is (return i2c_burst_read_dt(&dev, reg, buf, len);)."""
    code = "\n".join("\n".join(lines) for lines in texts.values())
    funcs = []
    for m in _FUNC_DEF.finditer(code):
        body, _ = _block(code, m.end() - 1)
        funcs.append((m.group(1), m.group(2) or "", m.group(3), body))
    out: Dict[str, Tuple[str, str]] = {}
    for kind, cls, name, body in funcs:
        if kind == "bool" and re.search(r"\breturn\s+false\b|\breturn\s*\([^;]*(==|!=|<|>)", body):
            out[name] = ("returns false on failure", cls)
        elif kind != "bool" and re.search(r"\breturn\s+(-\s*\d+|[A-Z_]*(ERR|FAIL|ERROR)\w*)|\breturn\b[^;]*:\s*-\s*\d+\s*;", body):
            out[name] = ("returns an error code on failure", cls)
    changed = True
    while changed:
        changed = False
        known = READ_CALLS + WRITE_CALLS + tuple(out)
        for kind, cls, name, body in funcs:
            if name not in out and re.search(r"\breturn\s+(?:[A-Za-z_]\w*\s*(?:\.|->)\s*)*(" + "|".join(map(re.escape, known))
                                             + r")\s*\(", body):
                out[name] = ("returns the status of the transfer", cls)
                changed = True
    return out


def failures_reported_as_success(texts: Dict[str, List[str]]) -> List[Tuple[str, int, str]]:
    """(file, line, message) for a branch taken because a call failed that returns success (true from a bool function,
    0 from one that returns negative codes): the caller then carries on as if the device were set up."""
    own = _status_functions(texts)
    names = READ_CALLS + WRITE_CALLS + tuple(own)
    call = r"(?:[A-Za-z_]\w*\s*(?:\.|->)\s*)?\b(" + "|".join(map(re.escape, names)) + r")\s*\("
    out = []
    for rel, lines in texts.items():
        code = "\n".join(lines)
        starts = [0]
        for ln in lines:
            starts.append(starts[-1] + len(ln) + 1)
        for f in _FUNC_DEF.finditer(code):
            kind = f.group(1)
            fbody, _ = _block(code, f.end() - 1)
            success = "true" if kind == "bool" else "0" if re.search(r"\breturn\s+-\s*\d", fbody) else None
            if success is None:
                continue
            base = f.end()
            for m in re.finditer(r"\bif\s*\(", fbody):
                cond, end = _block(fbody, m.end() - 1)
                failed = re.match(r"\s*!\s*\(?\s*" + call, cond) or (re.search(call, cond) and re.search(
                    r"\)\s*(!=\s*(0|true|\w*OK\b|\w+)|<\s*0|==\s*(false|-\s*\d))", cond))
                # the device is not the part (its ID read does not match), or the object was never set up: the TMP117
                # driver's mutation test turned both branches' 'return false' into 'return true' unnoticed
                id_bad = re.fullmatch(r"\s*\(?\s*\w*(?:chip_?id|device_?id|dev_?id|part_?id|who_?am_?i|\bid)\w*\s*\)?\s*!=\s*\w+\s*",
                                      cond, re.I)
                not_ready = re.fullmatch(r"\s*!\s*(?:this\s*->\s*)?(\w*(?:initiali[sz]ed|inited|ready|begun|started)\w*)\s*", cond, re.I)
                if not (failed or id_bad or not_ready):
                    continue
                branch, _ = _body(fbody, end)
                if re.search(rf"\breturn\s+{success}\s*;", branch) or re.fullmatch(rf"\s*return\s+{success}\s*", branch):
                    line = _line_of(starts, base + m.start())
                    why = (f"When {failed.group(1)}() fails" if failed else
                           f"When the ID read does not match ({cond.strip()})" if id_bad else
                           f"When {not_ready.group(1)} says the device was never set up")
                    out.append((rel, line, f"{why}, this branch returns {success} (success): the caller carries on as if it "
                                           "had worked."))
    return out


def _objects(code: str, cls: str) -> Set[str]:
    """Names declared as objects (or references / pointers) of a class: 'BMP388 bmp388;' -> {'bmp388'}."""
    return set(re.findall(rf"\b{re.escape(cls)}\s*[&*]?\s+([A-Za-z_]\w*)\s*(?=[;=(\[{{,)])", code))


def ignored_results(texts: Dict[str, List[str]]) -> List[Tuple[str, int, str, str]]:
    """(file, line, call, message) for results that report failure and are thrown away."""
    own = _status_functions(texts)
    every = "\n".join("\n".join(lines) for lines in texts.values())
    owners = {name: (cls, _objects(every, cls) if cls else set()) for name, (_how, cls) in own.items()}
    names = READ_CALLS + WRITE_CALLS + tuple(n for n in own if n not in ("main", "setup", "loop", "app_main"))
    out = []
    for rel, lines in texts.items():
        code = "\n".join(lines)
        starts = [0]
        for ln in lines:
            starts.append(starts[-1] + len(ln) + 1)
        for line, call, how in _results(code, starts, names, owners):
            reads = call in READ_CALLS or re.search(r"read|get|fetch|receive|recv|load", call, re.I)
            what = (f"{call}() {own[call][0]}" if call in own else
                    f"{call}() reports whether the {'read' if call in READ_CALLS else 'write'} worked")
            out.append((rel, line, call, f"{what}, but this call's {how}: a failure goes unnoticed"
                                         + (" and the buffer's old bytes are used as data." if reads else ".")))
    return out

embedforge/truth/trust.py:
"""Source trust classification: which origins may be treated as engineering ground truth.

There is no human approval step (Absolute-Trust RAG). Instead, trust is a deterministic
function of the origin: manufacturer domains and official framework repositories are
authoritative; everything else is recorded but flagged UNOFFICIAL and surfaced by the verifier.
"""

from enum import Enum
from urllib.parse import urlparse


class TrustTier(str, Enum):
    OFFICIAL_MANUFACTURER = "OFFICIAL_MANUFACTURER"
    OFFICIAL_REPO = "OFFICIAL_REPO"
    USER = "USER"
    UNOFFICIAL = "UNOFFICIAL"


OFFICIAL_DOMAINS = {
    # MCU / SoC vendors
    "st.com", "ti.com", "microchip.com", "atmel.com", "nxp.com", "nordicsemi.com",
    "espressif.com", "raspberrypi.com", "renesas.com", "silabs.com", "infineon.com",
    "analog.com", "maximintegrated.com", "gigadevice.com", "wch-ic.com", "cypress.com",
    "arm.com", "onsemi.com", "lattice.com", "nuvoton.com", "ambiq.com",
    "arterytek.com", "arterychip.com",
    # Sensor / peripheral / driver vendors
    "invensense.tdk.com", "tdk.com", "bosch-sensortec.com", "sensirion.com",
    "melexis.com", "ams-osram.com", "ams.com", "vishay.com", "rohm.com",
    "memsic.com", "honeywell.com", "murata.com", "fortiortech.com", "fd-ic.com",
    "semtech.com", "cirrus.com", "everlight.com", "winbond.com", "macronix.com",
    "knowles.com", "ublox.com", "u-blox.com", "quectel.com", "sitime.com",
}

# Hosts that are official for specific vendors/frameworks but aren't their own domain.
OFFICIAL_HOST_SUFFIXES = {
    "docs.espressif.com", "docs.zephyrproject.org", "docs.platformio.org",
    "arduino.cc", "docs.arduino.cc", "ardupilot.org", "betaflight.com",
    "docs.px4.io", "px4.io", "micropython.org", "developer.arm.com",
    "datasheets.raspberrypi.com", "docs.nordicsemi.com", "infocenter.nordicsemi.com",
}

OFFICIAL_GITHUB_ORGS = {
    "stmicroelectronics", "espressif", "raspberrypi", "nrfconnect", "nordicsemiconductor",
    "ardupilot", "betaflight", "px4", "zephyrproject-rtos", "platformio", "arduino",
    "microchip-pic-avr-solutions", "analogdevicesinc", "nxp-mcuxpresso", "tdk-invensense",
    "boschsensortec", "sensirion", "infineon", "renesas", "ti-sitara", "arm-software",
    "armmbed", "micropython", "arterytek", "am32", "bitdump", "simplefoc", "madflight",
}


def _host(url: str) -> str:
    return (urlparse(url).netloc or "").lower().split(":")[0]


def _matches(host: str, domain: str) -> bool:
    return host == domain or host.endswith("." + domain)


# Vendor-hosted forums (community.st.com, e2e.ti.com, forum.arduino.cc, devzone.nordicsemi.com, ez.analog.com): users'
# posts on an official domain are not the vendor's documentation
FORUM_LABELS = {"community", "communities", "forum", "forums", "e2e", "answers", "discuss", "discussions", "devzone",
                "ez", "engineerzone", "support-community"}


def classify_url(url: str) -> TrustTier:
    """Deterministically classify a source URL into a trust tier."""
    if not url:
        return TrustTier.UNOFFICIAL
    if url.startswith("user://"):
        return TrustTier.USER
    host = _host(url)
    if host.split(".")[0] in FORUM_LABELS or (host.startswith("www.") and host.split(".")[1] in FORUM_LABELS):
        return TrustTier.UNOFFICIAL
    if any(_matches(host, d) for d in OFFICIAL_DOMAINS | OFFICIAL_HOST_SUFFIXES):
        return TrustTier.OFFICIAL_MANUFACTURER
    if host in ("github.com", "raw.githubusercontent.com", "www.github.com", "gitlab.com"):
        parts = [p for p in urlparse(url).path.split("/") if p]
        if parts and parts[0].lower() in OFFICIAL_GITHUB_ORGS:
            return TrustTier.OFFICIAL_REPO
    return TrustTier.UNOFFICIAL


def is_authoritative(tier: TrustTier) -> bool:
    return tier in (TrustTier.OFFICIAL_MANUFACTURER, TrustTier.OFFICIAL_REPO, TrustTier.USER)

embedforge/verifybench/__main__.py:
"""python -m embedforge.verifybench [framework ...] [-v]: score verify on the DM388 drivers and planted bugs."""

import sys

from embedforge.verifybench.bench import run, summary


def main() -> int:
    args = [a for a in sys.argv[1:] if not a.startswith("-")]
    verbose = "-v" in sys.argv
    cases = run(args or None)
    by_fw = {}
    for c in cases:
        by_fw.setdefault(c.framework, []).append(c)
    for fw, cs in by_fw.items():
        if cs[0].mutation == "must_fail":
            c = cs[0]
            print(f"{fw:28} unchecked code {'blocked' if c.caught else 'PASSED VERIFY'}" +
                  (f"  [{c.errors[0][:110]}]" if verbose and c.errors else ""))
            continue
        correct = cs[0]
        muts = cs[1:]
        caught = sum(bool(c.caught) for c in muts)
        print(f"{fw:28} correct driver {'PASS' if correct.passed else 'FAIL'}   bugs caught {caught}/{len(muts)}")
        if not correct.passed:
            for e in correct.errors[:6]:
                print(f"      false error: {e}")
        for c in muts:
            if not c.caught or verbose:
                print(f"      {'caught' if c.caught else 'MISSED'} {c.mutation}: {c.what}" +
                      (f"  [{c.errors[0][:110]}]" if verbose and c.errors else ""))
    s = summary(cases)
    print(f"\ncorrect drivers passing: {s['correct_passed']}/{s['correct_total']}   bugs caught: {s['caught']}/{s['mutants']}"
          f"   unchecked code blocked: {s['unchecked_blocked']}/{s['unchecked_total']}")
    return 0


if __name__ == "__main__":
    sys.exit(main())

embedforge/verifybench/drivers.py:
"""DM388 drivers for the verify benchmark: one shared driver core (init sequence, calibration, temperature conversion) on
top of a bus layer per framework, and the mutations (bugs) verify has to catch. `@F(key)@` stands for the FACT id the
ground truth recorded for `key`."""

import re
from typing import Dict, List, Tuple

CORE = r"""
#define DM388_CHIP_ID_REG 0x00   /* @F(chip_id_reg)@ */
#define DM388_CHIP_ID     0x50   /* @F(chip_id)@ */
#define DM388_CMD_REG     0x7E   /* @F(cmd_reg)@ */
#define DM388_SOFTRESET   0xB6   /* @F(softreset)@ */
#define DM388_STARTUP_MS  2      /* @F(startup)@ */
#define DM388_CALIB_REG   0x31   /* @F(calib_reg)@ */
#define DM388_CALIB_LEN   21     /* @F(calib_len)@ */
#define DM388_OSR_REG     0x1C   /* @F(osr_reg)@ */
#define DM388_OSR_VALUE   0x0B   /* @F(osr_value)@ */
#define DM388_ODR_REG     0x1D   /* @F(odr_reg)@ */
#define DM388_ODR_VALUE   0x02   /* @F(odr_value)@ */
#define DM388_PWR_REG     0x1B   /* @F(pwr_reg)@ */
#define DM388_PWR_NORMAL  0x33   /* @F(pwr_normal)@ */
#define DM388_DATA_REG    0x04   /* @F(data_reg)@ */
#define DM388_DATA_LEN    6      /* @F(data_len)@ */

static float par_t1, par_t2, par_t3;

int dm388_init(void) {
    uint8_t id = 0;
    write_reg(DM388_CMD_REG, DM388_SOFTRESET);
    delay_ms(DM388_STARTUP_MS);
    if (read_regs(DM388_CHIP_ID_REG, &id, 1) != 0) return -1;
    if (id != DM388_CHIP_ID) return -2;
    uint8_t c[DM388_CALIB_LEN];
    if (read_regs(DM388_CALIB_REG, c, DM388_CALIB_LEN) != 0) return -1;
    uint16_t nvm_par_t1 = (uint16_t)(((uint16_t)c[1] << 8) | c[0]);
    uint16_t nvm_par_t2 = (uint16_t)(((uint16_t)c[3] << 8) | c[2]);
    int8_t nvm_par_t3 = (int8_t)c[4];
    par_t1 = (float)nvm_par_t1 / powf(2.0f, -8.0f);
    par_t2 = (float)nvm_par_t2 / powf(2.0f, 30.0f);
    par_t3 = (float)nvm_par_t3 / powf(2.0f, 48.0f);
    write_reg(DM388_OSR_REG, DM388_OSR_VALUE);
    write_reg(DM388_ODR_REG, DM388_ODR_VALUE);
    write_reg(DM388_PWR_REG, DM388_PWR_NORMAL);
    return 0;
}

float dm388_read_temperature(void) {
    uint8_t d[DM388_DATA_LEN];
    read_regs(DM388_DATA_REG, d, DM388_DATA_LEN);
    uint32_t uncomp_temp = ((uint32_t)d[5] << 16) | ((uint32_t)d[4] << 8) | (uint32_t)d[3];
    float partial_data1 = (float)uncomp_temp - par_t1;
    float partial_data2 = partial_data1 * par_t2;
    return partial_data2 + (partial_data1 * partial_data1) * par_t3;
}
"""

